INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('codingshot/sunnahsleep/pwa-audit-sunnahsleep', 'community', 'codingshot', 'sunnahsleep', 'codingshot/sunnahsleep', 'pwa-audit-sunnahsleep', 0, 0, 26, '2026-03-08T01:57:15.473Z', '2026-03-08T02:09:40.589Z', '536bd945b8748e513d29f7046c9b77a748482fbe2ba9f3d9b2bd7153775c5d94', '{"id":"codingshot/sunnahsleep/pwa-audit-sunnahsleep","name":"pwa-audit-sunnahsleep","description":{"en":"This AI Agent skill performs a technical audit of a Progressive Web App built with vite-plugin-pwa and Workbox. It validates the manifest.webmanifest, service worker caching strategies, and offline functionality for Quran audio, specifically for developers building Islamic wellness applications.","zh":"pwa-audit-sunnahsleep 技能为 PWA 应用提供审计和优化功能，使用 Vite-plugin-PWA 和 Workbox 实现离线缓存和服务工作器","ja":"pwa-audit-sunnahsleep スキルは PWA アプリのオーディットと最適化機能を提供し、Vite-plugin-PWA と Workbox を使用してオフラインキャッシュとサービスワーカーを実現","ko":"pwa-audit-sunnahsleep 스킬은 PWA 애플리케이션의 심사 및 최적화를 제공하며 Vite-plugin-PWA 및 Workbox를 사용하여 오프라인 캐시 및 서비스 워커를 구현","es":"pwa-audit-sunnahsleep es una herramienta que utiliza vite-plugin-pwa y Workbox para mejorar la experiencia del usuario. Ofrece una configuración de PWA para curar el insomnio con Islam","fr":"pwa-audit-sunnahsleep est un outil qui utilise vite-plugin-pwa et Workbox pour améliorer l''expérience utilisateur. Il propose une configuration de PWA pour soigner l''insomnie avec l''Islam - Outils IA","de":"pwa-audit-sunnahsleep ist ein Tool, das vite-plugin-pwa und Workbox verwendet, um die Benutzererfahrung zu verbessern. Es bietet eine PWA-Konfiguration, um Schlafstörungen mit dem Islam zu heilen - Entwicklungstools","pt":"O pwa-audit-sunnahsleep é uma ferramenta para desenvolvedores que visa melhorar a experiência do usuário com recursos de caching e precaching","ru":"pwa-audit-sunnahsleep - это инструмент для разработчиков, предназначенный для улучшения пользовательского опыта с помощью кэширования и предкэширования","ar":"pwa-audit-sunnahsleep هو أداة لبرمجة تطبيقات الويب التقدمية التي تهدف إلى تحسين تجربة المستخدم باستخدام ميزات التخزين المؤقت والتحميل المسبق"},"seo":{"title":{"en":"pwa-audit-sunnahsleep: PWA Audit Setup Guide | AI Agent S...","zh":"PWA 审计指南：使用 Vite-plugin-PWA 和 Workbox","ja":"PWA オーディットのベストプラクティス：Vite-plugin-PWA と Workbox を使用","ko":"PWA 심사 가이드: Vite-plugin-PWA 및 Workbox 사용","es":"Guía de configuración de pwa-audit-sunnahsleep para desar...","fr":"Paramétrer pwa-audit-sunnahsleep pour les développeurs - ...","de":"Einrichtungsleitfaden für pwa-audit-sunnahsleep - Entwick...","pt":"Guia de Configuração do pwa-audit-sunnahsleep para Desenv...","ru":"Настройка pwa-audit-sunnahsleep: Руководство для Разработ...","ar":"دليل إعداد pwa-audit-sunnahsleep لبرمجة تطبيقات الويب الت..."},"description":{"en":"Audit your PWA''s vite-plugin-pwa & Workbox setup. This AI Agent skill checks manifest.webmanifest configuration, service worker caching for Quran audio, and ...","zh":"使用 pwa-audit-sunnahsleep 技能来优化您的 PWA 应用，包括 Vite-plugin-PWA 和 Workbox 的设置","ja":"pwa-audit-sunnahsleep スキルを使用して PWA アプリを最適化します。Vite-plugin-PWA と Workbox の設定を含みます","ko":"pwa-audit-sunnahsleep 스킬을 사용하여 PWA 애플리케이션을 최적화합니다. Vite-plugin-PWA 및 Workbox 설정 포함","es":"Aprende a configurar pwa-audit-sunnahsleep con vite-plugin-pwa y Workbox para mejorar la experiencia del usuario","fr":"Découvrez comment paramétrer pwa-audit-sunnahsleep avec vite-plugin-pwa et Workbox pour améliorer l''expérience utilisateur - Outils IA","de":"Erfahren Sie, wie Sie pwa-audit-sunnahsleep mit vite-plugin-pwa und Workbox einrichten, um die Benutzererfahrung zu verbessern - Entwicklungstools","pt":"Aprenda a configurar o pwa-audit-sunnahsleep com vite-plugin-pwa e Workbox para melhorar a experiência do usuário","ru":"Узнайте, как настроить pwa-audit-sunnahsleep с помощью vite-plugin-pwa и Workbox для улучшения пользовательского опыта ИИ Агентов","ar":"تعرف على كيفية إعداد pwa-audit-sunnahsleep باستخدام vite-plugin-pwa و Workbox لتحسين تجربة المستخدم"},"definition":{"en":"pwa-audit-sunnahsleep is an AI Agent skill that conducts a technical SEO and performance audit for Progressive Web Apps. It specifically analyzes apps built using vite-plugin-pwa and Workbox, checking critical elements like the manifest file, service worker caching, and offline capabilities for religious audio content.","zh":"pwa-audit-sunnahsleep 是一个 PWA 审计技能，用于优化 PWA 应用的性能和功能","ja":"pwa-audit-sunnahsleep は PWA アプリのパフォーマンスと機能を最適化するための PWA オーディットスキル","ko":"pwa-audit-sunnahsleep는 PWA 애플리케이션의 성능 및 기능을 최적화하는 PWA 심사 스킬","es":"pwa-audit-sunnahsleep es una herramienta de desarrollo que utiliza tecnologías web progresivas para mejorar la experiencia del usuario","fr":"pwa-audit-sunnahsleep est un outil de développement qui utilise des technologies web progressives pour améliorer l''expérience utilisateur - Outils IA","de":"pwa-audit-sunnahsleep ist ein Entwicklungstool, das progressive Web-Technologien verwendet, um die Benutzererfahrung zu verbessern - Entwicklungstools","pt":"O que é pwa-audit-sunnahsleep? É uma ferramenta de auditoria para aplicações web progressivas","ru":"Что такое pwa-audit-sunnahsleep? Это инструмент аудита для прогрессивных веб-приложений ИИ Агентов","ar":"ما هو pwa-audit-sunnahsleep؟ هو أداة فحص لبرمجة تطبيقات الويب التقدمية"},"features":{"en":["Audits manifest.webmanifest for required fields like name, short_name, and icons","Validates PWA display properties including start_url and standalone display mode","Checks service worker implementation using Workbox via vite-plugin-pwa","Verifies offline caching strategies for app shell (HTML, JS, CSS) and Quran audio content","Examines runtime caching configuration for API responses like prayer times"],"zh":["使用 Vite-plugin-PWA 实现 PWA 功能","使用 Workbox 实现服务工作器和离线缓存","支持 manifest.webmanifest 文件","支持 Quran 音频缓存","提供 PWA 审计检查清单","支持多语言"],"ja":["Vite-plugin-PWA を使用して PWA 機能を実現","Workbox を使用してサービスワーカーとオフラインキャッシュを実現","manifest.webmanifest ファイルをサポート","Quran オーディオキャッシュをサポート","PWA オーディットチェックリストを提供","マルチ言語をサポート"],"ko":["Vite-plugin-PWA를 사용하여 PWA 기능을 구현","Workbox를 사용하여 서비스 워커 및 오프라인 캐시를 구현","manifest.webmanifest 파일을 지원","쿠란 오디오 캐시를 지원","PWA 심사 체크리스트를 제공","다중 언어를 지원"],"es":["Configuración de PWA con vite-plugin-pwa","Uso de Workbox para cachear respuestas de API","Caché de audio del Corán para una mejor experiencia offline","Compatibilidad con tecnologías web progresivas","Mejora de la experiencia del usuario con una configuración de PWA personalizada"],"fr":["Configuration de PWA avec vite-plugin-pwa","Utilisation de Workbox pour mettre en cache les réponses d''API","Mise en cache de l''audio du Coran pour une meilleure expérience hors ligne","Compatibilité avec les technologies web progressives","Amélioration de l''expérience utilisateur avec une configuration PWA personnalisée - Outils IA"],"de":["PWA-Konfiguration mit vite-plugin-pwa","Verwendung von Workbox, um API-Antworten zu cachen","Caché von Koranaudio für eine bessere Offline-Erfahrung","Kompatibilität mit progressiven Web-Technologien","Verbesserung der Benutzererfahrung durch eine personalisierte PWA-Konfiguration - Entwicklungstools"],"pt":["Utiliza vite-plugin-pwa para build e manifest","Emprega Workbox para service worker e caching","Suporta precaching de app shell e runtime cache para API responses","Inclui recursos de caching para áudio do Alcorão","Permite personalização de manifest e service worker"],"ru":["Использует vite-plugin-pwa для сборки и манифеста","Использует Workbox для сервис воркера и кэширования","Поддерживает предкэширование оболочки приложения и runtime cache для ответов API","Включает в себя функции кэширования для аудио Корана","Позволяет настраивать манифест и сервис воркер"],"ar":["يستخدم vite-plugin-pwa لإنشاء التطبيق وملف المظهر","يستخدم Workbox لخدمة العامل و التخزين المؤقت","يدعم التحميل المسبق للغلاف التطبيق و التخزين المؤقت للوقت التشغيلي لاستجابات واجهة البرمجة","يحتوي على ميزات التخزين المؤقت للصوت القرآن","يسمح بتخصيص ملف المظهر وخدمة العامل"]},"keywords":{"en":["how to use pwa-audit-sunnahsleep","what is pwa-audit-sunnahsleep","pwa-audit-sunnahsleep vs lighthouse","pwa-audit-sunnahsleep alternative","pwa-audit-sunnahsleep install guide","vite-plugin-pwa audit checklist","workbox service worker validation","manifest.webmanifest best practices","offline quran audio caching","pwa audit for islamic apps"],"zh":["PWA 审计","Vite-plugin-PWA","Workbox","服务工作器","离线缓存","manifest.webmanifest","Quran 音频缓存","PWA 优化","AI エージェント","AI 工具"],"ja":["PWA オーディット","Vite-plugin-PWA","Workbox","サービスワーカー","オフラインキャッシュ","manifest.webmanifest","Quran オーディオキャッシュ","PWA 最適化","AIエージェント","AIツール"],"ko":["PWA 심사","Vite-plugin-PWA","Workbox","서비스 워커","오프라인 캐시","manifest.webmanifest","쿠란 오디오 캐시","PWA 최적화","AI 에이전트","AI 도구"],"es":["pwa-audit-sunnahsleep","desarrollo web progresivo","vite-plugin-pwa","Workbox","caché de audio del Corán","configuración de PWA","herramientas de desarrollo","experiencia del usuario"],"fr":["pwa-audit-sunnahsleep","développement web progressif","vite-plugin-pwa","Workbox","mise en cache de l''audio du Coran","configuration de PWA","outils de développement","expérience utilisateur","Outils IA"],"de":["pwa-audit-sunnahsleep","progressive Web-Entwicklung","vite-plugin-pwa","Workbox","Caché von Koranaudio","PWA-Konfiguration","Entwicklungstools","Benutzererfahrung","Entwicklungstools"],"pt":["pwa-audit-sunnahsleep","vite-plugin-pwa","Workbox","caching","precaching","aplicações web progressivas","desenvolvimento web","otimização de desempenho"],"ru":["pwa-audit-sunnahsleep","vite-plugin-pwa","Workbox","кэширование","предкэширование","прогрессивные веб-приложения","разработка веб-приложений","оптимизация производительности","ИИ Агенты"],"ar":["pwa-audit-sunnahsleep","vite-plugin-pwa","Workbox","التخزين المؤقت","التحميل المسبق","تطبيقات الويب التقدمية","برمجة تطبيقات الويب","تحسين الأداء","أدوات الويب الذكية"]}},"owner":"codingshot","repo":"sunnahsleep","repoPath":"codingshot/sunnahsleep","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.473Z","topics":[],"category":"community","skillMd":{"name":"pwa-audit-sunnahsleep","description":"Audits PWA aspects of SunnahSleep. Use when working on offline support, service worker, manifest, caching, or install flow. Covers vite-plugin-pwa, Workbox, and PWA best practices.","bodyPreview":"# PWA Audit\n\n## Current Setup\n\n- **Build:** vite-plugin-pwa\n- **Manifest:** public/manifest.webmanifest (or generated)\n- **Service Worker:** Workbox (via plugin)\n- **Offline:** Quran audio cached\n\n## Audit Checklist\n\n### Manifest\n\n- [ ] name, short_name, description\n- [ ] icons: 192x192, 512x512\n- [ ] start_url, display: standalone\n- [ ] theme_color, background_color\n- [ ] scope\n\n### Service Worker\n\n- [ ] Precache app shell (HTML, JS, CSS)\n- [ ] Runtime cache for API responses (prayer times—shor","body":"# PWA Audit\n\n## Current Setup\n\n- **Build:** vite-plugin-pwa\n- **Manifest:** public/manifest.webmanifest (or generated)\n- **Service Worker:** Workbox (via plugin)\n- **Offline:** Quran audio cached\n\n## Audit Checklist\n\n### Manifest\n\n- [ ] name, short_name, description\n- [ ] icons: 192x192, 512x512\n- [ ] start_url, display: standalone\n- [ ] theme_color, background_color\n- [ ] scope\n\n### Service Worker\n\n- [ ] Precache app shell (HTML, JS, CSS)\n- [ ] Runtime cache for API responses (prayer times—short TTL)\n- [ ] Cache Quran audio (cdn.islamic.network)\n- [ ] Offline fallback page\n- [ ] Skip waiting / update prompt for new versions\n\n### Caching Strategy\n\n| Resource | Strategy | Notes |\n|----------|----------|-------|\n| App shell | precache | StaleWhileRevalidate |\n| Quran audio | runtime cache | CacheFirst, long TTL |\n| Prayer API | network first | Short cache, fallback to stale |\n| Images | cache first | Static assets |\n\n### Install\n\n- [ ] beforeinstallprompt handled (if desired)\n- [ ] /install page with platform-specific instructions\n- [ ] Display mode: standalone works on home screen\n\n### Performance\n\n- [ ] Lazy load routes where possible\n- [ ] Image optimization (WebP, sizes)\n- [ ] Font loading (Amiri, Inter) – preload critical\n\n## Common Issues\n\n1. **Cache invalidation** – New deploy must update SW; use Workbox’s skipWaiting\n2. **API in SW** – Fetch from SW can have different CORS behavior\n3. **Storage** – localStorage available; IndexedDB for larger data if needed\n4. **Notifications** – Require user permission; document in privacy policy\n"},"lastSynced":"2026-03-08T02:09:40.589Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Development Agents requiring in-depth Progressive Web App auditing capabilities, particularly those utilizing vite-plugin-pwa and Workbox for Islamic wellness applications.","zh":"适合需要进行深入进度式网络应用程序审计的Web开发代理，特别是那些使用vite-plugin-pwa和Workbox进行伊斯兰健康应用程序的代理。","ja":"Web開発エージェントがプログレッシブWebアプリの詳細な監査を必要とする場合、特にvite-plugin-pwaとWorkboxを使用してイスラムのウェルネスアプリケーションを作成する場合に適しています。","ko":"웹 개발 에이전트가 프로그레시브 웹 앱의 심층 감사를 필요로 할 때 적합합니다. 특히 vite-plugin-pwa와 Workbox를 사용하여 이슬람 웰네스 애플리케이션을 개발하는 경우에 적합합니다.","es":"Ideal para Agentes de Desarrollo Web que requieren capacidades de auditoría de Aplicaciones Web Progresivas en profundidad, particularmente aquellos que utilizan vite-plugin-pwa y Workbox para aplicaciones de bienestar islámico.","fr":"Idéal pour les agents de développement Web nécessitant des capacités d''audit d''applications Web progressives en profondeur, en particulier ceux utilisant vite-plugin-pwa et Workbox pour les applications de bien-être islamique.","de":"Ideal für Webentwicklungsagenten, die umfassende Progressive Web App-Prüffunktionen erfordern, insbesondere solche, die vite-plugin-pwa und Workbox für islamische Wellness-Anwendungen verwenden.","pt":"Ideal para agentes de desenvolvimento web que exigem capacidades de auditoria de Progressive Web App em profundidade, particularmente aqueles que utilizam vite-plugin-pwa e Workbox para aplicações de bem-estar islâmico.","ru":"Идеально подходит для агентов веб-разработки, требующих глубоких возможностей аудита Progressive Web App, особенно тех, которые используют vite-plugin-pwa и Workbox для исламских приложений для здоровья.","ar":"مثالي لعميل التطوير الويب الذي يتطلب قدرات تدقيق Progressive Web App متعمقة، خاصة تلك التي تستخدم vite-plugin-pwa و Workbox لتطبيقات الصحة الإسلامية."},"recommendation":{"en":"Empowers agents to validate manifest.webmanifest files, inspect service worker caching strategies, and ensure offline functionality for Quran audio, leveraging Workbox and vite-plugin-pwa for comprehensive PWA audits.","zh":"赋予代理验证manifest.webmanifest文件、检查服务工作线程缓存策略以及确保Quran音频的离线功能的能力，利用Workbox和vite-plugin-pwa进行全面PWA审计。","ja":"エージェントに、manifest.webmanifestファイルを検証し、サービスワーカーのキャッシュ戦略を調査し、クルアーンのオーディオのオフライン機能を確保する機能を提供し、Workboxとvite-plugin-pwaを使用して包括的なPWA監査を実行します。","ko":"에이전트에게 manifest.webmanifest 파일을 검증하고 서비스 워커의 캐싱 전략을 조사하며 쿠란 오디오의 오프라인 기능을 보장하는 기능을 제공하며, Workbox와 vite-plugin-pwa를 사용하여 포괄적인 PWA 감사를 수행합니다.","es":"Habilita a los agentes a validar archivos manifest.webmanifest, inspeccionar estrategias de almacenamiento en caché de service worker y garantizar la funcionalidad sin conexión para audio del Corán, aprovechando Workbox y vite-plugin-pwa para auditorías de PWA completas.","fr":"Permet aux agents de valider les fichiers manifest.webmanifest, d''inspecter les stratégies de mise en cache des service worker et de garantir la fonctionnalité hors ligne pour l''audio du Coran, en exploitant Workbox et vite-plugin-pwa pour des audits PWA complets.","de":"Ermöglicht es Agenten, manifest.webmanifest-Dateien zu überprüfen, Service-Worker-Caching-Strategien zu untersuchen und die Offline-Funktionalität für Quran-Audio sicherzustellen, indem Workbox und vite-plugin-pwa für umfassende PWA-Prüfungen genutzt werden.","pt":"Habilita os agentes a validar arquivos manifest.webmanifest, inspecionar estratégias de cache de service worker e garantir funcionalidade offline para áudio do Alcorão, utilizando Workbox e vite-plugin-pwa para auditorias de PWA abrangentes.","ru":"Наделяет агентов возможностью проверять файлы manifest.webmanifest, инспектировать стратегии кэширования service worker и обеспечивать функциональность offline для аудио Корана, используя Workbox и vite-plugin-pwa для всесторонних аудитов PWA.","ar":"يمنح الوكلاء القدرة على التحقق من صحة ملفات manifest.webmanifest، و فحص استراتيجيات تخزين مؤقت للعامل الخدمي، وضمان الوظيفة دون اتصال للصوت القرآني، باستخدام Workbox و vite-plugin-pwa لتدقيق شامل ل تطبيقات الويب التقدمية."},"useCases":{"en":["Auditing manifest.webmanifest for compliance","Debugging service worker caching issues for Quran audio","Validating offline functionality for Islamic wellness applications"],"zh":["审计manifest.webmanifest以进行合规性检查","调试服务工作线程的缓存问题以进行Quran音频的优化","验证伊斯兰健康应用程序的离线功能"],"ja":["コンプライアンスのためにmanifest.webmanifestを監査する","クルアーンのオーディオの最適化のためのサービスワーカーのキャッシュ問題をデバッグする","イスラムのウェルネスアプリケーションのオフライン機能を検証する"],"ko":["규정 준수를 위해 manifest.webmanifest를 감사하는 것","쿠란 오디오의 최적화를 위한 서비스 워커의 캐싱 문제를 디버깅하는 것","이슬람 웰네스 애플리케이션의 오프라인 기능을 검증하는 것"],"es":["Auditoría de manifest.webmanifest para cumplimiento","Depuración de problemas de caché de service worker para audio del Corán","Validación de la funcionalidad sin conexión para aplicaciones de bienestar islámico"],"fr":["Audit de manifest.webmanifest pour la conformité","Débogage des problèmes de mise en cache des service worker pour l''audio du Coran","Validation de la fonctionnalité hors ligne pour les applications de bien-être islamique"],"de":["Auditoría de manifest.webmanifest para cumplimiento","Fehlerbehebung bei Service-Worker-Caching-Problemen für Quran-Audio","Validierung der Offline-Funktionalität für islamische Wellness-Anwendungen"],"pt":["Auditoria de manifest.webmanifest para conformidade","Depuração de problemas de cache de service worker para áudio do Alcorão","Validação de funcionalidade offline para aplicações de bem-estar islâmico"],"ru":["Аудит manifest.webmanifest на соответствие","Отладка проблем кэширования service worker для аудио Корана","Проверка функциональности offline для исламских приложений для здоровья"],"ar":["تدقيق manifest.webmanifest للامتثال","تصحيح أخطاء تخزين مؤقت للعامل الخدمي للصوت القرآني","التحقق من الوظيفة دون اتصال لتطبيقات الصحة الإسلامية"]},"limitations":{"en":["Requires vite-plugin-pwa and Workbox setup","Specific to Progressive Web Apps with Quran audio caching"],"zh":["需要vite-plugin-pwa和Workbox的设置","仅适用于具有Quran音频缓存的进度式网络应用程序"],"ja":["vite-plugin-pwaとWorkboxの設定が必要","クルアーンのオーディオのキャッシュを備えたプログレッシブWebアプリのみに対応"],"ko":["vite-plugin-pwa와 Workbox의 설정이 필요함","쿠란 오디오 캐싱을備えた 프로그레시브 웹 애플리케이션에만 해당"],"es":["Requiere configuración de vite-plugin-pwa y Workbox","Específico para Aplicaciones Web Progresivas con caché de audio del Corán"],"fr":["Nécessite la configuration de vite-plugin-pwa et Workbox","Spécifique aux applications Web progressives avec mise en cache de l''audio du Coran"],"de":["Erfordert vite-plugin-pwa- und Workbox-Setup","Spezifisch für Progressive Web Apps mit Quran-Audio-Caching"],"pt":["Exige configuração do vite-plugin-pwa e Workbox","Específico para Progressive Web Apps com cache de áudio do Alcorão"],"ru":["Требует настройки vite-plugin-pwa и Workbox","Относится конкретно к Progressive Web Apps с кэшированием аудио Корана"],"ar":["يتطلب إعدادًا لـ vite-plugin-pwa و Workbox","محدد لتطبيقات الويب التقدمية مع تخزين مؤقت للصوت القرآني"]},"version":4},"contentHash":"536bd945b8748e513d29f7046c9b77a748482fbe2ba9f3d9b2bd7153775c5d94","qualityScore":26}');
