INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('codingshot/sunnahsleep/pwa-audit-sunnahsleep', 'pwa-audit-sunnahsleep', 'codingshot', 'sunnahsleep', 'community', 'pwa-audit-sunnahsleep codingshot sunnahsleep community This AI Agent skill performs a technical audit of a Progressive Web App built with vite-plugin-pwa and Workbox. It validates the manifest.webmanifest, service worker caching strategies, and offline functionality for Quran audio, specifically for developers building Islamic wellness applications. pwa-audit-sunnahsleep 技能为 PWA 应用提供审计和优化功能，使用 Vite-plugin-PWA 和 Workbox 实现离线缓存和服务工作器 pwa-audit-sunnahsleep スキルは PWA アプリのオーディットと最適化機能を提供し、Vite-plugin-PWA と Workbox を使用してオフラインキャッシュとサービスワーカーを実現 pwa-audit-sunnahsleep 스킬은 PWA 애플리케이션의 심사 및 최적화를 제공하며 Vite-plugin-PWA 및 Workbox를 사용하여 오프라인 캐시 및 서비스 워커를 구현 pwa-audit-sunnahsleep es una herramienta que utiliza vite-plugin-pwa y Workbox para mejorar la experiencia del usuario. Ofrece una configuración de PWA para curar el insomnio con Islam pwa-audit-sunnahsleep est un outil qui utilise vite-plugin-pwa et Workbox pour améliorer l''expérience utilisateur. Il propose une configuration de PWA pour soigner l''insomnie avec l''Islam - Outils IA pwa-audit-sunnahsleep ist ein Tool, das vite-plugin-pwa und Workbox verwendet, um die Benutzererfahrung zu verbessern. Es bietet eine PWA-Konfiguration, um Schlafstörungen mit dem Islam zu heilen - Entwicklungstools O pwa-audit-sunnahsleep é uma ferramenta para desenvolvedores que visa melhorar a experiência do usuário com recursos de caching e precaching pwa-audit-sunnahsleep - это инструмент для разработчиков, предназначенный для улучшения пользовательского опыта с помощью кэширования и предкэширования pwa-audit-sunnahsleep هو أداة لبرمجة تطبيقات الويب التقدمية التي تهدف إلى تحسين تجربة المستخدم باستخدام ميزات التخزين المؤقت والتحميل المسبق how to use pwa-audit-sunnahsleep what is pwa-audit-sunnahsleep pwa-audit-sunnahsleep vs lighthouse pwa-audit-sunnahsleep alternative pwa-audit-sunnahsleep install guide vite-plugin-pwa audit checklist workbox service worker validation manifest.webmanifest best practices offline quran audio caching pwa audit for islamic apps PWA 审计 Vite-plugin-PWA Workbox 服务工作器 离线缓存 manifest.webmanifest Quran 音频缓存 PWA 优化 AI エージェント AI 工具 Audits manifest.webmanifest for required fields like name, short_name, and icons Validates PWA display properties including start_url and standalone display mode Checks service worker implementation using Workbox via vite-plugin-pwa Verifies offline caching strategies for app shell (HTML, JS, CSS) and Quran audio content Examines runtime caching configuration for API responses like prayer times pwa-audit-sunnahsleep is an AI Agent skill that conducts a technical SEO and performance audit for Progressive Web Apps. It specifically analyzes apps built using vite-plugin-pwa and Workbox, checking critical elements like the manifest file, service worker caching, and offline capabilities for religious audio content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Sherloock/LoopTimer/nextjs-app-router-data-fetching', 'community', 'Sherloock', 'LoopTimer', 'Sherloock/LoopTimer', 'nextjs-app-router-data-fetching', 0, 0, 26, '2026-03-08T01:57:15.475Z', '2026-03-08T02:09:43.673Z', 'f1a37577ebf8d8b19cc7111e8e4a6039258ee41b0080108f02478389fe9c2290', '{"id":"Sherloock/LoopTimer/nextjs-app-router-data-fetching","name":"nextjs-app-router-data-fetching","description":{"en":"The nextjs-app-router-data-fetching skill optimizes data fetching in Next.js applications, benefiting developers who need to improve performance. It provides guidelines for route handlers, input validation, and caching.","zh":"Next.js 应用路由数据获取是一个高效的数据获取解决方案，通过路由处理、输入验证和缓存优化来提高应用性能","ja":"Next.js アプリルーターデータ取得は、高性能なデータ取得ソリューションです。ルーティングハンドラー、入力検証、キャッシング最適化などを通じて、アプリケーションのパフォーマンスを向上させます","ko":"Next.js 애플리케이션 라우터 데이터 패칭은 효율적인 데이터 패칭 솔루션으로, 라우팅 핸들러, 입력 검증, 캐싱 최적화를 통해 애플리케이션 성능을 향상시킵니다","es":"nextjs-app-router-data-fetching es una técnica para optimizar la obtención de datos en aplicaciones Next.js, utilizando validación de entradas con Zod y caché para mejorar el rendimiento","fr":"nextjs-app-router-data-fetching est une technique pour optimiser la récupération de données dans les applications Next.js, en utilisant la validation des entrées avec Zod et la mise en cache pour améliorer les performances","de":"nextjs-app-router-data-fetching ist eine Technik zur Optimierung der Datenerfassung in Next.js-Anwendungen, bei der die Eingabvalidierung mit Zod und Caching zum Performance-Boost eingesetzt werden","pt":"O Next.js App Router Data Fetching é uma técnica para melhorar o desempenho da sua aplicação, utilizando código split e validação de entradas","ru":"Next.js App Router Data Fetching - это техника для улучшения производительности вашего приложения, используя код-сплит и валидацию входных данных","ar":"Next.js App Router Data Fetching هو تقنية لتحسين أداء تطبيقك، باستخدام تقسيم الكود و التحقق من المدخلات"},"seo":{"title":{"en":"nextjs-app-router-data-fetching: Optimized Data Fetching ...","zh":"Next.js 应用路由数据获取最佳实践","ja":"Next.js アプリルーターデータ取得 Setup Guide","ko":"Next.js 애플리케이션 라우터 데이터 패칭 튜토리얼","es":"Guía de configuración de nextjs-app-router-data-fetching ...","fr":"Guide de mise en place de nextjs-app-router-data-fetching...","de":"Einrichtungsleitfaden für nextjs-app-router-data-fetching...","pt":"Guia de Configuração do Next.js App Router Data Fetching","ru":"Настройка ИИ Агентов: Next.js App Router Data Fetching","ar":"دليل إعداد Next.js App Router Data Fetching"},"description":{"en":"Learn how to optimize data fetching in Next.js apps with this AI agent skill, featuring code splitting and Suspense boundary techniques. Get started now!","zh":"了解 Next.js 应用路由数据获取的技术细节，包括路由处理、输入验证、缓存和性能优化","ja":"Next.js アプリルーターデータ取得のテクニカルな内容を学びましょう。ルーティングハンドラー、入力検証、キャッシング、パフォーマンス最適化など","ko":"Next.js 애플리케이션 라우터 데이터 패칭에 대한 기술적인 세부 사항을 알아보세요. 라우팅 핸들러, 입력 검증, 캐싱, 성능 최적화 등","es":"Aprenda a optimizar la obtención de datos en aplicaciones Next.js con nextjs-app-router-data-fetching, incluyendo validación de entradas y caché","fr":"Découvrez comment optimiser la récupération de données dans les applications Next.js avec nextjs-app-router-data-fetching, y compris la validation des entrée...","de":"Erfahren Sie, wie Sie die Datenerfassung in Next.js-Anwendungen mit nextjs-app-router-data-fetching optimieren, einschließlich Eingabvalidierung und Caching","pt":"Aprenda a configurar o Next.js App Router Data Fetching para melhorar o desempenho da sua aplicação","ru":"Узнайте, как настроить Next.js App Router Data Fetching для улучшения производительности вашего приложения","ar":"تعلم كيفية إعداد Next.js App Router Data Fetching لتحسين أداء تطبيقك"},"definition":{"en":"nextjs-app-router-data-fetching is a skill that provides best practices for optimizing data fetching in Next.js applications using techniques like code splitting and Suspense boundaries.","zh":"Next.js 应用路由数据获取是一种用于 Next.js 应用的数据获取机制，通过路由处理和输入验证来确保数据的准确性和安全性","ja":"Next.js アプリルーターデータ取得は、Next.js アプリケーション用のデータ取得メカニズムです。ルーティングハンドラーと入力検証を通じて、データの正確性とセキュリティを確保します","ko":"Next.js 애플리케이션 라우터 데이터 패칭은 Next.js 애플리케이션용 데이터 패칭 메커니즘으로, 라우팅 핸들러와 입력 검증을 통해 데이터의 정확성과 보안성을 보장합니다","es":"nextjs-app-router-data-fetching es una técnica de optimización de datos para aplicaciones Next.js que utiliza validación de entradas y caché","fr":"nextjs-app-router-data-fetching est une technique d''optimisation des données pour les applications Next.js qui utilise la validation des entrées et la mise en cache","de":"nextjs-app-router-data-fetching ist eine Technik zur Datenerfassungsoptimierung für Next.js-Anwendungen, die Eingabvalidierung und Caching verwendet","pt":"O que é Next.js App Router Data Fetching? É uma técnica de otimização de desempenho para aplicações Next.js","ru":"Что такое Next.js App Router Data Fetching? Это техника оптимизации производительности для приложений Next.js","ar":"ما هو Next.js App Router Data Fetching؟ هو تقنية لتحسين الأداء لتطبيقات Next.js"},"features":{"en":["Uses Zod for input validation and server-side authentication","Employs code splitting via next/dynamic for non-critical UI components","Utilizes Suspense boundaries with useSearchParams() for efficient data fetching","Prefer minimal payloads to avoid over-fetching","Keeps client components lean by moving heavy work server-side","Enforces authentication and validation for route handlers in app/apiroute.ts"],"zh":["路由处理：使用 `app/apiroute.ts` 处理路由","输入验证：使用 Zod 进行输入验证","缓存优化：使用 `next/dynamic` 实现代码分割","性能优化：保持客户端组件精简，移动重型工作到服务器端","Suspense 边界：使用 `useSearchParams()` 时，包装在独立组件中以避免构建/运行时问题"],"ja":["ルーティングハンドラー：`app/apiroute.ts` を使用してルーティングを処理","入力検証：Zod を使用して入力検証を実施","キャッシング最適化：`next/dynamic` を使用してコード分割を実現","パフォーマンス最適化：クライアント側コンポーネントを軽量化し、重い処理をサーバー側に移動","Suspense 境界：`useSearchParams()` を使用する際、独立したコンポーネントでラップしてビルド/実行時問題を回避"],"ko":["라우팅 핸들러：`app/apiroute.ts`를 사용하여 라우팅을 처리","입력 검증：Zod를 사용하여 입력 검증을 수행","캐싱 최적화：`next/dynamic`를 사용하여 코드 분할을 구현","성능 최적화：클라이언트側 컴포넌트를 가볍게 유지하고, 무거운 작업을 서버측으로 이동","Suspense 경계：`useSearchParams()`를 사용할 때,独立된 컴포넌트에서 래핑하여 빌드/실행 시 문제를 피함"],"es":["Validación de entradas con Zod","Uso de code splitting con next/dynamic para mejoras de rendimiento","Implementación de caché para reducir la cantidad de solicitudes","Uso de Suspense para evitar problemas de compilación y ejecución","Optimización de payloads para reducir la cantidad de datos transferidos","Soporte para autenticación y autorización en el servidor"],"fr":["Validation des entrées avec Zod","Utilisation de code splitting avec next/dynamic pour améliorer les performances","Mise en cache pour réduire le nombre de requêtes","Utilisation de Suspense pour éviter les problèmes de compilation et d''exécution","Optimisation des payloads pour réduire la quantité de données transférées","Prise en charge de l''authentification et de l''autorisation sur le serveur"],"de":["Eingabvalidierung mit Zod","Verwendung von Code-Splitting mit next/dynamic für Performance-Verbesserungen","Implementierung von Caching zur Reduzierung der Anzahl von Anfragen","Verwendung von Suspense zur Vermeidung von Kompilier- und Laufzeitproblemen","Optimierung von Payloads zur Reduzierung der übertragenen Datenmenge","Unterstützung für Authentifizierung und Autorisierung auf dem Server"],"pt":["Utiliza código split com next/dynamic para melhorar o carregamento inicial","Validação de entradas com Zod","Enforce autenticação servidor-side","Preferência por payloads mínimos para evitar over-fetching","Utiliza Suspense boundary para evitar problemas de build/runtime"],"ru":["Использует код-сплит с next/dynamic для улучшения初ального загрузки","Валидация входных данных с Zod","Принудительная аутентификация на стороне сервера","Предпочтение минимальных payload для избежания over-fetching","Использует Suspense boundary для избежания проблем с 빌дом/временем выполнения"],"ar":["يستخدم تقسيم الكود مع next/dynamic لتحسين التحميل الأولي","التحقق من المدخلات باستخدام Zod","التحقق من صحة المصادقة على الخادم","الاعتماد على payloads минимальة لتجنب التكرار","يستخدم Suspense boundary لتجنب مشاكل البناء/زمن التشغيل"]},"keywords":{"en":["how to use nextjs-app-router-data-fetching","nextjs-app-router-data-fetching setup guide","nextjs-app-router-data-fetching vs react-query","what is nextjs-app-router-data-fetching","nextjs-app-router-data-fetching install","nextjs-app-router-data-fetching alternative","nextjs-app-router-data-fetching best practices","nextjs-app-router-data-fetching performance optimization","nextjs-app-router-data-fetching caching strategies"],"zh":["Next.js 应用路由数据获取","路由处理","输入验证","缓存优化","性能优化","Suspense 边界","AIエージェント","Next.js 开发","前端开发"],"ja":["Next.js アプリルーターデータ取得","ルーティングハンドラー","入力検証","キャッシング最適化","パフォーマンス最適化","Suspense 境界","AIエージェント","Next.js 開発","フロントエンド開発"],"ko":["Next.js 애플리케이션 라우터 데이터 패칭","라우팅 핸들러","입력 검증","캐싱 최적화","성능 최적화","Suspense 경계","AI 에이전트","Next.js 개발","프론트엔드 개발"],"es":["nextjs-app-router-data-fetching","optimización de datos next.js","validación de entradas zod","caché next.js","code splitting next/dynamic","suspense next.js","autenticación next.js","desarrollo de aplicaciones next.js"],"fr":["nextjs-app-router-data-fetching","optimisation des données next.js","validation des entrées zod","mise en cache next.js","code splitting next/dynamic","suspense next.js","authentification next.js","développement d''applications next.js"],"de":["nextjs-app-router-data-fetching","datenoptimierung next.js","eingabvalidierung zod","caching next.js","code-splitting next/dynamic","suspense next.js","authentifizierung next.js","entwicklung von next.js-anwendungen"],"pt":["Next.js App Router Data Fetching","Otimização de desempenho","Código split","Validação de entradas","Autenticação servidor-side","React","Next.js"],"ru":["Next.js App Router Data Fetching","Оптимизация производительности","Код-сплит","Валидация входных данных","Принудительная аутентификация","React","Next.js","ИИ Агенты"],"ar":["Next.js App Router Data Fetching","تحسين الأداء","تقسيم الكود","التحقق من المدخلات","التحقق من صحة المصادقة","React","Next.js","أدوات الذكاء الاصطناعي"]}},"owner":"Sherloock","repo":"LoopTimer","repoPath":"Sherloock/LoopTimer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.475Z","topics":[],"category":"community","skillMd":{"name":"nextjs-app-router-data-fetching","description":"Use when working on Next.js App Router route handlers, caching, search params, or navigation/redirect patterns.","bodyPreview":"## Checklist\n\n- Route handlers live in `app/api/**/route.ts`.\n- Validate inputs (Zod) and enforce auth server-side.\n- Prefer minimal payloads; avoid over-fetching.\n\n## Search params rule\n\n- If using `useSearchParams()`, wrap it in a Suspense boundary (separate component + `<Suspense fallback={...}>`) to avoid build/runtime issues.\n\n## Caching / performance\n\n- Use code splitting (`next/dynamic`) for non-critical UI where it improves initial load.\n- Keep client components lean; move heavy work ser","body":"## Checklist\n\n- Route handlers live in `app/api/**/route.ts`.\n- Validate inputs (Zod) and enforce auth server-side.\n- Prefer minimal payloads; avoid over-fetching.\n\n## Search params rule\n\n- If using `useSearchParams()`, wrap it in a Suspense boundary (separate component + `<Suspense fallback={...}>`) to avoid build/runtime issues.\n\n## Caching / performance\n\n- Use code splitting (`next/dynamic`) for non-critical UI where it improves initial load.\n- Keep client components lean; move heavy work server-side when possible.\n\n## Repo references\n\n- Navigation utilities: `lib/navigation.ts`\n- Routes constants: `lib/constants/routes.ts`\n"},"lastSynced":"2026-03-08T02:09:43.673Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing optimized Next.js application performance through efficient data fetching and routing.","zh":"适合需要优化Next.js应用程序性能，通过高效数据获取和路由的前端代理。","ja":"Next.jsアプリケーションのパフォーマンスを最適化するために、効率的なデータ取得とルーティングが必要なフロントエンドエージェントに最適。","ko":"효율적인 데이터 가져오기와 라우팅을 통해 Next.js 애플리케이션 성능을 최적화해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes frontend que necesitan un rendimiento óptimo de la aplicación Next.js a través de una recolección y enrutamiento de datos eficientes.","fr":"Parfait pour les agents frontend qui ont besoin d''un rendimiento optimisé de l''application Next.js grâce à une collecte et un routage de données efficaces.","de":"Perfekt für Frontend-Agents, die ein optimiertes Next.js-Anwendungsleistung durch effizientes Datenabrufen und Routing benötigen.","pt":"Perfeito para Agentes Frontend que precisam de desempenho de aplicativos Next.js otimizado por meio de busca de dados eficiente e roteamento.","ru":"Идеально для фронтенд-агентов, которым необходим оптимизированный производительности приложений Next.js посредством эффективной выборки данных и маршрутизации.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى أداء تطبيقات Next.js محسّن من خلال استرجاع البيانات الفعال والتوجيه."},"recommendation":{"en":"Empowers agents to optimize Next.js applications with advanced route handling using `app/apiroute.ts`, input validation via Zod, and performance enhancements through code splitting with `next/dynamic` and minimal payload management.","zh":"赋予代理优化Next.js应用程序的能力，通过使用`app/apiroute.ts`进行高级路由处理、使用Zod进行输入验证以及通过`next/dynamic`代码分割和最小有效负载管理进行性能增强。","ja":"エージェントに、`app/apiroute.ts`を使用した高度なルートハンドリング、Zodを使用した入力検証、および`next/dynamic`コード分割と最小ペイロード管理を使用したパフォーマンスの向上により、Next.jsアプリケーションを最適化する能力を提供します。","ko":"에이전트에게 `app/apiroute.ts`를 사용한 고급 라우팅 처리, Zod를 사용한 입력 유효성 검사 및 `next/dynamic` 코드 분할 및 최소화된 페이로드 관리를 통해 성능을 향상시켜 Next.js 애플리케이션을 최적화할 수 있는 능력을 제공합니다.","es":"Habilita a los agentes a optimizar aplicaciones Next.js con un manejo de rutas avanzado utilizando `app/apiroute.ts`, validación de entrada a través de Zod y mejoras de rendimiento a través de la división de código con `next/dynamic` y una gestión de carga mínima.","fr":"Permet aux agents d''optimiser les applications Next.js avec une gestion de routes avancée en utilisant `app/apiroute.ts`, une validation des entrées via Zod et des améliorations des performances grâce à la division de code avec `next/dynamic` et une gestion de charge minimale.","de":"Ermöglicht es den Agenten, Next.js-Anwendungen mit erweitertem Routenhandling unter Verwendung von `app/apiroute.ts`, Eingabvalidierung über Zod und Leistungsverbesserungen durch Code-Splitting mit `next/dynamic` und minimalem Payload-Management zu optimieren.","pt":"Habilita os agentes a otimizar aplicações Next.js com tratamento de rota avançado usando `app/apiroute.ts`, validação de entrada via Zod e melhorias de desempenho por meio de divisão de código com `next/dynamic` e gerenciamento de carga mínima.","ru":"Наделяет агентов возможностью оптимизировать приложения Next.js с помощью продвинутого маршрутизации с использованием `app/apiroute.ts`, проверки входных данных через Zod и повышения производительности за счет разделения кода с `next/dynamic` и минимизации полезной нагрузки.","ar":"تمكن العميل من تحسين أداء تطبيقات Next.js باستخدام معالجة المسار المتقدمة باستخدام `app/apiroute.ts` ، وتصديق الإدخال عبر Zod ، وتحسين الأداء من خلال تقسيم الشفرة باستخدام `next/dynamic` وإدارة الحمولة الدنيا."},"useCases":{"en":["Optimizing data fetching for improved page loads","Implementing secure input validation with Zod","Enhancing application performance through caching and code splitting"],"zh":["优化数据获取以提高页面加载速度","使用Zod实现安全的输入验证","通过缓存和代码分割提高应用程序性能"],"ja":["ページロードの向上のためにデータ取得を最適化する","Zodを使用した安全な入力検証の実装","キャッシングとコード分割を使用したアプリケーションパフォーマンスの向上"],"ko":["페이지 로드 속도를 향상하기 위한 데이터 가져오기 최적화","Zod를 사용한 보안 입력 유효성 검사의 구현","캐싱 및 코드 분할을 통해 애플리케이션 성능을 향상시키기"],"es":["Optimizar la recolección de datos para mejorar la carga de páginas","Implementar una validación de entrada segura con Zod","Mejorar el rendimiento de la aplicación a través de la caché y la división de código"],"fr":["Optimiser la collecte de données pour améliorer les temps de chargement des pages","Implémenter une validation des entrées sécurisée avec Zod","Améliorer les performances de l''application grâce au cache et à la division de code"],"de":["Datenabruf für verbesserte Seitenaufbauzeiten optimieren","Sichere Eingabvalidierung mit Zod implementieren","Anwendungsleistung durch Caching und Code-Splitting verbessern"],"pt":["Otimizando a busca de dados para melhorar o carregamento de páginas","Implementando validação de entrada segura com Zod","Melhorando o desempenho da aplicação por meio de cache e divisão de código"],"ru":["Оптимизация выборки данных для улучшения загрузки страниц","Реализация безопасной проверки входных данных с помощью Zod","Повышение производительности приложения за счет кэширования и разделения кода"],"ar":["تحسين استرجاع البيانات لتحسين تحميل الصفحات","تنفيذ التحقق من صحة الإدخال الآمن باستخدام Zod","تحسين أداء التطبيق من خلال التخزين المؤقت وتقسيم الشفرة"]},"limitations":{"en":["Requires Next.js environment","Wrapping `useSearchParams()` in a Suspense boundary for compatibility"],"zh":["需要Next.js环境","需要将`useSearchParams()`包裹在Suspense边界中以实现兼容性"],"ja":["Next.js環境が必要","互換性のために`useSearchParams()`をSuspense境界でラップする必要がある"],"ko":["Next.js 환경이 필요합니다.","호환성을 위해 `useSearchParams()`를 Suspense 경계로 감싸야 합니다."],"es":["Requiere un entorno Next.js","Envolver `useSearchParams()` en un límite de Suspense para la compatibilidad"],"fr":["Nécessite un environnement Next.js","Envelopper `useSearchParams()` dans une limite de Suspense pour la compatibilité"],"de":["Benötigt eine Next.js-Umgebung","Umhüllen von `useSearchParams()` in eine Suspense-Grenze für die Kompatibilität"],"pt":["Requer ambiente Next.js","Envolvendo `useSearchParams()` em uma fronteira de Suspense para compatibilidade"],"ru":["Требуется среда Next.js","Обертывание `useSearchParams()` в границу Suspense для совместимости"],"ar":["يتطلب بيئة Next.js","التغليف `useSearchParams()` في حدود التوقّف للتوافق"]},"version":4},"cont