INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Sherloock/LoopTimer/nextjs-app-router-data-fetching', 'nextjs-app-router-data-fetching', 'Sherloock', 'LoopTimer', 'community', 'nextjs-app-router-data-fetching Sherloock LoopTimer community The nextjs-app-router-data-fetching skill optimizes data fetching in Next.js applications, benefiting developers who need to improve performance. It provides guidelines for route handlers, input validation, and caching. Next.js 应用路由数据获取是一个高效的数据获取解决方案，通过路由处理、输入验证和缓存优化来提高应用性能 Next.js アプリルーターデータ取得は、高性能なデータ取得ソリューションです。ルーティングハンドラー、入力検証、キャッシング最適化などを通じて、アプリケーションのパフォーマンスを向上させます Next.js 애플리케이션 라우터 데이터 패칭은 효율적인 데이터 패칭 솔루션으로, 라우팅 핸들러, 입력 검증, 캐싱 최적화를 통해 애플리케이션 성능을 향상시킵니다 nextjs-app-router-data-fetching es una técnica para optimizar la obtención de datos en aplicaciones Next.js, utilizando validación de entradas con Zod y caché para mejorar el rendimiento nextjs-app-router-data-fetching est une technique pour optimiser la récupération de données dans les applications Next.js, en utilisant la validation des entrées avec Zod et la mise en cache pour améliorer les performances nextjs-app-router-data-fetching ist eine Technik zur Optimierung der Datenerfassung in Next.js-Anwendungen, bei der die Eingabvalidierung mit Zod und Caching zum Performance-Boost eingesetzt werden O Next.js App Router Data Fetching é uma técnica para melhorar o desempenho da sua aplicação, utilizando código split e validação de entradas Next.js App Router Data Fetching - это техника для улучшения производительности вашего приложения, используя код-сплит и валидацию входных данных Next.js App Router Data Fetching هو تقنية لتحسين أداء تطبيقك، باستخدام تقسيم الكود و التحقق من المدخلات how to use nextjs-app-router-data-fetching nextjs-app-router-data-fetching setup guide nextjs-app-router-data-fetching vs react-query what is nextjs-app-router-data-fetching nextjs-app-router-data-fetching install nextjs-app-router-data-fetching alternative nextjs-app-router-data-fetching best practices nextjs-app-router-data-fetching performance optimization nextjs-app-router-data-fetching caching strategies Next.js 应用路由数据获取 路由处理 输入验证 缓存优化 性能优化 Suspense 边界 AIエージェント Next.js 开发 前端开发 Uses Zod for input validation and server-side authentication Employs code splitting via next/dynamic for non-critical UI components Utilizes Suspense boundaries with useSearchParams() for efficient data fetching Prefer minimal payloads to avoid over-fetching Keeps client components lean by moving heavy work server-side Enforces authentication and validation for route handlers in app/apiroute.ts nextjs-app-router-data-fetching is a skill that provides best practices for optimizing data fetching in Next.js applications using techniques like code splitting and Suspense boundaries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sperezintexas/fintech-app/ci-failure', 'community', 'sperezintexas', 'fintech-app', 'sperezintexas/fintech-app', 'ci-failure', 0, 0, 26, '2026-03-08T01:57:15.476Z', '2026-03-08T02:09:48.526Z', '4f588cf1db21a836e8b60ff91b6e0b90777d2235da223f1371dbbc7e20012f5a', '{"id":"sperezintexas/fintech-app/ci-failure","name":"ci-failure","description":{"en":"The ci-failure skill helps developers diagnose and resolve remote GitHub Actions CI failures by analyzing workflow files and pipeline summaries. It benefits developers working with GitHub Actions and CI pipelines.","zh":"CI 故障诊断技能帮助您快速识别和解决 GitHub Actions 远程 CI 失败问题，通过加载工作流和管道摘要文件","ja":"CI Failure スキルは、ワークフローとパイプラインのサマリー ファイルを読み込むことで、GitHub Actions のリモート CI 失敗を迅速に特定して解決します","ko":"CI 실패 진단 스킬은 워크플로 및 파이프라인 요약 파일을 로드하여 GitHub Actions의 원격 CI 실패를 신속하게 식별하고 해결합니다","es":"El agente de AI ''ci-failure'' ayuda a diagnosticar y resolver fallos de CI en GitHub Actions, utilizando archivos como .github/workflows/ci.yml","fr":"L''agent d''AI ''ci-failure'' aide à diagnostiquer et résoudre les échecs de CI dans GitHub Actions, en utilisant des fichiers tels que .github/workflows/ci.yml","de":"Der AI-Agent ''ci-failure'' hilft bei der Fehlerdiagnose und -behebung von CI-Fehlern in GitHub Actions, unter Verwendung von Dateien wie .github/workflows/ci.yml","pt":"O skill de falha de CI ajuda a diagnosticar e corrigir problemas de integração contínua, carregando arquivos de workflow e pipeline para identificar erros","ru":"Навык неисправности CI помогает диагностировать и исправлять проблемы непрерывной интеграции, загружая файлы рабочего процесса и конвейера для определения ошибок","ar":"مهارة فشل CI تساعد على تشخيص وأرقام إصلاح مشاكل التكامل المستمر، عن طريق تحميل ملفات سير العمل والأنابيب لتحديد الأخطاء"},"seo":{"title":{"en":"ci-failure: CI Failure Diagnosis Setup Guide | AI Age