INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sperezintexas/fintech-app/ci-failure', 'ci-failure', 'sperezintexas', 'fintech-app', 'community', 'ci-failure sperezintexas fintech-app community The ci-failure skill helps developers diagnose and resolve remote GitHub Actions CI failures by analyzing workflow files and pipeline summaries. It benefits developers working with GitHub Actions and CI pipelines. CI 故障诊断技能帮助您快速识别和解决 GitHub Actions 远程 CI 失败问题，通过加载工作流和管道摘要文件 CI Failure スキルは、ワークフローとパイプラインのサマリー ファイルを読み込むことで、GitHub Actions のリモート CI 失敗を迅速に特定して解決します CI 실패 진단 스킬은 워크플로 및 파이프라인 요약 파일을 로드하여 GitHub Actions의 원격 CI 실패를 신속하게 식별하고 해결합니다 El agente de AI ''ci-failure'' ayuda a diagnosticar y resolver fallos de CI en GitHub Actions, utilizando archivos como .github/workflows/ci.yml L''agent d''AI ''ci-failure'' aide à diagnostiquer et résoudre les échecs de CI dans GitHub Actions, en utilisant des fichiers tels que .github/workflows/ci.yml Der AI-Agent ''ci-failure'' hilft bei der Fehlerdiagnose und -behebung von CI-Fehlern in GitHub Actions, unter Verwendung von Dateien wie .github/workflows/ci.yml O skill de falha de CI ajuda a diagnosticar e corrigir problemas de integração contínua, carregando arquivos de workflow e pipeline para identificar erros Навык неисправности CI помогает диагностировать и исправлять проблемы непрерывной интеграции, загружая файлы рабочего процесса и конвейера для определения ошибок مهارة فشل CI تساعد على تشخيص وأرقام إصلاح مشاكل التكامل المستمر، عن طريق تحميل ملفات سير العمل والأنابيب لتحديد الأخطاء how to use ci-failure ci-failure setup guide github actions ci failure diagnosis ci-failure alternative ci-failure vs github actions troubleshooting ci failures ci failure analysis github workflow file analysis CI 故障诊断 GitHub Actions 持续集成 AI 技术 故障解决 CI 设置指南 AIエージェント 远程 CI 失败 Loads context from .github/workflows/ci.yml and .github/workflows/security.yml files Analyzes pipeline summaries from docs/ci.md to identify job and step issues Applies repo-specific fixes based on workflow and pipeline configurations Supports diagnosis of security-related CI failures Utilizes xAI to maximize profits in portfolio and options management ci-failure is a skill that assists in diagnosing and resolving CI failures in GitHub Actions by loading context from workflow files and pipeline summaries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shubhamtaywade82/repocontext/ruby-style', 'community', 'shubhamtaywade82', 'repocontext', 'shubhamtaywade82/repocontext', 'ruby-style', 0, 0, 26, '2026-03-08T01:57:15.477Z', '2026-03-08T02:09:51.888Z', 'f5067ec388dbdacc7a4584057eabcba5717ce9635d0b26634df47f2ff8cbb86c', '{"id":"shubhamtaywade82/repocontext/ruby-style","name":"ruby-style","description":{"en":"The ruby-style skill enforces the Ruby Style Guide for consistent and readable code, benefiting developers and teams working with Ruby. It applies guidelines for source code layout and style.","zh":"Ruby 风格指南是一套社区驱动的风格指南，用于提高 Ruby 代码的可读性和一致性。基于 RuboCop 和 Ruby Style Guide","ja":"Ruby スタイルガイドは、Ruby コードの可読性と一致性を高めるためのコミュニティ主導のスタイルガイドです。RuboCop と Ruby Style Guide に基づく","ko":"Ruby 스타일 가이드는 Ruby 코드의 가독성과 일관성을 높이는 위한 커뮤니티 주도 스타일 가이드입니다. RuboCop 및 Ruby Style Guide 기반","es":"El estilo de Ruby es una guía de estilo para programadores que busca mejorar la legibilidad y consistencia del código","fr":"Le style Ruby est un guide de style pour les programmeurs qui vise à améliorer la lisibilité et la cohérence du code","de":"Der Ruby-Style-Leitfaden ist ein Stilguide für Entwickler, der darauf abzielt, die Lesbarkeit und Konsistenz des Codes zu verbessern","pt":"O guia de estilo Ruby é uma ferramenta essencial para desenvolvedores que buscam melhorar a consistência e legibilidade do código","ru":"Руководство по стилю Ruby является необходимым инструментом для разработчиков, которые хотят повысить читаемость и последовательность кода","ar":"دليل أسلوب روبي هو أداة أساسية للمطورين الذين يريدون تحسين الاتساق وقراءة الكود"},"seo":{"title":{"en":"ruby-style: Code Consistency Setup Guide | AI Agent Skill","zh":"Ruby 风格指南 Setup Guide - AIエージェント工具","ja":"Ruby スタイルガイド Setup Guide - AIエージェント","ko":"Ruby 스타일 가이드 Setup Guide - AI 에이전트","es":"Guía de configuración para Ruby Style"