INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KiWi233333/JiwuChat/project-code-standards', 'project-code-standards', 'KiWi233333', 'JiwuChat', 'community', 'project-code-standards KiWi233333 JiwuChat community The project-code-standards skill provides a set of coding standards for AI agents, including guidelines for Vue components, ESLint, and Git rules, benefiting developers working on the JiwuChat project. 项目代码规范 Skill 定义了编码方式、Vue 组件、样式和 Commit 规范，帮助开发者提高代码质量 プロジェクトコード規約 Skill は、AIエージェントのためのコード規約を定義し、開発者の生産性を向上させる 프로젝트 코드 표준 Skill 은 코드 품질을 높이기 위한 규약을 정의하여 개발자에게 도움을 줍니다 Los estándares de código de proyecto definen la forma en que se estructura y escribe el código en un proyecto, incluyendo convenciones de nombramiento y estilo de codificación Les normes de code de projet définissent la façon dont le code est structuré et écrit dans un projet, y compris les conventions de nommage et le style de codage Die Projekt-Code-Standards definieren die Art und Weise, wie der Code in einem Projekt strukturiert und geschrieben wird, einschließlich Namenskonventionen und Codierungsstil O projeto-code-standards é um conjunto de diretrizes para padronizar o código do projeto, incluindo codificação, Vue e Git. Проект кодирования проекта - это набор руководств для стандартизации кода проекта, включая кодирование, Vue и Git. مشروع معاييرshiv код هو مجموعة من الإرشادات لتحسين معاييرshiv код المشروع، بما في ذلك كتابة الكود، Vue و Git how to use project-code-standards project-code-standards setup guide project-code-standards vs coding standards what is project-code-standards project-code-standards install project-code-standards alternative 项目代码规范 编码方式 Vue 组件 样式 Commit 规范 ESLint AI 代码审查 Enforces coding style consistency with ESLint Provides guidelines for Vue component development Defines naming conventions for files and functions Specifies Commit message formatting rules Supports Git rules for efficient version control project-code-standards is a set of guidelines for coding, naming, and commit conventions in the JiwuChat project repository.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BenWeatherall/vscode-python-ast-extension/ai-context-repository', 'community', 'BenWeatherall', 'vscode-python-ast-extension', 'BenWeatherall/vscode-python-ast-extension', 'ai-context-repository', 0, 0, 26, '2026-03-08T01:57:15.483Z', '2026-03-08T02:10:00.317Z', 'd1f2adbf83ab760de820f18ca614c503f5bdccb8379ec7c7eebae13f387f13e4', '{"id":"BenWeatherall/vscode-python-ast-extension/ai-context-repository","name":"ai-context-repository","description":{"en":"The ai-context-repository skill generates data and logic flow diagrams for Python projects, serving as a single source of truth for architecture and component layout. It benefits AI agent developers and Python project maintainers.","zh":"ai-context-repository是一个VSCode扩展，提供类似Unreal Engine的蓝图功能，用于Python项目的数据流和逻辑流程图","ja":"ai-context-repositoryは、Pythonプロジェクトのデータフローとロジックフローの図を作成するためのVSCode拡張機能です","ko":"ai-context-repository는 Python 프로젝트의 데이터 흐름과 로직 흐름을 시각화하는 VSCode 확장입니다","es":"ai-context-repository es una extensión de vscode que proporciona diagramas de flujo de datos y lógica para proyectos Python","fr":"ai-context-repository est une extension vscode qui fournit des diagrammes de flux de données et de logique pour les projets Python","de":"ai-context-repository ist eine vscode-Erweiterung, die Daten- und Logikflussdiagramme für Python-Projekte bereitstellt","pt":"O ai-context-repository é uma extensão do VSCode que fornece diagramas de fluxo de dados e lógica para projetos Python, semelhante aos Blueprints do Unreal Engine.","ru":"Ai-context-repository - это расширение VSCode, которое предоставляет диаграммы потока данных и логики для проектов Python, аналогичные Blueprints в Unreal Engine.","ar":"ai-context-repository هو امتداد VSCode يوفر مخططات تدفق البيانات والمنطق لأدوات Python، مشابهة لブルوبرينتس في Unreal Engine."},"seo":{"title":{"en":"ai-context-repository: Setup Guide for AI Agents | AI Age...","zh":"AIエージェント工具：ai-context-repository VSCode扩展设置指南","ja":"AIエージェント：ai-context-repositoryのVSCode拡張機能セットアップガイド","ko":"AI 에이전트 툴: ai-context-repository VSCode 확장 설정 가이드","es":"Guía de configuración de ai-context-repository para proye...","fr":"Guide de mise en place de ai-context-repository pour les ...","de":"Einrichtungsleitfaden für ai-context-repository in Python...","pt":"Guia de Configuração do ai-context-repository para Projet...","ru":"Настройка ai-context-repository для Проектов Python: Лучш...","ar":"دليل إعداد ai-context-repository لأدوات Python"},"description":{"en":"Discover how to leverage ai-context-repository for streamlined Python project architecture and data flow management - get started with our expert guide","zh":"了解ai-context-repository VSCode扩展的功能和优点，用于Python项目的数据流和逻辑流程图","ja":"ai-context-repositoryのVSCode拡張機能を使用して、Pythonプロジェクトのデータフローとロジックフローの図を作成する","ko":"ai-context-repository VSCode 확장을 사용하여 Python 프로젝트의 데이터 흐름과 로직 흐름을 시각화하는 방법","es":"Descubre cómo ai-context-repository mejora la visualización de flujos de datos en proyectos Python con su extensión de vscode","fr":"Découvrez comment ai-context-repository améliore la visualisation des flux de données dans les projets Python avec son extension vscode","de":"Erfahren Sie, wie ai-context-repository die Datenflussvisualisierung in Python-Projekten mit seiner vscode-Erweiterung verbessert","pt":"Aprenda a configurar o ai-context-repository, uma extensão do VSCode que fornece diagramas de fluxo de dados e lógica para projetos Python","ru":"Узнайте, как настроить ai-context-repository, расширение VSCode, которое предоставляет диаграммы потока данных и логики для проектов Python","ar":"تعرف على كيفية إعداد ai-context-repository، امتداد VSCode الذي يوفر مخططات تدفق البيانات والمنطق لأدوات Python"},"definition":{"en":"ai-context-repository is a vscode extension that provides data and logic flow diagrams similar to Unreal Engine''s Blueprints for Python projects, facilitating streamlined architecture and maintenance","zh":"ai-context-repository是一种VSCode扩展，用于创建和管理Python项目的数据流和逻辑流程图","ja":"ai-context-repositoryは、Pythonプロジェクトのデータフローとロジックフローの図を作成するためのツールです","ko":"ai-context-repository는 Python 프로젝트의 데이터 흐름과 로직 흐름을 시각화하는 도구입니다","es":"ai-context-repository es una herramienta de visualización de datos y lógica para proyectos Python","fr":"ai-context-repository est un outil de visualisation de données et de logique pour les projets Python","de":"ai-context-repository ist ein Tool für die Visualisierung von Daten und Logik in Python-Projekten","pt":"O que é ai-context-repository? É uma ferramenta que fornece diagramas de fluxo de dados e lógica para projetos Python.","ru":"Что такое ai-context-repository? Это инструмент, который предоставляет диаграммы потока данных и логики для проектов Python.","ar":"ما هو ai-context-repository؟ هو أداة توفر مخططات تدفق البيانات والمنطق لأدوات Python."},"features":{"en":["Generates and maintains docs/AI_CONTEXT/AI_CONTEXT_REPOSITORY.md as a single source of truth","Provides overall architecture and directory and component layout visualization","Illustrates data flow between services for enhanced understanding","Supports high-level extension points for customized integration","Enables linking from other AI_CONTEXT documents for structured documentation"],"zh":["提供类似Unreal Engine的蓝图功能","支持Python项目的数据流和逻辑流程图","集成VSCode扩展功能","支持多种数据流和逻辑流程图形状","提供单一的真实来源文档"],"ja":["Unreal Engineのブループリント機能を提供","Pythonプロジェクトのデータフローとロジックフローの図をサポート","VSCode拡張機能を統合","多種多様なデータフローとロジックフローの図形状をサポート","単一の真実の情報源ドキュメントを提供"],"ko":["언리얼 엔진의 블루프린트 기능 제공","파이썬 프로젝트의 데이터 흐름과 로직 흐름을 시각화","VSCode 확장 기능 통합","다양한 데이터 흐름과 로직 흐름의 그래프를 지원","단일의 사실 정보 원본 문서 제공"],"es":["Proporciona diagramas de flujo de datos y lógica similares a Unreal Engine''s Blueprints","Mejora la visualización de la arquitectura general del proyecto","Permite la visualización del flujo de datos entre servicios","Ofrece puntos de extensión de alto nivel","Se integra con vscode para una experiencia de desarrollo más eficiente"],"fr":["Fournit des diagrammes de flux de données et de logique similaires à Unreal Engine''s Blueprints","Améliore la visualisation de l''architecture générale du projet","Permet la visualisation du flux de données entre les services","Offre des points d''extension de haut niveau","Se integre avec vscode pour une expérience de développement plus efficace"],"de":["Bietet Daten- und Logikflussdiagramme ähnlich wie Unreal Engine''s Blueprints","Verbessert die Visualisierung der Gesamtarquitectur des Projekts","Ermöglicht die Visualisierung des Datenflusses zwischen Diensten","Bietet Erweiterungspunkte auf hohem Niveau","Integriert sich mit vscode für eine effizientere Entwicklungserfahrung"],"pt":["Fornece diagramas de fluxo de dados e lógica para projetos Python","Semelhante aos Blueprints do Unreal Engine","Permite a visualização da arquitetura do projeto","Facilita a manutenção e atualização do código","Integração com o VSCode"],"ru":["Предоставляет диаграммы потока данных и логики для проектов Python","Аналогичен Blueprints в Unreal Engine","Позволяет визуализировать архитектуру проекта","Облегчает обслуживание и обновление кода","Интегрируется с VSCode"],"ar":["توفر مخططات تدفق البيانات والمنطق لأدوات Python","مشابهة لブルوبرينتس في Unreal Engine","تمكن من تصور هيكل المشروع","تسهل صيانة وتحديث الشفرة","تتكامل مع VSCode"]},"keywords":{"en":["how to use ai-context-repository","ai-context-repository setup guide","ai-context-repository alternative","ai-context-repository vs Unreal Engine Blueprints","install ai-context-repository","ai-context-repository for Python projects","vscode extension for data flow diagrams","what is ai-context-repository","ai-context-repository documentation"],"zh":["AIエージェント工具","VSCode扩展","Python项目","数据流","逻辑流程图","Unreal Engine","蓝图功能"],"ja":["AIエージェント","VSCode拡張機能","Pythonプロジェクト","データフロー","ロジックフロー","Unreal Engine","ブループリント機能"],"ko":["AI 에이전트 툴","VSCode 확장","파이썬 프로젝트","데이터 흐름","로직 흐름","언리얼 엔진","블루프린트 기능"],"es":["ai-context-repository","herramientas de ai","visualización de datos","proyectos python","vscode extensiones","diagramas de flujo de datos","arquitectura de software","desarrollo de software"],"fr":["ai-context-repository","outils d''intelligence artificielle","visualisation de données","projets python","extensions vscode","diagrammes de flux de données","architecture logicielle","développement de logiciels"],"de":["ai-context-repository","künstliche intelligenz tools","datenvisualisierung","python-projekte","vscode-erweiterungen","datenflussdiagramme","software-architektur","software-entwicklung"],"pt":["ai-context-repository","VSCode","Python","diagramas de fluxo de dados","lógica de programação","Unreal Engine","Blueprints","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["ai-context-repository","VSCode","Python","диаграммы потока данных","логика программирования","Unreal Engine","Blueprints","инструменты разработки","разработка программного обеспечения","ИИ Агенты"],"ar":["ai-context-repository","VSCode","Python","مخططات تدفق البيانات","منطق البرمجة","Unreal Engine","ブルーبرインツ","أدوات التطوير","تطوير البرمجيات","أدوات ذكاء اصطناعي"]}},"owner":"BenWeatherall","repo":"vscode-python-ast-extension","repoPath":"BenWeatherall/vscode-python-ast-extension","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.483Z","topics":[],"category":"community","skillMd":{"name":"ai-context-repository","description":"Guides the ai-context-writer subagent in maintaining AI_CONTEXT_REPOSITORY.md, documenting repository architecture, directory structure, component responsibilities, data flow, and extension points for the python-vis project. Use when creating or updating the repository AI context file.","bodyPreview":"# AI Context Repository Skill\r\n\r\n## Purpose\r\n\r\nHelp the `ai-context-writer` subagent generate and maintain `docs/AI_CONTEXT/AI_CONTEXT_REPOSITORY.md` as the **single source of truth** for:\r\n\r\n- Overall architecture\r\n- Directory and component layout\r\n- Data flow between services\r\n- High-level extension points\r\n\r\nOther AI_CONTEXT documents (patterns, component-specific docs) should link back here for structure.\r\n\r\n## Sources to Read\r\n\r\nBefore updating the repository document, read (as appropriate)","body":"# AI Context Repository Skill\r\n\r\n## Purpose\r\n\r\nHelp the `ai-context-writer` subagent generate and maintain `docs/AI_CONTEXT/AI_CONTEXT_REPOSITORY.md` as the **single source of truth** for:\r\n\r\n- Overall architecture\r\n- Directory and component layout\r\n- Data flow between services\r\n- High-level extension points\r\n\r\nOther AI_CONTEXT documents (patterns, component-specific docs) should link back here for structure.\r\n\r\n## Sources to Read\r\n\r\nBefore updating the repository document, read (as appropriate):\r\n\r\n- `@README.md` — project purpose and high-level goals\r\n- `@python_service/` — parser, models, server entry point\r\n- `@src/` — extension host, commands, integration logic\r\n- `@webview-ui/` — React + Rete webview implementation\r\n- `@tests/` — to see where tests live\r\n- `@.cursor/rules/environment.mdc` — structure and tooling expectations\r\n- Existing `@docs/AI_CONTEXT/AI_CONTEXT_REPOSITORY.md` (if present)\r\n\r\n## Required Sections in AI_CONTEXT_REPOSITORY.md\r\n\r\nAt minimum, ensure the file contains:\r\n\r\n1. **Metadata**\r\n   - Version\r\n   - Last Updated (ISO date)\r\n   - Tags (include `architecture`, `repository`)\r\n   - Cross-References to quick reference, patterns, and component-specific AI_CONTEXT docs\r\n\r\n2. **High-Level Overview**\r\n   - Goal of the system in 1–2 paragraphs\r\n   - Summary of the sidecar architecture (Python service, extension host, webview UI)\r\n\r\n3. **Directory Structure**\r\n   - An annotated tree of the most important directories:\r\n     - `python_service/`\r\n     - `src/`\r\n     - `webview-ui/`\r\n     - `tests/`\r\n     - `.cursor/`\r\n     - `_features/` (and others if relevant)\r\n\r\n4. **Component Responsibilities**\r\n   - Subsections for each major component:\r\n     - Python service\r\n     - Extension host\r\n     - Webview UI\r\n   - For each: what it does, key modules, and main responsibilities.\r\n\r\n5. **Data Flow**\r\n   - End-to-end flow from VS Code editor → extension → Python service → webview → back to editor.\r\n   - Auto-refresh flow on save.\r\n   - Error and retry flow.\r\n   - At least one **mermaid diagram** illustrating the main happy path.\r\n\r\n6. **Service Boundaries & Dependencies**\r\n   - Clarify the boundaries between:\r\n     - Python process\r\n     - Node/extension host\r\n     - Webview/browser runtime\r\n   - List key external libraries and frameworks per component.\r\n\r\n7. **Entry Points & Extension Hooks**\r\n   - Python service entry (`python_service.__main__`, `ASTParseServer`).\r\n   - Extension activation (`extension.ts`, command registration).\r\n   - Webview bootstrap (`webview-ui/src/index.tsx` and `App.tsx`).\r\n   - Guidance on where to plug in:\r\n     - New AST node visitors\r\n     - New webview messages\r\n     - New VS Code commands\r\n\r\n## Style & Constraints\r\n\r\n- Keep the document **architectural**, not tutorial-style.\r\n- Use **semantic headings** and short paragraphs.\r\n- Prefer diagrams and structured lists over long prose.\r\n- Avoid management or roadmap content; focus purely on **how the system is structured today**.\r\n- Keep under the content length limit; if it grows too large:\r\n  - Split into sub-documents (e.g. `AI_CONTEXT_REPOSITORY/`) per `content_length` rules.\r\n  - Provide an index with links and one-line descriptions.\r\n\r\n## Update Strategy\r\n\r\nWhen the project structure or flow changes:\r\n\r\n1. Update the directory tree to match the real repository.\r\n2. Adjust component responsibilities and data flow descriptions.\r\n3. Refresh diagrams to reflect new paths or services.\r\n4. Bump version/last-updated metadata.\r\n5. Ensure cross-references to component-specific docs remain valid.\r\n\r\n"},"lastSynced":"2026-03-08T02:10:00.317Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing comprehensive architecture documentation and component layout visualization for Python projects.","zh":"非常适合需要全面架构文档和组件布局可视化的Python项目的AI代理。","ja":"Pythonプロジェクトの包括的なアーキテクチャドキュメントとコンポーネントレイアウトの視覚化が必要なAIエージェントに最適です。","ko":"파이썬 프로젝트에 대한 포괄적인 아키텍처 문서 및 구성 요소 레이아웃 시각화를 필요로 하는 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan documentación de arquitectura integral y visualización de diseño de componentes para proyectos de Python.","fr":"Parfait pour les agents d''IA nécessitant une documentation d''architecture complète et une visualisation de la disposition des composants pour les projets Python.","de":"Perfekt für KI-Agenten, die eine umfassende Architekturdokumentation und eine Visualisierung der Komponentenlayout für Python-Projekte benötigen.","pt":"Perfeito para Agentes de IA que necessitam de documentação de arquitetura abrangente e visualização de layout de componentes para projetos Python.","ru":"Идеально для агентов ИИ, которым требуется комплексная документация архитектуры и визуализация компонентов для проектов Python.","ar":"مثالي لعمليات 智能 الإيجاد التي تحتاج إلى توثيق هيكلي شامل وتصوير تخطيطي لمكونات مشاريع Python."},"recommendation":{"en":"Empowers agents to generate and maintain data and logic flow diagrams, serving as a single source of truth for overall architecture, directory and component layout, and high-level extension points, utilizing Markdown documentation and linking to other AI_CONTEXT documents.","zh":"赋予代理生成和维护数据和逻辑流程图的能力，作为整个架构、目录和组件布局以及高级扩展点的单一真实来源，利用Markdown文档并链接到其他AI_CONTEXT文档。","ja":"エージェントがデータフロー図とロジックフロー図を生成して維持することができ、全体のアーキテクチャ、ディレクトリ、コンポーネントレイアウト、および高レベルの拡張ポイントの単一の真実の情報源となるようにします。Markdownドキュメントを利用し、他のAI_CONTEXTドキュメントにリンクします。","ko":"에이전트가 데이터 흐름図와 논리 흐름도를 생성하고 유지할 수 있도록 하여 전체 아키텍처, 디렉토리 및 구성 요소 레이아웃 및 고급 확장 지점에 대한 단일 사실의 원천 역할을 하며, 마크다운 문서를 사용하고 다른 AI_CONTEXT 문서에 연결합니다.","es":"Habilita a los agentes a generar y mantener diagramas de flujo de datos y lógica, sirviendo como una única fuente de verdad para la arquitectura general, el directorio y el diseño de componentes, y los puntos de extensión de alto nivel, utilizando la documentación de Markdown y enlazando con otros documentos de AI_CONTEXT.","fr":"Permet aux agents de générer et de maintenir des diagrammes de flux de données et de logique, servant de source unique de vérité pour l''architecture globale, le répertoire et la disposition des composants, et les points d''extension de haut niveau, en utilisant la documentation Markdown et en faisant des liens vers d''autres documents d''AI_CONTEXT.","de":"Ermöglicht es den Agenten, Daten- und Logikflussdiagramme zu generieren und zu warten, die als einzige Quelle der Wahrheit für die allgemeine Architektur, das Verzeichnis und die Komponentenlayout sowie die Erweiterungspunkte auf hohem Niveau dienen, wobei die Markdown-Dokumentation verwendet und auf andere AI_CONTEXT-Dokumente verlinkt wird.","pt":"Habilita os agentes a gerarem e manterem diagramas de fluxo de dados e lógica, servindo como uma única fonte de verdade para a arquitetura geral, diretório e layout de componentes e pontos de extensão de alto nível, utilizando documentação Markdown e linkando para outros documentos AI_CONTEXT.","ru":"Позволяет агентам генерировать и поддерживать диаграммы потока данных и логических связей, служа единственным источником информации для общей архитектуры, директории и компонентного расположения, а также высокоуровневых точек расширения, используя документацию Markdown и ссылки на другие документы AI_CONTEXT.","ar":"تمكّن العمليات من إنشاء وتنظيم مخططات تدفق البيانات ومنطق التشغيل، وتوفير مصدر وحيد للمعلومات حول الهيكل العام والمجلدات وترتيب المكونات ونقاط التوسيع عالية المستوى، وذلك باستخدام توثيق Markdown وربطها بالوثائق الأخرى AI_CONTEXT."},"useCases":{"en":["Generating data flow diagrams for Python services","Maintaining a single source of truth for architecture documentation","Creating high-level extension points for AI agent developers"],"zh":["为Python服务生成数据流程图","维护架构文档的单一真实来源","为AI代理开发人员创建高级扩展点"],"ja":["Pythonサービスのデータフロー図を生成する","アーキテクチャドキュメントの単一の真実の情報源を維持する","AIエージェント開発者のための高レベルの拡張ポイントを作成する"],"ko":["파이썬 서비스에 대한 데이터 흐름図 생성","아키텍처 문서의 단일 사실의 원천 유지","AI 에이전트 개발자를 위한 고급 확장 지점 생성"],"es":["Generar diagramas de flujo de datos para servicios de Python","Mantener una única fuente de verdad para la documentación de la arquitectura","Crear puntos de extensión de alto nivel para los desarrolladores de agentes de IA"],"fr":["Générer des diagrammes de flux de données pour les services Python","Maintenir une source unique de vérité pour la documentation d''architecture","Créer des points d''extension de haut niveau pour les développeurs d''agents d''IA"],"de":["Generieren von Datenflussdiagrammen für Python-Dienste","Warten einer einzigen Quelle der Wahrheit für die Architekturdokumentation","Erstellen von Erweiterungspunkten auf hohem Niveau für KI-Agenten-Entwickler"],"pt":["Gerar diagramas de fluxo de dados para serviços Python","Manter uma única fonte de verdade para documentação de arquitetura","Criar pontos de extensão de alto nível para desenvolvedores de agentes de IA"],"ru":["Генерировать диаграммы потока данных для сервисов Python","Поддерживать единственный источник информации для документации архитектуры","Создавать высокоуровневые точки расширения для разработчиков агентов ИИ"],"ar":["إنشاء مخططات تدفق البيانات لمشاريع Python","الحفاظ على مصدر وحيد للمعلومات حول توثيق الهيكل","إنشاء نقاط توسيع عالية المستوى لمطوري عمليات الذكاء الإصطناعي"]},"limitations":{"en":["Requires Python project setup","Limited to generating documentation for Python projects","Needs access to project directory structure"],"zh":["需要Python项目设置","仅限生成Python项目文档","需要访问项目目录结构"],"ja":["Pythonプロジェクトの設定が必要","Pythonプロジェクトのドキュメントの生成のみ","プロジェクトディレクトリ構造へのアクセスが必要"],"ko":["파이썬 프로젝트 설정이 필요","파이썬 프로젝트 문서의 생성만 가능","프로젝트 디렉토리 구조에 대한 액세스가 필요"],"es":["Requiere la configuración del proyecto de Python","Limitado a la generación de documentación para proyectos de Python","Necesita acceso a la estructura del directorio del proyecto"],"fr":["Nécessite la configuration du projet Python","Limité à la génération de documentation pour les projets Python","A besoin d''un accès à la structure du répertoire du projet"],"de":["Benötigt die Einrichtung des Python-Projekts","Begrenzt auf die Generierung von Dokumentationen für Python-Projekte","Benötigt den Zugriff auf die Verzeichnisstruktur des Projekts"],"pt":["Requer configuração de projeto Python","Limitado a gerar documentação para projetos Python","Necessita acesso à estrutura de diretório do projeto"],"ru":["Требует настройки проекта Python","Ограничен генерацией документации только для проектов Python","Требует доступа к структуре директории проекта"],"ar":["يتطلب إعداد مشروع Python","محدود بإنتاج توثيق لمشاريع Python فقط","يحتاج إلى الوصول إلى هيكل المجلدات للمشروع"]},"version":4},"contentHash":"d1f2adbf83ab760de820f18ca614c503f5bdccb8379ec7c7eebae13f387f13e4","qualityScore":26}');
