INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BenWeatherall/vscode-python-ast-extension/ai-context-repository', 'ai-context-repository', 'BenWeatherall', 'vscode-python-ast-extension', 'community', 'ai-context-repository BenWeatherall vscode-python-ast-extension community The ai-context-repository skill generates data and logic flow diagrams for Python projects, serving as a single source of truth for architecture and component layout. It benefits AI agent developers and Python project maintainers. ai-context-repository是一个VSCode扩展，提供类似Unreal Engine的蓝图功能，用于Python项目的数据流和逻辑流程图 ai-context-repositoryは、Pythonプロジェクトのデータフローとロジックフローの図を作成するためのVSCode拡張機能です ai-context-repository는 Python 프로젝트의 데이터 흐름과 로직 흐름을 시각화하는 VSCode 확장입니다 ai-context-repository es una extensión de vscode que proporciona diagramas de flujo de datos y lógica para proyectos Python ai-context-repository est une extension vscode qui fournit des diagrammes de flux de données et de logique pour les projets Python ai-context-repository ist eine vscode-Erweiterung, die Daten- und Logikflussdiagramme für Python-Projekte bereitstellt O ai-context-repository é uma extensão do VSCode que fornece diagramas de fluxo de dados e lógica para projetos Python, semelhante aos Blueprints do Unreal Engine. Ai-context-repository - это расширение VSCode, которое предоставляет диаграммы потока данных и логики для проектов Python, аналогичные Blueprints в Unreal Engine. ai-context-repository هو امتداد VSCode يوفر مخططات تدفق البيانات والمنطق لأدوات Python، مشابهة لブルوبرينتس في Unreal Engine. how to use ai-context-repository ai-context-repository setup guide ai-context-repository alternative ai-context-repository vs Unreal Engine Blueprints install ai-context-repository ai-context-repository for Python projects vscode extension for data flow diagrams what is ai-context-repository ai-context-repository documentation AIエージェント工具 VSCode扩展 Python项目 数据流 逻辑流程图 Unreal Engine 蓝图功能 Generates and maintains docs/AI_CONTEXT/AI_CONTEXT_REPOSITORY.md as a single source of truth Provides overall architecture and directory and component layout visualization Illustrates data flow between services for enhanced understanding Supports high-level extension points for customized integration Enables linking from other AI_CONTEXT documents for structured documentation ai-context-repository is a vscode extension that provides data and logic flow diagrams similar to Unreal Engine''s Blueprints for Python projects, facilitating streamlined architecture and maintenance');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marcusvbda/marcusvbda/performance', 'community', 'marcusvbda', 'marcusvbda', 'marcusvbda/marcusvbda', 'performance', 0, 0, 26, '2026-03-08T01:57:15.495Z', '2026-03-08T02:10:12.772Z', '07f3b5f40e50412b9c4b17f2dbad25a757e030e8e059ef19c8d63b04a54f0d23', '{"id":"marcusvbda/marcusvbda/performance","name":"performance","description":{"en":"The performance skill enables developers to design scalable layers for predictable load handling, utilizing async processing and event-driven architecture. It benefits developers building high-performance applications.","zh":"性能是首要关注点，所有层必须设计为在负载下可预测地扩展","ja":"パフォーマンスは第一の関心事である。すべてのレイヤーは負荷下で予測可能にスケールするように設計する必要がある","ko":"성능은 첫 번째 우선순위입니다. 모든 레이어는 로드 하에서 예측 가능한 확장성을 갖도록 설계해야 합니다","es":"El rendimiento es una preocupación de primera clase para los agentes de inteligencia artificial, con tecnologías como socket.io y QStash para async y event processing.","fr":"Les performances sont une préoccupation de première classe pour les agents d''IA, avec des technologies comme socket.io et QStash pour le traitement async et d''événements.","de":"Die Leistung ist ein vorrangiges Anliegen für KI-Agents, mit Technologien wie socket.io und QStash für Async- und Ereignisverarbeitung.","pt":"O desempenho é uma preocupação fundamental. Aprenda a configurar o desempenho das suas aplicações com técnicas de processamento assíncrono","ru":"Производительность является первоочередной задачей. Узнайте, как настроить производительность ваших приложений с помощью асинхронной обработки","ar":"الأداء هو مصدر قلق رئيسي. تعرف على كيفية تحسين أداء تطبيقاتك باستخدام تقنيات المعالجة غير المتزامنة"},"seo":{"title":{"en":"Performance: Async Processing Setup Guide | AI Agent Skill","zh":"性能优化指南：提高AI工具性能","ja":"パフォーマンスのチューニング：AIエージェントの最適化","ko":"성능 최적화 가이드: AI 툴의 성능 향상","es":"Guía de configuración de rendimiento para agentes de inte...","fr":"Guide de mise en place des performances pour les agents d''IA","de":"Leitfaden für die Leistungsoptimierung von KI-Agents","pt":"Otimização de Desempenho: Guia de Configuração para Ferra...","ru":"Настройка производительности ИИ Агентов: Лучшие практики","ar":"تحسين الأداء لعمليات إدارة الوكلاء الذكية: دليل الإعداد"},"description":{"en":"Unlock scalable performance with async processing! Learn how to design layers for predictable load handling and explore socket.io, Pusher, and QStash for rea...","zh":"了解如何优化AI工具的性能，包括异步处理和事件驱动架构","ja":"AIエージェントのパフォーマンスを最適化する方法を学習し、非同期処理とイベントドリブンアーキテクチャを実装する","ko":"AI 툴의 성능을 최적화하는 방법에 대해 알아보고, 비동기 처리와 이벤트 驱动 아키텍처를 구현하세요","es":"Mejora el rendimiento de tus agentes de inteligencia artificial con nuestra guía de configuración y mejores prácticas para async y event processing","fr":"Améliorez les performances de vos agents d''IA grâce à notre guide de configuration et de meilleures pratiques pour le traitement async et d''événements","de":"Verbessern Sie die Leistung Ihrer KI-Agents mit unserem Konfigurationsleitfaden und Best Practices für Async- und Ereignisverarbeitung","pt":"Aprenda a configurar o desempenho das suas Ferramentas de IA com socket.io, Pusher e QStash para uma comunicação em tempo real e processamento em segundo pla...","ru":"Узнайте, как настроить производительность ИИ Агентов с использованием socket.io, Pusher и QStash для эффективной реализации коммуникации в реальном времени и...","ar":"تعرف على كيفية تحسين أداء عمليات إدارة الوكلاء الذكية باستخدام socket.io و Pusher و QStash للاتصالات في الوقت الفعلي والمعالجة في الخلفية الفعالة"},"definition":{"en":"Performance is a first-class concern in software development, referring to the ability of an application to scale predictably under load, using technologies like socket.io and QStash.","zh":"性能优化是指通过异步处理和事件驱动架构来提高AI工具的响应速度和吞吐量","ja":"パフォーマンス最適化とは、非同期処理とイベントドリブンアーキテクチャを通じてAIエージェントのレスポンス速度とスループットを向上させること","ko":"성능 최적화는 비동기 처리와 이벤트 驱动 아키텍처를 통해 AI 툴의 응답 속도와 처리량을 향상시키는 것을 의미합니다","es":"El rendimiento se refiere a la capacidad de un agente de inteligencia artificial para procesar información de manera eficiente y escalable.","fr":"Les performances font référence à la capacité d''un agent d''IA à traiter les informations de manière efficace et évolutives.","de":"Die Leistung bezieht sich auf die Fähigkeit eines KI-Agents, Informationen effizient und skalierbar zu verarbeiten.","pt":"O desempenho refere-se à capacidade de uma aplicação de lidar com cargas de trabalho pesadas de forma eficaz","ru":"Производительность относится к способности приложения эффективно обрабатывать интенсивные рабочие нагрузки","ar":"الأداء يعتبر القدرة على معالجة الحمل الزائد بطريقة فعالة"},"features":{"en":["Utilizes socket.io for real-time communication","Leverages Pusher for external or third-party messaging","Employs QStash for background and long-running jobs","Ensures HTTP requests never block on long-running tasks","Enforces idempotent and retry-safe background jobs","Explicitly handles async processing for observability"],"zh":["使用socket.io进行实时通信","利用Pusher进行外部或第三方消息传递","使用QStash进行后台和长时间运行的任务","实现异步处理和事件驱动架构","确保HTTP请求不会阻塞长时间运行的任务","实现所有后台任务的幂等性和重试安全性"],"ja":["socket.ioを使用したリアルタイム通信","Pusherを使用した外部または第三者メッセージング","QStashを使用したバックグラウンドと長時間実行ジョブ","非同期処理とイベントドリブンアーキテクチャの実装","HTTPリクエストが長時間実行タスクをブロックしないことを確認","すべてのバックグラウンドジョブの冪等性とリトライ安全性の実装"],"ko":["socket.io를 사용한 실시간 통신","Pusher를 사용한 외부 또는 제3자 메시징","QStash를 사용한 백그라운드 및 장기간 실행 작업","비동기 처리 및 이벤트 驱动 아키텍처의 구현","HTTP 요청이 장기간 실행 작업을 블록하지 않는 것을 확인","모든 백그라운드 작업의 멱등성 및 재시도 안전성의 구현"],"es":["Uso de socket.io para la comunicación en tiempo real","Integración con Pusher para mensajería externa","Implementación de QStash para trabajos en segundo plano y tareas de larga duración","Procesamiento async explícito y observable","Trabajos en segundo plano idempotentes y seguros para reintento"],"fr":["Utilisation de socket.io pour la communication en temps réel","Intégration avec Pusher pour la messagerie externe","Mise en œuvre de QStash pour les tâches en arrière-plan et les tâches à long terme","Traitement async explicite et observable","Tâches en arrière-plan idempotentes et sécurisées pour la reprise"],"de":["Verwendung von socket.io für Echtzeitkommunikation","Integration mit Pusher für externe Messaging","Implementierung von QStash für Hintergrund- und Langzeitjobs","Explizite und beobachtbare Async-Verarbeitung","Hintergrundjobs idempotent und sicher für Wiederholung"],"pt":["Utilização de socket.io para comunicação em tempo real","Integração com Pusher para mensagens externas ou de terceiros","Uso de QStash para trabalhos em segundo plano e de longa duração","Processamento assíncrono explícito e observável","Trabalhos em segundo plano idempotentes e seguros para repetição"],"ru":["Использование socket.io для коммуникации в реальном времени","Интеграция с Pusher для внешних или третьих сообщений","Использование QStash для фоновых и долгосрочных задач","Явная и наблюдаемая асинхронная обработка","Идемпотентные и безопасные для повторения фоновые задачи"],"ar":["استخدام socket.io للاتصالات في الوقت الفعلي","التكامل مع Pusher للرسائل الخارجية أو لطرف ثالث","استخدام QStash للعمليات في الخلفية والطويلة الأمد","المعالجة غير المتزامنة الصريحة والمُرَاقَبَة","المهام الخلفية المتطابقة وآمنة للتكرار"]},"keywords":{"en":["how to use performance in AI agents","what is performance in software development","performance vs scalability","performance alternative to synchronous processing","performance setup guide for developers","installing performance optimization tools","async processing best practices"],"zh":["AI工具性能优化","异步处理","事件驱动架构","socket.io","Pusher","QStash","性能优化指南","AI工具开发","实时通信"],"ja":["AIエージェントパフォーマンス最適化","非同期処理","イベントドリブンアーキテクチャ","socket.io","Pusher","QStash","パフォーマンスチューニングガイド","AIエージェント開発","リアルタイム通信"],"ko":["AI 툴 성능 최적화","비동기 처리","이벤트 驱动 아키텍처","socket.io","Pusher","QStash","성능 최적화 가이드","AI 툴 개발","실시간 통신"],"es":["rendimiento de agentes de inteligencia artificial","configuración de async","event processing","socket.io","QStash","Pusher","desarrollo de agentes de IA","optimización de rendimiento","tecnologías de inteligencia artificial"],"fr":["performances des agents d''IA","configuration async","traitement d''événements","socket.io","QStash","Pusher","développement d''agents d''IA","optimisation des performances","technologies d''intelligence artificielle"],"de":["Leistung von KI-Agents","Konfiguration von Async","Ereignisverarbeitung","socket.io","QStash","Pusher","Entwicklung von KI-Agents","Leistungsoptimierung","Künstliche-Intelligenz-Technologien"],"pt":["otimização de desempenho","ferramentas de ia","processamento assíncrono","socket.io","Pusher","QStash","desenvolvimento de aplicações","tecnologias de ia"],"ru":["настройка производительности","ии агенты","асинхронная обработка","socket.io","Pusher","QStash","разработка приложений","технологии ии"],"ar":["تحسين الأداء","أدوات ذكية","معالجة غير متزامنة","socket.io","Pusher","QStash","تطوير التطبيقات","تكنولوجيا ذكية"]}},"owner":"marcusvbda","repo":"marcusvbda","repoPath":"marcusvbda/marcusvbda","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.495Z","topics":[],"category":"community","skillMd":{"name":"performance","description":"Defines performance constraints for frontend rendering, backend execution, async processing, and database access. Use when implementing async jobs, caching, or optimizing performance.","bodyPreview":"# Performance & Async Processing\n\nPerformance is a **first-class concern**.\nAll layers must be designed to scale predictably under load.\n\n---\n\n## Async & Event Processing\n\n### Stack\n\n- socket.io for real-time communication\n- Pusher for external or third-party messaging\n- QStash for background and long-running jobs\n\n---\n\n### Core Async Rules\n\n- HTTP requests must never block on long-running tasks\n- All background jobs must be idempotent and retry-safe\n- Async processing must be explicit and obser","body":"# Performance & Async Processing\n\nPerformance is a **first-class concern**.\nAll layers must be designed to scale predictably under load.\n\n---\n\n## Async & Event Processing\n\n### Stack\n\n- socket.io for real-time communication\n- Pusher for external or third-party messaging\n- QStash for background and long-running jobs\n\n---\n\n### Core Async Rules\n\n- HTTP requests must never block on long-running tasks\n- All background jobs must be idempotent and retry-safe\n- Async processing must be explicit and observable\n\nRules:\n\n- Fire-and-forget without tracking is forbidden\n- Job retries must be bounded\n- Side effects must be idempotent\n\n---\n\n## Job Execution\n\n- Jobs must have a single responsibility\n- Job input must be validated\n- Jobs must tolerate duplicate execution\n\nRules:\n\n- No shared mutable state\n- No reliance on execution order\n- Job failures must be detectable and recoverable\n\n---\n\n## Shared Clients\n\n- External clients must be instantiated in `/lib`\n- Clients must be reused where possible\n- Client configuration must be explicit\n\nRules:\n\n- No per-request client instantiation\n- No hidden global state\n\n---\n\n## Backend Performance\n\n- Minimize cold starts\n- Cache aggressively where safe\n- Avoid synchronous heavy work in request lifecycle\n\nRules:\n\n- No blocking IO in request handlers\n- CPU-heavy work must be offloaded\n- Cache invalidation must be explicit\n\n---\n\n## Frontend Performance\n\n- Reduce JavaScript bundle size\n- Avoid unnecessary hydration\n- Prefer Server Components\n- Measure Core Web Vitals continuously\n\nRules:\n\n- No client components by default\n- No hydration for static or read-only content\n- Performance regressions block approval\n\n---\n\n## Caching Strategy\n\n- Cache only deterministic outputs\n- Cache invalidation must be explicit\n- No stale data without intent\n\nRules:\n\n- Prefer server-side caching\n- Client cache must be consistent with backend contracts\n\n---\n\n## Observability\n\n- Use structured logging\n- Prefer metrics over logs\n- Measure performance; never assume it\n\nRules:\n\n- Every async system must emit metrics\n- Latency and error rates must be trackable\n- Logs must be machine-readable\n\n---\n\n## Testing & Validation\n\n- Load-sensitive paths must be tested\n- Async retry behavior must be validated\n- Performance changes must be measurable\n\n---\n\n## Non-Negotiables\n\n- No blocking HTTP requests\n- No unbounded retries\n- No silent async failures\n- No performance assumptions\n\nPerformance issues are production bugs.\n"},"lastSynced":"2026-03-08T02:10:12.772Z","agentAnalysis":{"suitability":{"en":"Ideal for High-Performance Agents requiring scalable async processing and event-driven architecture for predictable load handling.","zh":"适用于需要可扩展的异步处理和事件驱动架构来处理可预测负载的高性能代理。","ja":"高パフォーマンスエージェントに適しており、予測可能な負荷処理のためのスケーラブルな非同期処理とイベント駆動型アーキテクチャを必要とする。","ko":"예측 가능한 로드 처리를 위한 확장 가능하고 비동기 처리 및 이벤트 주도 아키텍처가 필요한 고성능 에이전트에 적합합니다.","es":"Ideal para agentes de alto rendimiento que requieren procesamiento asíncrono escalable y arquitectura orientada a eventos para manejo de carga predecible.","fr":"Idéal pour les agents haute performance nécessitant un traitement asynchrone scalable et une architecture orientée événement pour une gestion de charge prévisible.","de":"Ideal für Hochleistungsagenten, die ein skalierbares asynchrone Verarbeitung und eine ereignisgesteuerte Architektur für eine vorhersehbare Lastverwaltung erfordern.","pt":"Ideal para Agentes de Alto Desempenho que exigem processamento assíncrono escalável e arquitetura orientada a eventos para manipulação de carga previsível.","ru":"Идеально для агентов с высокими производительными характеристиками, требующих масштабируемой асинхронной обработки и событийно-ориентированной архитектуры для предсказуемого обработки нагрузки.","ar":"متوافق تمامًا مع وكلاء الأداء العالي الذين يتطلبون معالجة غير متزامنة قابلة للتوسع وعمارة مدفوعة بالأحداث لتعامل الحمل المتوقع."},"recommendation":{"en":"Empowers agents to design scalable layers utilizing async processing with libraries like socket.io for real-time communication, Pusher for external messaging, and QStash for background jobs, ensuring predictable performance under load.","zh":"赋予代理设计使用类似 socket.io 的异步处理库进行实时通信、使用 Pusher 进行外部消息传递、使用 QStash 进行后台任务，确保在负载下的可预测性能。","ja":"ソケット.IO のようなライブラリを使用した非同期処理により、リアルタイム通信、プッシャーによる外部メッセージング、QStash によるバックグラウンドジョブを実現し、負荷下での予測可能なパフォーマンスを保証する。","ko":"socket.io와 같은 라이브러리를 사용한 비동기 처리를 통해 실시간 통신, 푸셔를 통한 외부 메시지 전달, QStash를 통한 백그라운드 작업을 구현하여 로드下的 예측 가능한 성능을 보장합니다.","es":"Permite a los agentes diseñar capas escalables utilizando el procesamiento asíncrono con bibliotecas como socket.io para la comunicación en tiempo real, Pusher para mensajería externa y QStash para trabajos en segundo plano, garantizando un rendimiento predecible bajo carga.","fr":"Permet aux agents de concevoir des couches scalables en utilisant le traitement asynchrone avec des bibliothèques comme socket.io pour la communication en temps réel, Pusher pour le messagisme externe et QStash pour les tâches en arrière-plan, assurant des performances prévisibles sous charge.","de":"Ermöglicht es den Agenten, skalierbare Schichten mit asynchroner Verarbeitung und Bibliotheken wie socket.io für Echtzeitkommunikation, Pusher für externe Messaging und QStash für Hintergrundaufgaben zu entwerfen, um eine vorhersehbare Leistung unter Last zu gewährleisten.","pt":"Habilita os agentes a projetarem camadas escaláveis utilizando processamento assíncrono com bibliotecas como socket.io para comunicação em tempo real, Pusher para mensagens externas e QStash para trabalhos em segundo plano, garantindo desempenho previsível sob carga.","ru":"Позволяет агентам проектировать масштабируемые слои, используя асинхронную обработку с библиотеками, такими как socket.io для реального времени, Pusher для внешней рассылки сообщений и QStash для заданий в фоновом режиме, обеспечивая предсказуемую производительность под нагрузкой.","ar":"تمكّن الوكلاء من تصميم طبقات قابلة للتوسع باستخدام المعالجة غير المتزامنة مع مكتبات مثل socket.io للاتصال في الوقت الفعلي و Pusher للرسائل الخارجية و QStash لوظائف الخلفية، مما يضمن أداءً متوقعًا تحت الحمل."},"useCases":{"en":["Designing scalable applications with async processing","Implementing event-driven architecture for real-time communication","Optimizing background jobs with QStash for improved performance"],"zh":["使用异步处理设计可扩展的应用程序","实现事件驱动架构以进行实时通信","使用 QStash 优化后台任务以提高性能"],"ja":["非同期処理を使用してスケーラブルなアプリケーションを設計する","イベント駆動型アーキテクチャを実装してリアルタイム通信を行う","QStash を使用してバックグラウンドジョブを最適化してパフォーマンスを向上させる"],"ko":["비동기 처리를 사용하여 확장 가능한 애플리케이션을 설계하는 것","이벤트 주도 아키텍처를 구현하여 실시간 통신을 수행하는 것","QStash를 사용하여 백그라운드 작업을 최적화하여 성능을 개선하는 것"],"es":["Diseñar aplicaciones escalables con procesamiento asíncrono","Implementar arquitectura orientada a eventos para la comunicación en tiempo real","Optimizar trabajos en segundo plano con QStash para mejorar el rendimiento"],"fr":["Concevoir des applications scalables avec un traitement asynchrone","Mettre en œuvre une architecture orientée événement pour la communication en temps réel","Optimiser les tâches en arrière-plan avec QStash pour améliorer les performances"],"de":["Entwerfen von skalierbaren Anwendungen mit asynchroner Verarbeitung","Implementierung einer ereignisgesteuerten Architektur für Echtzeitkommunikation","Optimieren von Hintergrundaufgaben mit QStash für verbesserte Leistung"],"pt":["Projetar aplicações escaláveis com processamento assíncrono","Implementar arquitetura orientada a eventos para comunicação em tempo real","Otimizar trabalhos em segundo plano com QStash para melhorar o desempenho"],"ru":["Проектирование масштабируемых приложений с асинхронной обработкой","Реализация событийно-ориентированной архитектуры для реального времени","Оптимизация заданий в фоновом режиме с помощью QStash для улучшения производительности"],"ar":["تصميم تطبيقات قابلة للتوسع مع معالجة غير متزامنة","تنفيذ بنية مدفوعة بالأحداث للاتصال في الوقت الفعلي","تحسين وظائف الخلفية مع QStash لتحسين الأداء"]},"limitations":{"en":["Requires explicit async processing implementation","Background jobs must be idempotent and retry-safe"],"zh":["需要显式的异步处理实现","后台任务必须是幂等的和重试安全的"],"ja":["非同期処理の明示的な実装が必要","バックグラウンドジョブは冪等的でリトライセーフである必要がある"],"ko":["비동기 처리의 명시적인 구현이 필요함","백그라운드 작업은 멱등적이고 재시도 안전해야 함"],"es":["Requiere implementación explícita de procesamiento asíncrono","Los trabajos en segundo plano deben ser idempotentes y seguros para reintento"],"fr":["Nécessite une mise en œuvre explicite du traitement asynchrone","Les tâches en arrière-plan doivent être idempotentes et sécurisées pour le réessai"],"de":["Erfordert explizite Implementierung der asynchronen Verarbeitung","Hintergrundaufgaben müssen idempotent und sicher für Wiederholung sein"],"pt":["Exige implementação explícita de processamento assíncrono","Trabalhos em segundo plano devem ser idempotentes e seguros para repetição"],"ru":["Требует явной реализации асинхронной обработки","Задания в фоновом режиме должны быть идемпотентными и безопасными для повторения"],"ar":["يتطلب تنفيذًا صريحًا للمعالجة غير المتزامنة","يجب أن تكون وظائف الخلفية متطابقة وقابلة للتكرار بأمان"]},"version":4},"contentHash":"07f3b5f40e50412b9c4b17f2dbad25a757e030e8e059ef19c8d63b04a54f0d23","qualityScore":26}');
