INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marcusvbda/marcusvbda/performance', 'performance', 'marcusvbda', 'marcusvbda', 'community', 'performance marcusvbda marcusvbda community The performance skill enables developers to design scalable layers for predictable load handling, utilizing async processing and event-driven architecture. It benefits developers building high-performance applications. 性能是首要关注点，所有层必须设计为在负载下可预测地扩展 パフォーマンスは第一の関心事である。すべてのレイヤーは負荷下で予測可能にスケールするように設計する必要がある 성능은 첫 번째 우선순위입니다. 모든 레이어는 로드 하에서 예측 가능한 확장성을 갖도록 설계해야 합니다 El rendimiento es una preocupación de primera clase para los agentes de inteligencia artificial, con tecnologías como socket.io y QStash para async y event processing. Les performances sont une préoccupation de première classe pour les agents d''IA, avec des technologies comme socket.io et QStash pour le traitement async et d''événements. Die Leistung ist ein vorrangiges Anliegen für KI-Agents, mit Technologien wie socket.io und QStash für Async- und Ereignisverarbeitung. O desempenho é uma preocupação fundamental. Aprenda a configurar o desempenho das suas aplicações com técnicas de processamento assíncrono Производительность является первоочередной задачей. Узнайте, как настроить производительность ваших приложений с помощью асинхронной обработки الأداء هو مصدر قلق رئيسي. تعرف على كيفية تحسين أداء تطبيقاتك باستخدام تقنيات المعالجة غير المتزامنة how to use performance in AI agents what is performance in software development performance vs scalability performance alternative to synchronous processing performance setup guide for developers installing performance optimization tools async processing best practices AI工具性能优化 异步处理 事件驱动架构 socket.io Pusher QStash 性能优化指南 AI工具开发 实时通信 Utilizes socket.io for real-time communication Leverages Pusher for external or third-party messaging Employs QStash for background and long-running jobs Ensures HTTP requests never block on long-running tasks Enforces idempotent and retry-safe background jobs Explicitly handles async processing for observability Performance is a first-class concern in software development, referring to the ability of an application to scale predictably under load, using technologies like socket.io and QStash.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MoniVibe/HeadlessRebuildTool/anviloop-nightly', 'community', 'MoniVibe', 'HeadlessRebuildTool', 'MoniVibe/HeadlessRebuildTool', 'anviloop-nightly', 0, 0, 26, '2026-03-08T01:57:15.497Z', '2026-03-08T02:10:14.047Z', '363e1bb827aa4dcb7c645fac9defca0a6010e27846ce7e91fbee254625e3feef', '{"id":"MoniVibe/HeadlessRebuildTool/anviloop-nightly","name":"anviloop-nightly","description":{"en":"anviloop-nightly automates nightly runs for developers, ensuring efficient disk space management and queue cleanup using PowerShell scripts and WSL runner. It benefits developers who need to optimize their nightly build processes.","zh":"anviloop-nightly 是一种用于夜间运行的自动化工具，包括磁盘门控、队列清理和守护进程设置","ja":"anviloop-nightly はナイトリーミング用の自動化ツールで、ディスク ゲート、キュークリーンアップ、デーモン設定を含みます","ko":"anviloop-nightly는夜间 실행을 위한 자동화 도구로, 디스크 게이트, 큐 클리닝 및 데몬 설정을 포함합니다","es":"anviloop-nightly es un protocolo de ejecución nocturna que utiliza PowerShell y WSL para automatizar tareas","fr":"anviloop-nightly est un protocole d''exécution nocturne qui utilise PowerShell et WSL pour automatiser des tâches","de":"anviloop-nightly ist ein Protokoll für Nachtliche Ausführungen, das PowerShell und WSL zur Automatisierung von Aufgaben verwendet","pt":"O Anviloop Nightly é uma solução para execuções noturnas automatizadas, com recursos como gate de disco e limpeza de fila","ru":"Anviloop Nightly - это решение для автоматизации ночных запусков, с функциями, такими как дисковый шлюз и очистка очереди","ar":"أنفيلوب الليلي هو حل للتشغيل الليلي التلقائي، مع ميزات مثل بوابة القرص وتنظيف الطابور"},"seo":{"title":{"en":"anviloop-nightly: Automated Nightly Run Setup Guide | AI ...","zh":"anviloop-nightly 设定指南：自动化夜间运行","ja":"anviloop-nightly セットアップガイド：自動化ナイトリーミング","ko":"anviloop-nightly 설정 가이드: 자동화된夜間 실행","es":"Guía de configuración para anviloop-nightly: automatizaci...","fr":"Guide de configuration pour anviloop-nightly: exécution n...","de":"Konfigurationsleitfaden für anviloop-nightly: Nachtliche ...","pt":"Guia de Configuração do Anviloop Nightly para Execuções N...","ru":"Настройка Anviloop Nightly: ИИ Агенты для Автоматизации","ar":"دليل إعداد أنفيلوب الليلي للتشغيل الليلي التلقائي"},"description":{"en":"Discover how to optimize your nightly runs with anviloop-nightly. Learn how to automate disk cleanup and queue management with PowerShell and WSL runner.","zh":"了解 anviloop-nightly 的技术细节，包括磁盘门控、队列清理和守护进程设置","ja":"anviloop-nightly の技術的詳細をご覧ください。ディスク ゲート、キュークリーンアップ、デーモン設定など","ko":"anviloop-nightly의 기술적 세부 사항을 알아보세요. 디스크 게이트, 큐 클리닝 및 데몬 설정 등","es":"Aprende a configurar anviloop-nightly para ejecuciones automáticas nocturnas con PowerShell y WSL","fr":"Découvrez comment configurer anviloop-nightly pour les exécutions automatiques nocturnes avec PowerShell et WSL","de":"Erfahren Sie, wie Sie anviloop-nightly für automatisierte Nachtliche Ausführungen mit PowerShell und WSL konfigurieren","pt":"Aprenda a configurar o Anviloop Nightly para execuções noturnas automatizadas com gate de disco e limpeza de fila","ru":"Узнайте, как настроить Anviloop Nightly для автоматизации ночных запусков с помощью дискового шлюза и очистки очереди","ar":"تعرف على كيفية إعداد أنفيلوب الليلي للتشغيل الليلي التلقائي مع بوابة القرص وتنظيف الطابور"},"definition":{"en":"anviloop-nightly is a skill that automates nightly runs, performing disk gate checks and queue cleanup using PowerShell and WSL runner, ensuring efficient system resource management.","zh":"anviloop-nightly 是一种 AI 工具，用于自动化夜间运行","ja":"anviloop-nightly は、ナイトリーミングを自動化する AI エージェントです","ko":"anviloop-nightly는夜间 실행을 자동화하는 AI 에이전트입니다","es":"anviloop-nightly es un agente de inteligencia artificial que ejecuta tareas nocturnas con tecnologías como PowerShell y WSL","fr":"anviloop-nightly est un outil d''intelligence artificielle qui exécute des tâches nocturnes avec des technologies comme PowerShell et WSL","de":"anviloop-nightly ist ein KI-Tool, das Nachtliche Aufgaben mit Technologien wie PowerShell und WSL ausführt","pt":"O que é Anviloop Nightly? Uma ferramenta de automação para execuções noturnas","ru":"Что такое Anviloop Nightly? Инструмент для автоматизации ночных запусков","ar":"ما هو أنفيلوب الليلي؟ أداة للتشغيل الليلي التلقائي"},"features":{"en":["Performs disk gate checks using PowerShell command `pwsh -NoProfile -Command \"''C_free_GB='' + [math]::Round((Get-PSDrive C).Free/1GB,1)\"`","Automates queue cleanup with `cleanup_queue.ps1` script and WSL runner","Runs Intel ingest using `Po` command"," Stops builds if disk space falls below 40 GB","Retains last 3 builds per scenario for 7 days using `Polish/cleanup_queue.ps1` script"],"zh":["磁盘门控：停止构建当磁盘空间小于 40 GB","队列清理：使用 PowerShell 脚本清理队列","WSL 运行器：使用 WSL 运行器运行守护进程","Intel 消费：使用 Intel ingest 消费数据","自动化夜间运行：设置夜间运行的自动化流程"],"ja":["ディスク ゲート：40 GB 未満の場合ビルドを停止","キュークリーンアップ：PowerShell スクリプトを使用してキュークリーンアップ","WSL ランナー：WSL ランナーを使用してデーモンを実行","Intel インジェスト：Intel インジェストを使用してデータを消費","ナイトリーミングの自動化：ナイトリーミングの自動化フローを設定"],"ko":["디스크 게이트：40 GB 미만의 경우 빌드를 중지","큐 클리닝：PowerShell 스크립트를 사용하여 큐 클리닝","WSL 런너：WSL 런너를 사용하여 데몬 실행","Intel 인제스트：Intel 인제스트를 사용하여 데이터 소비","夜間 실행의 자동화：夜間 실행의 자동화 흐름을 설정"],"es":["Ejecución de comandos de PowerShell para limpieza de cola","Utilización de WSL para ejecutar tareas en un entorno de Linux","Configuración de umbrales de disco para detener ejecuciones","Limpieza de cola con script de PowerShell personalizado","Ejecución de tareas en segundo plano con demonios"],"fr":["Exécution de commandes PowerShell pour le nettoyage de la file d''attente","Utilisation de WSL pour exécuter des tâches dans un environnement Linux","Configuration de seuils de disque pour arrêter les exécutions","Nettoyage de la file d''attente avec un script PowerShell personnalisé","Exécution de tâches en arrière-plan avec des démons"],"de":["Ausführung von PowerShell-Befehlen zur Warteschlangenreinigung","Verwendung von WSL zur Ausführung von Aufgaben in einer Linux-Umgebung","Konfiguration von Festplattenschwellen zur Beendigung von Ausführungen","Warteschlangenreinigung mit benutzerdefiniertem PowerShell-Skript","Ausführung von Aufgaben im Hintergrund mit Dämonen"],"pt":["Gate de disco para controlar o espaço em disco","Limpeza de fila com retenção de 7 dias","Suporte a WSL runner para execuções automatizadas","Integração com Intel ingest para processamento de dados","Comando pwsh para execução de scripts personalizados"],"ru":["Дисковый шлюз для контроля свободного места на диске","Очистка очереди с сохранением 7 дней","Поддержка WSL runner для автоматизированных запусков","Интеграция с Intel ingest для обработки данных","Команда pwsh для выполнения пользовательских скриптов"],"ar":["بوابة القرص للسيطرة على المساحة الخالية على القرص","تنظيف الطابور مع الاحتفاظ ب 7 أيام","دعم تشغيل WSL للتشغيل التلقائي","دمج مع Intel ingest لمعالجة البيانات","أمر pwsh لتشغيل البرامج النصية المخصصة"]},"keywords":{"en":["anviloop-nightly setup guide","how to use anviloop-nightly","anviloop-nightly vs cron job","anviloop-nightly install","what is anviloop-nightly","anviloop-nightly alternative","automated nightly runs","PowerShell script for disk cleanup","WSL runner for queue management"],"zh":["anviloop-nightly","AI 工具","夜间运行","自动化","磁盘门控","队列清理","WSL 运行器","Intel 消费","PowerShell 脚本"],"ja":["anviloop-nightly","AI エージェント","ナイトリーミング","自動化","ディスク ゲート","キュークリーンアップ","WSL ランナー","Intel インジェスト","PowerShell スクリプト"],"ko":["anviloop-nightly","AI 에이전트","夜間 실행","자동화","디스크 게이트","큐 클리닝","WSL 런너","Intel 인제스트","PowerShell 스크립트"],"es":["anviloop-nightly","agentes de inteligencia artificial","herramientas de automatización","PowerShell","WSL","limpieza de cola","configuración de umbrales de disco"],"fr":["anviloop-nightly","outils d''intelligence artificielle","outils d''automatisation","PowerShell","WSL","nettoyage de la file d''attente","configuration de seuils de disque"],"de":["anviloop-nightly","KI-Tools","Automatisierungstools","PowerShell","WSL","Warteschlangenreinigung","Konfiguration von Festplattenschwellen"],"pt":["Anviloop Nightly","execuções noturnas automatizadas","gate de disco","limpeza de fila","WSL runner","Intel ingest","automatização de processos","ferramentas de automação","soluções de automação"],"ru":["Anviloop Nightly","автоматизация ночных запусков","дисковый шлюз","очистка очереди","WSL runner","Intel ingest","автоматизация процессов","инструменты автоматизации","решения для автоматизации"],"ar":["أنفيلوب الليلي","التشغيل الليلي التلقائي","بوابة القرص","تنظيف الطابور","تشغيل WSL","Intel ingest","أتمتة العمليات","أدوات الأتمتة","حلول الأتمتة"]}},"owner":"MoniVibe","repo":"HeadlessRebuildTool","repoPath":"MoniVibe/HeadlessRebuildTool","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.497Z","topics":[],"category":"community","skillMd":{"name":"anviloop-nightly","description":"Run the Anviloop nightly protocol: disk gate, cleanup, required daemons, validity checks, chain-of-custody, and stop rules. Use when planning or executing nightly cycles.","bodyPreview":"# Anviloop Nightly Protocol\r\n\r\n## Gates and cleanup (do first)\r\n\r\n- Disk gate: `pwsh -NoProfile -Command \"''C_free_GB='' + [math]::Round((Get-PSDrive C).Free/1GB,1)\"`\r\n  - Stop builds if < 40 GB.\r\n- Queue cleanup: `pwsh -NoProfile -File Polish/cleanup_queue.ps1 -QueueRoot \"C:/polish/queue\" -RetentionDays 7 -KeepLastPerScenario 3 -Apply`\r\n\r\n## Required daemons\r\n\r\n- WSL runner: `./Polish/WSL/wsl_runner.sh --queue /mnt/c/polish/queue --daemon --print-summary --status-interval 60`\r\n- Intel ingest: `Po","body":"# Anviloop Nightly Protocol\r\n\r\n## Gates and cleanup (do first)\r\n\r\n- Disk gate: `pwsh -NoProfile -Command \"''C_free_GB='' + [math]::Round((Get-PSDrive C).Free/1GB,1)\"`\r\n  - Stop builds if < 40 GB.\r\n- Queue cleanup: `pwsh -NoProfile -File Polish/cleanup_queue.ps1 -QueueRoot \"C:/polish/queue\" -RetentionDays 7 -KeepLastPerScenario 3 -Apply`\r\n\r\n## Required daemons\r\n\r\n- WSL runner: `./Polish/WSL/wsl_runner.sh --queue /mnt/c/polish/queue --daemon --print-summary --status-interval 60`\r\n- Intel ingest: `Polish/Intel/anviloop_intel.py`\r\n- Scoreboard/headline: `Polish/Goals/scoreboard.py`\r\n\r\n## Nightly structure\r\n\r\n- Cycle 0 sentinel once (FTL); proof in `out/player.log` contains `[Anviloop][FTL] FTL_JUMP` with `tick >= 30`.\r\n- Exactly one concept goal per night.\r\n- Do not change scenario and code in the same cycle (code-only first).\r\n\r\n## Validity + chain-of-custody\r\n\r\n- INVALID if telemetry missing/truncated, invariants missing, or oracle keys missing.\r\n- Keep commits only with headless proof.\r\n- Commit in artifact manifest must match result `meta.json`.\r\n\r\n## Stop/switch rules\r\n\r\n- If the same failure signature repeats twice, consult the ledger first.\r\n- If disk drops below gate, stop builds and switch to analysis/doc.\r\n\r\n## References\r\n\r\n- `C:/Dev/unity_clean/headlessrebuildtool/Polish/Docs/NIGHTLY_PROTOCOL.md`\r\n- `C:/Dev/unity_clean/headlessrebuildtool/Polish/Docs/MORNING_VIEW.md`\r\n- `C:/Dev/unity_clean/headlessrebuildtool/Polish/Docs/ANVILOOP_RECURRING_ERRORS.md`\r\n"},"lastSynced":"2026-03-08T02:10:14.047Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing automated nightly build optimization and disk space management using PowerShell scripts and WSL runner.","zh":"非常适合需要使用PowerShell脚本和WSL runner实现自动化夜间构建优化和磁盘空间管理的DevOps代理。","ja":"PowerShellスクリプトとWSLランナーを使用して自動化された夜間ビルドの最適化とディスクスペースの管理が必要なDevOpsエージェントに最適です。","ko":"PowerShell 스크립트와 WSL 러너를 사용하여 자동화된 밤 빌드 최적화 및 디스크 공간 관리가 필요한 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan optimización de compilación automática nocturna y gestión de espacio en disco utilizando scripts de PowerShell y WSL runner.","fr":"Parfait pour les agents DevOps ayant besoin d''une optimisation de build nocturne automatisée et d''une gestion de l''espace disque à l''aide de scripts PowerShell et de WSL runner.","de":"Perfekt für DevOps-Agents, die eine automatisierte Optimierung der Nachtcompilierung und der Festplattenspeicherung mit PowerShell-Skripten und WSL-Runner benötigen.","pt":"Perfeito para agentes DevOps que necessitam de otimização de compilação noturna automatizada e gerenciamento de espaço em disco usando scripts PowerShell e WSL runner.","ru":"Идеально подходит для агентов DevOps, которым необходима автоматизированная оптимизация ночных сборок и управление свободным пространством на диске с помощью скриптов PowerShell и запускаера WSL.","ar":"مثالي لعميل DevOps الذين يحتاجون إلى تحسين الإنشاء الليلي التلقائي وإدارة مساحة القرص باستخدام نصوص PowerShell وبرنامج تشغيل WSL."},"recommendation":{"en":"Empowers agents to automate nightly runs, ensuring efficient disk space management through disk gate checks and queue cleanup using protocols like WSL runner and PowerShell commands, while also handling Intel ingest and retention policies.","zh":"赋予代理人自动化夜间运行的能力，通过磁盘门检查和队列清理等协议（如WSL runner和PowerShell命令）确保高效的磁盘空间管理，同时也处理英特尔摄取和保留策略。","ja":"エージェントに夜間の自動実行を可能にし、WSLランナーやPowerShellコマンドなどのプロトコルを使用してディスク門のチェックやキューのクリーンアップを行い、効率的なディスクスペースの管理を確保し、インテルのインジェストとリテンションポリシーも処理します。","ko":"에이전트가 밤에 자동으로 실행할 수 있도록 하며, WSL 러너 및 PowerShell 명령과 같은 프로토콜을 사용하여 디스크 게이트 체크 및 큐 정리를 통해 효율적인 디스크 공간 관리를 보장하며, 인텔의摄取 및 보존 정책도 처리합니다.","es":"Habilita a los agentes a automatizar las ejecuciones nocturnas, garantizando una gestión eficiente del espacio en disco a través de controles de puerta de disco y limpieza de cola utilizando protocolos como WSL runner y comandos de PowerShell, y también manejar las políticas de ingesta y retención de Intel.","fr":"Permet aux agents d''automatiser les exécutions nocturnes, garantissant une gestion efficace de l''espace disque grâce à des contrôles de portail de disque et à un nettoyage de file d''attente en utilisant des protocoles tels que WSL runner et des commandes PowerShell, tout en gérant les politiques d''ingestion et de rétention d''Intel.","de":"Ermächtigt die Agents, Nachtläufe zu automatisieren und eine effiziente Festplatten-Speicherung durch Platten-Tor-Prüfungen und Warteschlangenreinigung unter Verwendung von Protokollen wie WSL-Runner und PowerShell-Befehlen zu gewährleisten, und auch die Richtlinien für die Intel-Erfassung und -Speicherung zu verwalten.","pt":"Concede poderes aos agentes para automatizar execuções noturnas, garantindo um gerenciamento eficiente de espaço em disco por meio de verificações de porta de disco e limpeza de fila usando protocolos como WSL runner e comandos PowerShell, além de lidar com políticas de retenção e ingestão da Intel.","ru":"Наделяет агентов возможностью автоматизировать ночные запуски, обеспечивая эффективное управление свободным пространством на диске посредством проверок шлюза диска и очистки очереди с использованием протоколов, таких как WSL runner и команды PowerShell, а также обработку политики хранения и ингести данных Intel.","ar":"تمكن الوكيل من تشغيل الإنشاء الليلي التلقائي، مما يضمن إدارة فعالة لمساحة القرص من خلال عمليات فحص البوابة والتنظيف والبروتوكولات مثل تشغيل WSL وأوامر PowerShell، بالإضافة إلى التعامل مع سياسات الاحتفاظ والاستهلاك الفني من Intel."},"useCases":{"en":["Automating nightly build processes with disk space checks","Optimizing queue cleanup using PowerShell scripts and WSL runner","Ensuring retention policies through Intel ingest and queue management"],"zh":["使用磁盘空间检查自动化夜间构建过程","使用PowerShell脚本和WSL runner优化队列清理","通过英特尔摄取和队列管理确保保留策略"],"ja":["ディスクスペースのチェックを使用して夜間ビルドのプロセスを自動化する","PowerShellスクリプトとWSLランナーを使用してキューのクリーンアップを最適化する","インテルのインジェストとキューの管理を使用してリテンションポリシーを確保する"],"ko":["디스크 공간 체크를 사용하여 밤 빌드 프로세스를 자동화하는 것","PowerShell 스크립트 및 WSL 러너를 사용하여 큐 정리를 최적화하는 것","인텔의 摄取 및 큐 관리를 사용하여 보존 정책을 보장하는 것"],"es":["Automatizar los procesos de compilación nocturna con controles de espacio en disco","Optimizar la limpieza de cola utilizando scripts de PowerShell y WSL runner","Garantizar las políticas de retención a través de la ingesta de Intel y la gestión de cola"],"