INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SIRI-bit-tech/Standard-Chartered-/skills', 'skills', 'SIRI-bit-tech', 'Standard-Chartered-', 'community', 'skills SIRI-bit-tech Standard-Chartered- community The Skills AI agent generates country-specific account numbers and assigns primary currencies based on user selection, benefiting developers and banking platforms. AIエージェント技能允许开发者自动生成国家特定账户号码，支持多种国家和货币 AIエージェントのスキルは、開発者が国コードに基づいて口座番号を自動生成できるようにします AI 에이전트 기술을 통해 개발자는 국가별 계좌 번호를 자동 생성하고 여러 국가와 통화를 지원할 수 있습니다 Las habilidades de banco permiten la generación automática de números de cuenta y la asignación de moneda primaria según la ubicación del usuario Les compétences de la plateforme bancaire permettent la génération automatique de numéros de compte et l''attribution de la devise principale en fonction de l''emplacement de l''utilisateur Die Fähigkeiten der Banking-Plattform ermöglichen die automatische Generierung von Kontonummern und die Zuweisung der primären Währung basierend auf dem Benutzerstandort As habilidades de banco permitem a geração automática de números de conta específicos do país, garantindo a unicidade em todas as contas. Навыки банковского платформенного ИИ Агентов позволяют автоматически создавать страновые номера счетов, обеспечивая уникальность во всех счетах. تمكن مهارات الوكيل الإصطناعي للبنوك من إنشاء أرقام حساب أوتوماتيكية محددة بالدولة، مما يضمن الفردية في جميع الحسابات. how to use skills for account number generation skills alternative for banking platforms skills vs manual account number generation skills setup guide for AI agents what is skills in banking skills install for developers AIエージェント技能 自动账户编号生成 国家特定账户号码 多种国家和货币 账户号码唯一性 数字长度 多币种分配 基于用户选择的国家进行主币种分配 Automatically generates country-specific account numbers with correct digit lengths Ensures uniqueness across all accounts Assigns primary currency based on user''s selected country Supports multi-currency assignment Stores account numbers as strings to preserve leading zeros Skills is an AI agent capability that automatically generates and manages account numbers and currencies for banking platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sandraschi/robotics-mcp/ros-robotics-expert', 'community', 'sandraschi', 'robotics-mcp', 'sandraschi/robotics-mcp', 'ros-robotics-expert', 0, 0, 26, '2026-03-08T01:57:15.519Z', '2026-03-08T02:10:39.584Z', '37547e30ed8ea6877f808b7bac4a3b2ba275b725e70f601e49ad89b4a388d8ec', '{"id":"sandraschi/robotics-mcp/ros-robotics-expert","name":"ros-robotics-expert","description":{"en":"The ros-robotics-expert skill enables developers to coordinate multiple robots using shared LIDAR maps, collaborative SLAM, and RF-based movement detection. It benefits robotics engineers and AI developers working with ROS architecture.","zh":"ROS 机器人专家技能实现 FastMCP 2.14 多机器人协调，通过共享 LIDAR 地图、协作 SLAM 和实时碰撞避免","ja":"ROS ロボティクス エキスパート スキルは FastMCP 2.14 マルチロボット協調を実現し、共有 LIDAR マップ、協調 SLAM、リアルタイムの衝突回避を提供","ko":"ROS 로봇 전문가 스킬은 FastMCP 2.14 멀티 로봇 협조를 구현하고 공유 LIDAR 맵, 협력 SLAM 및 실시간 충돌 회피를 제공","es":"ros-robotics-expert es un framework de coordinación de robots múltiples que utiliza tecnologías como LIDAR y SLAM para la detección de movimientos y la evitación de colisiones","fr":"ros-robotics-expert est un framework de coordination de robots multiples qui utilise des technologies comme LIDAR et SLAM pour la détection de mouvements et l''évitement de collisions","de":"ros-robotics-expert ist ein Framework für die Koordination mehrerer Roboter, das Technologien wie LIDAR und SLAM für die Bewegungserkennung und Kollisionsvermeidung verwendet","pt":"O ros-robotics-expert é um framework para coordenação de robôs com tecnologias como LIDAR e SLAM. Aprenda a configurá-lo com FastMCP 2.14","ru":"ros-robotics-expert - это фреймворк для координации роботов с технологиями LIDAR и SLAM. Узнайте, как настроить его с FastMCP 2.14","ar":"ros-robotics-expert هو إطار عمل لتنسيق الروبوتات مع تقنيات LIDAR و SLAM. تعلم كيفية إعداده مع FastMCP 2.14"},"seo":{"title":{"en":"ros-robotics-expert: Multi-Robot Coordination Setup Guide...","zh":"ROS 机器人专家：FastMCP 2.14 多机器人协调设置指南","ja":"ROS ロボティクス エキスパート：FastMCP 2.14 マルチロボット協調設定ガイド","ko":"ROS 로봇 전문가: FastMCP 2.14 멀티 로봇 협調 설정 가이드","es":"Guía de configuración para ros-robotics-expert","fr":"Guide de démarrage pour ros-robotics-expert","de":"Einrichtungsleitfaden für ros-robotics-expert","pt":"Guia de Configuração do ros-robotics-expert para Desenvol...","ru":"Настройка ros-robotics-expert: ИИ Агенты для Робототехники","ar":"دليل إعداد ros-robotics-expert للrobotics مع أدوات الإي ا..."},"description":{"en":"Unlock seamless collaboration between Yahboom ROSMASTER, Dreame D20 Pro, and more with ros-robotics-expert. Get started with our expert guide and discover th...","zh":"了解 ROS 机器人专家技能，实现 FastMCP 2.14 多机器人协调，共享 LIDAR 地图，协作 SLAM 和实时碰撞避免","ja":"ROS ロボティクス エキスパート スキルを使用して FastMCP 2.14 マルチロボット協調を実現し、共有 LIDAR マップ、協調 SLAM、リアルタイムの衝突回避を実現","ko":"ROS 로봇 전문가 스킬을 사용하여 FastMCP 2.14 멀티 로봇 협조를 구현하고 공유 LIDAR 맵, 협력 SLAM 및 실시간 충돌 회피를 구현","es":"Aprende a configurar y utilizar ros-robotics-expert para la coordinación de robots múltiples con tecnologías como LIDAR y SLAM","fr":"Découvrez comment configurer et utiliser ros-robotics-expert pour la coordination de robots multiples avec des technologies comme LIDAR et SLAM","de":"Erfahren Sie, wie Sie ros-robotics-expert für die Koordination mehrerer Roboter mit Technologien wie LIDAR und SLAM konfigurieren und verwenden","pt":"Aprenda a configurar o ros-robotics-expert com FastMCP 2.14 e coordene robôs com mapeamento LIDAR compartilhado e evasão de colisões em tempo real","ru":"Узнайте, как настроить ros-robotics-expert с FastMCP 2.14 и координировать роботов с помощью общих карт LIDAR и реального времени избегания столкновений","ar":"تعلم كيفية إعداد ros-robotics-expert مع FastMCP 2.14 وتنسيق الروبوتات باستخدام خرائط LIDAR المشتركة وتجنب الاصطدامات في الوقت الفعلي"},"definition":{"en":"ros-robotics-expert is a skill that facilitates multi-robot coordination through FastMCP 2.14, enabling physical and virtual robots to work as one system using ROS concepts and messaging patterns.","zh":"ROS 机器人专家是一种 AI 工具，实现多机器人协调，通过共享 LIDAR 地图、协作 SLAM 和实时碰撞避免","ja":"ROS ロボティクス エキスパートは AI エージェントの一種で、マルチロボット協調を実現し、共有 LIDAR マップ、協調 SLAM、リアルタイムの衝突回避を提供","ko":"ROS 로봇 전문가는一种 AI 도구로 멀티 로봇 협조를 구현하고 공유 LIDAR 맵, 협력 SLAM 및 실시간 충돌 회피를 제공","es":"ros-robotics-expert es un experto en robótica que utiliza ROS para la coordinación de robots múltiples","fr":"ros-robotics-expert est un expert en robotique qui utilise ROS pour la coordination de robots multiples","de":"ros-robotics-expert ist ein Experte für Robotik, der ROS für die Koordination mehrerer Roboter verwendet","pt":"ros-robotics-expert é um framework de coordenação de robôs que combina mapeamento LIDAR e SLAM para robôs físicos e virtuais","ru":"ros-robotics-expert - это фреймворк координации роботов, который объединяет картографирование LIDAR и SLAM для физических и виртуальных роботов","ar":"ros-robotics-expert هو إطار عمل لتنسيق الروبوتات الذي يجمع بين خرائط LIDAR و SLAM للروبوتات الفيزيائية و الافتراضية"},"features":{"en":["Utilizes shared LIDAR maps for seamless robot coordination","Employs collaborative SLAM for enhanced mapping capabilities","Supports RF-based movement detection for real-time tracking","Enables real-time collision avoidance for safe robot operation","Integrates with Yahboom ROSMASTER, Dreame D20 Pro, and other robots","Leverages ROS architecture and messaging patterns for robust communication"],"zh":["FastMCP 2.14 多机器人协调","共享 LIDAR 地图","协作 SLAM","实时碰撞避免","支持 Yahboom ROSMASTER、Dreame D20 Pro、Tdrone Mini、Unitree Go2/G1 和 Philips Hue Bridge Pro"],"ja":["FastMCP 2.14 マルチロボット協調","共有 LIDAR マップ","協調 SLAM","リアルタイムの衝突回避","Yahboom ROSMASTER、Dreame D20 Pro、Tdrone Mini、Unitree Go2/G1、Philips Hue Bridge Pro をサポート"],"ko":["FastMCP 2.14 멀티 로봇 협조","공유 LIDAR 맵","협력 SLAM","실시간 충돌 회피","Yahboom ROSMASTER, Dreame D20 Pro, Tdrone Mini, Unitree Go2/G1, Philips Hue Bridge Pro 지원"],"es":["Coordinac