INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sandraschi/robotics-mcp/ros-robotics-expert', 'ros-robotics-expert', 'sandraschi', 'robotics-mcp', 'community', 'ros-robotics-expert sandraschi robotics-mcp community The ros-robotics-expert skill enables developers to coordinate multiple robots using shared LIDAR maps, collaborative SLAM, and RF-based movement detection. It benefits robotics engineers and AI developers working with ROS architecture. ROS 机器人专家技能实现 FastMCP 2.14 多机器人协调，通过共享 LIDAR 地图、协作 SLAM 和实时碰撞避免 ROS ロボティクス エキスパート スキルは FastMCP 2.14 マルチロボット協調を実現し、共有 LIDAR マップ、協調 SLAM、リアルタイムの衝突回避を提供 ROS 로봇 전문가 스킬은 FastMCP 2.14 멀티 로봇 협조를 구현하고 공유 LIDAR 맵, 협력 SLAM 및 실시간 충돌 회피를 제공 ros-robotics-expert es un framework de coordinación de robots múltiples que utiliza tecnologías como LIDAR y SLAM para la detección de movimientos y la evitación de colisiones ros-robotics-expert est un framework de coordination de robots multiples qui utilise des technologies comme LIDAR et SLAM pour la détection de mouvements et l''évitement de collisions ros-robotics-expert ist ein Framework für die Koordination mehrerer Roboter, das Technologien wie LIDAR und SLAM für die Bewegungserkennung und Kollisionsvermeidung verwendet O ros-robotics-expert é um framework para coordenação de robôs com tecnologias como LIDAR e SLAM. Aprenda a configurá-lo com FastMCP 2.14 ros-robotics-expert - это фреймворк для координации роботов с технологиями LIDAR и SLAM. Узнайте, как настроить его с FastMCP 2.14 ros-robotics-expert هو إطار عمل لتنسيق الروبوتات مع تقنيات LIDAR و SLAM. تعلم كيفية إعداده مع FastMCP 2.14 how to use ros-robotics-expert ros-robotics-expert setup guide ros-robotics-expert vs multi-robot coordination what is ros-robotics-expert ros-robotics-expert install ros-robotics-expert alternative multi-robot coordination with ros ros-robotics-expert tutorial ros-robotics-expert documentation ROS 机器人专家 FastMCP 2.14 多机器人协调 共享 LIDAR 地图 协作 SLAM 实时碰撞避免 AI 工具 机器人开发 Utilizes shared LIDAR maps for seamless robot coordination Employs collaborative SLAM for enhanced mapping capabilities Supports RF-based movement detection for real-time tracking Enables real-time collision avoidance for safe robot operation Integrates with Yahboom ROSMASTER, Dreame D20 Pro, and other robots Leverages ROS architecture and messaging patterns for robust communication ros-robotics-expert is a skill that facilitates multi-robot coordination through FastMCP 2.14, enabling physical and virtual robots to work as one system using ROS concepts and messaging patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HaoNgo232/agent-bridge-kit/vr-ar', 'community', 'HaoNgo232', 'agent-bridge-kit', 'HaoNgo232/agent-bridge-kit', 'vr-ar', 0, 0, 26, '2026-03-08T01:57:15.542Z', '2026-03-08T02:11:13.271Z', '59ddbdecc4fa17e74c4747f5f02bd69edb8bffcd1cdc2866dd6a053e19bc139e', '{"id":"HaoNgo232/agent-bridge-kit/vr-ar","name":"vr-ar","description":{"en":"The vr-ar skill converts configurations from Antigravity IDE to formats compatible with IDEs and CLIs, benefiting developers working with VR/AR platforms like Quest, PCVR, and WebXR.","zh":"VR/AR开发工具配置转换工具，支持Quest、PCVR、PSVR、WebXR、ARKit、ARCore和HoloLens等平台","ja":"VR/AR開発ツール設定変換ツール。Quest、PCVR、PSVR、WebXR、ARKit、ARCore、HoloLensなどのプラットフォームをサポート","ko":"VR/AR 개발 도구 설정 변환 도구. Quest, PCVR, PSVR, WebXR, ARKit, ARCore, HoloLens 등의 플랫폼을 지원합니다","es":"Herramienta para convertir configuraciones de vr-ar a formatos compatibles con IDEs y CLIs. Soporta plataformas como Quest, PCVR, PSVR, WebXR, ARKit, ARCore y HoloLens.","fr":"Outil pour convertir les configurations de vr-ar en formats compatibles avec les IDE et les CLIs. Prend en charge les plates-formes telles que Quest, PCVR, PSVR, WebXR, ARKit, ARCore et HoloLens.","de":"Werkzeug zum Konvertieren von vr-ar-Konfigurationen in Formate, die mit IDEs und CLIs kompatibel sind. Unterstützt Plattformen wie Quest, PCVR, PSVR, WebXR, ARKit, ARCore und HoloLens.","pt":"O VR/AR é uma ferramenta para converter configurações de Agent, Skill e Workflows do Antigravity IDE para formatos compatíveis com IDEs e CLIs.","ru":"VR/AR - это инструмент для конвертации конфигураций Agent, Skill и Workflows из Antigravity IDE в форматы, совместимые с ИИ Агентами и инструментами разработки.","ar":"الواقع الافتراضي والمعزز هو أداة لتحويل تكوين الوكيل والمهارة والتدفقات العمل من Antigravity IDE إلى تنسيقات متوافقة مع الأدوات البرمجية"},"seo":{"title":{"en":"vr-ar: Immersive Experience Setup Guide | AI Agent Skill","zh":"VR/AR开发工具配置转换Setup Guide","ja":"VR/AR開発ツール設定変換ベストプラクティス","ko":"VR/AR 개발 도구 설정 변환 가이드","es":"Guía de configuración de vr-ar para IDEs y CLIs","fr":"Guide de configuration vr-ar pour les IDE et les CLIs","de":"Konfigurationsleitfaden für vr-ar in IDEs und CLIs","pt":"Guia de Configuração VR/AR para Ferramentas de Desenvolvi...","ru":"Настройка VR/AR для ИИ Агентов и Инструментов Разработки","ar":"دليل إعداد الواقع الافتراضي والمعزز للأدوات البرمجية"},"description":{"en":"Unlock seamless VR/AR development with our AI agent skill, compatible with GitHub Copilot and WebXR. Get started now and discover new possibilities!","zh":"了解如何将Antigravity IDE配置转换为GitHub Copilot、Cursor等IDE和Kiro、OpenCode等CLI兼容格式","ja":"Antigravity IDEの設定をGitHub Copilot、CursorなどのIDEやKiro、OpenCodeなどのCLIと互換性のある形式に変換する方法を学ぶ","ko":"Antigravity IDE 설정을 GitHub Copilot, Cursor 등의 IDE 및 Kiro, OpenCode 등의 CLI와 호환되는 형식으로 변환하는 방법을 알아보세요","es":"Convierta configuraciones de Agent, Skill y Workflows de Antigravity IDE a formatos compatibles con GitHub Copilot, Cursor y otros","fr":"Convertissez les configurations d''Agent, Skill et Workflows d''Antigravity IDE en formats compatibles avec GitHub Copilot, Cursor et autres","de":"Konvertieren Sie Konfigurationen von Agent, Skill und Workflows von Antigravity IDE in Formate, die mit GitHub Copilot, Cursor und anderen kompatibel sind","pt":"Aprenda a configurar o VR/AR para ferramentas de desenvolvimento como GitHub Copilot e CLI, com dicas de plataforma e princípios de confort","ru":"Узнайте, как настроить VR/AR для ИИ Агентов и инструментов разработки, таких как GitHub Copilot и CLI, с советами по выбору платформы и принципам комфорта","ar":"تعلم كيفية إعداد الواقع الافتراضي والمعزز للأدوات البرمجية مثل GitHub Copilot و CLI، مع نصائح حول اختيار المنصة ومبادئ الراحة"},"definition":{"en":"vr-ar is a tool for converting Agent, Skill, and Workflows configurations to compatible formats for various IDEs and CLIs, enabling immersive experience development","zh":"VR/AR开发工具配置转换是指将Antigravity IDE配置转换为其他IDE和CLI兼容格式的过程","ja":"VR/AR開発ツール設定変換とは、Antigravity IDEの設定を他のIDEやCLIと互換性のある形式に変換するプロセスを指す","ko":"VR/AR 개발 도구 설정 변환은 Antigravity IDE 설정을 다른 IDE 및 CLI와 호환되는 형식으로 변환하는 과정입니다","es":"vr-ar es una herramienta para convertir configuraciones de Agent, Skill y Workflows a formatos compatibles con IDEs y CLIs","fr":"vr-ar est un outil pour convertir les configurations d''Agent, Skill et Workflows en formats compatibles avec les IDE et les CLIs","de":"vr-ar ist ein Werkzeug zum Konvertieren von Konfigurationen von Agent, Skill und Workflows in Formate, die mit IDEs und CLIs kompatibel sind","pt":"O que é VR/AR? É uma ferramenta de conversão de configurações para desenvolvimento de realidade virtual e aumentada.","ru":"Что такое VR/AR? Это инструмент для конвертации конфигураций для разработки виртуальной и дополненной реальности.","ar":"ما هو الواقع الافتراضي والمعزز؟ إنه أداة لتحويل التكوين لتطوير الواقع الافتراضي والمعزز"},"features":{"en":["Supports VR platform selection, including Quest, PCVR, and PSVR","Enables AR development with ARKit, ARCore, WebXR, and HoloLens","Provides comfort principles for immersive experience development","Compatible with GitHub Copilot, Cursor, Kiro, and OpenCode","Facilitates browser-based AR development with WebXR","Offers standalone, wireless, and high-fidelity VR experiences"],"zh":["支持Quest、PCVR、PSVR、WebXR等VR平台","支持ARKit、ARCore、HoloLens等AR平台","兼容GitHub Copilot、Cursor等IDE","兼容Kiro、OpenCode等CLI","实现Antigravity IDE配置转换","提供Immersive experience principles"],"ja":["Quest、PCVR、PSVR、WebXRなどのVRプラットフォームをサポート","ARKit、ARCore、HoloLensなどのARプラットフォームをサポート","GitHub Copilot、CursorなどのIDEと互換性","Kiro、OpenCodeなどのCLIと互換性","Antigravity IDEの設定変換を実現","Immersive experience principlesを提供"],"ko":["Quest, PCVR, PSVR, WebXR 등의 VR 플랫폼 지원","ARKit, ARCore, HoloLens 등의 AR 플랫폼 지원","GitHub Copilot, Cursor 등의 IDE와 호환","Kiro, OpenCode 등의 CLI와 호환","Antigravity IDE 설정 변환 구현","Immersive experience principles 제공"],"es":["Compatibilidad con plataformas de realidad virtual como Quest y PCVR","Soporte para plataformas de realidad aumentada como ARKit y ARCore","Conversión de configuraciones a formatos compatibles con GitHub Copilot y Cursor","Compatibilidad con WebXR para experiencias de realidad virtual y aumentada en el navegador","Soporte para HoloLens para aplicaciones empresariales","Conversión de configuraciones de Agent, Skill y Workflows de Antigravity IDE"],"fr":["Compatibilité avec les plates-formes de réalité virtuelle telles que Quest et PCVR","Prise en charge des plates-formes de réalité augmentée telles que ARKit et ARCore","Conversion des configurations en formats compatibles avec GitHub Copilot et Cursor","Compatibilité avec WebXR pour des expériences de réalité virtuelle et augmentée dans le navigateur","Prise en charge de HoloLens pour des applications d''entreprise","Conversion des configurations d''Agent, Skill et Workflows d''Antigravity IDE"],"de":["Kompatibilität mit virtuellen Plattformen wie Quest und PCVR","Unterstützung für erweiterte Realitätsplattformen wie ARKit und ARCore","Konvertierung von Konfigurationen in Formate, die mit GitHub Copilot und Cursor kompatibel sind","Kompatibilität mit WebXR für virtuelle und erweiterte Realitätserfahrungen im Browser","Unterstützung für HoloLens für Unternehmensanwendungen","Konvertierung von Konfigurationen von Agent, Skill und Workflows von Antigravity IDE"],"pt":["Suporte a plataformas de VR como Quest, PCVR e PSVR","Suporte a plataformas de AR como ARKit, ARCore e WebXR","Princípios de confort para desenvolvimento de realidade virtual e aumentada","Compatibilidade com IDEs como GitHub Copilot e CLIs como Kiro e OpenCode"],"ru":["Поддержка платформ VR, таких как Quest, PCVR и PSVR","Поддержка платформ AR, таких как ARKit, ARCore и WebXR","Принципы комфорта для разработки виртуальной и дополненной реальности","Совместимость с ИИ Агентами и инструментами разработки, такими как GitHub Copilot и CLI"],"ar":["دعم منصات الواقع الافتراضي مثل Quest و PCVR و PSVR","دعم منصات الواقع المعزز مثل ARKit و ARCore و WebXR","مبادئ الراحة لتطوير الواقع الافتراضي والمعزز","توافق مع الأدوات البرمجية مثل GitHub Copilot و CLI"]},"keywords":{"en":["how to use vr-ar","vr-ar setup guide","vr-ar vs arkit","webxr development","vr-ar install","vr-ar alternative","what is vr-ar","immersive experience development","vr-ar compatible platforms","github copilot vr-ar"],"zh":["VR/AR开发工具","Antigravity IDE配置转换","GitHub Copilot","Cursor","Kiro","OpenCode","VR平台","AR平台","Immersive experience principles"],"ja":["VR/AR開発ツール","Antigravity IDE設定変換","GitHub Copilot","Cursor","Kiro","OpenCode","VRプラットフォーム","ARプラットフォーム","Immersive experience principles"],"ko":["VR/AR 개발 도구","Antigravity IDE 설정 변환","GitHub Copilot","Cursor","Kiro","OpenCode","VR 플랫폼","AR 플랫폼","Immersive experience principles"],"es":["vr-ar","realidad virtual","realidad aumentada","GitHub Copilot","Cursor","Quest","PCVR","PSVR","WebXR","ARKit","ARCore","HoloLens"],"fr":["vr-ar","réalité virtuelle","réalité augmentée","GitHub Copilot","Cursor","Quest","PCVR","PSVR","WebXR","ARKit","ARCore","HoloLens"],"de":["vr-ar","virtuelle Realität","erweiterte Realität","GitHub Copilot","Cursor","Quest","PCVR","PSVR","WebXR","ARKit","ARCore","HoloLens"],"pt":["VR/AR","desenvolvimento de realidade virtual","desenvolvimento de realidade aumentada","plataformas de VR","plataformas de AR","GitHub Copilot","CLI","Kiro","OpenCode"],"ru":["VR/AR","разработка виртуальной реальности","разработка дополненной реальности","платформы VR","платформы AR","ИИ Агенты","инструменты разработки","GitHub Copilot","CLI"],"ar":["الواقع الافتراضي والمعزز","تطوير الواقع الافتراضي","تطوير الواقع المعزز","منصات الواقع الافتراضي","منصات الواقع المعزز","الأدوات البرمجية","GitHub Copilot","CLI"]}},"owner":"HaoNgo232","repo":"agent-bridge-kit","repoPath":"HaoNgo232/agent-bridge-kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.542Z","topics":[],"category":"community","skillMd":{"name":"vr-ar","description":"VR/AR development principles. Comfort, interaction, performance requirements.","bodyPreview":"# VR/AR Development\n\n> Immersive experience principles.\n\n---\n\n## 1. Platform Selection\n\n### VR Platforms\n\n| Platform | Use Case |\n|----------|----------|\n| **Quest** | Standalone, wireless |\n| **PCVR** | High fidelity |\n| **PSVR** | Console market |\n| **WebXR** | Browser-based |\n\n### AR Platforms\n\n| Platform | Use Case |\n|----------|----------|\n| **ARKit** | iOS devices |\n| **ARCore** | Android devices |\n| **WebXR** | Browser AR |\n| **HoloLens** | Enterprise |\n\n---\n\n## 2. Comfort Principles\n\n###","body":"# VR/AR Development\n\n> Immersive experience principles.\n\n---\n\n## 1. Platform Selection\n\n### VR Platforms\n\n| Platform | Use Case |\n|----------|----------|\n| **Quest** | Standalone, wireless |\n| **PCVR** | High fidelity |\n| **PSVR** | Console market |\n| **WebXR** | Browser-based |\n\n### AR Platforms\n\n| Platform | Use Case |\n|----------|----------|\n| **ARKit** | iOS devices |\n| **ARCore** | Android devices |\n| **WebXR** | Browser AR |\n| **HoloLens** | Enterprise |\n\n---\n\n## 2. Comfort Principles\n\n### Motion Sickness Prevention\n\n| Cause | Solution |\n|-------|----------|\n| **Locomotion** | Teleport, snap turn |\n| **Low FPS** | Maintain 90 FPS |\n| **Camera shake** | Avoid or minimize |\n| **Rapid acceleration** | Gradual movement |\n\n### Comfort Settings\n\n- Vignette during movement\n- Snap vs smooth turning\n- Seated vs standing modes\n- Height calibration\n\n---\n\n## 3. Performance Requirements\n\n### Target Metrics\n\n| Platform | FPS | Resolution |\n|----------|-----|------------|\n| Quest 2 | 72-90 | 1832x1920 |\n| Quest 3 | 90-120 | 2064x2208 |\n| PCVR | 90 | 2160x2160+ |\n| PSVR2 | 90-120 | 2000x2040 |\n\n### Frame Budget\n\n- VR requires consistent frame times\n- Single dropped frame = visible judder\n- 90 FPS = 11.11ms budget\n\n---\n\n## 4. Interaction Principles\n\n### Controller Interaction\n\n| Type | Use |\n|------|-----|\n| **Point + click** | UI, distant objects |\n| **Grab** | Manipulation |\n| **Gesture** | Magic, special actions |\n| **Physical** | Throwing, swinging |\n\n### Hand Tracking\n\n- More immersive but less precise\n- Good for: social, casual\n- Challenging for: action, precision\n\n---\n\n## 5. Spatial Design\n\n### World Scale\n\n- 1 unit = 1 meter (critical)\n- Objects must feel right size\n- Test with real measurements\n\n### Depth Cues\n\n| Cue | Importance |\n|-----|------------|\n| Stereo | Primary depth |\n| Motion parallax | Secondary |\n| Shadows | Grounding |\n| Occlusion | Layering |\n\n---\n\n## 6. Anti-Patterns\n\n| ❌ Don''t | ✅ Do |\n|----------|-------|\n| Move camera without player | Player controls camera |\n| Drop below 90 FPS | Maintain frame rate |\n| Use tiny UI text | Large, readable text |\n| Ignore arm length | Scale to player reach |\n\n---\n\n> **Remember:** Comfort is not optional. Sick players don''t play.\n"},"lastSynced":"2026-03-08T02:11:13.271Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents focused on immersive experience development, needing seamless integration with VR/AR platforms like Quest, PCVR, and WebXR.","zh":"适用于专注于沉浸式体验开发的 AI 代理，需要与 VR/AR 平台（如 Quest、PCVR 和 WebXR）实现无缝集成。","ja":"VR/AR プラットフォーム（Quest、PCVR、WebXR など）とのシームレスな統合が必要な、没入型体験開発に特化した AI エージェントに適しています。","ko":"Quest, PCVR 및 WebXR와 같은 VR/AR 플랫폼과의 무결점 통합이 필요한 몰입형 경험 개발에 중점을 둔 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA centrados en el desarrollo de experiencias inmersivas, que necesitan una integración perfecta con plataformas de realidad virtual/aumentada como Quest, PCVR y WebXR.","fr":"Idéal pour les agents IA axés sur le développement d''expériences immersives, nécessitant une intégration transparente avec des plateformes de réalité virtuelle/augmentée comme Quest, PCVR et WebXR.","de":"Ideal für KI-Agents, die auf die Entwicklung von immersiven Erfahrungen ausgerichtet sind und eine nahtlose Integration mit VR/AR-Plattformen wie Quest, PCVR und WebXR benötigen.","pt":"Ideal para Agentes de IA focados no desenvolvimento de experiências imersivas, necessitando de integração sem problemas com plataformas de VR/AR como Quest, PCVR e WebXR.","ru":"Идеально для агентов ИИ, ориентированных на разработку иммерсивных опытов, требующих бесшовной интеграции с платформами VR/AR, такими как Quest, PCVR и WebXR.","ar":"مثالي للوكلاء الذكيين الذين يركزون على تطوير الخبرات الغامرة، وهم بحاجة إلى تكامل بدون مشاكل مع منصات VR/AR مثل Quest و PCVR و WebXR."},"recommendation":{"en":"Empowers agents to convert configurations from Antigravity IDE to formats compatible with various IDEs and CLIs, supporting development on Quest, PCVR, and WebXR, and leveraging technologies like ARKit, ARCore, and WebXR for browser-based AR experiences.","zh":"赋予代理将配置从 Antigravity IDE 转换为与各种 IDE 和 CLI 兼容的格式，支持在 Quest、PCVR 和 WebXR 上进行开发，并利用 ARKit、ARCore 和 WebXR 等技术实现基于浏览器的 AR 体验。","ja":"エージェントは、Antigravity IDE の構成を、さまざまな IDE や CLI と互換性のある形式に変換できるようになり、Quest、PCVR、WebXR での開発をサポートし、ARKit、ARCore、WebXR などのテクノロジーを使用してブラウザベースの AR 体験を実現します。","ko":"에이전트가 Antigravity IDE의 구성 파일을 다양한 IDE 및 CLI와 호환되는 형식으로 변환할 수 있도록 하여 Quest, PCVR 및 WebXR에서 개발을 지원하며 ARKit, ARCore 및 WebXR와 같은 기술을 사용하여 브라우저 기반의 AR 경험을 제공합니다.","es":"Permite a los agentes convertir configuraciones desde Antigravity IDE a formatos compatibles con varios IDE y CLIs, lo que admite el desarrollo en Quest, PCVR y WebXR, y aprovecha tecnologías como ARKit, ARCore y WebXR para experiencias de realidad aumentada basadas en navegador.","fr":"Permet aux agents de convertir des configurations à partir d''Antigravity IDE vers des formats compatibles avec divers IDE et CLIs, ce qui prend en charge le développement sur Quest, PCVR et WebXR, et tire parti de technologies comme ARKit, ARCore et WebXR pour des expériences de réalité augmentée basées sur navigateur.","de":"Ermöglicht es Agenten, Konfigurationen von Antigravity IDE in Formate umzuwandeln, die mit verschiedenen IDEs und CLIs kompatibel sind, wodurch die Entwicklung auf Quest, PCVR und WebXR unterstützt wird und Technologien wie ARKit, ARCore und WebXR für browserbasierte AR-Erfahrungen genutzt werden.","pt":"Permite que os agentes convertam configurações do Antigravity IDE para formatos compatíveis com vários IDEs e CLIs, apoiando o desenvolvimento no Quest, PCVR e WebXR, e aproveitando tecnologias como ARKit, ARCore e WebXR para experiências de AR baseadas em navegador.","ru":"Наделяет агентов возможностью преобразовывать конфигурации Antigravity IDE в форматы, совместимые с различными IDE и CLI, поддерживая разработку на Quest, PCVR и WebXR, и использует технологии, такие как ARKit, ARCore и WebXR для браузерных опытов AR.","ar":"تمكّن الوكلاء من تحويل التكوينات من Antigravity IDE إلى صيغ متوافقة مع مختلف بيئات التطوير المتكاملة وواجهات سطر الأوامر، داعمًا التطوير على Quest و PCVR و WebXR، واستخدام تقنيات مثل ARKit و ARCore و WebXR لتجارب الواقع المعزز المبنية على المتصفح."},"useCases":{"en":["Converting Antigravity IDE configurations for PCVR development","Generating compatible formats for WebXR browser-based experiences","Streamlining AR development with ARKit and ARCore"],"zh":["将 Antigravity IDE 配置转换为 PCVR 开发兼容格式","为 WebXR 浏览器体验生成兼容格式","使用 ARKit 和 ARCore 简化 AR 开发"],"ja":["PCVR 開発用の Antigravity IDE 構成を変換する","WebXR ブラウザ体験用の互換性のある形式を生成する","ARKit と ARCore を使用して AR 開発を簡素化する"],"ko":["PCVR 개발을 위한 Antigravity IDE 구성 파일을 변환하는 것","WebXR 브라우저 경험을 위한 호환 형식 생성","ARKit 및 ARCore를 사용하여 AR 개발을 간소화"],"es":["Conversión de configuraciones de Antigravity IDE para el desarrollo de PCVR","Generación de formatos compatibles para experiencias basadas en WebXR en el navegador","Optimización del desarrollo de AR con ARKit y ARCore"],"fr":["Conversion de configurations d''Antigravity IDE pour le développement PCVR","Génération de formats compatibles pour des expériences WebXR basées sur navigateur","Optimisation du développement AR avec ARKit et ARCore"],"de":["Konvertierung von Antigravity IDE-Konfigurationen für die PCVR-Entwicklung","Erzeugung von kompatiblen Formaten für WebXR-basierte Browser-Erfahrungen","Optimierung der AR-Entwicklung mit ARKit und ARCore"],"pt":["Converter configurações do Antigravity IDE para desenvolvimento de PCVR","Gerar formatos compatíveis para experiências baseadas em navegador do WebXR","Otimizar o desenvolvimento de AR com ARKit e ARCore"],"ru":["Преобразовывать конфигурации Antigravity IDE для разработки PCVR","Генерировать совместимые форматы для браузерных опытов WebXR","Оптимизировать разработку AR с помощью ARKit и ARCore"],"ar":["تحويل تكوينات Antigravity IDE لتطوير PCVR","генерировать صيغ متوافقة لتجارب المتصفح المبنية على WebXR","تحسين تطوير الواقع المعزز باستخدام ARKit و ARCore"]},"limitations":{"en":["Requires Antigravity IDE configuration files","Compatibility limited to specified VR/AR platforms"],"zh":["需要 Antigravity IDE 配置文件","兼容性仅限于指定的 VR/AR 平台"],"ja":["Antigravity IDE 構成ファイルが必要","互換性は指定された VR/AR プラットフォームに限定される"],"ko":["Antigravity IDE 구성 파일이 필요","호환성은 지정된 VR/AR 플랫폼에만 제한"],"es":["Requiere archivos de configuración de Antigravity IDE","Compatibilidad limitada a las plataformas de realidad virtual/aumentada especificadas"],"fr":["Nécessite des fichiers de configuration d''Antigravity IDE","Compatibilité limitée aux plateformes de réalité virtuelle/augmentée spécifiées"],"de":["Benötigt Antigravity IDE-Konfigurationsdateien","Kompatibilität auf die angegebenen VR/AR-Plattformen beschränkt"],"pt":["Requer arquivos de configuração do Antigravity IDE","Compatibilidade limitada às plataformas de VR/AR especificadas"],"ru":["Требует файлов конфигурации Antigravity IDE","Совместимость ограничена указанными платформами VR/AR"],"ar":["يتطلب ملفات تكوين Antigravity IDE","التوافق مقيد بالمنصات المحددة من VR/AR"]},"version":4},"contentHash":"59ddbdecc4fa17e74c4747f5f02bd69edb8bffcd1cdc2866dd6a053e19bc139e","qualityScore":26}');
