INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HaoNgo232/agent-bridge-kit/vr-ar', 'vr-ar', 'HaoNgo232', 'agent-bridge-kit', 'community', 'vr-ar HaoNgo232 agent-bridge-kit community The vr-ar skill converts configurations from Antigravity IDE to formats compatible with IDEs and CLIs, benefiting developers working with VR/AR platforms like Quest, PCVR, and WebXR. VR/AR开发工具配置转换工具，支持Quest、PCVR、PSVR、WebXR、ARKit、ARCore和HoloLens等平台 VR/AR開発ツール設定変換ツール。Quest、PCVR、PSVR、WebXR、ARKit、ARCore、HoloLensなどのプラットフォームをサポート VR/AR 개발 도구 설정 변환 도구. Quest, PCVR, PSVR, WebXR, ARKit, ARCore, HoloLens 등의 플랫폼을 지원합니다 Herramienta para convertir configuraciones de vr-ar a formatos compatibles con IDEs y CLIs. Soporta plataformas como Quest, PCVR, PSVR, WebXR, ARKit, ARCore y HoloLens. Outil pour convertir les configurations de vr-ar en formats compatibles avec les IDE et les CLIs. Prend en charge les plates-formes telles que Quest, PCVR, PSVR, WebXR, ARKit, ARCore et HoloLens. Werkzeug zum Konvertieren von vr-ar-Konfigurationen in Formate, die mit IDEs und CLIs kompatibel sind. Unterstützt Plattformen wie Quest, PCVR, PSVR, WebXR, ARKit, ARCore und HoloLens. O VR/AR é uma ferramenta para converter configurações de Agent, Skill e Workflows do Antigravity IDE para formatos compatíveis com IDEs e CLIs. VR/AR - это инструмент для конвертации конфигураций Agent, Skill и Workflows из Antigravity IDE в форматы, совместимые с ИИ Агентами и инструментами разработки. الواقع الافتراضي والمعزز هو أداة لتحويل تكوين الوكيل والمهارة والتدفقات العمل من Antigravity IDE إلى تنسيقات متوافقة مع الأدوات البرمجية how to use vr-ar vr-ar setup guide vr-ar vs arkit webxr development vr-ar install vr-ar alternative what is vr-ar immersive experience development vr-ar compatible platforms github copilot vr-ar VR/AR开发工具 Antigravity IDE配置转换 GitHub Copilot Cursor Kiro OpenCode VR平台 AR平台 Immersive experience principles Supports VR platform selection, including Quest, PCVR, and PSVR Enables AR development with ARKit, ARCore, WebXR, and HoloLens Provides comfort principles for immersive experience development Compatible with GitHub Copilot, Cursor, Kiro, and OpenCode Facilitates browser-based AR development with WebXR Offers standalone, wireless, and high-fidelity VR experiences vr-ar is a tool for converting Agent, Skill, and Workflows configurations to compatible formats for various IDEs and CLIs, enabling immersive experience development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('angular/angular/reference-core', 'community', 'angular', 'angular', 'angular/angular', 'reference-core', 0, 0, 26, '2026-03-08T01:57:15.562Z', '2026-03-08T02:11:35.967Z', 'c4c1c69569c62394fd6727ed0d09ca281d842fe48fd812d766e56b11320239d6', '{"id":"angular/angular/reference-core","name":"reference-core","description":{"en":"reference-core delivers web apps with confidence by providing the runtime logic for Angular, managing rendering, dependency injection, and change detection. This skill benefits Angular developers.","zh":"reference-core 是 Angular 框架的核心，提供 Ivy/Render3 渲染、依赖注入和变化检测等功能，帮助开发者打造高性能的 Web 应用","ja":"reference-core は Angular フレームワークの核であり、Ivy/Render3 レンダリング、依存性注入、変更検知などの機能を提供し、高パフォーマンスの Web アプリを作成するのに役立ちます","ko":"reference-core는 Angular 프레임워크의 핵심으로, Ivy/Render3 렌더링, 의존성 주입, 변경 감지 등의 기능을 제공하여 고성능의 웹앱을 개발하는 데 도움을 줍니다","es":"Reference-core es el núcleo de la arquitectura de Angular, proporcionando funcionalidades como rendering, inyección de dependencias y detección de cambios","fr":"Reference-core est le cœur de l''architecture d''Angular, offrant des fonctionnalités telles que le rendu, l''injection de dépendances et la détection de changements","de":"Reference-core ist der Kern der Angular-Architektur und bietet Funktionen wie Rendering, Abhängigkeitsinjektion und Änderungserkennung","pt":"O reference-core é o núcleo do framework Angular, responsável por renderização, injeção de dependência e detecção de alterações","ru":"reference-core является сердцем фреймворка Angular, ответственного за рендеринг, внедрение зависимостей и обнаружение изменений для ИИ Агентов","ar":"مرجعي_core هو قلب إطار العمل Angular، المسؤول عن تحويل القوالب وتحديثات DOM وإدارة الكائنات"},"seo":{"title":{"en":"reference-core: Angular Core Setup Guide | AI Agent Skill","zh":"reference-core 架构指南：Angular Core 高级设置","ja":"reference-core のベストプラクティス：Angular Core を使った Web アプリ開発","ko":"reference-core 설정 가이드: Angular Core를 이용한 웹앱 개발","es":"Guía de configuración de reference-core para aplicaciones...","fr":"Guide de démarrage de reference-core pour les application...","de":"Einrichtungsleitfaden für reference-core in Webanwendungen","pt":"Guia de Configuração do reference-core para Desenvolvedores","ru":"Руководство по настройке reference-core для ИИ Агентов","ar":"دليل إعداد مرجعي_core لمنصة التطبيقات الويب"},"description":{"en":"Unlock confident web app delivery with reference-core. Learn how to harness Angular Core''s rendering, dependency injection, and change detection capabilities.","zh":"了解 reference-core 的技术细节，包括 Ivy/Render3 渲染、依赖注入和变化检测，打造高性能的 Angular Web 应用","ja":"reference-core の技術的詳細を学び、Ivy/Render3 レンダリング、依存性注入、変更検知を使用して、高パフォーマンスの Angular Web アプリを作成する","ko":"reference-core의 기술적 세부사항을 익히고, Ivy/Render3 렌더링, 의존성 주입, 변경 감지를 사용하여 고성능의 Angular 웹앱을 개발하세요","es":"Aprende a entregar aplicaciones web con confianza utilizando reference-core, con características como Ivy/Render3 y Dependency Injection","fr":"Découvrez comment livrer des applications web avec confiance en utilisant reference-core, avec des fonctionnalités comme Ivy/Render3 et Injection de dépendances","de":"Erfahren Sie, wie Sie Webanwendungen mit reference-core und Funktionen wie Ivy/Render3 und Abhängigkeitsinjektion mit Vertrauen bereitstellen","pt":"Aprenda a entregar aplicativos web com confiança usando o reference-core e suas funcionalidades de renderização Ivy/Render3 e injeção de dependência","ru":"Узнайте, как доставлять веб-приложения с уверенностью, используя reference-core и его возможности рендеринга Ivy/Render3 и внедрения зависимостей для ИИ Агентов","ar":"تعلم كيفية تسليم التطبيقات الويب بثقة باستخدام مرجعي_core ووظائفه في تحويل القوالب إلى تحديثات DOM"},"definition":{"en":"reference-core is the heart of the Angular framework, containing the runtime logic for rendering, dependency injection, and change detection.","zh":"reference-core 是 Angular 框架的核心组件，负责渲染、依赖注入和变化检测等功能","ja":"reference-core は Angular フレームワークの核心コンポーネントであり、レンダリング、依存性注入、変更検知などの機能を担当します","ko":"reference-core는 Angular 프레임워크의 핵심 컴포넌트로서 렌더링, 의존성 주입, 변경 감지 등의 기능을 담당합니다","es":"Reference-core es el componente central de Angular que gestiona la lógica de ejecución y proporciona funcionalidades clave","fr":"Reference-core est le composant central d''Angular qui gère la logique d''exécution et fournit des fonctionnalités clés","de":"Reference-core ist das zentrale Komponenten von Angular, das die Laufzeitlogik verwaltet und wichtige Funktionen bereitstellt","pt":"O reference-core é um componente central do Angular que gerencia a lógica de execução","ru":"reference-core - это центральный компонент Angular, который управляет логикой выполнения для ИИ Агентов","ar":"مرجعي_core هو مكون مركزي في إطار العمل Angular لإدارة 논理 التشغيل"},"features":{"en":["Transforms templates into DOM updates using Ivy/Render3 rendering","Manages object creation and lifetime via Dependency Injection (DI)","Synchronizes the model with the view using Change Detection","Contains the primary responsibilities of the Angular framework in packages/core"],"zh":["Ivy/Render3 渲染","依赖注入（DI）","变化检测","高性能 Web 应用开发"],"ja":["Ivy/Render3 レンダリング","依存性注入（DI）","変更検知","高パフォーマンス Web アプリ開発"],"ko":["Ivy/Render3 렌더링","의존성 주입（DI）","변경 감지","고성능 웹앱 개발"],"es":["Rendering con Ivy/Render3","Inyección de dependencias (DI)","Detección de cambios","Arquitectura de ejecución de Angular","Gestión de la lógica de ejecución"],"fr":["Rendu avec Ivy/Render3","Injection de dépendances (DI)","Détection de changements","Architecture d''exécution d''Angular","Gestion de la logique d''exécution"],"de":["Rendering mit Ivy/Render3","Abhängigkeitsinjektion (DI)","Änderungserkennung","Ausführungsarchitektur von Angular","Verwaltung der Laufzeitlogik"],"pt":["Renderização Ivy/Render3 para transformar templates em atualizações DOM","Injeção de dependência para gerenciar a criação e vida útil de objetos","Detecção de alterações para sincronizar o modelo com a vista","Arquitetura de alto nível para o núcleo do Angular","Gerenciamento de objetos com Dependency Injection"],"ru":["Рендеринг Ivy/Render3 для преобразования шаблонов в обновления DOM","Внедрение зависимостей для управления созданием и жизнью объектов","Обнаружение изменений для синхронизации модели с представлением","Высокоуровневая архитектура для ядра Angular","Управление объектами с помощью внедрения зависимостей для ИИ Агентов"],"ar":["تحويل القوالب إلى تحديثات DOM باستخدام Ivy/Render3","إدارة الكائنات مع الإدخال التبعي","التحقق من التغييرات لتنسيق النموذج مع العرض","هيكل معماري مركزي لمرجعي_core","إدارة الكائنات باستخدام الإدخال التبعي"]},"keywords":{"en":["how to use reference-core","what is reference-core","reference-core alternative","reference-core vs React","reference-core install","reference-core setup guide","Angular Core tutorial","Ivy/Render3 rendering example","Dependency Injection in Angular"],"zh":["reference-core","Angular Core","Ivy/Render3","依赖注入","变化检测","高性能 Web 应用","AIエージェント","Angular开发"],"ja":["reference-core","Angular Core","Ivy/Render3","依存性注入","変更検知","高パフォーマンス Web アプリ","AIエージェント","Angular開発"],"ko":["reference-core","Angular Core","Ivy/Render3","의존성 주입","변경 감지","고성능 웹앱","AI 에이전트","Angular 개발"],"es":["reference-core","Angular","Ivy/Render3","Inyección de dependencias","Detección de cambios","Desarrollo web","Arquitectura de software","Herramientas de desarrollo","AI Herramientas"],"fr":["reference-core","Angular","Ivy/Render3","Injection de dépendances","Détection de changements","Développement web","Architecture logicielle","Outils de développement","Outils d''IA"],"de":["reference-core","Angular","Ivy/Render3","Abhängigkeitsinjektion","Änderungserkennung","Webentwicklung","Softwarearchitektur","Entwicklungstools","KI-Tools"],"pt":["reference-core","Angular","renderização Ivy/Render3","injeção de dependência","detecção de alterações","desenvolvimento web","aplicativos web","framework Angular"],"ru":["reference-core","Angular","рендеринг Ivy/Render3","внедрение зависимостей","обнаружение изменений","разработка веб-приложений","веб-приложения","фреймворк Angular","ИИ Агенты"],"ar":["مرجعي_core","Angular","تحويل القوالب إلى تحديثات DOM","إدارة الكائنات","التحقق من التغييرات","تطوير التطبيقات الويب","التطبيقات الويب","إطار العمل Angular"]}},"owner":"angular","repo":"angular","repoPath":"angular/angular","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.562Z","topics":[],"category":"community","skillMd":{"name":"reference-core","description":"Explains the mental model and architecture of the code under `packages/core`. You MUST use this skill any time you plan to work with code in `packages/core`","bodyPreview":"# Angular Core (`packages/core`) Mental Model\n\nThis document outlines the architecture and mental model for `packages/core`, the heart of the Angular framework.\n\n## 1. High-Level Architecture\n\n`packages/core` contains the runtime logic for Angular. Its primary responsibilities are:\n\n1.  **Rendering (Ivy/Render3)**: Transforming templates into DOM updates.\n2.  **Dependency Injection (DI)**: Managing object creation and lifetime.\n3.  **Change Detection**: Synchronizing the model with the view.\n4.","body":"# Angular Core (`packages/core`) Mental Model\n\nThis document outlines the architecture and mental model for `packages/core`, the heart of the Angular framework.\n\n## 1. High-Level Architecture\n\n`packages/core` contains the runtime logic for Angular. Its primary responsibilities are:\n\n1.  **Rendering (Ivy/Render3)**: Transforming templates into DOM updates.\n2.  **Dependency Injection (DI)**: Managing object creation and lifetime.\n3.  **Change Detection**: Synchronizing the model with the view.\n4.  **Reactivity**: Signals and Zone.js integration.\n\n## 2. Rendering Engine (Ivy / Render3)\n\nThe rendering engine (located in `packages/core/src/render3`) uses an **instruction-based** approach.\n\n### Key Concepts\n\n- **Instructions**: The Angular compiler transforms templates into a sequence of instruction calls (e.g., `ɵɵelementStart`, `ɵɵtext`, `ɵɵproperty`). These instructions are executed at runtime to create and update the view.\n  - _Location_: `packages/core/src/render3/instructions`\n\n- **LView (Logical View)**: An array containing the _state_ of a specific view instance. It holds:\n  - DOM nodes (`RElement`, `RText`).\n  - Binding values (for change detection).\n  - Directive/Component instances.\n  - _Context_: `packages/core/src/render3/interfaces/view.ts`\n\n- **TView (Template View)**: An array containing the _static structure_ of a view. It is shared across all instances (`LView`s) of the same component/template. It holds:\n  - Property names for bindings.\n  - Node relationship information.\n  - Compiled directive definitions.\n  - _Context_: `packages/core/src/render3/interfaces/view.ts`\n\n- **Memory Layout**: `LView` and `TView` are parallel arrays. Index `i` in `LView` corresponds to metadata at index `i` in `TView`.\n  - `HEADER`: Fixed size, contains context (Parent, Host, etc.).\n  - `DECLS`: Static nodes (elements, text, pipes).\n  - `VARS`: Binding values.\n  - `EXPANDO`: Dynamic data (host bindings, injectors).\n\n### The Render Cycle\n\n1.  **Creation Mode**: Instructions create DOM nodes and store them in `LView`.\n2.  **Update Mode**: Instructions check current values against previous values stored in `LView`. If changed, they update the DOM.\n\n## 3. Dependency Injection (DI)\n\nDI in Angular is hierarchical and split into two systems that interact:\n\n### Module Injector (`R3Injector`)\n\n- Configured via `@NgModule.providers` or `providedIn: ''root''`.\n- Stored in a hierarchy of `R3Injector` instances.\n- _Location_: `packages/core/src/di/r3_injector.ts`\n\n### Node Injector\n\n- Configured via `@Component.providers` or `@Directive.providers`.\n- **Not a class**, but a data structure embedded in the `LView` (\"Expando\" section).\n- Uses **Bloom Filters** (`TView.data`) to quickly check if a token is present at a specific node index before traversing up the tree.\n- Resolves tokens starting from the current node, walking up the view tree (Element Injector hierarchy), and falling back to the Module Injector if not found.\n\n## 4. Change Detection\n\n- **Dirty Checking**: Angular checks if values bound in templates have changed.\n- **Strategies**:\n  - `Default`: Checks everything.\n  - `OnPush`: Checks only if inputs change, events fire, or signals update.\n- **Signals**: The new reactivity primitive. Signals notify the scheduler when they change, potentially allowing for fine-grained updates (Zoneless).\n\n## 5. Key Directories to Know\n\n- `src/render3`: The Ivy rendering engine.\n  - `instructions`: The runtime instructions called by compiled code.\n  - `interfaces`: `LView`, `TView`, `TNode` definitions.\n- `src/di`: Dependency injection system.\n- `src/change_detection`: Change detection logic.\n- `src/zone`: Zone.js integration.\n- `src/signal`: Signals implementation (if present in this version, otherwise likely in `primitives`).\n\n## 6. Conventions & Gotchas\n\n- **Prefixes**: Private/Internal exports often start with `ɵ`.\n- **Global State**: Ivy relies heavily on global state (e.g., `getLView()`) during instruction execution to avoid passing context arguments everywhere. This is for performance and code size.\n- **Performance**: The code is highly optimized for performance and memory. You will see arrays used instead of objects, bitmasks, and manual memory management patterns. **Respect these patterns.**\n\n## 7. How to Modify Core\n\n1.  **Understand the Instruction**: If modifying runtime behavior, find the corresponding instruction in `src/render3/instructions`.\n2.  **Check `LView`/`TView` Impact**: If adding state, understand where it fits in the `LView` array.\n3.  **Tests**: Core has extensive tests. Run them using Bazel.\n"},"lastSynced":"2026-03-08T02:11:35.967Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents specializing in Angular development, needing advanced rendering, dependency injection, and change detection capabilities.","zh":"适合专门从事Angular开发的前端代理，需要高级渲染、依赖注入和变更检测功能。","ja":"Angular開発を専門とするフロントエンドエージェントに適しています。高度なレンダリング、依存性の注入、および変更検出機能が必要です。","ko":"Angular 개발을 전문으로 하는 프론트엔드 에이전트에게 적합합니다. 고급 렌더링, 의존성 주입 및 변경 감지 기능이 필요합니다.","es":"Perfecto para agentes de frontend especializados en desarrollo de Angular, que necesitan capacidades de renderizado avanzado, inyección de dependencias y detección de cambios.","fr":"Parfait pour les agents frontend spécialisés dans le développement Angular, nécessitant des capacités de rendu avancées, d''injection de dépendances et de détection de changements.","de":"Perfekt für Frontend-Agents, die auf Angular-Entwicklung spezialisiert sind und erweiterte Rendering-, Dependency-Injection- und Change-Detection-Fähigkeiten benötigen.","pt":"Perfeito para Agentes Frontend especializados em desenvolvimento Angular, necessitando de capacidades avançadas de renderização, injeção de dependência e detecção de alterações.","ru":"Идеально подходит для агентов Frontend, специализирующихся на разработке Angular, требующих продвинутых возможностей рендеринга, внедрения зависимостей и обнаружения изменений.","ar":"مثالي للوكلاء الأمامية المتخصصة في تطوير Angular، بحاجة إلى قدرات متقدمة في العرض والتوصيل بالاعتماد والكشف عن التغييرات."},"recommendation":{"en":"Empowers agents to manage rendering with Ivy/Render3, leverage dependency injection for efficient object creation, and synchronize models with views through robust change detection, utilizing the Angular Core (`packages/core`) mental model.","zh":"赋予代理管理渲染的能力，使用Ivy/Render3，利用依赖注入进行高效的对象创建，并通过强大的变更检测同步模型与视图，利用Angular Core（`packages/core`）的心理模型。","ja":"エージェントにレンダリングを管理する能力を与え、Ivy/Render3を使用し、依存性の注入を使用して効率的なオブジェクトの作成を行い、強力な変更検出を使用してモデルとビューを同期する、Angular Core（`packages/core`）のメンタルモデルを使用します。","ko":"에이전트에게 렌더링을 관리하는 능력을 부여하고, Ivy/Render3를 사용하며, 의존성 주입을 사용하여 효율적인 객체 생성을 수행하며, 강력한 변경 감지를 사용하여 모델과 뷰를 동기화하고, Angular Core(`packages/core`)的心理 모델을 사용합니다.","es":"Habilita a los agentes a gestionar el renderizado con Ivy/Render3, aprovechar la inyección de dependencias para una creación eficiente de objetos y sincronizar modelos con vistas a través de una robusta detección de cambios, utilizando el modelo mental de Angular Core (`packages/core`)","fr":"Permet aux agents de gérer le rendu avec Ivy/Render3, d''exploiter l''injection de dépendances pour une création d''objets efficace et de synchroniser les modèles avec les vues via une détection de changements robuste, en utilisant le modèle mental d''Angular Core (`packages/core`)","de":"Ermächtigt die Agenten, das Rendering mit Ivy/Render3 zu verwalten, die Dependency-Injection für eine effiziente Objekterstellung zu nutzen und Modelle mit Ansichten durch eine robuste Change-Detection zu synchronisieren, unter Verwendung des Angular Core (`packages/core`) mentalen Modells.","pt":"Habilita os agentes a gerenciar a renderização com Ivy/Render3, aproveitar a injeção de dependência para criação eficiente de objetos e sincronizar modelos com visualizações por meio de detecção robusta de alterações, utilizando o modelo mental do Angular Core (packages/core).","ru":"Наделяет агентов возможностью управлять рендерингом с помощью Ivy/Render3, использовать внедрение зависимостей для эффективного создания объектов и синхронизировать модели с представлениями посредством прочного обнаружения изменений, используя ментальную модель Angular Core (packages/core).","ar":"تمكّن الوكلاء من إدارة العرض باستخدام Ivy/Render3، واستخدام الحقن بالاعتماد لإنشاء كائنات فعالة، وتنسيق النماذج مع العروض من خلال كشف متين عن التغييرات، باستخدام نموذج Angular Core العقلي (packages/core)."},"useCases":{"en":["Rendering dynamic templates into DOM updates","Implementing dependency injection for efficient object management","Debugging change detection issues in Angular applications"],"zh":["将动态模板渲染为DOM更新","实现依赖注入以进行高效的对象管理","在Angular应用程序中调试变更检测问题"],"ja":["動的なテンプレートをDOM更新としてレンダリングする","依存性の注入を実装して効率的なオブジェクト管理を行う","Angularアプリケーションでの変更検出問題のデバッグ"],"ko":["동적 템플릿을 DOM 업데이트로 렌더링하는 것","의존성 주입을 구현하여 효율적인 객체 관리를 수행하는 것","Angular 애플리케이션에서 변경 감지 문제를 디버깅하는 것"],"es":["Renderizado de plantillas dinámicas en actualizaciones de DOM","Implementación de inyección de dependencias para una gestión eficiente de objetos","Depuración de problemas de detección de cambios en aplicaciones Angular"],"fr":["Rendu de modèles dynamiques dans des mises à jour de DOM","Mise en œuvre d''une injection de dépendances pour une gestion efficace des objets","Débogage des problèmes de détection de changements dans les applications Angular"],"de":["Rendering dynamischer Vorlagen in DOM-Updates","Implementierung der Dependency-Injection für eine effiziente Objektverwaltung","Fehlerbehebung bei Change-Detection-Problemen in Angular-Anwendungen"],"pt":["Renderização de modelos dinâmicos em atualizações do DOM","Implementação de injeção de dependência para gerenciamento eficiente de objetos","Depuração de problemas de detecção de alterações em aplicações Angular"],"ru":["Рендеринг динамических шаблонов в обновления DOM","Реализация внедрения зависимостей для эффективного управления объектами","Отладка проблем обнаружения изменений в приложениях Angular"],"ar":["عرض القوالب الديناميكية في تحديثات DOM","تنفيذ الحقن بالاعتماد لإدارة الكائنات الفعالة","تصحيح أخطاء كشف التغييرات في تطبيقات Angular"]},"limitations":{"en":["Specific to Angular framework","Requires understanding of Angular Core architecture","Limited to web application development"],"zh":["特定于Angular框架","需要理解Angular Core架构","仅限于Web应用程序开发"],"ja":["Angularフレームワークに特有のもの","Angular Coreアーキテクチャの理解が必要","Webアプリケーション開発に限定"],"ko":["Angular 프레임워크에 특정된 것","Angular Core 아키텍처에 대한 이해가 필요","웹 애플리케이션 개발에만 국한"],"es":["Específico del framework Angular","Requiere comprensión de la arquitectura de Angular Core","Limitado al desarrollo de aplicaciones web"],"fr":["Spécifique au framework Angular","Nécessite une compréhension de l''architecture d''Angular Core","Limité au développement d''applications web"],"de":["Spezifisch für das Angular-Framework","Benötigt Verständnis der Angular Core-Architektur","Begrenzt auf die Entwicklung von Webanwendungen"],"pt":["Específico do framework Angular","Requer entendimento da arquitetura do Angular Core","Limitado ao desenvolvimento de aplicações web"],"ru":["Специфичен для фреймворка Angular","Требует понимания архитектуры Angular Core","Ограничен разработкой веб-приложений"],"ar":["محدد لإطار Angular","يتطلب فهمًا للهيكل المعماري للنواة Angular","محدود بتطوير تطبيقات الويب"]},"version":4},"contentHash":"c4c1c69569c62394fd6727ed0d09ca281d842fe48fd812d766e56b11320239d6","qualityScore":26}');
