INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('angular/angular/reference-core', 'reference-core', 'angular', 'angular', 'community', 'reference-core angular angular community reference-core delivers web apps with confidence by providing the runtime logic for Angular, managing rendering, dependency injection, and change detection. This skill benefits Angular developers. reference-core 是 Angular 框架的核心，提供 Ivy/Render3 渲染、依赖注入和变化检测等功能，帮助开发者打造高性能的 Web 应用 reference-core は Angular フレームワークの核であり、Ivy/Render3 レンダリング、依存性注入、変更検知などの機能を提供し、高パフォーマンスの Web アプリを作成するのに役立ちます reference-core는 Angular 프레임워크의 핵심으로, Ivy/Render3 렌더링, 의존성 주입, 변경 감지 등의 기능을 제공하여 고성능의 웹앱을 개발하는 데 도움을 줍니다 Reference-core es el núcleo de la arquitectura de Angular, proporcionando funcionalidades como rendering, inyección de dependencias y detección de cambios Reference-core est le cœur de l''architecture d''Angular, offrant des fonctionnalités telles que le rendu, l''injection de dépendances et la détection de changements Reference-core ist der Kern der Angular-Architektur und bietet Funktionen wie Rendering, Abhängigkeitsinjektion und Änderungserkennung O reference-core é o núcleo do framework Angular, responsável por renderização, injeção de dependência e detecção de alterações reference-core является сердцем фреймворка Angular, ответственного за рендеринг, внедрение зависимостей и обнаружение изменений для ИИ Агентов مرجعي_core هو قلب إطار العمل Angular، المسؤول عن تحويل القوالب وتحديثات DOM وإدارة الكائنات how to use reference-core what is reference-core reference-core alternative reference-core vs React reference-core install reference-core setup guide Angular Core tutorial Ivy/Render3 rendering example Dependency Injection in Angular reference-core Angular Core Ivy/Render3 依赖注入 变化检测 高性能 Web 应用 AIエージェント Angular开发 Transforms templates into DOM updates using Ivy/Render3 rendering Manages object creation and lifetime via Dependency Injection (DI) Synchronizes the model with the view using Change Detection Contains the primary responsibilities of the Angular framework in packages/core reference-core is the heart of the Angular framework, containing the runtime logic for rendering, dependency injection, and change detection.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flutter/flutter-intellij/triage-helper', 'community', 'flutter', 'flutter-intellij', 'flutter/flutter-intellij', 'triage-helper', 0, 0, 26, '2026-03-08T01:57:15.562Z', '2026-03-08T02:11:37.003Z', '1e680800adb1a9e060dfd749d2652e3721183ff60afac59329e8ec01b70bf884', '{"id":"flutter/flutter-intellij/triage-helper","name":"triage-helper","description":{"en":"The triage-helper skill assists users with GitHub issue triage in the CLI, finding latest open issues in the Flutter IntelliJ repo. It benefits developers working with Flutter and IntelliJ.","zh":"triage-helper是Flutter插件，帮助您通过CLI高效解决问题。它从GitHub仓库中找出最新的未解决问题，并提供详细的设置说明","ja":"triage-helperはFlutterプラグインであり、CLIを介して問題を効率的に解決するのに役立ちます。GitHubリポジトリから最新の未解決問題を見つけて設定の詳細な説明を提供します","ko":"triage-helper는 Flutter 플러그인으로, CLI를 통해 문제를 효율적으로 해결하는 데 도움이 됩니다. GitHub 저장소에서 최신의 미해결 문제를 찾고 설정에 대한 자세한 설명을 제공합니다","es":"triage-helper es un plugin de Flutter para IntelliJ que ayuda a los usuarios a encontrar y priorizar problemas en el repositorio de GitHub","fr":"triage-helper est un plugin Flutter pour IntelliJ qui aide les utilisateurs à trouver et à prioriser les problèmes dans le référentiel GitHub","de":"triage-helper ist ein Flutter-Plugin für IntelliJ, das Benutzern hilft, Probleme im GitHub-Repository zu finden und zu priorisieren","pt":"O Triage-Helper é um plugin do IntelliJ para Flutter que auxilia na triagem de issues do GitHub. Ele apresenta as issues mais recentes sem prioridade e fornece orientação para resolver problemas de autenticação","ru":"Triage-Helper - плагин для IntelliJ для Flutter, который помогает в сортировке задач на GitHub. Он показывает последние задачи без приоритета и дает рекомендации по устранению проблем с аутентификацией","ar":"مساعد التriage هو مكون إضافي للغة Flutter الذي يساعد في فرز المسائل على GitHub. إنه يعرض أحدث المسائل بدون أولوية ويوفر