INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flutter/flutter-intellij/triage-helper', 'triage-helper', 'flutter', 'flutter-intellij', 'community', 'triage-helper flutter flutter-intellij community The triage-helper skill assists users with GitHub issue triage in the CLI, finding latest open issues in the Flutter IntelliJ repo. It benefits developers working with Flutter and IntelliJ. triage-helper是Flutter插件，帮助您通过CLI高效解决问题。它从GitHub仓库中找出最新的未解决问题，并提供详细的设置说明 triage-helperはFlutterプラグインであり、CLIを介して問題を効率的に解決するのに役立ちます。GitHubリポジトリから最新の未解決問題を見つけて設定の詳細な説明を提供します triage-helper는 Flutter 플러그인으로, CLI를 통해 문제를 효율적으로 해결하는 데 도움이 됩니다. GitHub 저장소에서 최신의 미해결 문제를 찾고 설정에 대한 자세한 설명을 제공합니다 triage-helper es un plugin de Flutter para IntelliJ que ayuda a los usuarios a encontrar y priorizar problemas en el repositorio de GitHub triage-helper est un plugin Flutter pour IntelliJ qui aide les utilisateurs à trouver et à prioriser les problèmes dans le référentiel GitHub triage-helper ist ein Flutter-Plugin für IntelliJ, das Benutzern hilft, Probleme im GitHub-Repository zu finden und zu priorisieren O Triage-Helper é um plugin do IntelliJ para Flutter que auxilia na triagem de issues do GitHub. Ele apresenta as issues mais recentes sem prioridade e fornece orientação para resolver problemas de autenticação Triage-Helper - плагин для IntelliJ для Flutter, который помогает в сортировке задач на GitHub. Он показывает последние задачи без приоритета и дает рекомендации по устранению проблем с аутентификацией مساعد التriage هو مكون إضافي للغة Flutter الذي يساعد في فرز المسائل على GitHub. إنه يعرض أحدث المسائل بدون أولوية ويوفر إرشادات لحل مشاكل المصادقة how to use triage-helper triage-helper setup guide triage-helper alternative triage-helper vs GitHub issue manager triage-helper install what is triage-helper triage-helper for IntelliJ GitHub issue triage with triage-helper triage-helper for Flutter developers triage-helper Flutter插件 CLI问题解决 GitHub仓库 AI工具 问题解决流程 github-mcp-server gh auth status Finds latest open issues in the https://github.com/flutter/flutter-intellij/ repo without a priority label Guides users to check their `github-mcp-server` setup or `gh auth status` for authentication issues References `docs/Triaging.md` for detailed setup instructions Presents issues one at a time to the user, including issue URL and other details Considers the most recently updated issues first for efficient triage triage-helper is a Flutter Plugin for IntelliJ that aids in GitHub issue triage by finding and presenting open issues for efficient resolution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nicanac/familly-journal/agent-memory-systems', 'community', 'nicanac', 'familly-journal', 'nicanac/familly-journal', 'agent-memory-systems', 0, 0, 26, '2026-03-08T01:57:15.565Z', '2026-03-08T02:11:39.937Z', 'c45f6da6e83d7740b91c32e9ba5a7320bbdc4e5c973416af6371b53e599f1dc6', '{"id":"nicanac/familly-journal/agent-memory-systems","name":"agent-memory-systems","description":{"en":"Agent-memory-systems enables cognitive architects to build intelligent agents by optimizing memory retrieval. It helps overcome memory failures that resemble intelligence failures.","zh":"AI智能代理内存系统是代理智能的核心，设计高效的内存检索机制至关重要。","ja":"AIエージェントのメモリーシステムはエージェントの知能の核となるため、効率的なメモリ検索メカニズムの設計が重要である。","ko":"AI 에이전트의 메모리 시스템은 에이전트의 지능의 핵심이므로 효율적인 메모리 검색 메커니즘의 설계가 중요하다.","es":"Los sistemas de memoria de agentes permiten a los agentes de inteligencia artificial recordar y recuperar información de manera efectiva","fr":"Les systèmes de mémoire d''agents permettent aux agents de l''IA de mémoriser et de récupérer des informations de manière efficace","de":"Agenten-Memory-Systeme ermöglichen es KI-Agents, Informationen effektiv zu speichern und wiederzuerlangen","pt":"Sistemas de memória de agentes permitem que os agentes lidem com milhões de interações de forma inteligente","ru":"Системы памяти ИИ Агентов позволяют агентам обрабатывать миллионы взаимодействий интеллектуально","ar":"أنظمة الذاكرة للوكلاء الذكاء الاصطناعي تمكن الوكلاء من التعامل مع ملايين التفاعلات بذهن متقدم"},"seo":{"title":{"en":"Agent-Memory-Systems: Retrieval Optimization for AI Agent...","zh":"AI智能代理内存系统配置指南","ja":"AIエージェントのメモリーシステム設定ガイド","ko":"AI 에이전트 메모리 시스템 구축 가이드","es":"Guía de Configuración de Sistemas de Memoria de Agentes","fr":"Meilleures Pratiques pour les Systèmes de Mémoire d''Agents","de":"Leitfaden für Agenten-Memory-Systeme","pt":"Guia de Configuração de Sistemas de Memória de Agentes","ru":"Руководство по настройке систем памяти ИИ Агентов","ar":"دليل إعداد أنظمة الذاكرة للوكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock efficient memory retrieval for your AI agents. Learn how to implement chunking strategies and overcome memory failures with agent-memory-systems.","zh":"了解AI智能代理内存系统的设计原理，优化内存检索，提高代理的智能表现","ja":"AIエージェントのメモリーシステムを設計し、メモリの検索を最適化して、エージェントの知能を高める","ko":"AI 에이전트의 메모리 시스템을 설계하고 메모리 검색을 최적화하여 에이전트의 지능을 높이는 방법","es":"Aprende a diseñar sistemas de memoria para agentes de inteligencia artificial con nuestra guía de configuración y mejores prácticas","fr":"Découvrez comment améliorer la mémoire de vos agents avec nos meilleures pratiques et tutoriels","de":"Erfahren Sie, wie Sie Memory-Systeme für KI-Agents entwickeln und optimieren können","pt":"Aprenda a otimizar a memória dos agentes com estratégias de chunking e resolução de problemas de recuperação de memória","ru":"Узнайте, как оптимизировать память ИИ Агентов с помощью стратегий chunking и решения проблем извлечения памяти","ar":"تعلم كيفية تحسين الذاكرة للوكلاء الذكاء الاصطناعي باستخدام استراتيجيات chunking و حل مشاكل استرجاع الذاكرة"},"definition":{"en":"Agent-memory-systems is a technology that enables efficient memory retrieval for AI agents, focusing on chunking strategies to prevent memory failures.","zh":"AI智能代理内存系统是指代理存储和检索信息的机制，包括数据存储和检索策略。","ja":"AIエージェントのメモリーシステムとは、エージェントが情報を保存して検索するメカニズムのことであり、データ保存と検索戦略を含む。","ko":"AI 에이전트의 메모리 시스템이란 에이전트가 정보를 저장하고 검색하는 메커니즘을 말하며, 데이터 저장과 검색 전략을 포함한다.","es":"Un sistema de memoria de agentes es un componente que permite a los agentes de inteligencia artificial almacenar y recuperar información","fr":"Un système de mémoire d''agent est un composant qui permet aux agents de l''IA de stocker et de récupérer des informations","de":"Ein Agenten-Memory-System ist ein Komponente, der es KI-Agents ermöglicht, Informationen zu speichern und wiederzuerlangen","pt":"Sistema de memória de agente é um componente que permite que os agentes armazenem e recuperem informações","ru":"Система памяти ИИ Агента - это компонент, который позволяет агентам хранить и извлекать информацию","ar":"نظام الذاكرة للوكيل هو مكون يسمح للوكلاء بتخزين واسترجاع المعلومات"},"features":{"en":["Optimizes memory retrieval for AI agents handling millions of interactions","Implements chunking strategies to prevent memory failures","Overcomes intelligence failures caused by retrieval problems, not storage issues","Enables cognitive architects to build intelligent agents with efficient memory systems","Focuses on retrieval rather than storage to improve agent performance","Helps prevent inconsistent answers and forgetting in AI agents"],"zh":["高效的内存检索机制","数据存储和检索策略","代理智能的核心组件","支持代理处理大量交互","优化代理的智能表现"],"ja":["効率的なメモリ検索メカニズム","データ保存と検索戦略","エージェントの知能の核となるコンポーネント","大量の相互作用を処理するエージェントのサポート","エージェントの知能の表現を最適化"],"ko":["효율적인 메모리 검색 메커니즘","데이터 저장과 검색 전략","에이전트의 지능의 핵심 컴포넌트","大量의 상호작용을 처리하는 에이전트의 지원","에이전트의 지능의 표현을 최적화"],"es":["Diseño de estrategias de chunking para la recuperación de memoria","Implementación de algoritmos de recuperación de memoria efectivos","Optimización de la memoria para agentes que manejan millones de interacciones","Solución de problemas de recuperación de memoria para evitar fallos de inteligencia","Integración con herramientas de inteligencia artificial como React y Python"],"fr":["Conception de stratégies de chunking pour la récupération de mémoire","Mise en œuvre d''algorithmes de récupération de mémoire efficaces","Optimisation de la mémoire pour les agents qui gèrent des millions d''interactions","Résolution de problèmes de récupération de mémoire pour éviter les défaillances d''intelligence","Intégration avec des outils d''IA tels que React et Python"],"de":["Entwicklung von Chunking-Strategien für die Speicherung von Memory","Implementierung effektiver Algorithmen für die Speicherung von Memory","Optimierung der Memory für Agents, die Millionen von Interaktionen verarbeiten","Lösung von Problemen bei der Speicherung von Memory, um Intelligenzfehler zu vermeiden","Integration mit AI-Tools wie React und Python"],"pt":["Estratégias de chunking para otimizar a memória","Resolução de problemas de recuperação de memória","Armazenamento de milhões de interações","Recuperação de memória em tempo real","Integração com tecnologias de inteligência artificial"],"ru":["Стратегии chunking для оптимизации памяти","Решение проблем извлечения памяти","Хранение миллионов взаимодействий","Извлечение памяти в реальном времени","Интеграция с технологиями искусственного интеллекта"],"ar":["استراتيجيات chunking لتحسين الذاكرة","حل مشاكل استرجاع الذاكرة","تخزين ملايين التفاعلات","استرجاع الذاكرة في الوقت الفعلي","التكامل مع تكنولوجيا الذكاء الاصطناعي"]},"keywords":{"en":["how to use agent-memory-systems","agent-memory-systems setup guide","what is agent-memory-systems","agent-memory-systems alternative","agent-memory-systems vs competing technologies","agent-memory-systems install","agent-memory-systems retrieval optimization","chunking strategies for AI agents","overcoming memory failures in AI agents"],"zh":["AI智能代理","内存系统","代理智能","内存检索","数据存储","检索策略","AI开发","代理开发"],"ja":["AIエージェント","メモリーシステム","エージェントの知能","メモリ検索","データ保存","検索戦略","AI開発","エージェント開発"],"ko":["AI 에이전트","메모리 시스템","에이전트의 지능","메모리 검색","데이터 저장","검색 전략","AI 개발","에이전트 개발"],"es":["sistemas de memoria de agentes","inteligencia artificial","agentes de IA","diseño de sistemas de memoria","estrategias de chunking","algoritmos de recuperación de memoria","optimización de memoria","solución de problemas de recuperación de memoria"],"fr":["systèmes de mémoire d''agents","intelligence artificielle","agents de l''IA","conception de systèmes de mémoire","stratégies de chunking","algorithmes de récupération de mémoire","optimisation de la mémoire","résolution de problèmes de récupération de mémoire"],"de":["Agenten-Memory-Systeme","künstliche Intelligenz","KI-Agents","Entwicklung von Memory-Systemen","Chunking-Strategien","Algorithmen für die Speicherung von Memory","Optimierung der Memory","Lösung von Problemen bei der Speicherung von Memory"],"pt":["sistemas de memória de agentes","estratégias de chunking","recuperação de memória","inteligência artificial","agentes de IA","otimização de memória","desenvolvimento de agentes","tecnologias de IA"],"ru":["системы памяти ИИ Агентов","стратегии chunking","извлечение памяти","искусственный интеллект","ИИ Агенты","оптимизация памяти","разработка агентов","технологии ИИ"],"ar":["أنظمة الذاكرة للوكلاء","استراتيجيات chunking","استرجاع الذاكرة","الذكاء الاصطناعي","الوكلاء الذكاء الاصطناعي","تحسين الذاكرة","تطوير الوكلاء","تكنولوجيا الذكاء الاصطناعي"]}},"owner":"nicanac","repo":"familly-journal","repoPath":"nicanac/familly-journal","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.565Z","topics":[],"category":"community","skillMd":{"name":"agent-memory-systems","description":"Memory is the cornerstone of intelligent agents. Without it, every interaction starts from zero. This skill covers the architecture of agent memory: short-term (context window), long-term (vector stores), and the cognitive architectures that organize them.  Key insight: Memory isnt just storage - its retrieval. A million stored facts mean nothing if you cant find the right one. Chunking, embedding, and retrieval strategies determine whether your agent remembers or forgets.  The field is fragm","bodyPreview":"# Agent Memory Systems\n\nYou are a cognitive architect who understands that memory makes agents intelligent.\nYou''ve built memory systems for agents handling millions of interactions. You know\nthat the hard part isn''t storing - it''s retrieving the right memory at the right time.\n\nYour core insight: Memory failures look like intelligence failures. When an agent\n\"forgets\" or gives inconsistent answers, it''s almost always a retrieval problem,\nnot a storage problem. You obsess over chunking strategies","body":"# Agent Memory Systems\n\nYou are a cognitive architect who understands that memory makes agents intelligent.\nYou''ve built memory systems for agents handling millions of interactions. You know\nthat the hard part isn''t storing - it''s retrieving the right memory at the right time.\n\nYour core insight: Memory failures look like intelligence failures. When an agent\n\"forgets\" or gives inconsistent answers, it''s almost always a retrieval problem,\nnot a storage problem. You obsess over chunking strategies, embedding quality,\nand\n\n## Capabilities\n\n- agent-memory\n- long-term-memory\n- short-term-memory\n- working-memory\n- episodic-memory\n- semantic-memory\n- procedural-memory\n- memory-retrieval\n- memory-formation\n- memory-decay\n\n## Patterns\n\n### Memory Type Architecture\n\nChoosing the right memory type for different information\n\n### Vector Store Selection Pattern\n\nChoosing the right vector database for your use case\n\n### Chunking Strategy Pattern\n\nBreaking documents into retrievable chunks\n\n## Anti-Patterns\n\n### ❌ Store Everything Forever\n\n### ❌ Chunk Without Testing Retrieval\n\n### ❌ Single Memory Type for All Data\n\n## ⚠️ Sharp Edges\n\n| Issue | Severity | Solution |\n|-------|----------|----------|\n| Issue | critical | ## Contextual Chunking (Anthropic''s approach) |\n| Issue | high | ## Test different sizes |\n| Issue | high | ## Always filter by metadata first |\n| Issue | high | ## Add temporal scoring |\n| Issue | medium | ## Detect conflicts on storage |\n| Issue | medium | ## Budget tokens for different memory types |\n| Issue | medium | ## Track embedding model in metadata |\n\n## Related Skills\n\nWorks well with: `autonomous-agents`, `multi-agent-orchestration`, `llm-architect`, `agent-tool-builder`\n"},"lastSynced":"2026-03-08T02:11:39.937Z","agentAnalysis":{"suitability":{"en":"Ideal for Cognitive Architects building intelligent agents that require advanced memory retrieval and chunking strategies.","zh":"适合于构建需要高级内存检索和分块策略的智能代理的认知架构师。","ja":"高度なメモリの検索とチャンキング戦略を必要とする智能エージェントを構築する認知アーキテクトに最適。","ko":"고급 메모리 검색 및 청킹 전략이 필요한 지능형 에이전트를 구축하는 인지 아키텍트에게 적합합니다.","es":"Ideal para Arquitectos Cognitivos que construyen agentes inteligentes que requieren estrategias de recuperación de memoria y fragmentación avanzadas.","fr":"Idéal pour les Architectes Cognitifs qui construisent des agents intelligents nécessitant des stratégies de récupération de mémoire et de regroupement avancées.","de":"Ideal für Kognitive Architekten, die intelligente Agenten bauen, die erweiterte Speicherabruf- und Chunking-Strategien erfordern.","pt":"Ideal para Arquitetos Cognitivos que constroem agentes inteligentes que requerem recuperação de memória avançada e estratégias de chunking.","ru":"Идеально для когнитивных архитекторов, строящих интеллектуальные агенты, требующие передовой памяти и стратегий чанкинга.","ar":"مثالية لمهندسي البنية المعرفية الذين يبنين وكلاء ذكاء يحتاجون إلى استرجاع ذاكرة متقدم و استراتيجيات تشانكينج."},"recommendation":{"en":"Empowers agents to overcome memory failures by optimizing retrieval processes, utilizing chunking strategies to ensure consistent and accurate responses, and leveraging memory systems to handle millions of interactions.","zh":"赋予代理以优化检索过程、利用分块策略确保一致性和准确性的响应、并利用内存系统处理数百万交互的能力，以克服内存故障。","ja":"エージェントに、検索プロセスを最適化し、チャンキング戦略を利用しての一貫性と正確性を確保し、またメモリーシステムを利用して数百万のやり取りを処理することで、メモリの故障を克服する力を与える。","ko":"에이전트가 검색 프로세스를 최적화하고, 청킹 전략을 활용하여 일관성과 정확성을 보장하고, 메모리 시스템을 활용하여 수백만의 상호 작용을 처리함으로써 메모리 오류를 극복할 수 있는 능력을 부여합니다.","es":"Permite a los agentes superar los fallos de memoria al optimizar los procesos de recuperación, utilizando estrategias de fragmentación para garantizar respuestas consistentes y precisas, y aprovechando los sistemas de memoria para manejar millones de interacciones.","fr":"Permet aux agents de surmonter les défaillances de mémoire en optimisant les processus de récupération, en utilisant des stratégies de regroupement pour assurer des réponses cohérentes et précises, et en exploitant les systèmes de mémoire pour gérer des millions d''interactions.","de":"Ermöglicht es den Agenten, Speicherfehler zu überwinden, indem sie die Abrufprozesse optimieren, Chunking-Strategien nutzen, um konsistente und genaue Antworten sicherzustellen, und die Speichersysteme nutzen, um Millionen von Interaktionen zu bewältigen.","pt":"Habilita os agentes a superar falhas de memória, otimizando os processos de recuperação, utilizando estratégias de chunking para garantir respostas consistentes e precisas, e aproveitando os sistemas de memória para lidar com milhões de interações.","ru":"Наделяет агентов способностью преодолевать сбои памяти, оптимизируя процессы извлечения, используя стратегии чанкинга для обеспечения последовательных и точных ответов, и использует системы памяти для обработки миллионов взаимодействий.","ar":"تمكّن الوكلاء من تجاوز فشل الذاكرة من خلال تحسين عمليات الاسترجاع، واستخدام استراتيجيات تشانكينج لضمان استجابات متسقة ودقيقة، وتسخير أنظمة الذاكرة لمعالجة ملايين التفاعلات."},"useCases":{"en":["Optimizing memory retrieval for agents handling high-volume interactions","Implementing chunking strategies to improve memory consistency","Debugging memory failures to enhance agent intelligence"],"zh":["优化处理大量交互的代理的内存检索","实施分块策略以提高内存一致性","调试内存故障以增强代理智能"],"ja":["大量のやり取りを処理するエージェントのメモリの検索を最適化する","チャンキング戦略を実装してメモリの一貫性を向上させる","メモリの故障をデバッグしてエージェントの知能を高める"],"ko":["대량의 상호 작용을 처리하는 에이전트의 메모리 검색을 최적화하는 것","청킹 전략을 구현하여 메모리 일관성을 향상시키는 것","메모리 오류를 디버깅하여 에이전트의 지능을 향상시키는 것"],"es":["Optimizar la recuperación de memoria para agentes que manejan interacciones de alto volumen","Implementar estrategias de fragmentación para mejorar la consistencia de la memoria","Depurar fallos de memoria para mejorar la inteligencia del agente"],"fr":["Optimiser la récupération de mémoire pour les agents qui gèrent des interactions à haut volume","Mettre en œuvre des stratégies de regroupement pour améliorer la cohérence de la mémoire","Déboguer les défaillances de mémoire pour améliorer l''intelligence de l''agent"],"de":["Optimieren des Speicherabrufs für Agenten, die Interaktionen in großen Mengen verarbeiten","Implementieren von Chunking-Strategien, um die Speicher Konsistenz zu verbessern","Fehlerbehebung von Speicherfehlern, um die Intelligenz des Agenten zu verbessern"],"pt":["Otimizando a recuperação de memória para agentes que lidam com interações de alto volume","Implementando estratégias de chunking para melhorar a consistência da memória","Depurando falhas de memória para melhorar a inteligência do agente"],"ru":["Оптимизация извлечения памяти для агентов, обрабатывающих высокообъемные взаимодействия","Реализация стратегий чанкинга для улучшения последовательности памяти","Отладка сбоев памяти для повышения интеллекта агента"],"ar":["تحسين استرجاع الذاكرة للوكلاء الذين يتعاملون مع تفاعلات حجم عال","تنفيذ استراتيجيات تشانكينج لتحسين اتساق الذاكرة","تصحيح فشل الذاكرة لتحسين ذكاء الوكيل"]},"limitations":{"en":["Requires expertise in cognitive architecture and memory systems","May not be suitable for agents with simple storage needs"],"zh":["需要认知架构和内存系统方面的专业知识","可能不适合具有简单存储需求的代理"],"ja":["認知アーキテクチャとメモリーシステムの専門知識が必要","単純なストレージのニーズを持つエージェントには適さない可能性がある"],"ko":["인지 아키텍처 및 메모리 시스템에 대한 전문 지식이 필요합니다.","단순한 저장소需求을 가진 에이전트에게는 적합하지 않을 수 있습니다."],"es":["Requiere experiencia en arquitectura cognitiva y sistemas de memoria","Puede no ser adecuado para agentes con necesidades de almacenamiento simples"],"fr":["Nécessite une expertise en architecture cognitive et systèmes de mémoire","Peut ne pas être adapté pour les agents ayant des besoins de stockage simples"],"de":["Benötigt Erfahrung in kognitiver Architektur und Speichersystemen","Kann für Agenten mit einfachen Speicherbedürfnissen nicht geeignet sein"],"pt":["Requer conhecimento especializado em arquitetura cognitiva e sistemas de memória","Pode não ser adequado para agentes com necessidades de armazenamento simples"],"ru":["Требует специальных знаний в области когнитивной архитектуры и систем памяти","Может быть не подходящим для агентов с простыми потребностями в хранении"],"ar":["يتطلب خبرة متخصصة في الهندسة المعمارية المعرفية وأنظمة الذاكرة","قد لا يكون مناسباً للوكلاء الذين لديهم احتياجات تخزين بسيطة"]},"version":4},"contentHash":"c45f6da6e83d7740b91c32e9ba5a7320bbdc4e5c973416af6371b53e599f1dc6","qualityScore":26}');
