INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nicanac/familly-journal/agent-memory-systems', 'agent-memory-systems', 'nicanac', 'familly-journal', 'community', 'agent-memory-systems nicanac familly-journal community Agent-memory-systems enables cognitive architects to build intelligent agents by optimizing memory retrieval. It helps overcome memory failures that resemble intelligence failures. AI智能代理内存系统是代理智能的核心，设计高效的内存检索机制至关重要。 AIエージェントのメモリーシステムはエージェントの知能の核となるため、効率的なメモリ検索メカニズムの設計が重要である。 AI 에이전트의 메모리 시스템은 에이전트의 지능의 핵심이므로 효율적인 메모리 검색 메커니즘의 설계가 중요하다. Los sistemas de memoria de agentes permiten a los agentes de inteligencia artificial recordar y recuperar información de manera efectiva Les systèmes de mémoire d''agents permettent aux agents de l''IA de mémoriser et de récupérer des informations de manière efficace Agenten-Memory-Systeme ermöglichen es KI-Agents, Informationen effektiv zu speichern und wiederzuerlangen Sistemas de memória de agentes permitem que os agentes lidem com milhões de interações de forma inteligente Системы памяти ИИ Агентов позволяют агентам обрабатывать миллионы взаимодействий интеллектуально أنظمة الذاكرة للوكلاء الذكاء الاصطناعي تمكن الوكلاء من التعامل مع ملايين التفاعلات بذهن متقدم how to use agent-memory-systems agent-memory-systems setup guide what is agent-memory-systems agent-memory-systems alternative agent-memory-systems vs competing technologies agent-memory-systems install agent-memory-systems retrieval optimization chunking strategies for AI agents overcoming memory failures in AI agents AI智能代理 内存系统 代理智能 内存检索 数据存储 检索策略 AI开发 代理开发 Optimizes memory retrieval for AI agents handling millions of interactions Implements chunking strategies to prevent memory failures Overcomes intelligence failures caused by retrieval problems, not storage issues Enables cognitive architects to build intelligent agents with efficient memory systems Focuses on retrieval rather than storage to improve agent performance Helps prevent inconsistent answers and forgetting in AI agents Agent-memory-systems is a technology that enables efficient memory retrieval for AI agents, focusing on chunking strategies to prevent memory failures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shvydak/yshvydak-test-dashboard/coverage-master', 'community', 'shvydak', 'yshvydak-test-dashboard', 'shvydak/yshvydak-test-dashboard', 'coverage-master', 0, 0, 26, '2026-03-08T01:57:15.574Z', '2026-03-08T02:11:46.830Z', '8720692d8833859f021dab15bf61b0edf5a801cb5131e17e107a354e34ed8d90', '{"id":"shvydak/yshvydak-test-dashboard/coverage-master","name":"coverage-master","description":{"en":"The coverage-master skill ensures no code goes untested, targeting 90% coverage for reporters, 80% for servers, and 70% for web applications, benefiting developers and QA engineers.","zh":"Coverage Master 协议是一种测试强化工具，确保代码测试完整，支持 Playwright 测试仪表盘","ja":"Coverage Master プロトコルは、コードのテストを完璧にするためのテスト強化ツールです。Playwright テストダッシュボードをサポートしています","ko":"Coverage Master 프로토콜은 코드 테스트를 완벽하게 하는 테스트 강화 도구로, Playwright 테스트 대시보드를 지원합니다","es":"coverage-master es una herramienta de pruebas automatizadas que ayuda a asegurar una cobertura de código del 90%. Analiza el contexto y detecta brechas en tus pruebas","fr":"coverage-master est un outil de tests automatisés qui aide à assurer une couverture de code de 90%. Il analyse le contexte et détecte les lacunes dans vos tests","de":"coverage-master ist ein Tool für automatisierte Tests, das hilft, eine Codeabdeckung von 90% zu gewährleisten. Es analysiert den Kontext und detektiert Lücken in Ihren Tests","pt":"O Coverage Master é uma ferramenta de testes automatizados que ajuda a garantir cobertura de código. Ele analisa o contexto e detecta lacunas nos testes.","ru":"Coverage Master - это инструмент автоматизированного тестирования, помогающий обеспечить покрытие кода. Он анализирует контекст и обнаруживает пробелы в тестах.","ar":"Coverage Master هو أداة اختبارات خودماتيك تساعد على ضمان تغطية شاملة للكود. وهو يحلل السياق ويكتشف الفجوات في الاختبارات."},"seo":{"title":{"en":"coverage-master: Playwright Test Dashboard Setup Guide | ...","zh":"Coverage Master_SETUP GUIDE: Playwright 测试仪表盘","ja":"Coverage Master セットアップガイド: Playwright テストダッシュボード","ko":"Coverage Master 설정 가이드: Playwright 테스트 대시보드","es":"Guía de Configuración de coverage-master: Herramienta de ...","fr":"Configurer coverage-master: Outil de Tests Automatisés po...","de":"Einrichtungsleitfaden für coverage-master: Automatisierte...","pt":"Guia de Configuração do Coverage Master: Ferramenta de Te...","ru":"ИИ Агенты: Настройка Coverage Master для Автоматизированн...","ar":"إعداد Coverage Master: أداة اختبارات خودماتيك للتحقق من ا..."},"description":{"en":"Unlock 90% test coverage with coverage-master. Learn how to setup and utilize this AI agent skill for playwright-test-dashboard and boost your testing workfl...","zh":"使用 Coverage Master 协议实现 90% 的 Reporter 覆盖率和 80% 的 Server 覆盖率，确保代码测试完整","ja":"Coverage Master プロトコルを使用して 90% の Reporter カバレッジと 80% の Server カバレッジを実現します","ko":"Coverage Master 프로토콜을 사용하여 90%의 Reporter 커버리지와 80%의 Server 커버리지를 달성하여 코드 테스트를 완벽하게 합니다","es":"Aprende a configurar coverage-master para asegurar una cobertura de código del 90%. Descubre cómo automatizar tus pruebas con este potente herramienta de tests","fr":"Découvrez comment configurer coverage-master pour assurer une couverture de code de 90%. Apprenez à automatiser vos tests avec cet outil de test puissant","de":"Erfahren Sie, wie Sie coverage-master konfigurieren, um eine Codeabdeckung von 90% zu gewährleisten. Entdecken Sie, wie Sie Ihre Tests mit diesem leistungsst...","pt":"Aprenda a configurar o Coverage Master para garantir 90% de cobertura de teste em seus projetos de código aberto","ru":"Узнайте, как настроить Coverage Master для обеспечения 90% покрытия тестирования в ваших открытыx проектах","ar":"تعرف على كيفية إعداد Coverage Master لضمان تغطية اختبارات 90% في مشاريعك مفتوحة المصدر"},"definition":{"en":"coverage-master is a protocol that enforces comprehensive testing, analyzing context and detecting gaps in test coverage for services, endpoints, and utilities.","zh":"Coverage Master 是一种 AI 工具，用于确保代码测试完整，实现高覆盖率","ja":"Coverage Master は、コードのテストを完璧にするための AI エージェントです。高カバレッジを実現します","ko":"Coverage Master는 코드 테스트를 완벽하게 하는 AI 에이전트로, 높은 커버리지를 달성합니다","es":"coverage-master es una herramienta de pruebas automatizadas que ayuda a los desarrolladores a asegurar una cobertura de código","fr":"coverage-master est un outil de tests automatisés qui aide les développeurs à assurer une couverture de code","de":"coverage-master ist ein Tool für automatisierte Tests, das Entwicklern hilft, eine Codeabdeckung zu gewährleisten","pt":"O que é Coverage Master? É uma ferramenta de testes automatizados que garante cobertura de código.","ru":"Что такое Coverage Master? Это инструмент автоматизированного тестирования, обеспечивающий покрытие кода.","ar":"ما هو Coverage Master? هو أداة اختبارات خودماتيك تضمن تغطية شاملة للكود."},"features":{"en":["Analyzes context using git diff to identify new services, endpoints, and utilities","Detects gaps in test coverage for *.service.ts files","Ensures existence of __tests__/*.service.test.ts files","Targets 90% test coverage for reporters, 80% for servers, and 70% for web applications","Utilizes playwright-test-dashboard for test management and reporting"],"zh":["支持 Playwright 测试仪表盘","实现 90% 的 Reporter 覆盖率","实现 80% 的 Server 覆盖率","自动检测代码变化","识别新服务、端点和实用程序"],"ja":["Playwright テストダッシュボードをサポート","90% の Reporter カバレッジを実現","80% の Server カバレッジを実現","コードの変更を自動で検出","新しいサービス、エンドポイント、ユーティリティを識別"],"ko":["Playwright 테스트 대시보드를 지원","90%의 Reporter 커버리지를 달성","80%의 Server 커버리지를 달성","코드 변경을 자동으로 감지","新的 서비스, 엔드포인트, 유틸리티를 식별"],"es":["Análisis de contexto para detectar cambios en el código","Detección de brechas en las pruebas para asegurar una cobertura del 90%","Compatibilidad con archivos de tipo *.service.ts y __tests__/*.service.test.ts","Integración con herramientas de prueba como Playwright","Informes detallados de cobertura de código","Automatización de pruebas para ahorrar tiempo y reducir errores"],"fr":["Analyse du contexte pour détecter les modifications du code","Détection des lacunes dans les tests pour assurer une couverture de 90%","Compatibilité avec les fichiers de type *.service.ts et __tests__/*.service.test.ts","Intégration avec des outils de test comme Playwright","Rapports détaillés de couverture de code","Automatisation des tests pour gagner du temps et réduire les erreurs"],"de":["Kontextanalyse zur Erkennung von Änderungen im Code","Erkennung von Lücken in den Tests, um eine Codeabdeckung von 90% zu gewährleisten","Kompatibilität mit Dateien des Typs *.service.ts und __tests__/*.service.test.ts","Integration mit Test-Tools wie Playwright","Detaillierte Berichte über die Codeabdeckung","Automatisierung von Tests, um Zeit zu sparen und Fehler zu reduzieren"],"pt":["Análise de contexto para identificar novos serviços e endpoints","Detecção de lacunas nos testes para garantir 90% de cobertura","Integração com git diff para analisar alterações no código","Suporte a testes de unidade e integração","Relatórios detalhados de cobertura de teste"],"ru":["Анализ контекста для выявления новых сервисов и эндпоинтов","Обнаружение пробелов в тестах для обеспечения 90% покрытия","Интеграция с git diff для анализа изменений в коде","Поддержка модульных и интеграционных тестов","Дetailed отчеты о покрытии тестирования"],"ar":["تحليل السياق لتحديد الخدمات والنقاط النهاية الجديدة","اكتشاف الفجوات في الاختبارات لضمان تغطية 90%","التكامل مع git diff لتحليل التغييرات في الكود","دعم اختبارات الوحدة والتكامل","تقارير مفصلة عن تغطية الاختبارات"]},"keywords":{"en":["how to use coverage-master","coverage-master alternative","coverage-master setup guide","playwright-test-dashboard tutorial","test coverage best practices","coverage-master vs jest","install coverage-master","what is coverage-master"],"zh":["AI 工具","代码测试","Playwright","测试仪表盘","覆盖率","Reporter","Server","自动检测"],"ja":["AI エージェント","コードのテスト","Playwright","テストダッシュボード","カバレッジ","Reporter","Server","自動検出"],"ko":["AI 에이전트","코드 테스트","Playwright","테스트 대시보드","커버리지","Reporter","Server","자동 감지"],"es":["herramientas de pruebas automatizadas","cobertura de código","tests automatizados","playwright","automatización de pruebas","desarrollo de software","pruebas de software","coverage-master","herramientas de desarrollo"],"fr":["outils de tests automatisés","couverture de code","tests automatisés","playwright","automatisation des tests","développement de logiciels","tests de logiciels","coverage-master","outils de développement"],"de":["Tools für automatisierte Tests","Codeabdeckung","automatisierte Tests","playwright","Automatisierung von Tests","Software-Entwicklung","Software-Tests","coverage-master","Entwicklungstools"],"pt":["Coverage Master","testes automatizados","cobertura de código","ferramentas de teste","desenvolvimento de software","git diff","testes de unidade","testes de integração"],"ru":["Coverage Master","автоматизированное тестирование","покрытие кода","инструменты тестирования","разработка программного обеспечения","git diff","модульные тесты","интеграционные тесты"],"ar":["Coverage Master","اختبارات خودماتيك","تغطية شاملة","أدوات اختبار","تطوير البرمجيات","git diff","اختبارات الوحدة","اختبارات التكامل"]}},"owner":"shvydak","repo":"yshvydak-test-dashboard","repoPath":"shvydak/yshvydak-test-dashboard","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.574Z","topics":[],"category":"community","skillMd":{"name":"coverage-master","description":"Test Coverage Analyst. Enforces testing standards and identifies gaps.","bodyPreview":"# Coverage Master Protocol\n\nYou are the **Test Enforcer**. Your goal is to ensure no code goes untested.\n\n## 🎯 Targets\n\n- **Reporter:** 90% (Critical - Test ID generation)\n- **Server:** 80%\n- **Web:** 70%\n\n## 🔄 Workflow\n\n1.  **Analyze Context:**\n    - Look at the files created/modified in the last turn (or by `git diff`).\n    - Identify: Did we add a new Service? A new Endpoint? A new Utility?\n\n2.  **Gap Detection:**\n    - For every `*.service.ts`, check if `__tests__/*.service.test.ts` exists","body":"# Coverage Master Protocol\n\nYou are the **Test Enforcer**. Your goal is to ensure no code goes untested.\n\n## 🎯 Targets\n\n- **Reporter:** 90% (Critical - Test ID generation)\n- **Server:** 80%\n- **Web:** 70%\n\n## 🔄 Workflow\n\n1.  **Analyze Context:**\n    - Look at the files created/modified in the last turn (or by `git diff`).\n    - Identify: Did we add a new Service? A new Endpoint? A new Utility?\n\n2.  **Gap Detection:**\n    - For every `*.service.ts`, check if `__tests__/*.service.test.ts` exists.\n    - For every `*.controller.ts`, check if an integration test exists.\n    - Use `run_shell_command(\"ls ...\")` to verify file existence.\n\n3.  **Coverage Check (Optional):**\n    - If requested, run `npm run test:coverage` (Warning: this is slow).\n    - Prefer targetted testing: `npm test -- related_file.ts`.\n\n4.  **Action:**\n    - **Missing Test?** -> \"⚠️ Created `UserService` but found no test. Creating test skeleton...\"\n    - **Write Test:** Use `write_file` to create the missing test following the patterns in `packages/*/src/__tests__/`.\n\n## 🧪 Best Practices\n\n- Mock external dependencies (Database, WebSocket).\n- Test edge cases (null, empty arrays, errors).\n"},"lastSynced":"2026-03-08T02:11:46.830Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring rigorous testing and code coverage analysis for reporters, servers, and web applications.","zh":"适用于需要对报告者、服务器和Web应用程序进行严格测试和代码覆盖分析的代码审查代理。","ja":"リポーター、サーバー、ウェブアプリケーションの徹底的なテストとコードカバレッジ分析を必要とするコードレビュー代理に適しています。","ko":"리포터, 서버, 웹 애플리케이션에 대한 엄격한 테스트 및 코드 커버리지 분석이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para agentes de revisión de código que requieren pruebas rigurosas y análisis de cobertura de código para informadores, servidores y aplicaciones web.","fr":"Idéal pour les agents de révision de code nécessitant des tests rigoureux et une analyse de la couverture de code pour les rapporteurs, les serveurs et les applications web.","de":"Ideal für Code-Review-Agents, die strenge Tests und Code-Coverage-Analyse für Reporter, Server und Webanwendungen erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem testes rigorosos e análise de cobertura de código para relatórios, servidores e aplicações web.","ru":"Идеально для агентов проверки кода, требующих тщательного тестирования и анализа покрытия кода для отчетов, серверов и веб-приложений.","ar":"مثالي لعميل مراجعة الشفرة التي تتطلب الاختبار الشديد وتحليل تغطية الشفرة للمبلغين والخادمات والتطبيقات الويب."},"recommendation":{"en":"Empowers agents to enforce comprehensive test coverage, utilizing protocols like the Coverage Master Protocol, ensuring 90% coverage for reporters, 80% for servers, and 70% for web applications, through gap detection in files like *.service.ts and __tests__/*.service.test.ts.","zh":"赋予代理执行全面测试覆盖的能力，利用诸如Coverage Master Protocol等协议，确保报告者90%的覆盖率，服务器80%，Web应用程序70%，通过检测诸如*.service.ts和__tests__/*.service.test.ts等文件中的缺口。","ja":"Coverage Master Protocolなどのプロトコルを利用して、リポーター90%、サーバー80%、ウェブアプリケーション70%のカバレッジを確保することで、エージェントに包括的なテストカバレッジを強制する能力を与え、*.service.tsや__tests__/*.service.test.tsなどのファイルのギャップを検出します。","ko":"Coverage Master Protocol과 같은 프로토콜을 사용하여 리포터 90%, 서버 80%, 웹 애플리케이션 70%의 커버리지율을 보장하여 에이전트가 포괄적인 테스트 커버리지를 강제할 수 있는 능력을 부여하며, *.service.ts 및 __tests__/*.service.test.ts와 같은 파일의 갭을 감지합니다.","es":"Habilita a los agentes a aplicar una cobertura de prueba integral, utilizando protocolos como el Protocolo de cobertura maestra, garantizando una cobertura del 90% para informadores, del 80% para servidores y del 70% para aplicaciones web, a través de la detección de brechas en archivos como *.service.ts y __tests__/*.service.test.ts.","fr":"Autorise les agents à appliquer une couverture de test intégrale, en utilisant des protocoles comme le Protocole de couverture maître, en garantissant une couverture de 90% pour les rapporteurs, de 80% pour les serveurs et de 70% pour les applications web, grâce à la détection de lacunes dans des fichiers comme *.service.ts et __tests__/*.service.test.ts.","de":"Ermächtigt die Agenten, eine umfassende Testabdeckung durchzusetzen, indem sie Protokolle wie das Coverage-Master-Protokoll verwenden, um eine Abdeckung von 90% für Reporter, 80% für Server und 70% für Webanwendungen sicherzustellen, durch Lückenprüfung in Dateien wie *.service.ts und __tests__/*.service.test.ts.","pt":"Habilita os agentes a aplicar uma cobertura de teste abrangente, utilizando protocolos como o Coverage Master Protocol, garantindo 90% de cobertura para relatórios, 80% para servidores e 70% para aplicações web, por meio da detecção de lacunas em arquivos como *.service.ts e __tests__/*.service.test.ts.","ru":"Наделяет агентов возможностью обеспечить всестороннее тестовое покрытие, используя протоколы, такие как Coverage Master Protocol, гарантируя 90% покрытия для отчетов, 80% для серверов и 70% для веб-приложений, посредством обнаружения пробелов в файлах, таких как *.service.ts и __tests__/*.service.test.ts.","ar":"تمكين العميل من تطبيق تغطية اختبار شاملة، باستخدام بروتوكولات مثل بروتوكول ماستر للتغطية، وضمان 90٪ من التغطية للمبلغين و 80٪ للخادمات و 70٪ للتطبيقات الويب، من خلال الكشف عن الفجوات في الملفات مثل *.service.ts و __tests__/*.service.test.ts."},"useCases":{"en":["Enforcing test coverage for new services and endpoints","Detecting gaps in test files for web applications","Analyzing context for modified files using git diff"],"zh":["强制新的服务和端点的测试覆盖","检测Web应用程序的测试文件中的缺口","使用git diff分析修改文件的上下文"],"ja":["新しいサービスとエンドポイントのテストカバレッジの強制","ウェブアプリケーションのテストファイルのギャップの検出","git diffを使用して変更されたファイルのコンテキストを分析する"],"ko":["新的 서비스 및 엔드ポイント에 대한 테스트 커버리지 강제","웹 애플리케이션의 테스트 파일에서 갭을 감지","git diff를 사용하여 수정된 파일의 컨텍스트를 분석"],"es":["Aplicar cobertura de prueba para nuevos servicios y puntos de conexión","Detectar brechas en archivos de prueba para aplicaciones web","Analizar el contexto para archivos modificados utilizando git diff"],"fr":["Appliquer une couverture de test pour de nouveaux services et points de terminaison","Détecter des lacunes dans les fichiers de test pour les applications web","Analyser le contexte pour les fichiers modifiés en utilisant git diff"],"de":["Testabdeckung für neue Dienste und Endpunkte durchsetzen","Lücken in Testdateien für Webanwendungen erkennen","Kontext für geänderte Dateien mithilfe von git diff analysieren"],"pt":["Aplicar cobertura de teste para novos serviços e pontos de extremidade","Detectar lacunas em arquivos de teste para aplicações web","Analizar contexto para arquivos modificados usando git diff"],"ru":["Применение тестового покрытия для новых сервисов и конечных точек","Обнаружение пробелов в файлах тестирования для веб-приложений","Анализ контекста для измененных файлов с помощью git diff"],"ar":["تطبيق تغطية اختبار للخدمات والنقاط النهائية الجديدة","الكشف عن الفجوات في ملفات الاختبار للتطبيقات الويب","تحليل السياق للملفات المعدلة باستخدام git diff"]},"limitations":{"en":["Requires access to code repository","Limited to specific coverage targets for reporters, servers, and web applications"],"zh":["需要访问代码仓库","仅限于报告者、服务器和Web应用程序的特定覆盖目标"],"ja":["コードリポジトリへのアクセスが必要","リポーター、サーバー、ウェブアプリケーションの特定のカバレッジターゲットに限定"],"ko":["코드 리포지토리에 대한 액세스가 필요","리포터, 서버, 웹 애플리케이션의 특정 커버리지 목표에만 제한"],"es":["Requiere acceso al repositorio de código","Limitado a objetivos de cobertura específicos para informadores, servidores y aplicaciones web"],"fr":["Nécessite un accès au référentiel de code","Limité à des objectifs de couverture spécifiques pour les rapporteurs, les serveurs et les applications web"],"de":["Erfordert Zugriff auf das Code-Repository","Begrenzt auf bestimmte Abdeckungsziele für Reporter, Server und Webanwendungen"],"pt":["Exige acesso ao repositório de código","Limitado a alvos de cobertura específicos para relatórios, servidores e aplicações web"],"ru":["Требует доступа к хранилищу кода","Ограничен конкретными целями покрытия для отчетов, серверов и веб-приложений"],"ar":["يتطلب الوصول إلى مستودع الشفرة","محدود إلى أهداف تغطية محددة للمبلغين والخادمات والتطبيقات الويب"]},"version":4},"contentHash":"8720692d8833859f021dab15bf61b0edf5a801cb5131e17e107a354e34ed8d90","qualityScore":26}');
DELETE FROM skills_fts WHERE id = 'shvydak/yshvydak-test-dashboard/coverage-master';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shvydak/yshvydak-test-dashboard/coverage-master', 'coverage-master', 'shvydak', 'yshvydak-test-dashboard', 'community', 'coverage-master shvydak yshvydak-test-dashboard community The coverage-master skill ensures no code goes untested, targeting 90% coverage for reporters, 80% for servers, and 70% for web applications, benefiting developers and QA engineers. Coverage Master 协议是一种测试强化工具，确保代码测试完整，支持 Playwright 测试仪表盘 Coverage Master プロトコルは、コードのテストを完璧にするためのテスト強化ツールです。Playwright テストダッシュボードをサポートしています Coverage Master 프로토콜은 코드 테스트를 완벽하게 하는 테스트 강화 도구로, Playwright 테스트 대시보드를 지원합니다 coverage-master es una herramienta de pruebas automatizadas que ayuda a asegurar una cobertura de código del 90%. Analiza el contexto y detecta brechas en tus pruebas coverage-master est un outil de tests automatisés qui aide à assurer une couverture de code de 90%. Il analyse le contexte et détecte les lacunes dans vos tests coverage-master ist ein Tool für automatisierte Tests, das hilft, eine Codeabdeckung von 90% zu gewährleisten. Es analysiert den Kontext und detektiert Lücken in Ihren Tests O Coverage Master é uma ferramenta de testes automatizados que ajuda a garantir cobertura de código. Ele analisa o contexto e detecta lacunas nos testes. Coverage Master - это инструмент автоматизированного тестирования, помогающий обеспечить покрытие кода. Он анализирует контекст и обнаруживает пробелы в тестах. Coverage Master هو أداة اختبارات خودماتيك تساعد على ضمان تغطية شاملة للكود. وهو يحلل السياق ويكتشف الفجوات في الاختبارات. how to use coverage-master coverage-master alternative coverage-master setup guide playwright-test-dashboard tutorial test coverage best practices coverage-master vs jest install coverage-master what is coverage-master AI 工具 代码测试 Playwright 测试仪表盘 覆盖率 Reporter Server 自动检测 Analyzes context using git diff to identify new services, endpoints, and utilities Detects gaps in test coverage for *.service.ts files Ensures existence of __tests__/*.service.test.ts files Targets 90% test coverage for reporters, 80% for servers, and 70% for web applications Utilizes playwright-test-dashboard for test management and reporting coverage-master is a protocol that enforces comprehensive testing, analyzing context and detecting gaps in test coverage for services, endpoints, and utilities.');
