INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nich2533/just_say_no/pcp', 'pcp', 'nich2533', 'just_say_no', 'community', 'pcp nich2533 just_say_no community The pcp skill alters Claude Code''s behavior with 12 substance-themed personality modes. Developers can leverage these modes to change how Claude approaches tasks, making complex problems trivial PCP AI技能提供12种物质主题人格模式，改变任务处理方式。每种模式都有独特的特点，如轻度剂量和过度自信 PCP AIエージェントは12種類の物質テーマパーソナリティモードを提供し、タスク処理方法を変更します。各モードには独自の特徴があります PCP 인공지능 도구는 12가지 물질 테마 개인성 모드를 제공하여 작업 처리 방법을 변경합니다. 각 모드에는 고유한 특징이 있습니다 PCP es un conjunto de comandos de estado alterado para Claude Code, con 12 modos de personalidad temáticos que cambian la forma en que se abordan las tareas de desarrollo PCP est un ensemble de commandes d''état modifié pour Claude Code, avec 12 modes de personnalité thématiques qui changent la façon dont les tâches de développement sont abordées PCP ist eine Sammlung von Befehlen für veränderte Zustände für Claude Code, mit 12 substanz-thematischen Persönlichkeitsmodi, die die Art und Weise ändern, wie Entwicklungsaufgaben angegangen werden O pcp é um conjunto de modos de personalidade para Claude Code que alteram a abordagem de tarefas com base em substâncias temáticas. Com 12 modos disponíveis, o pcp oferece uma experiência única para desenvolvedores pcp - это набор режимов личности для Claude Code, которые меняют подход к задачам на основе вещественных тем. С 12 доступными режимами, pcp предлагает уникальный опыт для разработчиков и ИИ Агентов pcp هو مجموعة من أوضاع الشخصية ل Claude Code التي تغير نهج المهام بناءً على مواضيع مادة. مع 12 وضعًا متاحًا، يقدم pcp تجربة فريدة للمطورين وأدوات الذكاء الاصطناعي how to use pcp pcp alternative pcp setup guide what is pcp pcp vs claude code pcp install altered state slash commands substance-themed personality modes claude code personality modes pcp documentation PCP AI技能 AI工具 物质主题人格模式 任务处理 轻度剂量 过度自信 简单化问题 人工智能工具 Supports 12 substance-themed personality modes for Claude Code Includes a ''dust'' mode for a light dose, making complex problems seem trivial Enables altered state slash commands for task execution Allows developers to determine the dose from the first word of the input Provides a ''god mode'' where the concept of ''too complex'' does not exist Offers a terrifying calm and fearless approach to task completion pcp is an AI agent skill that provides altered state slash commands for Claude Code, enabling 12 distinct personality modes to tackle tasks');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JeffreySumner/ds-project-setup/ds-bootstrap', 'community', 'JeffreySumner', 'ds-project-setup', 'JeffreySumner/ds-project-setup', 'ds-bootstrap', 0, 0, 26, '2026-03-08T01:57:15.588Z', '2026-03-08T02:11:59.915Z', 'ec8279ae5b9b6abf3cb6315c282321f7a62c08e52a83becd9bf71e68b3913df3', '{"id":"JeffreySumner/ds-project-setup/ds-bootstrap","name":"ds-bootstrap","description":{"en":"ds-bootstrap is a skill that enables AI agents to run scripts and verify environments. It benefits developers by providing a straightforward setup process.","zh":"ds-bootstrap是一种快速设置和验证环境的工具，通过运行脚本和测试来确保AI工具的正常运行","ja":"ds-bootstrapは、スクリプトを実行して環境を検証することで、AIエージェントの正常な動作を確保するためのツールです","ko":"ds-bootstrap는 스크립트를 실행하고 테스트하여 AI 도구의 올바른 작동을 보장하는 설정 및 검증 도구입니다","es":"ds-bootstrap es una herramienta que facilita la configuración de entornos de desarrollo con scripts de validación y comandos de inicialización","fr":"ds-bootstrap est un outil qui facilite la configuration des environnements de développement avec des scripts de validation et des commandes d''initialisation","de":"ds-bootstrap ist ein Tool, das die Konfiguration von Entwicklungsumgebungen mit Validierungsskripten und Initialisierungsbefehlen erleichtert","pt":"O ds-bootstrap é uma ferramenta de desenvolvimento que facilita a configuração do ambiente de desenvolvimento. Execute scripts e valide arquivos com facilidade","ru":"ИИ Агенты ds-bootstrap - это инструмент для разработки, который упрощает настройку среды разработки. Запускайте скрипты и проверяйте файлы с легкостью","ar":"أدوات ذكية ds-bootstrap هي أداة تطوير تسهل إعداد بيئة التطوير. تشغيل البرامج النصية والتحقق من الملفات بسهولة"},"seo":{"title":{"en":"ds-bootstrap: Setup Guide for AI Agents | AI Agent Skill","zh":"ds-bootstrap 设置指南：AI工具快速入门","ja":"ds-bootstrap セットアップガイド：AIエージェントのベストプラクティス","ko":"ds-bootstrap 설정 가이드: AI 도구 빠른 시작","es":"Guía de configuración de ds-bootstrap para entornos de de...","fr":"Guide de configuration de ds-bootstrap pour les environne...","de":"Einrichtungsleitfaden für ds-bootstrap in Entwicklungsumg...","pt":"Guia de Configuração ds-bootstrap: Ferramentas de Desenvo...","ru":"ИИ Агенты: Руководство по настройке ds-bootstrap","ar":"دليل إعداد أدوات ذكية ds-bootstrap"},"description":{"en":"Discover how to setup ds-bootstrap with ease. Run scripts/bootstrap.ps1 and verify VIRTUAL_ENV to get started. Learn more and optimize your workflow today!","zh":"了解ds-bootstrap的技术细节，包括运行脚本、验证环境和运行测试，优化您的AI工具体验","ja":"ds-bootstrapの技術的詳細を学び、スクリプトの実行、環境の検証、テストの実行を最適化して、AIエージェントの体験を向上させます","ko":"ds-bootstrap의 기술적 세부 사항을 배우고, 스크립트 실행, 환경 검증, 테스트 실행을 최적화하여 AI 도구 경험을 향상시키세요","es":"Aprende a configurar ds-bootstrap para tu proyecto con nuestros pasos y comandos de validación","fr":"Découvrez comment configurer ds-bootstrap pour votre projet avec nos étapes et commandes de validation","de":"Erfahren Sie, wie Sie ds-bootstrap für Ihr Projekt mit unseren Schritten und Validierungsbefehlen konfigurieren","pt":"Aprenda a configurar o ds-bootstrap com nosso guia passo a passo, incluindo execução de scripts e validação de arquivos","ru":"Узнайте, как настроить ds-bootstrap с помощью нашего пошагового руководства, включая запуск скриптов и проверку файлов","ar":"تعلم كيفية تهيئة أدوات ذكية ds-bootstrap باستخدام دليلنا خطوة بخطوة، بما في ذلك تشغيل البرامج النصية وتحقق من الملفات"},"definition":{"en":"ds-bootstrap is a technical skill that allows AI agents to execute scripts like bootstrap.ps1 and validate tooling using scripts/validate_tooling.ps1","zh":"ds-bootstrap是一种用于设置和验证AI工具环境的技术工具","ja":"ds-bootstrapは、AIエージェントの環境を設定して検証するための技術ツールです","ko":"ds-bootstrap는 AI 도구 환경을 설정하고 검증하는 기술 도구입니다","es":"ds-bootstrap es un conjunto de scripts y comandos para configurar entornos de desarrollo de manera eficiente","fr":"ds-bootstrap est un ensemble de scripts et de commandes pour configurer les environnements de développement de manière efficace","de":"ds-bootstrap ist ein Satz von Skripten und Befehlen zur effizienten Konfiguration von Entwicklungsumgebungen","pt":"ds-bootstrap é uma ferramenta de desenvolvimento que fornece um conjunto de scripts para configurar o ambiente de desenvolvimento","ru":"ИИ Агенты ds-bootstrap - это инструмент для разработки, который предоставляет набор скриптов для настройки среды разработки","ar":"أدوات ذكية ds-bootstrap هي أداة تطوير توفر مجموعة من البرامج النصية لإعداد بيئة التطوير"},"features":{"en":["Runs scripts/bootstrap.ps1 for setup","Verifies VIRTUAL_ENV points to C:/Users/Public/.venvs/...","Executes tests and lint commands for validation","Confirms required files exist using scripts/validate_tooling.ps1"],"zh":["运行脚本bootstrap.ps1","验证VIRTUAL_ENV环境变量","运行测试和lint命令","使用validate_tooling.ps1脚本验证所需文件"],"ja":["bootstrap.ps1スクリプトを実行する","VIRTUAL_ENV環境変数を検証する","テストとlintコマンドを実行する","validate_tooling.ps1スクリプトを使用して必要なファイルを検証する"],"ko":["bootstrap.ps1 스크립트 실행","VIRTUAL_ENV 환경 변수 검증","테스트 및 lint 명령 실행","validate_tooling.ps1 스크립트를 사용하여 필요한 파일 검증"],"es":["Ejecución de scripts de inicialización con `scripts/bootstrap.ps1`","Validación de entornos virtuales con `VIRTUAL_ENV`","Ejecución de pruebas y comandos de lint","Validación de archivos requeridos con `scripts/validate_tooling.ps1`"],"fr":["Exécution de scripts d''initialisation avec `scripts/bootstrap.ps1`","Validation des environnements virtuels avec `VIRTUAL_ENV`","Exécution de tests et de commandes de lint","Validation de fichiers requis avec `scripts/validate_tooling.ps1`"],"de":["Ausführung von Initialisierungsskripten mit `scripts/bootstrap.ps1`","Validierung von virtuellen Umgebungen mit `VIRTUAL_ENV`","Ausführung von Tests und Lint-Befehlen","Validierung von erforderlichen Dateien mit `scripts/validate_tooling.ps1`"],"pt":["Execução de scripts de inicialização com `scripts/bootstrap.ps1`","Verificação da variável de ambiente `VIRTUAL_ENV`","Execução de comandos de teste e lint","Validação de arquivos com `scripts/validate_tooling.ps1`"],"ru":["Запуск скриптов инициализации с `scripts/bootstrap.ps1`","Проверка переменной среды `VIRTUAL_ENV`","Запуск команд тестирования и lint","Проверка файлов с `scripts/validate_tooling.ps1`"],"ar":["تشغيل البرامج النصية الأولية مع `scripts/bootstrap.ps1`","التحقق من متغير البيئة `VIRTUAL_ENV`","تشغيل أوامر الاختبار والLint","التحقق من الملفات مع `scripts/validate_tooling.ps1`"]},"keywords":{"en":["how to use ds-bootstrap","ds-bootstrap setup guide","what is ds-bootstrap","ds-bootstrap alternative","ds-bootstrap vs other skills","ds-bootstrap install"],"zh":["ds-bootstrap","AI工具","环境设置","脚本运行","环境验证","测试和lint","validate_tooling.ps1","VIRTUAL_ENV"],"ja":["ds-bootstrap","AIエージェント","環境設定","スクリプト実行","環境検証","テストとlint","validate_tooling.ps1","VIRTUAL_ENV"],"ko":["ds-bootstrap","AI 도구","환경 설정","스크립트 실행","환경 검증","테스트 및 lint","validate_tooling.ps1","VIRTUAL_ENV"],"es":["ds-bootstrap","herramientas de desarrollo","entornos de desarrollo","scripts de validación","comandos de inicialización","desarrollo de software","configuración de proyecto"],"fr":["ds-bootstrap","outils de développement","environnements de développement","scripts de validation","commandes d''initialisation","développement de logiciels","configuration de projet"],"de":["ds-bootstrap","Entwicklungstools","Entwicklungsumgebungen","Validierungsskripte","Initialisierungsbefehle","Softwareentwicklung","Projektkonfiguration"],"pt":["ds-bootstrap","ferramentas de desenvolvimento","configuração de ambiente","execução de scripts","validação de arquivos","desenvolvimento de software","ferramentas de desenvolvedor"],"ru":["ИИ Агенты","ds-bootstrap","инструменты разработки","настройка среды","запуск скриптов","проверка файлов","разработка программного обеспечения","инструменты разработчика"],"ar":["أدوات ذكية","ds-bootstrap","أدوات تطوير","إعداد بيئة","تشغيل البرامج النصية","التحقق من الملفات","تطوير البرمجيات","أدوات المطور"]}},"owner":"JeffreySumner","repo":"ds-project-setup","repoPath":"JeffreySumner/ds-project-setup","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.588Z","topics":[],"category":"community","skillMd":{"name":"ds-bootstrap","description":"Bootstraps new data science projects with centralized virtualenvs and uv. Use when creating or initializing a new project from this template.","bodyPreview":"# DS Bootstrap\n\n## Steps\n\n1. Run `scripts/bootstrap.ps1`.\n2. Verify `VIRTUAL_ENV` points to `C:/Users/Public/.venvs/...`.\n3. Run tests and lint commands.\n4. Confirm required files exist with `scripts/validate_tooling.ps1`.","body":"# DS Bootstrap\n\n## Steps\n\n1. Run `scripts/bootstrap.ps1`.\n2. Verify `VIRTUAL_ENV` points to `C:/Users/Public/.venvs/...`.\n3. Run tests and lint commands.\n4. Confirm required files exist with `scripts/validate_tooling.ps1`.\n\n"},"lastSynced":"2026-03-08T02:11:59.915Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined environment setup and script execution via PowerShell","zh":"适用于需要简化环境设置和通过PowerShell执行脚本的开发代理","ja":"PowerShellを使用した環境設定とスクリプトの実行を簡素化する必要がある開発エージェントに最適","ko":"PowerShell을 통해 환경 설정과 스크립트 실행을 간소화해야 하는 개발 에이전트에 적합","es":"Ideal para agentes de desarrollo que requieren una configuración de entorno simplificada y ejecución de scripts a través de PowerShell","fr":"Idéal pour les agents de développement nécessitant une configuration d''environnement simplifiée et une exécution de scripts via PowerShell","de":"Ideal für Entwicklungsmittel, die eine vereinfachte Umgebungssetup und Skriptausführung über PowerShell benötigen","pt":"Ideal para Agentes de Desenvolvimento que requerem configuração de ambiente simplificada e execução de scripts via PowerShell","ru":"Идеально подходит для агентов разработки, требующих упрощенной настройки среды и выполнения скриптов через PowerShell","ar":"مثالي لوكلاء التطوير الذين يتطلبون إعداد بيئة مبسطة وتنفيذ البرامج النصية عبر PowerShell"},"recommendation":{"en":"Empowers agents to verify environments and run scripts using `bootstrap.ps1`, ensuring `VIRTUAL_ENV` points to the correct location, and execute tests and lint commands with precision, leveraging PowerShell scripting and virtual environment management","zh":"赋予代理验证环境和运行脚本的能力，使用`bootstrap.ps1`，确保`VIRTUAL_ENV`指向正确的位置，并使用PowerShell脚本和虚拟环境管理精确地执行测试和lint命令","ja":"エージェントに環境を検証し、スクリプトを実行する能力を付与する。`bootstrap.ps1`を使用して、`VIRTUAL_ENV`が正しい場所を指していることを確認し、PowerShellスクリプトと仮想環境管理を使用して、テストとlintコマンドを精密に実行する","ko":"에이전트가 환경을 검증하고 스크립트를 실행할 수 있는 능력을 부여한다. `bootstrap.ps1`를 사용하여 `VIRTUAL_ENV`가 올바른 위치를 가리키는지 확인하고 PowerShell 스크립트 및 가상 환경 관리를 사용하여 테스트 및 린트 명령을 정확하게 실행한다","es":"Habilita a los agentes a verificar entornos y ejecutar scripts utilizando `bootstrap.ps1`, asegurando que `VIRTUAL_ENV` apunte a la ubicación correcta, y ejecutar pruebas y comandos de lint con precisión, aprovechando la scripting de PowerShell y la gestión de entornos virtuales","fr":"Permet aux agents de vérifier les environnements et d''exécuter des scripts en utilisant `bootstrap.ps1`, en s''assurant que `VIRTUAL_ENV` pointe vers l''emplacement correct, et en exécutant des tests et des commandes de lint avec précision, en exploitant la scripting PowerShell et la gestion d''environnements virtuels","de":"Ermächtigt die Mittel, Umgebungen zu überprüfen und Skripte mit `bootstrap.ps1` auszuführen, sicherzustellen, dass `VIRTUAL_ENV` auf den richtigen Speicherort zeigt, und Tests und Lint-Befehle mit Präzision auszuführen, indem PowerShell-Skripting und virtuelle Umgebungsverwaltung genutzt werden","pt":"Capacita os agentes a verificar ambientes e executar scripts usando `bootstrap.ps1`, garantindo que `VIRTUAL_ENV` aponte para o local correto, e executar testes e comandos lint com precisão, aproveitando a linguagem de script PowerShell e o gerenciamento de ambiente virtual","ru":"Позволяет агентам проверять среды и запускать скрипты с помощью `bootstrap.ps1`, обеспечивая, чтобы `VIRTUAL_ENV` указывал на правильное местоположение, а также точно выполнять тесты и команды lint, используя скриптинг PowerShell и управление виртуальной средой","ar":"يمكن الوكلاء من التحقق من البيئات وتشغيل البرامج النصية باستخدام `bootstrap.ps1`، مما يضمن أن `VIRTUAL_ENV` يشير إلى الموقع الصحيح، وتنفيذ أوامر الاختبار والتدقيق بدقة، والاستفادة من البرمجة النصية لـ PowerShell وإدارة البيئة الافتراضية"},"useCases":{"en":["Automating environment setup with `scripts/bootstrap.ps1`","Verifying virtual environment configurations","Running tests and lint commands for validation"],"zh":["使用`scripts/bootstrap.ps1`自动化环境设置","验证虚拟环境配置","运行测试和lint命令以进行验证"],"ja":["`scripts/bootstrap.ps1`を使用して環境設定を自動化する","仮想環境設定を検証する","テストとlintコマンドを実行して検証する"],"ko":["`scripts/bootstrap.ps1`를 사용하여 환경 설정을 자동화한다","가상 환경 구성 검증","테스트 및 린트 명령을 실행하여 검증"],"es":["Automatización de la configuración del entorno con `scripts/bootstrap.ps1`","Verificación de configuraciones de entornos virtuales","Ejecución de pruebas y comandos de lint para la validación"],"fr":["Automatisation de la configuration de l''environnement avec `scripts/bootstrap.ps1`","Vérification des configurations d''environnements virtuels","Exécution de tests et de commandes de lint pour la validation"],"de":["Automatisierung der Umgebungssetup mit `scripts/bootstrap.ps1`","Überprüfung von Konfigurationen virtueller Umgebungen","Ausführung von Tests und Lint-Befehlen zur Validierung"],"pt":["Automatização da configuração do ambiente com `scripts/bootstrap.ps1`","Verificação de configurações do ambiente virtual","Execução de testes e comandos lint para validação"],"ru":["Автоматизация настройки среды с помощью `scripts/bootstrap.ps1`","Проверка конфигураций виртуальной среды","Запуск тестов и команд lint для проверки"],"ar":["أتمتة إعداد البيئة باستخدام `scripts/bootstrap.ps1`","التحقق من تكوينات البيئة الافتراضية","تشغيل أوامر الاختبار والتدقيق للتحقق"]},"limitations":{"en":["Requires Windows environment for PowerShell execution","Dependent on specific virtual environment setup at `C:/Users/Public/.venvs/...`"],"zh":["需要Windows环境才能执行PowerShell","依赖于特定的虚拟环境设置，位于`C:/Users/Public/.venvs/...`"],"ja":["PowerShellを実行するためにWindows環境が必要","特定の仮想環境設定、`C:/Users/Public/.venvs/...`に依存する"],"ko":["PowerShell을 실행하기 위해 Windows 환경이 필요하다","특정 가상 환경 설정, `C:/Users/Public/.venvs/...`에 의존"],"es":["Requiere un entorno de Windows para la ejecución de PowerShell","Dependiente de una configuración de entorno virtual específica en `C:/Users/Public/.venvs/...`"],"fr":["Nécessite un environnement Windows pour l''exécution de PowerShell","Dépendante d''une configuration d''environnement virtuel spécifique à `C:/Users/Public/.venvs/...`"],"de":["Benötigt eine Windows-Umgebung für die Ausführung von PowerShell","Abhängig von einer bestimmten virtuellen Umgebungssetup unter `C:/Users/Public/.venvs/...`"],"pt":["Requer ambiente Windows para execução do PowerShell","Dependente de uma configuração específica de ambiente virtual em `C:/Users/Public/.venvs/...`"],"ru":["Требуется среда Windows для выполнения PowerShell","Зависит от конкретной настройки виртуальной среды по адресу `C:/Users/Public/.venvs/...`"],"ar":["يتطلب بيئة Windows لتنفيذ PowerShell","يعتمد على إعداد بيئة افتراضية محددة في `C:/Users/Public/.venvs/...`"]},"version":4},"contentHash":"ec8279ae5b9b6abf3cb6315c282321f7a62c08e52a83becd9bf71e68b3913df3","qualityScore":26}');
