INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JeffreySumner/ds-project-setup/ds-bootstrap', 'ds-bootstrap', 'JeffreySumner', 'ds-project-setup', 'community', 'ds-bootstrap JeffreySumner ds-project-setup community ds-bootstrap is a skill that enables AI agents to run scripts and verify environments. It benefits developers by providing a straightforward setup process. ds-bootstrap是一种快速设置和验证环境的工具，通过运行脚本和测试来确保AI工具的正常运行 ds-bootstrapは、スクリプトを実行して環境を検証することで、AIエージェントの正常な動作を確保するためのツールです ds-bootstrap는 스크립트를 실행하고 테스트하여 AI 도구의 올바른 작동을 보장하는 설정 및 검증 도구입니다 ds-bootstrap es una herramienta que facilita la configuración de entornos de desarrollo con scripts de validación y comandos de inicialización ds-bootstrap est un outil qui facilite la configuration des environnements de développement avec des scripts de validation et des commandes d''initialisation ds-bootstrap ist ein Tool, das die Konfiguration von Entwicklungsumgebungen mit Validierungsskripten und Initialisierungsbefehlen erleichtert O ds-bootstrap é uma ferramenta de desenvolvimento que facilita a configuração do ambiente de desenvolvimento. Execute scripts e valide arquivos com facilidade ИИ Агенты ds-bootstrap - это инструмент для разработки, который упрощает настройку среды разработки. Запускайте скрипты и проверяйте файлы с легкостью أدوات ذكية ds-bootstrap هي أداة تطوير تسهل إعداد بيئة التطوير. تشغيل البرامج النصية والتحقق من الملفات بسهولة how to use ds-bootstrap ds-bootstrap setup guide what is ds-bootstrap ds-bootstrap alternative ds-bootstrap vs other skills ds-bootstrap install ds-bootstrap AI工具 环境设置 脚本运行 环境验证 测试和lint validate_tooling.ps1 VIRTUAL_ENV Runs scripts/bootstrap.ps1 for setup Verifies VIRTUAL_ENV points to C:/Users/Public/.venvs/... Executes tests and lint commands for validation Confirms required files exist using scripts/validate_tooling.ps1 ds-bootstrap is a technical skill that allows AI agents to execute scripts like bootstrap.ps1 and validate tooling using scripts/validate_tooling.ps1');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wgutmann/sim-steward-plugin/priority-tracking', 'community', 'wgutmann', 'sim-steward-plugin', 'wgutmann/sim-steward-plugin', 'priority-tracking', 0, 0, 26, '2026-03-08T01:57:15.589Z', '2026-03-08T02:12:00.867Z', '71575954d30db509dadec0feb8c83146562cf3f1c481ee886e71966c26732b5f', '{"id":"wgutmann/sim-steward-plugin/priority-tracking","name":"priority-tracking","description":{"en":"The priority-tracking skill automates incident detection and protest for iRacing, helping users manage tasks and priorities. It benefits developers and users of SimSteward.com by streamlining their workflow.","zh":"优先级跟踪是一种AI智能工具，能够自动化任务管理和优化工作流程。它可以帮助用户跟踪和管理任务优先级，提高生产力","ja":"優先順位追跡は、タスク管理を自動化し、ワークフローを最適化するAIエージェントです。ユーザーがタスクの優先順位を追跡して管理するのを支援し、生産性を向上させます","ko":"우선 순위 추적은 작업 관리를 자동화하고 워크플ロー 최적화를 제공하는 AI 에이전트입니다. 사용자가 작업 우선 순위를 추적하고 관리하도록 지원하여 생산성을 향상시킵니다","es":"El plugin de SimHub para SimSteward.com permite la detección de incidentes y la automatización de protestas en iRacing. Gestione sus prioridades de manera eficiente","fr":"Le plugin SimHub pour SimSteward.com permet la détection d''incidents et l''automatisation des protestations sur iRacing. Gérez vos priorités de manière efficace","de":"Das SimHub-Plugin für SimSteward.com ermöglicht die Incident-Erkennung und die Automatisierung von Protesten in iRacing. Verwalten Sie Ihre Prioritäten effizient","pt":"O Priority-Tracking é um plugin oficial para SimSteward que automatiza a detecção de incidentes e protestos para iRacing, permitindo que os desenvolvedores gastem mais tempo correndo e menos tempo editando","ru":"Priority-Tracking - это официальный плагин для SimSteward, который автоматизирует обнаружение инцидентов и протестов для iRacing, позволяя разработчикам тратить больше времени на гонки и меньше времени на редактирование с помощью ИИ Агентов","ar":"Priority-Tracking هو إضافة رسمية لمنصة SimSteward التي تلقم أتمتة الكشف عن الحوادث والاحتجاجات لمنصة iRacing، مما يسمح للمطورين بإنفاق المزيد من الوقت في السباق وأقل وقت في التحرير"},"seo":{"title":{"en":"Priority-Tracking: Setup Guide for AI Agents | AI Agent S...","zh":"优先级跟踪设置指南 - AI智能工具","ja":"優先順位追跡のベストプラクティス - AIエージェント","ko":"우선 순위 추적 설정 가이드 - AI 에이전트","es":"Guía de configuración de seguimiento de prioridad para iR...","fr":"Guide de configuration de suivi de priorité pour iRacing","de":"Konfigurationsleitfaden für Prioritätsverfolgung in iRacing","pt":"Guia de Configuração do Priority-Tracking para Desenvolve...","ru":"Настройка Priority-Tracking: Руководство для Разработчико...","ar":"دليل إعداد Priority-Tracking لمنصة SimSteward"},"description":{"en":"Streamline your workflow with priority-tracking, the official SimHub plugin for SimSteward.com - automate incident detection and protest for iRacing, learn h...","zh":"了解优先级跟踪的工作原理，如何自动化任务管理和优化工作流程，提高生产力","ja":"優先順位追跡のしくみを理解し、タスク管理を自動化して生産性を向上させる","ko":"우선 순위 추적의 작동 원리를 이해하고 작업 관리를 자동화하여 생산성을 향상시키는 방법","es":"Automatice la detección de incidentes y la protesta en iRacing con el plugin oficial de SimHub. Mejore su experiencia de carreras","fr":"Automatisez la détection d''incidents et la protestation sur iRacing avec le plugin officiel de SimHub. Améliorez votre expérience de course","de":"Automatisieren Sie die Incident-Erkennung und Protest-Verwaltung in iRacing mit dem offiziellen SimHub-Plugin. Verbessern Sie Ihre Renn-Erfahrung","pt":"Aprenda a configurar o plugin Priority-Tracking para SimSteward e melhore a eficiência do seu workflow de desenvolvimento","ru":"Узнайте, как настроить плагин Priority-Tracking для SimSteward и повысьте производительность своего рабочего процесса разработки с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد إضافة Priority-Tracking لمنصة SimSteward وتحسين كفاءة سير عمل التطوير الخاص بك"},"definition":{"en":"priority-tracking is a SimHub plugin for automating incident detection and protest for iRacing, utilizing a canonical file for priority management","zh":"优先级跟踪是一种AI智能工具，用于自动化任务管理和优化工作流程","ja":"優先順位追跡は、タスク管理を自動化し、ワークフローを最適化するAIエージェント","ko":"우선 순위 추적은 작업 관리를 자동화하고 워크플ロー 최적화를 제공하는 AI 에이전트","es":"Seguimiento de prioridad es una función que permite a los usuarios gestionar y priorizar tareas en iRacing","fr":"Suivi de priorité est une fonction qui permet aux utilisateurs de gérer et de prioriser des tâches sur iRacing","de":"Prioritätsverfolgung ist eine Funktion, die es Benutzern ermöglicht, Aufgaben in iRacing zu verwalten und zu priorisieren","pt":"O Priority-Tracking é uma ferramenta de automação de workflow que gerencia prioridades e tarefas para desenvolvedores","ru":"Priority-Tracking - это инструмент автоматизации рабочего процесса, который управляет приоритетами и задачами для разработчиков ИИ Агентов","ar":"Priority-Tracking هو أداة أتمتة سير عمل لإدارة الأولويات والمهام للمطورين"},"features":{"en":["Utilizes a canonical file for priority management in docs/product/priorities.md","Automates task movement from Now/Next to Done based on user completion","Promotes next item when user starts work on a task","Adds new tasks to Next or Backlog with assigned priority","Supports blocker reporting and assignment to Blocked with description"],"zh":["自动化任务管理","优化工作流程","跟踪任务优先级","支持多种触发器和动作","集成文档和优先级管理"],"ja":["タスク管理の自動化","ワークフローの最適化","タスクの優先順位の追跡","複数のトリガーとアクションのサポート","ドキュメントと優先順位管理の統合"],"ko":["작업 관리 자동화","워크플ロー 최적화","작업 우선 순위 추적","다중 트리거 및 액션 지원","문서 및 우선 순위 관리 통합"],"es":["Detección automática de incidentes","Automatización de protestas","Gestión de prioridades mediante el archivo `docs/product/priorities.md`","Actualización de prioridades cuando el usuario completa una tarea","Compatibilidad con el plugin oficial de SimHub para SimSteward.com"],"fr":["Détection automatique d''incidents","Automatisation des protestations","Gestion des priorités via le fichier `docs/product/priorities.md`","Mise à jour des priorités lorsque l''utilisateur termine une tâche","Compatibilité avec le plugin officiel de SimHub pour SimSteward.com"],"de":["Automatische Incident-Erkennung","Automatisierung von Protesten","Prioritätsverwaltung über die Datei `docs/product/priorities.md`","Aktualisierung von Prioritäten wenn der Benutzer eine Aufgabe abschließt","Kompatibilität mit dem offiziellen SimHub-Plugin für SimSteward.com"],"pt":["Automatização da detecção de incidentes e protestos para iRacing","Gestão de prioridades e tarefas com base em ações do usuário","Integração com o plugin SimHub para SimSteward","Atualização automática das prioridades com base em ações do usuário","Suporte à adição de tarefas e bloqueios com descrições"],"ru":["Автоматизация обнаружения инцидентов и протестов для iRacing","Управление приоритетами и задачами на основе действий пользователя","Интеграция с плагином SimHub для SimSteward и ИИ Агентами","Автоматическое обновление приоритетов на основе действий пользователя","Поддержка добавления задач и блокировок с описаниями"],"ar":["أتمتة الكشف عن الحوادث والاحتجاجات لمنصة iRacing","إدارة الأولويات والمهام بناءً على إجراءات المستخدم","التكامل مع إضافة SimHub لمنصة SimSteward","التحديث التلقائي للأولويات بناءً على إجراءات المستخدم","دعم إضافة المهام والحواجز مع الوصف"]},"keywords":{"en":["how to use priority-tracking","priority-tracking setup guide","priority-tracking alternative","priority-tracking vs SimHub","what is priority-tracking","priority-tracking install","SimSteward.com priority management","iRacing incident detection automation","priority-tracking plugin for SimHub"],"zh":["AI智能工具","优先级跟踪","任务管理","工作流程优化","自动化","优先顺位管理","触发器和动作","文档管理"],"ja":["AIエージェント","優先順位追跡","タスク管理","ワークフローの最適化","自動化","優先順位管理","トリガーとアクション","ドキュメント管理"],"ko":["AI 에이전트","우선 순위 추적","작업 관리","워크플ロー 최적화","자동화","우선 순위 관리","트리거와 액션","문서 관리"],"es":["seguimiento de prioridad iRacing","plugin SimHub","automatización de protestas","gestión de prioridades","iRacing herramientas","SimSteward.com plugin"],"fr":["suivi de priorité iRacing","plugin SimHub","automatisation des protestations","gestion des priorités","iRacing outils","SimSteward.com plugin"],"de":["Prioritätsverfolgung iRacing","SimHub-Plugin","Automatisierung von Protesten","Prioritätsverwaltung","iRacing-Tools","SimSteward.com-Plugin"],"pt":["priority-tracking","simsteward","iracing","automatização de workflow","gestão de prioridades","desenvolvimento de software","plugin simhub","riority tracking para desenvolvedores"],"ru":["priority-tracking","simsteward","iracing","автоматизация рабочего процесса","управление приоритетами","разработка программного обеспечения","плагин simhub","ИИ Агенты","riority tracking для разработчиков"],"ar":["priority-tracking","simsteward","iracing","أتمتة سير عمل","إدارة الأولويات","تطوير البرمجيات","إضافة simhub","أدوات الذكاء الاصطناعي","priority tracking لمنصة simsteward"]}},"owner":"wgutmann","repo":"sim-steward-plugin","repoPath":"wgutmann/sim-steward-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.589Z","topics":[],"category":"community","skillMd":{"name":"priority-tracking","description":"Maintains and updates project priorities in docs/product/priorities.md. Use when the user asks to update priorities, track tasks, plan work, reprioritize, complete a task, start new work, or review whats next.","bodyPreview":"# Priority Tracking\n\n## Canonical File\n\nAll priorities live in `docs/product/priorities.md`.\n\n## When to Update\n\n| Trigger | Action |\n|---------|--------|\n| User completes a task | Move from Now/Next to Done; promote next item |\n| User starts work | Move item to Now; ensure Next is populated |\n| User adds a task | Add to Next (with priority) or Backlog |\n| User reports blocker | Add to Blocked with blocker description |\n| User asks \"what''s next?\" | Read priorities; suggest next item |\n| User rep","body":"# Priority Tracking\n\n## Canonical File\n\nAll priorities live in `docs/product/priorities.md`.\n\n## When to Update\n\n| Trigger | Action |\n|---------|--------|\n| User completes a task | Move from Now/Next to Done; promote next item |\n| User starts work | Move item to Now; ensure Next is populated |\n| User adds a task | Add to Next (with priority) or Backlog |\n| User reports blocker | Add to Blocked with blocker description |\n| User asks \"what''s next?\" | Read priorities; suggest next item |\n| User reprioritizes | Reorder Next; update Backlog |\n\n## Section Definitions\n\n| Section | Purpose |\n|---------|---------|\n| **Now** | Currently in progress (1–3 items max) |\n| **Next** | Queued, ordered by priority |\n| **Backlog** | Not yet scheduled |\n| **Blocked** | Waiting on something |\n| **Done** | Recently completed |\n\n## Format\n\n- Use markdown tables for Now, Next, Blocked, Done.\n- Use bullet list for Backlog.\n- Include **Last updated** at top; update when editing.\n- Keep Now lean (1–3 items); avoid context switching.\n\n## Workflow\n\n1. Read current priorities.\n2. Apply the requested change (add, move, complete, block).\n3. Reorder Next if needed.\n4. Update Last updated date.\n5. Summarize changes for the user.\n\n## Post-Task Delegation\n\nAfter implementing a task, delegate to priority-steward to update priorities (move completed item to Done, promote Next). This happens automatically via the delegation rule.\n"},"lastSynced":"2026-03-08T02:12:00.867Z","agentAnalysis":{"suitability":{"en":"Ideal for Task Management Agents requiring automated incident detection and priority tracking for streamlined workflows.","zh":"适用于需要自动化事件检测和优先级跟踪以实现流程优化的任务管理代理。","ja":"タスク管理エージェントに適しています。自動的なインシデント検出と優先度の追跡が必要な場合、ワークフローを最適化できます。","ko":"작업 관리 에이전트에 적합합니다. 자동화된 인시던트 감지 및 우선 순위 추적이 필요한 경우 워크플로우를 최적화할 수 있습니다.","es":"Ideal para agentes de gestión de tareas que requieren la detección automática de incidentes y el seguimiento de prioridades para flujos de trabajo optimizados.","fr":"Idéal pour les agents de gestion de tâches nécessitant la détection automatisée d''incidents et le suivi des priorités pour des flux de travail rationalisés.","de":"Ideal für Task-Management-Agents, die die automatische Erkennung von Vorfällen und die Nachverfolgung von Prioritäten für optimierte Workflows erfordern.","pt":"Ideal para Agentes de Gerenciamento de Tarefas que exigem detecção de incidentes automatizada e acompanhamento de prioridades para fluxos de trabalho otimizados.","ru":"Идеально подходит для агентов по управлению задачами, требующих автоматического обнаружения инцидентов и отслеживания приоритетов для оптимизированных рабочих процессов.","ar":"مثالي لعمليات وكيل إدارة المهام التي تتطلب الكشف التلقائي عن الحوادث وتتبع الأولويات من أجل سير عمل مبسط"},"recommendation":{"en":"Empowers agents to automate task prioritization using markdown files, specifically updating priorities in `docs/product/priorities.md` and managing tasks based on user interactions, such as completing tasks, starting work, or reporting blockers, utilizing triggers and actions for efficient workflow management.","zh":"赋予代理自动化任务优先级使用 markdown 文件的能力，特别是更新 `docs/product/priorities.md` 中的优先级，并根据用户交互（如完成任务、开始工作或报告阻塞）管理任务，利用触发器和操作实现高效的工作流管理。","ja":"エージェントにタスクの優先度を自動化する能力を付与します。特に、`docs/product/priorities.md` の優先度を更新し、ユーザーのやり取り（タスクの完了、作業の開始、ブロッカーの報告など）に基づいてタスクを管理し、トリガーとアクションを使用して効率的なワークフロー管理を実現します。","ko":"에이전트가 마크다운 파일을 사용하여 작업의 우선 순위를 자동화 할 수 있는 능력을 제공합니다. 특히, `docs/product/priorities.md`의 우선 순위를 업데이트하고, 사용자의 상호 작용(작업 완료, 작업 시작, 블로커報告 등)에 따라 작업을 관리하며, 트리거와 액션을 사용하여 효율적인 워크플로우 관리를 실현합니다.","es":"Habilita a los agentes a automatizar la priorización de tareas utilizando archivos markdown, actualizando específicamente las prioridades en `docs/product/priorities.md` y gestionando tareas en función de las interacciones del usuario, como completar tareas, iniciar el trabajo o informar bloqueos, utilizando disparadores y acciones para una gestión eficiente del flujo de trabajo.","fr":"Permet aux agents d''automatiser la priorisation des tâches en utilisant des fichiers markdown, en mettant spécifiquement à jour les priorités dans `docs/product/priorities.md` et en gérant les tâches en fonction des interactions de l''utilisateur, comme compléter des tâches, commencer à travailler ou signaler des bloqueurs, en utilisant des déclencheurs et des actions pour une gestion efficace du flux de travail.","de":"Ermächtigt die Agenten, die Priorisierung von Aufgaben mithilfe von Markdown-Dateien zu automatisieren, indem sie speziell die Prioritäten in `docs/product/priorities.md` aktualisieren und Aufgaben auf der Grundlage von Benutzerinteraktionen wie dem Abschließen von Aufgaben, dem Starten der Arbeit oder dem Melden von Blockierungen verwalten, wobei Trigger und Aktionen für eine effiziente Workflow-Verwaltung verwendet werden.","pt":"Habilita os agentes a automatizar a priorização de tarefas usando arquivos markdown, especificamente atualizando prioridades em `docs/product/priorities.md` e gerenciando tarefas com base em interações do usuário, como concluir tarefas, iniciar trabalhos ou relatar bloqueadores, utilizando gatilhos e ações para gerenciamento de fluxo de trabalho eficiente.","ru":"Наделяет агентов возможностью автоматизировать определение приоритета задач с помощью файлов markdown, в частности, обновляя приоритеты в `docs/product/priorities.md` и управляя задачами на основе взаимодействия пользователей, таких как выполнение задач, начало работы или сообщение о блокировках, используя триггеры и действия для эффективного управления рабочим процессом.","ar":"تمكين الوكلاء من توفير آلي لتخصيص任务 الأولوية باستخدام ملفات markdown، على سبيل المثال تحديث الأولويات في `docs/product/priorities.md` وإدارة المهام بناءً على تفاعلات المستخدم، مثل إكمال المهام أو بدء العمل أو الإبلاغ عن الحواجز، باستخدام عمليات التنشيط والإجراءات لإدارة سير العمل الفعالة."},"useCases":{"en":["Automating incident detection for iRacing","Streamlining task management workflows for SimSteward.com developers and users","Generating prioritized task lists based on user inputs and updates"],"zh":["自动化事件检测 for iRacing","为 SimSteward.com 开发人员和用户优化任务管理工作流","根据用户输入和更新生成优先级任务列表"],"ja":["iRacing のインシデント検出の自動化","SimSteward.com 開発者とユーザーのタスク管理ワークフローの最適化","ユーザーの入力と更新に基づいて優先順位付きのタスクリストを生成する"],"ko":["iRacing을 위한 자동화된 인시던트 감지","SimSteward.com 개발자와 사용자의 작업 관리 워크플로우 최적화","사용자 입력 및 업데이트에 따라 우선 순위가 있는 작업 목록 생성"],"es":["Automatizar la detección de incidentes para iRacing","Optimizar los flujos de trabajo de gestión de tareas para desarrolladores y usuarios de SimSteward.com","Generar listas de tareas priorizadas en función de las entradas y actualizaciones del usuario"],"fr":["Automatiser la détection d''incidents pour iRacing","Rationaliser les flux de travail de gestion de tâches pour les développeurs et les utilisateurs de SimSteward.com","Générer des listes de tâches priorisées en fonction des entrées et des mises à jour de l''utilisateur"],"de":["Automatisierung der Erkennung von Vorfällen für iRacing","Optimierung der Workflows für die Aufgabenverwaltung für Entwickler und Benutzer von SimSteward.com","Erstellung von priorisierten Aufgabenlisten auf der Grundlage von Benutzereingaben und -aktualisierungen"],"pt":["Automatizar a detecção de incidentes para iRacing","Otimizar fluxos de trabalho de gerenciamento de tarefas para desenvolvedores e usuários do SimSteward.com","Gerar listas de tarefas priorizadas com base em entradas e atualizações do usuário"],"ru":["Автоматизировать обнаружение инцидентов для iRacing","Оптимизировать рабочие процессы управления задачами для разработчиков и пользователей SimSteward.com","Генерировать список задач с учетом приоритета на основе ввода и обновления пользователя"],"ar":["توفير آلي للكشف عن الحوادث لـ iRacing","تبسيط سير عمل إدارة المهام لمطوري ومستخدمي SimSteward.com","توليد قوائم المهام الموظفة بناءً على مدخلات المستخدم وتحديثاته"]},"limitations":{"en":["Requires access to `docs/product/priorities.md` for priority updates","Limited to managing tasks and priorities within the specified markdown file structure"],"zh":["需要访问 `docs/product/priorities.md` 以更新优先级","仅限于在指定的 markdown 文件结构内管理任务和优先级"],"ja":["優先度の更新には `docs/product/priorities.md` へのアクセスが必要","指定されたマークダウンファイル構造内でのみタスクと優先度を管理することが可能"],"ko":["우선 순위 업데이트를 위해 `docs/product/priorities.md`에 접근해야 함","지정된 마크다운 파일 구조 내에서만 작업 및 우선 순위를 관리할 수 있음"],"es":["Requiere acceso a `docs/product/priorities.md` para actualizar prioridades","Limitado a la gestión de tareas y prioridades dentro de la estructura de archivo markdown especificada"],"fr":["Nécessite un accès à `docs/product/priorities.md` pour mettre à jour les priorités","Limité à la gestion des tâches et des priorités au sein de la structure de fichier markdown spécifiée"],"de":["Erfordert Zugriff auf `docs/product/priorities.md` für die Aktualisierung von Prioritäten","Begrenzt auf die Verwaltung von Aufgaben und Prioritäten innerhalb der angegebenen Markdown-Dateistruktur"],"pt":["Exige acesso a `docs/product/priorities.md` para atualizações de prioridade","Limitado ao gerenciamento de tarefas e prioridades dentro da estrutura de arquivo markdown especificada"],"ru":["Требует доступа к `docs/product/priorities.md` для обновления приоритета","Ограничен управлением задачами и приоритетами внутри определенной структуры файла markdown"],"ar":["يتطلب الوصول إلى `docs/product/priorities.md` لتحديث الأولويات","محدود بإدارة المهام والأولويات داخل هيكل ملف markdown المحدد"]},"version":4},"contentHash":"71575954d30db509dadec0feb8c83146562cf3f1c481ee886e71966c26732b5f","qualityScore":26}');
