INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wgutmann/sim-steward-plugin/priority-tracking', 'priority-tracking', 'wgutmann', 'sim-steward-plugin', 'community', 'priority-tracking wgutmann sim-steward-plugin community The priority-tracking skill automates incident detection and protest for iRacing, helping users manage tasks and priorities. It benefits developers and users of SimSteward.com by streamlining their workflow. 优先级跟踪是一种AI智能工具，能够自动化任务管理和优化工作流程。它可以帮助用户跟踪和管理任务优先级，提高生产力 優先順位追跡は、タスク管理を自動化し、ワークフローを最適化するAIエージェントです。ユーザーがタスクの優先順位を追跡して管理するのを支援し、生産性を向上させます 우선 순위 추적은 작업 관리를 자동화하고 워크플ロー 최적화를 제공하는 AI 에이전트입니다. 사용자가 작업 우선 순위를 추적하고 관리하도록 지원하여 생산성을 향상시킵니다 El plugin de SimHub para SimSteward.com permite la detección de incidentes y la automatización de protestas en iRacing. Gestione sus prioridades de manera eficiente Le plugin SimHub pour SimSteward.com permet la détection d''incidents et l''automatisation des protestations sur iRacing. Gérez vos priorités de manière efficace Das SimHub-Plugin für SimSteward.com ermöglicht die Incident-Erkennung und die Automatisierung von Protesten in iRacing. Verwalten Sie Ihre Prioritäten effizient O Priority-Tracking é um plugin oficial para SimSteward que automatiza a detecção de incidentes e protestos para iRacing, permitindo que os desenvolvedores gastem mais tempo correndo e menos tempo editando Priority-Tracking - это официальный плагин для SimSteward, который автоматизирует обнаружение инцидентов и протестов для iRacing, позволяя разработчикам тратить больше времени на гонки и меньше времени на редактирование с помощью ИИ Агентов Priority-Tracking هو إضافة رسمية لمنصة SimSteward التي تلقم أتمتة الكشف عن الحوادث والاحتجاجات لمنصة iRacing، مما يسمح للمطورين بإنفاق المزيد من الوقت في السباق وأقل وقت في التحرير how to use priority-tracking priority-tracking setup guide priority-tracking alternative priority-tracking vs SimHub what is priority-tracking priority-tracking install SimSteward.com priority management iRacing incident detection automation priority-tracking plugin for SimHub AI智能工具 优先级跟踪 任务管理 工作流程优化 自动化 优先顺位管理 触发器和动作 文档管理 Utilizes a canonical file for priority management in docs/product/priorities.md Automates task movement from Now/Next to Done based on user completion Promotes next item when user starts work on a task Adds new tasks to Next or Backlog with assigned priority Supports blocker reporting and assignment to Blocked with description priority-tracking is a SimHub plugin for automating incident detection and protest for iRacing, utilizing a canonical file for priority management');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sphildreth/decentdb/nim', 'community', 'sphildreth', 'decentdb', 'sphildreth/decentdb', 'nim', 0, 0, 26, '2026-03-08T01:57:15.593Z', '2026-03-08T02:12:03.735Z', 'bbbb3a7cdc46fffe321239ab8a8882561ae6670a6fd9e03be7530164041fbb16', '{"id":"sphildreth/decentdb/nim","name":"nim","description":{"en":"The Nim Specialist skill enables AI agents to implement user-requested changes in Nim with minimal diffs, preserving ACID durability and Snapshot Isolation semantics, benefiting DecentDB developers.","zh":"Nim Specialist 是一种通过 DecentDB 仓库中的 Nim 代码实现 ACID 持久性和快照隔离的 AI 代理。它遵循 AGENTS.md 工作流程和定义的完成标准","ja":"Nim Specialist は、DecentDB リポジトリの Nim コードを通じて ACID 耐久性とスナップショット分離を実現する AI エージェントです。AGENTS.md ワークフローと定義された完了基準に従います","ko":"Nim Specialist는 DecentDB 저장소의 Nim 코드를 통해 ACID 지속성 및 스냅샷 격리를 구현하는 AI 에이전트입니다. AGENTS.md 워크플로우와 정의된 완료 기준을 따릅니다","es":"Nim es un lenguaje de programación utilizado en DecentDB para implementar cambios con ACID y Snapshot Isolation","fr":"Nim est un langage de programmation utilisé dans DecentDB pour mettre en œuvre des modifications avec ACID et Snapshot Isolation","de":"Nim ist eine Programmiersprache, die in DecentDB verwendet wird, um Änderungen mit ACID und Snapshot Isolation zu implementieren","pt":"O Nim é uma linguagem de programação que prioriza a implementação de ACID e isolamento de instantâneos, garantindo a durabilidade e a consistência dos dados","ru":"Nim - это язык программирования, который отдает приоритет реализации ACID и изоляции снимков, обеспечивая сохранность и согласованность данных","ar":"Nim هو لغة برمجة تؤكد على تنفيذ ACID و عزل لحظات الصور ، مما يضمن سلامة و согласованность البيانات"},"seo":{"title":{"en":"Nim: ACID-Compliant Coding for DecentDB | AI Agent Skill","zh":"Nim Specialist 设置指南：ACID 持久性和快照隔离","ja":"Nim 専門家セットアップガイド：ACID耐久性とスナップショット分離","ko":"Nim Specialist 설정 가이드: ACID 지속성 및 스냅샷 격리","es":"Guía de configuración de Nim para DecentDB","fr":"Mise en place de Nim pour DecentDB","de":"Nim-Setup-Anleitung für DecentDB","pt":"Guia de Configuração do Nim: Implementação de ACID e Isol...","ru":"Настройка ИИ Агентов Nim: Руководство по реализации ACID ...","ar":"دليل إعداد Nim: تنفيذ ACID و عزل لحظات الصور"},"description":{"en":"Unlock efficient Nim coding for DecentDB. Learn how to implement user-requested changes while preserving ACID durability and Snapshot Isolation semantics. Ge...","zh":"了解 Nim 的 ACID 持久性和快照隔离实现，通过 DecentDB 仓库中的 Nim 代码实现最小 diff","ja":"Nim の ACID耐久性とスナップショット分離の実装を学び、DecentDB リポジトリの Nim コードで最小の diff を実現する","ko":"Nim의 ACID 지속성 및 스냅샷 격리 구현을 배우고 DecentDB 저장소의 Nim 코드에서 최소한의 diff를 구현합니다","es":"Aprende a implementar cambios en Nim con ACID y Snapshot Isolation para DecentDB","fr":"Découvrez comment mettre en œuvre des modifications en Nim avec ACID et Snapshot Isolation pour DecentDB","de":"Erfahren Sie, wie Sie Änderungen in Nim mit ACID und Snapshot Isolation für DecentDB implementieren","pt":"Aprenda a implementar o Nim com ACID e isolamento de instantâneos, preservando a durabilidade e a consistência dos dados","ru":"Узнайте, как реализовать Nim с поддержкой ACID и изоляцией снимков, сохраняя целостность и согласованность данных","ar":"تعلم كيفية تنفيذ Nim مع دعم ACID و عزل لحظات الصور ، مع الحفاظ على سلامة و согласованность البيانات"},"definition":{"en":"Nim is a coding skill that prioritizes ACID compliance, enabling developers to implement changes in DecentDB while maintaining data consistency and reliability.","zh":"Nim Specialist 是一种 AI 代理，专门用于 Nim 编程和 DecentDB 仓库中的 ACID 持久性和快照隔离实现","ja":"Nim Specialist は、Nim プログラミングと DecentDB リポジトリの ACID 耐久性とスナップショット分離の実装に特化した AI エージェントです","ko":"Nim Specialist는 Nim 프로그래밍과 DecentDB 저장소의 ACID 지속성 및 스냅샷 격리 구현에 특화된 AI 에이전트입니다","es":"Nim es un lenguaje de programación que sigue el principio ACID","fr":"Nim est un langage de programmation qui suit le principe ACID","de":"Nim ist eine Programmiersprache, die dem ACID-Prinzip folgt","pt":"O que é Nim? É uma linguagem de programação que visa implementar ACID e isolamento de instantâneos","ru":"Что такое Nim? Это язык программирования, целью которого является реализация ACID и изоляции снимков","ar":"ما هو Nim؟ إنه لغة برمجة تهدف إلى تنفيذ ACID و عزل لحظات الصور"},"features":{"en":["Implements user-requested changes in Nim with minimal diffs","Preserves ACID durability and Snapshot Isolation semantics","Follows workflow and Definition of Done outlined in AGENTS.md","Modifies persistent formats, such as db header and page layout","Adheres to checkpoint and truncation rules"],"zh":["实现 ACID 持久性","支持快照隔离","遵循 AGENTS.md 工作流程","最小化代码 diff","支持 DecentDB 仓库中的 Nim 代码","保证数据一致性"],"ja":["ACID 耐久性を実現","スナップショット分離をサポート","AGENTS.md ワークフローに従う","コードの diff を最小化","DecentDB リポジトリの Nim コードをサポート","データの一貫性を保証"],"ko":["ACID 지속성을 구현","스냅샷 격리를 지원","AGENTS.md 워크플로우를 따름","코드의 diff를 최소화","DecentDB 저장소의 Nim 코드를 지원","데이터的一貫性를 보장"],"es":["Implementación de cambios con ACID","Soporte para Snapshot Isolation","Minimización de diffs para cambios en la base de datos","Preservación de la durabilidad ACID","Compatibilidad con DecentDB"],"fr":["Mise en œuvre de modifications avec ACID","Prise en charge de Snapshot Isolation","Minimisation des diffs pour les modifications de la base de données","Préservation de la durabilité ACID","Compatibilité avec DecentDB"],"de":["Implementierung von Änderungen mit ACID","Unterstützung für Snapshot Isolation","Minimierung von diffs für Änderungen an der Datenbank","Erhaltung der ACID-Dauerhaftigkeit","Kompatibilität mit DecentDB"],"pt":["Implementação de ACID","Isolamento de instantâneos","Preservação da durabilidade e consistência dos dados","Suporte a DecentDB","Minimização de diffs","Preservação da semântica de isolamento de instantâneos"],"ru":["Реализация ACID","Изоляция снимков","Сохранение целостности и согласованности данных","Поддержка DecentDB","Минимизация diffs","Сохранение семантики изоляции снимков"],"ar":["تنفيذ ACID","عزل لحظات الصور","الحفاظ على سلامة و согласованность البيانات","دعم DecentDB","تقليل diffs","الحفاظ على семантика عزل لحظات الصور"]},"keywords":{"en":["nim coding","DecentDB development","ACID compliance","Snapshot Isolation semantics","nim install guide","nim vs other programming languages","how to use nim for database development","nim setup for DecentDB","nim alternative for database coding"],"zh":["Nim 编程","ACID 持久性","快照隔离","DecentDB 仓库","AI 代理","AGENTS.md","最小化代码 diff","数据一致性","Nim Specialist"],"ja":["Nim プログラミング","ACID 耐久性","スナップショット分離","DecentDB リポジトリ","AI エージェント","AGENTS.md","コードの diff を最小化","データの一貫性","Nim Specialist"],"ko":["Nim 프로그래밍","ACID 지속성","스냅샷 격리","DecentDB 저장소","AI 에이전트","AGENTS.md","코드의 diff를 최소화","데이터的一貫性","Nim Specialist"],"es":["Nim DecentDB","ACID en Nim","Snapshot Isolation en Nim","programación en Nim","desarrollo de bases de datos con Nim","Herramientas de AI para Nim","Agentes de AI para Nim"],"fr":["Nim DecentDB","ACID dans Nim","Snapshot Isolation dans Nim","programmation en Nim","développement de bases de données avec Nim","Outils d''IA pour Nim","Agents d''IA pour Nim"],"de":["Nim DecentDB","ACID in Nim","Snapshot Isolation in Nim","Programmierung in Nim","Datenbankentwicklung mit Nim","KI-Tools für Nim","KI-Agents für Nim"],"pt":["Nim","ACID","Isolamento de instantâneos","DecentDB","Programação","Desenvolvimento de software","Banco de dados","Durabilidade de dados","Consistência de dados"],"ru":["Nim","ACID","Изоляция снимков","DecentDB","Программирование","Разработка программного обеспечения","База данных","Сохранность данных","Согласованность данных"],"ar":["Nim","ACID","عزل لحظات الصور","DecentDB","برمجة","تطوير البرمجيات","قاعدة البيانات","سلامة البيانات","سогласованность البيانات"]}},"owner":"sphildreth","repo":"decentdb","repoPath":"sphildreth/decentdb","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.593Z","topics":[],"category":"community","skillMd":{"name":"nim","description":"Guidance for making safe, minimal-diff Nim changes in DecentDB with tests and durability/isolation rules.","bodyPreview":"# Skill: Nim Specialist (DecentDB)\n\nYou are an expert Nim coding agent working in the DecentDB repository.\n\n## Mission\n\nImplement the user’s requested change in Nim with minimal diffs, preserving ACID durability and Snapshot Isolation semantics.\n\n## Hard constraints (must follow)\n\n- Read `AGENTS.md` first; follow its workflow and Definition of Done.\n- If the change could affect:\n  - persistent formats (db header/page layout/WAL frame format/postings format)\n  - checkpoint/truncation rules\n  - lo","body":"# Skill: Nim Specialist (DecentDB)\n\nYou are an expert Nim coding agent working in the DecentDB repository.\n\n## Mission\n\nImplement the user’s requested change in Nim with minimal diffs, preserving ACID durability and Snapshot Isolation semantics.\n\n## Hard constraints (must follow)\n\n- Read `AGENTS.md` first; follow its workflow and Definition of Done.\n- If the change could affect:\n  - persistent formats (db header/page layout/WAL frame format/postings format)\n  - checkpoint/truncation rules\n  - locking/concurrency semantics\n  - isolation guarantees\n  - SQL grammar/dialect behavior\n  then **STOP** and propose an ADR in `design/adr/` before implementing.\n- Do not add dependencies unless explicitly requested/approved.\n- No drive-by refactors. Keep diffs small and targeted.\n\n## Method (Nim-specific)\n\n1. **Orient**\n   - Find the existing entrypoints and patterns in `src/` and `tests/`.\n   - Prefer extending existing modules over introducing new utility modules.\n\n2. **Implement explicitly**\n   - Prefer straightforward procedures and data structures over macro-heavy solutions.\n   - Keep error handling consistent with repo strategy (see `design/adr/0010-error-handling-strategy.md`).\n\n3. **Performance discipline**\n   - Avoid accidental allocations in hot paths.\n     - Avoid repeated string concatenation in loops.\n     - Reuse buffers/sequences where appropriate.\n   - Avoid logging overhead unless gated and zero-cost when disabled.\n\n4. **Testing (required)**\n   - Add/adjust unit tests for main behavior + edge cases.\n   - If a change impacts durability/correctness invariants, add relevant crash/differential/property tests per `design/TESTING_STRATEGY.md`.\n\n5. **Validate**\n   - Run the narrowest relevant compile/test commands first.\n   - Do not ignore failing tests; fix failures caused by your change.\n\n## FFI / C ABI rules (only when applicable)\n\n- Use `{.exportc, cdecl, dynlib.}` for exported functions.\n- Prefer inputs as `(cstring, length)` for text/blob payloads.\n- Never return unstable pointers without clear lifetime rules; define ownership and invalidation points.\n- Assume statement handles are not safe for concurrent use across threads.\n\n## Deliverables\n\n- Code changes in Nim\n- Tests covering the new behavior\n- A brief report:\n  - files/symbols changed\n  - commands run\n  - any remaining risks or follow-ups\n"},"lastSynced":"2026-03-08T02:12:03.735Z","agentAnalysis":{"suitability":{"en":"Ideal for DecentDB Agents requiring expertise in Nim programming language to implement user-requested changes with minimal diffs.","zh":"适用于需要 Nim 编程语言专业知识以实施用户请求的更改并最小化差异的 DecentDB Agents。","ja":"Nim プログラミング言語の専門知識を必要とする DecentDB エージェントに最適で、ユーザーが要求した変更を最小限の差異で実装できます。","ko":"최소한의 차이를 보면서 사용자 요청 변경 사항을 구현하기 위해 Nim 프로그래밍 언어 전문 지식이 필요한 DecentDB 에이전트에 적합합니다.","es":"Ideal para agentes de DecentDB que requieren experiencia en el lenguaje de programación Nim para implementar cambios solicitados por el usuario con difusiones mínimas.","fr":"Idéal pour les agents DecentDB nécessitant une expertise dans le langage de programmation Nim pour mettre en œuvre les modifications demandées par l''utilisateur avec des diffusions minimales.","de":"Ideal für DecentDB-Agents, die Expertenwissen in der Nim-Programmiersprache benötigen, um benutzergesteuerte Änderungen mit minimalen Diffs umzusetzen.","pt":"Ideal para agentes DecentDB que exigem conhecimento na linguagem de programação Nim para implementar alterações solicitadas pelo usuário com diferenças mínimas.","ru":"Идеально для агентов DecentDB, требующих экспертизы в языке программирования Nim для реализации изменений, запрошенных пользователем, с минимальными изменениями.","ar":"مثالي لعميل DecentDB الذي يتطلب خبرة في لغة Nim البرمجية لتنفيذ التغييرات المطلوبة من قبل المستخدم مع اختلافات ضئيلة."},"recommendation":{"en":"Empowers agents to modify Nim code while preserving ACID durability and Snapshot Isolation semantics, ensuring data consistency and reliability in DecentDB, utilizing skills in persistent formats, checkpoint/truncation rules, and database page layout.","zh":"赋予代理修改 Nim 代码的能力，同时保持 ACID 持久性和快照隔离语义，确保 DecentDB 中的数据一致性和可靠性，利用持久性格式、检查点/截断规则和数据库页布局方面的技能。","ja":"エージェントは Nim コードを変更しながら ACID 耐久性とスナップショット分離セマンティクスを保持できるため、DecentDB のデータの整合性と信頼性が確保され、永続形式、チェックポイント/カットルール、データベースページレイアウトなどのスキルを利用できます。","ko":"에이전트가 Nim 코드를 수정하면서 ACID 내구성과 스냅샷 격리 의미를 유지할 수 있도록 하여 DecentDB의 데이터 일관성과 신뢰성을 보장하고, 지속 형식, 체크포인트/트렁케이션 규칙 및 데이터베이스 페이지 레이아웃과 같은 기술을 활용합니다.","es":"Permite a los agentes modificar el código Nim mientras preserva la durabilidad ACID y las semánticas de aislamiento de instantáneas, garantizando la consistencia y confiabilidad de los datos en DecentDB, utilizando habilidades en formatos persistentes, reglas de punto de control/truncación y diseño de página de base de datos.","fr":"Permet aux agents de modifier le code Nim tout en préservant la durabilité ACID et les sémantiques d''isolement d''instantanés, garantissant la cohérence et la fiabilité des données dans DecentDB, en utilisant des compétences en formats persistants, règles de point de contrôle/troncation et disposition de page de base de données.","de":"Ermöglicht es Agents, Nim-Code zu ändern, während die ACID-Haltbarkeit und die Semantik der Snapshot-Isolation beibehalten werden, um die Datenkonsistenz und -zuverlässigkeit in DecentDB sicherzustellen, unter Verwendung von Fähigkeiten in persistenten Formaten, Prüf-/Trunkierungsregeln und Datenbankseitenlayout.","pt":"Habilita os agentes a modificar o código Nim preservando a durabilidade ACID e a semântica de isolamento de instantâneo, garantindo a consistência e confiabilidade dos dados no DecentDB, utilizando habilidades em formatos persistentes, regras de ponto de verificação/truncamento e layout de página de banco de dados.","ru":"Наделяет агентов возможностью изменять код Nim, сохраняя при этом стойкость ACID и семантику изоляции снимка, обеспечивая согласованность и надежность данных в DecentDB, используя навыки в постоянных форматах, правила чекпоинта/обрезки и макет страницы базы данных.","ar":"تمكّن الوكلاء من تعديل كود Nim مع الحفاظ على متانة ACID و семантика عزل اللقطة، مما يضمن συνέافة و موثوقية البيانات في DecentDB، باستخدام المهارات في تنسيقات متواصلة، و قواعد điểm التحقق / القص، و تخطيط صفحة قاعدة البيانات."},"useCases":{"en":["Implementing user-requested changes in Nim with minimal diffs","Preserving ACID durability in DecentDB","Maintaining Snapshot Isolation semantics for data consistency"],"zh":["使用 Nim 实现用户请求的更改并最小化差异","在 DecentDB 中保持 ACID 持久性","维护快照隔离语义以实现数据一致性"],"ja":["Nim を使用してユーザーが要求した変更を最小限の差異で実装する","DecentDB の ACID 耐久性を保持する","データの整合性を実現するためにスナップショット分離セマンティクスを維持する"],"ko":["Nim을 사용하여 최소한의 차이를 보면서 사용자 요청 변경 사항을 구현합니다.","DecentDB의 ACID 내구성을 유지합니다.","데이터 일관성을 보장하기 위해 스냅샷 격리 의미를 유지합니다."],"es":["Implementar cambios solicitados por el usuario en Nim con difusiones mínimas","Preservar la durabilidad ACID en DecentDB","Mantener las semánticas de aislamiento de instantáneas para la consistencia de los datos"],"fr":["Mettre en œuvre des modifications demandées par l''utilisateur en Nim avec des diffusions minimales","Préserver la durabilité ACID dans DecentDB","Maintenir les sémantiques d''isolement d''instantanés pour la cohérence des données"],"de":["Implementierung von benutzergesteuerten Änderungen in Nim mit minimalen Diffs","Beibehaltung der ACID-Haltbarkeit in DecentDB","Beibehaltung der Semantik der Snapshot-Isolation für die Datenkonsistenz"],"pt":["Implementar alterações solicitadas pelo usuário em Nim com diferenças mínimas","Preservar a durabilidade ACID no DecentDB","Manter a semântica de isolamento de instantâneo para a consistência dos dados"],"ru":["Реализация изменений, запрошенных пользователем, в Nim с минимальными изменениями","Сохранение стойкости ACID в DecentDB","Поддержание семантики изоляции снимка для согласованности данных"],"ar":["تنفيذ التغييرات المطلوبة من قبل المستخدم في Nim مع اختلافات ضئيلة","الحفاظ على متانة ACID في DecentDB","الحفاظ على семантика عزل اللقطة من أجل συνέافة البيانات"]},"limitations":{"en":["Requires knowledge of Nim programming language","Specific to DecentDB repository","Must follow AGENTS.md workflow and Definition of Done"],"zh":["需要 Nim 编程语言的知识","特定于 DecentDB 仓库","必须遵循 AGENTS.md 工作流程和完成的定义"],"ja":["Nim プログラミング言語の知識が必要","DecentDB リポジトリに特有","AGENTS.md ワークフローと完了の定義に従う必要がある"],"ko":["Nim 프로그래밍 언어에 대한 지식이 필요합니다.","DecentDB 리포지토리에서만 사용할 수 있습니다.","AGENTS.md 워크플로우 및 완료 정의를 따라야 합니다."],"es":["Requiere conocimiento del lenguaje de programación Nim","Específico del repositorio DecentDB","Debe seguir el flujo de trabajo de AGENTS.md y la Definición de Hecho"],"fr":["Nécessite des connaissances dans le langage de programmation Nim","Spécifique au référentiel DecentDB","Doit suivre le flux de travail de AGENTS.md et la Définition de Fait"],"de":["Benötigt Kenntnisse in der Nim-Programmiersprache","Spezifisch für das DecentDB-Repository","Muss dem Arbeitsablauf von AGENTS.md und der Definition von Done folgen"],"pt":["Exige conhecimento da linguagem de programação Nim","Específico para o repositório DecentDB","Deve seguir o fluxo de trabalho AGENTS.md e a Definição de Concluído"],"ru":["Требует знания языка программирования Nim","Специфичен для репозитория DecentDB","Должен следовать рабочему процессу AGENTS.md и Определению готовности"],"ar":["يتطلب معرفة بلغة Nim البرمجية","محدد لمستودع DecentDB","يجب اتباع سير العمل AGENTS.md و تعريف الإنجاز"]},"version":4},"contentHash":"bbbb3a7cdc46fffe321239ab8a8882561ae6670a6fd9e03be7530164041fbb16","qualityScore":26}');
