INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sphildreth/decentdb/nim', 'nim', 'sphildreth', 'decentdb', 'community', 'nim sphildreth decentdb community The Nim Specialist skill enables AI agents to implement user-requested changes in Nim with minimal diffs, preserving ACID durability and Snapshot Isolation semantics, benefiting DecentDB developers. Nim Specialist 是一种通过 DecentDB 仓库中的 Nim 代码实现 ACID 持久性和快照隔离的 AI 代理。它遵循 AGENTS.md 工作流程和定义的完成标准 Nim Specialist は、DecentDB リポジトリの Nim コードを通じて ACID 耐久性とスナップショット分離を実現する AI エージェントです。AGENTS.md ワークフローと定義された完了基準に従います Nim Specialist는 DecentDB 저장소의 Nim 코드를 통해 ACID 지속성 및 스냅샷 격리를 구현하는 AI 에이전트입니다. AGENTS.md 워크플로우와 정의된 완료 기준을 따릅니다 Nim es un lenguaje de programación utilizado en DecentDB para implementar cambios con ACID y Snapshot Isolation Nim est un langage de programmation utilisé dans DecentDB pour mettre en œuvre des modifications avec ACID et Snapshot Isolation Nim ist eine Programmiersprache, die in DecentDB verwendet wird, um Änderungen mit ACID und Snapshot Isolation zu implementieren O Nim é uma linguagem de programação que prioriza a implementação de ACID e isolamento de instantâneos, garantindo a durabilidade e a consistência dos dados Nim - это язык программирования, который отдает приоритет реализации ACID и изоляции снимков, обеспечивая сохранность и согласованность данных Nim هو لغة برمجة تؤكد على تنفيذ ACID و عزل لحظات الصور ، مما يضمن سلامة و согласованность البيانات nim coding DecentDB development ACID compliance Snapshot Isolation semantics nim install guide nim vs other programming languages how to use nim for database development nim setup for DecentDB nim alternative for database coding Nim 编程 ACID 持久性 快照隔离 DecentDB 仓库 AI 代理 AGENTS.md 最小化代码 diff 数据一致性 Nim Specialist Implements user-requested changes in Nim with minimal diffs Preserves ACID durability and Snapshot Isolation semantics Follows workflow and Definition of Done outlined in AGENTS.md Modifies persistent formats, such as db header and page layout Adheres to checkpoint and truncation rules Nim is a coding skill that prioritizes ACID compliance, enabling developers to implement changes in DecentDB while maintaining data consistency and reliability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alfred1137/ScreenBanter/python-ml-workflow', 'community', 'alfred1137', 'ScreenBanter', 'alfred1137/ScreenBanter', 'python-ml-workflow', 0, 0, 26, '2026-03-08T01:57:15.598Z', '2026-03-08T02:12:07.648Z', '04d31bacc40eec3b61fc70668edfbff44fbf533103501a7fe851bf298ba50864', '{"id":"alfred1137/ScreenBanter/python-ml-workflow","name":"python-ml-workflow","description":{"en":"The python-ml-workflow skill enables Python masters, ML engineers, and data scientists to create elegant and efficient machine learning workflows. It utilizes Python 3.10+, uv, Poetry, and Ruff for optimized development.","zh":"Python 机器学习工作流是一种使用 Python 3.10+ 和 uv 进行机器学习开发的方法，注重优雅和效率","ja":"Python マシンラーニングワークフローは、Python 3.10+ と uv を使用してマシンラーニング開発を実現する方法で、優雅さと効率性を重視","ko":"Python 기계학습 워크플로우는 Python 3.10+와 uv를 사용하여 기계학습 개발을 효율적이고 우아하게 구현하는 방법","es":"Python-ml-workflow es un proyecto que combina Python 3.10+ con uv, Poetry y pytest para crear flujos de trabajo de aprendizaje automático eficientes","fr":"Python-ml-workflow est un projet qui combine Python 3.10+ avec uv, Poetry et pytest pour créer des flux de travail d''apprentissage automatique efficaces","de":"Python-ml-workflow ist ein Projekt, das Python 3.10+ mit uv, Poetry und pytest kombiniert, um effiziente maschinelles Lernen-Workflows zu erstellen","pt":"O python-ml-workflow é uma solução de ML/LLM que combina Python 3.10+ com ferramentas de gerenciamento e teste para desenvolver aplicações eficientes","ru":"Python-ml-workflow - это решение ML/LLM, объединяющее Python 3.10+ с инструментами управления и тестирования для разработки эффективных приложений с помощью ИИ Агентов","ar":"python-ml-workflow هو حل ML/LLM يجمع بين Python 3.10+ وأدوات الإدارة والاختبار لتطوير تطبيقات فعالة مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"python-ml-workflow: Optimized ML Workflow Setup Guide | A...","zh":"Python 机器学习工作流 Setup Guide","ja":"Python マシンラーニングワークフロー ベストプラクティス","ko":"Python 기계학습 워크플로우 설정 가이드","es":"Guía de configuración de python-ml-workflow para Agentes ...","fr":"Guide d''installation de python-ml-workflow pour Outils d''IA","de":"Einrichtungsleitfaden für python-ml-workflow und KI-Tools","pt":"Guia de Configuração do python-ml-workflow para Desenvolv...","ru":"Настройка python-ml-workflow: Руководство для Разработчик...","ar":"دليل إعداد python-ml-workflow للبرمجة مع أدوات الذكاء الا..."},"description":{"en":"Unlock efficient machine learning workflows with python-ml-workflow. Discover how to leverage Python 3.10+, uv, Poetry, and Ruff for seamless ML development ...","zh":"使用 Python 3.10+、uv、Poetry 和 Rye 进行机器学习开发，实现高效和优雅的代码","ja":"Python 3.10+、uv、Poetry、Rye を使用してマシンラーニング開発を実現し、効率性と優雅さを実現する","ko":"Python 3.10+、uv、Poetry 및 Rye를 사용하여 기계학습 개발을 효율적이고 우아하게 구현","es":"Aprende a configurar python-ml-workflow con tecnologías como uv, Poetry y pytest para mejorar tus proyectos de IA","fr":"Découvrez comment configurer python-ml-workflow avec des technologies comme uv, Poetry et pytest pour améliorer vos projets d''IA","de":"Erfahren Sie, wie Sie python-ml-workflow mit Technologien wie uv, Poetry und pytest für bessere KI-Projekte konfigurieren","pt":"Aprenda a configurar o python-ml-workflow com Python 3.10+, uv, Poetry e pytest para desenvolver soluções de ML/LLM eficientes","ru":"Узнайте, как настроить python-ml-workflow с Python 3.10+, uv, Poetry и pytest для разработки эффективных решений ML/LLM с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد python-ml-workflow باستخدام Python 3.10+ و uv و Poetry و pytest لتطوير حلول ML/LLM فعالة مع أدوات الذكاء الاصطناعي"},"definition":{"en":"python-ml-workflow is a skill that combines Python, machine learning, and efficient workflow management using tools like uv, Poetry, and Ruff for streamlined development.","zh":"Python 机器学习工作流是一种使用 Python 进行机器学习开发的方法，使用 uv、Poetry 和 Rye 进行管理和测试","ja":"Python マシンラーニングワークフローは、Python を使用してマシンラーニング開発を実現する方法で、uv、Poetry、Rye を使用して管理とテストを行う","ko":"Python 기계학습 워크플로우는 Python을 사용하여 기계학습 개발을 효율적으로 구현하는 방법으로 uv, Poetry 및 Rye를 사용하여 관리 및 테스트","es":"Python-ml-workflow es un conjunto de herramientas para crear flujos de trabajo de aprendizaje automático con Python","fr":"Python-ml-workflow est un ensemble d''outils pour créer des flux de travail d''apprentissage automatique avec Python","de":"Python-ml-workflow ist eine Sammlung von Tools zur Erstellung von maschinellem Lernen-Workflows mit Python","pt":"O python-ml-workflow é um framework de ML/LLM que utiliza Python 3.10+ e ferramentas de gerenciamento para desenvolver soluções eficientes","ru":"Python-ml-workflow - это фреймворк ML/LLM, использующий Python 3.10+ и инструменты управления для разработки эффективных решений","ar":"python-ml-workflow هو إطار عمل ML/LLM يستخدم Python 3.10+ وأدوات الإدارة لتطوير حلول فعالة"},"features":{"en":["Utilizes Python 3.10+ for optimized ML development","Leverages uv, Poetry, and Rye for efficient dependency management","Employs Ruff for consistent code formatting","Supports strict type hinting using the typing module","Adheres to PEP 8 and the Zen of Python for Pythonic code","Uses pytest for comprehensive testing and validation"],"zh":["使用 Python 3.10+ 进行机器学习开发","uv、Poetry 和 Rye 进行管理和测试","Ruff 进行代码格式化","pytest 进行测试","Strict typing 模块用于类型提示"],"ja":["Python 3.10+ を使用してマシンラーニング開発を実現","uv、Poetry、Rye を使用して管理とテストを行う","Ruff を使用してコードを整形","pytest を使用してテストを行う","Strict typing モジュールを使用して型ヒントを行う"],"ko":["Python 3.10+를 사용하여 기계학습 개발을 효율적으로 구현","uv, Poetry 및 Rye를 사용하여 관리 및 테스트","Ruff를 사용하여 코드를 정렬","pytest를 사용하여 테스트","Strict typing 모듈을 사용하여 타입 힌트"],"es":["Compatibilidad con Python 3.10+","Gestión de dependencias con uv y Poetry","Pruebas unitarias con pytest","Formato de código con Ruff","Uso estricto del módulo de inferencia de tipos"],"fr":["Compatibilité avec Python 3.10+","Gestion des dépendances avec uv et Poetry","Tests unitaires avec pytest","Formatage de code avec Ruff","Utilisation stricte du module d''inférence de types"],"de":["Kompatibilität mit Python 3.10+","Abhängigkeitsverwaltung mit uv und Poetry","Einheitliche Tests mit pytest","Code-Formatierung mit Ruff","Strenger Einsatz des Typinferenz-Moduls"],"pt":["Suporte a Python 3.10+","Gerenciamento de dependências com uv e Poetry","Testes unitários com pytest","Formatação de código com Ruff","Tipagem estrita com módulo typing"],"ru":["Поддержка Python 3.10+","Управление зависимостями с помощью uv и Poetry","Юнит-тесты с помощью pytest","Форматирование кода с помощью Ruff","Строгая типизация с помощью модуля typing"],"ar":["دعم Python 3.10+","إدارة الإعتماديات مع uv و Poetry","اختبارات الوحدة مع pytest","تنسيق الكود مع Ruff","التحديد الصارم مع وحدة typing"]},"keywords":{"en":["python-ml-workflow setup guide","python-ml-workflow vs TensorFlow","how to use python-ml-workflow","python-ml-workflow install","python-ml-workflow alternative","what is python-ml-workflow","python-ml-workflow tutorial","python-ml-workflow best practices","python-ml-workflow documentation"],"zh":["Python 机器学习","Python 机器学习工作流","uv","Poetry","Rye","Ruff","pytest","Strict typing","AIエージェント"],"ja":["Python マシンラーニング","Python マシンラーニングワークフロー","uv","Poetry","Rye","Ruff","pytest","Strict typing","AIエージェント"],"ko":["Python 기계학습","Python 기계학습 워크플로우","uv","Poetry","Rye","Ruff","pytest","Strict typing","인공지능 도구"],"es":["python-ml-workflow","agentes de ia","herramientas de ia","aprendizaje automático","python 3.10+","uv","poetry","pytest","ruff","tipos de datos"],"fr":["python-ml-workflow","outils d''ia","agents d''ia","apprentissage automatique","python 3.10+","uv","poetry","pytest","ruff","types de données"],"de":["python-ml-workflow","ki-tools","ki-agenten","maschinelles lernen","python 3.10+","uv","poetry","pytest","ruff","datentypen"],"pt":["python-ml-workflow","desenvolvimento de ML/LLM","Python 3.10+","uv","Poetry","pytest","Ruff","typing","desenvolvedores de IA"],"ru":["python-ml-workflow","разработка ML/LLM","Python 3.10+","uv","Poetry","pytest","Ruff","typing","ИИ Агенты","разработчики ИИ"],"ar":["python-ml-workflow","تطوير ML/LLM","Python 3.10+","uv","Poetry","pytest","Ruff","typing","أدوات الذكاء الاصطناعي","مطورو الذكاء الاصطناعي"]}},"owner":"alfred1137","repo":"ScreenBanter","repoPath":"alfred1137/ScreenBanter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.598Z","topics":[],"category":"community","skillMd":{"name":"python-ml-workflow","description":"Expert guidelines for Python ML and LLM workflows. Covers code quality, experiment tracking, and data handling. Use when working on AI/ML components or data pipelines.","bodyPreview":"# Python ML/LLM Workflow\n\n## Persona\nAct as a Python Master, ML Engineer, and Data Scientist. Prioritize elegance, efficiency, and clarity.\n\n## Technology Stack\n- **Python**: 3.10+\n- **Management**: uv / Poetry / Rye\n- **Formatting**: Ruff\n- **Testing**: pytest\n- **Type Hinting**: Strict `typing` module usage.\n\n## Coding Guidelines\n- **Pythonic**: Adhere to PEP 8 and the Zen of Python.\n- **Explicit**: Favor explicit code over implicit magic.\n- **Documentation**: Google-style docstrings for ALL p","body":"# Python ML/LLM Workflow\n\n## Persona\nAct as a Python Master, ML Engineer, and Data Scientist. Prioritize elegance, efficiency, and clarity.\n\n## Technology Stack\n- **Python**: 3.10+\n- **Management**: uv / Poetry / Rye\n- **Formatting**: Ruff\n- **Testing**: pytest\n- **Type Hinting**: Strict `typing` module usage.\n\n## Coding Guidelines\n- **Pythonic**: Adhere to PEP 8 and the Zen of Python.\n- **Explicit**: Favor explicit code over implicit magic.\n- **Documentation**: Google-style docstrings for ALL public members.\n- **Testing**: Aim for >90% coverage.\n\n## ML/AI Specifics\n- **Reproducibility**: Use `hydra` or `yaml` for configs. Use `dvc` for data pipelines.\n- **Prompt Engineering**: Version control your prompt templates.\n- **Experiment Tracking**: Log parameters and results (MLflow/TensorBoard).\n- **Model Versioning**: Use git-lfs or cloud storage.\n\n## Performance\n- **Async**: Use `async`/`await` for I/O.\n- **Caching**: Use `functools.lru_cache` or similar.\n- **Monitoring**: Watch resource usage (`psutil`).\n"},"lastSynced":"2026-03-08T02:12:07.648Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced machine learning workflow capabilities with Python 3.10+","zh":"非常适合需要高级机器学习工作流能力的 AI Agent，支持 Python 3.10+","ja":"Python 3.10+ を使用した高度な機械学習ワークフロー機能が必要な AI エージェントに最適","ko":"Python 3.10+를 사용하여 고급 기계 학습 워크플로우 기능이 필요한 AI 에이전트에 적합","es":"Perfecto para agentes de IA que necesitan capacidades de flujo de trabajo de aprendizaje automático avanzadas con Python 3.10+","fr":"Parfait pour les agents IA nécessitant des capacités de workflow d''apprentissage automatique avancées avec Python 3.10+","de":"Perfekt für KI-Agents, die erweiterte maschinelles Lernen-Workflow-Fähigkeiten mit Python 3.10+ benötigen","pt":"Perfeito para Agents de IA que precisam de capacidades de fluxo de trabalho de aprendizado de máquina avançadas com Python 3.10+","ru":"Идеально для агентов ИИ, которым требуются расширенные возможности рабочего процесса машинного обучения с Python 3.10+","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى إمكانيات متقدمة في سير عمل التعلم الآلي مع Python 3.10+"},"recommendation":{"en":"Empowers agents to create elegant and efficient machine learning workflows utilizing uv, Poetry, and Ruff for optimized development, with strict adherence to PEP 8 and the Zen of Python, and leveraging pytest for testing and the typing module for type hinting","zh":"赋予代理创建优雅高效的机器学习工作流的能力，利用 uv、Poetry 和 Ruff 进行优化开发，严格遵守 PEP 8 和 Python 之禅，并利用 pytest 进行测试和 typing 模块进行类型提示","ja":"エージェントが、uv、Poetry、Ruff を使用して最適化された開発を行い、PEP 8 および Python の禅に厳密に従い、pytest を使用してテストを行い、typing モジュールを使用して型ヒントを行うことで、エレガントで効率的な機械学習ワークフローを作成する能力を付与","ko":"에이전트가 uv, Poetry, Ruff를 사용하여 최적화된 개발을 수행하고 PEP 8 및 Python의 제자로 엄격히遵守하며 pytest를 사용하여 테스트를 수행하고 typing 모듈을 사용하여 형식 힌트를 하는 기능을 부여하여 우아하고 효율적인 기계 학습 워크플로우를 생성","es":"Habilita a los agentes a crear flujos de trabajo de aprendizaje automático elegantes y eficientes utilizando uv, Poetry y Ruff para un desarrollo optimizado, con una estricta adherencia a PEP 8 y la Zen de Python, y aprovechando pytest para pruebas y el módulo de tipado para la inferencia de tipos","fr":"Permet aux agents de créer des flux de travail d''apprentissage automatique élégants et efficaces en utilisant uv, Poetry et Ruff pour un développement optimisé, avec une stricte adhésion à PEP 8 et la Zen de Python, et en exploitant pytest pour les tests et le module de typage pour l''inférence de types","de":"Ermöglicht es Agenten, elegante und effiziente maschinelles Lernen-Workflows zu erstellen, indem uv, Poetry und Ruff für optimierte Entwicklung verwendet werden, mit strikter Einhaltung von PEP 8 und der Zen von Python und unter Nutzung von pytest für Tests und des Typing-Moduls für die Typinferenz","pt":"Habilita os agentes a criarem fluxos de trabalho de aprendizado de máquina elegantes e eficientes utilizando uv, Poetry e Ruff para desenvolvimento otimizado, com aderência estrita ao PEP 8 e ao Zen of Python, e aproveitando pytest para testes e o módulo typing para dicas de tipo","ru":"Наделяет агентов возможностью создавать элегантные и эффективные рабочие процессы машинного обучения, используя uv, Poetry и Ruff для оптимизированного развития, со строгим соблюдением PEP 8 и Зена Питона, и использует pytest для тестирования и модуль typing для типовых намеков","ar":"يمنح الوكلاء khảية إنشاء سلاسل عمل التعلم الآلي الأنعم والأكثر كفاءة باستخدام uv و Poetry و Ruff لتطوير محسّن، مع التزام صارم ببروتوكول PEP 8 وZen of Python، ووفّر pytest للاختبار ومODULE typing لنصائح النوع"},"useCases":{"en":["Automating machine learning model deployment with Poetry and uv","Generating optimized data pipelines using Python 3.10+ and Ruff","Debugging machine learning workflows with pytest and strict type hinting"],"zh":["使用 Poetry 和 uv 自动化机器学习模型部署","使用 Python 3.10+ 和 Ruff 生成优化的数据管道","使用 pytest 和严格的类型提示调试机器学习工作流"],"ja":["Poetry と uv を使用した機械学習モデルデプロイの自動化","Python 3.10+ と Ruff を使用した最適化されたデータパイプラインの生成","pytest と厳密な型ヒントを使用した機械学習ワークフローのデバッグ"],"ko":["Poetry 및 uv를 사용하여 기계 학습 모델 배포 자동화","Python 3.10+ 및 Ruff를 사용하여 최적화된 데이터 파이프라인 생성","pytest 및 엄격한 형식 힌트를 사용하여 기계 학습 워크플로우 디버깅"],"es":["Automatización de la implementación de modelos de aprendizaje automático con Poetry y uv","Generación de tuberías de datos optimizadas utilizando Python 3.10+ y Ruff","Depuración de flujos de trabajo de aprendizaje automático con pytest y una estricta inferencia de tipos"],"fr":["Automatisation du déploiement de modèles d''apprentissage automatique avec Poetry et uv","Génération de pipelines de données optimisés en utilisant Python 3.10+ et Ruff","Débogage de flux de travail d''apprentissage automatique avec pytest et une stricte inférence de types"],"de":["Automatisierung der Bereitstellung von maschinellem Lernen-Modellen mit Poetry und uv","Generierung von optimierten Datenpipelines unter Verwendung von Python 3.10+ und Ruff","Fehlerbehebung von maschinellem Lernen-Workflows mit pytest und strenger Typinferenz"],"pt":["Automatizar a implantação de modelos de aprendizado de máquina com Poetry e uv","Gerar pipelines de dados otimizados usando Python 3.10+ e Ruff","Depurar fluxos de trabalho de aprendizado de máquina com pytest e dicas de tipo rigorosas"],"ru":["Автоматизировать развертывание моделей машинного обучения с помощью Poetry и uv","Генерировать оптимизированные конвейеры данных, используя Python 3.10+ и Ruff","Отладить рабочие процессы машинного обучения с помощью pytest и строгих типовых намеков"],"ar":["تأتمتة نشر نماذج التعلم الآلي باستخدام Poetry وuv","توليد أنابيب بيانات محسّنة باستخدام Python 3.10+ و Ruff","تصحيح أخطاء سلاسل عمل التعلم الآلي باستخدام pytest ونصائح النوع الصارمة"]},"limitations":{"en":["Requires Python 3.10+","Limited to uv, Poetry, and Ruff for management and formatting","Strict adherence to PEP 8 and the Zen of Python may limit flexibility"],"zh":["需要 Python 3.10+","仅限 uv, Poetry 和 Ruff 进行管理和格式化","严格遵守 PEP 8 和 Python 之禅可能会限制灵活性"],"ja":["Python 3.10+ が必要","管理およびフォーマットは uv、Poetry、Ruff に限定","PEP 8 および Python の禅に厳密に従うことで柔軟性が制限される可能性"],"ko":["Python 3.10+ 필요","관리 및 서식은 uv, Poetry, Ruff로 제한","PEP 8 및 Python의 제자로 엄격히 지키는 것으로 유연성이 제한될 수"],"es":["Requiere Python 3.10+","Limitado a uv, Poetry y Ruff para la administración y el formato","La estricta adherencia a PEP 8 y la Zen de Python puede limitar la flexibilidad"],"fr":["Nécessite Python 3.10+","Limité à uv, Poetry et Ruff pour la gestion et le formatage","La stricte adhésion à PEP 8 et la Zen de Python peut limiter la flexibilité"],"de":["Benötigt Python 3.10+","Begrenzt auf uv, Poetry und Ruff für die Verwaltung und Formatierung","Die strikte Einhaltung von PEP 8 und der Zen von Python kann die Flexibilität einschränken"],"pt":["Exige Python 3.10+","Limitado a uv, Poetry e Ruff para gerenciamento e formatação","A aderência estrita ao PEP 8 e ao Zen of Python pode limitar a flexibilidade"],"ru":["Требует Python 3.10+","Ограничен uv, Poetry и Ruff для управления и форматирования","Соблюдение PEP 8 и Зена Питона может ограничить гибкость"],"ar":["يتطلب Python 3.10+","محدد ب uv و Poetry و Ruff لإدارة والتنسيق","الالتزام الصارم ببروتوكول PEP 8 وZen of Python قد يقيد المرونة"]},"version":4},"contentHash":"04d31bacc40eec3b61fc70668edfbff44fbf533103501a7fe851bf298ba50864","qualityScore":26}');
