INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alfred1137/ScreenBanter/python-ml-workflow', 'python-ml-workflow', 'alfred1137', 'ScreenBanter', 'community', 'python-ml-workflow alfred1137 ScreenBanter community The python-ml-workflow skill enables Python masters, ML engineers, and data scientists to create elegant and efficient machine learning workflows. It utilizes Python 3.10+, uv, Poetry, and Ruff for optimized development. Python 机器学习工作流是一种使用 Python 3.10+ 和 uv 进行机器学习开发的方法，注重优雅和效率 Python マシンラーニングワークフローは、Python 3.10+ と uv を使用してマシンラーニング開発を実現する方法で、優雅さと効率性を重視 Python 기계학습 워크플로우는 Python 3.10+와 uv를 사용하여 기계학습 개발을 효율적이고 우아하게 구현하는 방법 Python-ml-workflow es un proyecto que combina Python 3.10+ con uv, Poetry y pytest para crear flujos de trabajo de aprendizaje automático eficientes Python-ml-workflow est un projet qui combine Python 3.10+ avec uv, Poetry et pytest pour créer des flux de travail d''apprentissage automatique efficaces Python-ml-workflow ist ein Projekt, das Python 3.10+ mit uv, Poetry und pytest kombiniert, um effiziente maschinelles Lernen-Workflows zu erstellen O python-ml-workflow é uma solução de ML/LLM que combina Python 3.10+ com ferramentas de gerenciamento e teste para desenvolver aplicações eficientes Python-ml-workflow - это решение ML/LLM, объединяющее Python 3.10+ с инструментами управления и тестирования для разработки эффективных приложений с помощью ИИ Агентов python-ml-workflow هو حل ML/LLM يجمع بين Python 3.10+ وأدوات الإدارة والاختبار لتطوير تطبيقات فعالة مع أدوات الذكاء الاصطناعي python-ml-workflow setup guide python-ml-workflow vs TensorFlow how to use python-ml-workflow python-ml-workflow install python-ml-workflow alternative what is python-ml-workflow python-ml-workflow tutorial python-ml-workflow best practices python-ml-workflow documentation Python 机器学习 Python 机器学习工作流 uv Poetry Rye Ruff pytest Strict typing AIエージェント Utilizes Python 3.10+ for optimized ML development Leverages uv, Poetry, and Rye for efficient dependency management Employs Ruff for consistent code formatting Supports strict type hinting using the typing module Adheres to PEP 8 and the Zen of Python for Pythonic code Uses pytest for comprehensive testing and validation python-ml-workflow is a skill that combines Python, machine learning, and efficient workflow management using tools like uv, Poetry, and Ruff for streamlined development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('1105564578/erosion-gully-system/erosion-gully-analysis', 'community', '1105564578', 'erosion-gully-system', '1105564578/erosion-gully-system', 'erosion-gully-analysis', 0, 0, 26, '2026-03-08T01:57:15.603Z', '2026-03-08T02:13:08.125Z', '7d407173e6cf9b9e70ed0425c7ce2947ca2186bf2579b3aeb39394cd1ccc4cc5', '{"id":"1105564578/erosion-gully-system/erosion-gully-analysis","name":"erosion-gully-analysis","description":{"en":"The erosion-gully-analysis skill provides AI-driven analysis for gully erosion, enhancing judgment quality and advice generation for developers and researchers. It supports SiliconFlow and OpenAI interfaces.","zh":"erosion-gully-analysis 是一个 AI 分析模块，提供稳定可复用的操作流程，支持提升判断质量和优化治理建议","ja":"erosion-gully-analysis は AI 分析モジュールであり、安定した再利用可能な操作フローを提供し、判断の質の向上と治水提案の最適化をサポート","ko":"erosion-gully-analysis는 AI 분석 모듈로서 안정적이고 재사용 가능한 운영 프로세스를 제공하고, 판단의 품질 향상과 치수 제안의 최적화를 지원","es":"El análisis de erosión de cauces es una habilidad de IA que utiliza Python y SiliconFlow para analizar y optimizar la calidad de los juicios y las recomendaciones de tratamiento","fr":"L''analyse d''érosion de ravins est une compétence d''IA qui utilise Python et SiliconFlow pour analyser et optimiser la qualité des jugements et des recommandations de traitement","de":"Die Analyse von Erosionsgräben ist eine KI-Fähigkeit, die Python und SiliconFlow verwendet, um die Qualität der Urteile und Behandlungsempfehlungen zu analysieren und zu optimieren","pt":"O erosion-gully-analysis é uma ferramenta de análise de erosão que utiliza AI para melhorar a qualidade de julgamento e fornecer sugestões de tratamento otimizadas","ru":"erosion-gully-analysis - это инструмент анализа эрозии, который использует ИИ для повышения качества суждения и предоставления оптимизированных рекомендаций по лечению","ar":"erosion-gully-analysis هو أداة لتحليل الانحلال التي تستخدم أدوات الذكاء الاصطناعي لتحسين جودة الحكم وتقديم اقتراحات علاج محسنة"},"seo":{"title":{"en":"erosion-gully-analysis: AI-Powered Gully Erosion Setup Gu...","zh":"erosion-gully-analysis Setup Guide - 侵蚀沟 AI 分析最佳实践","ja":"erosion-gully-analysis セットアップガイド - 侵食谷 AI 分析ツール","ko":"erosion-gully-analysis 설정 가이드 - 침식 골 AI 분석 에이전트","es":"Guía de configuración para análisis de erosión de cauces ...","fr":"Guide de configuration pour l''analyse d''érosion de ravins...","de":"Konfigurationsleitfaden für die Analyse von Erosionsgräbe...","pt":"Guia de Configuração do erosion-gully-analysis para Análi...","ru":"Настройка erosion-gully-analysis: Руководство по Анализу ...","ar":"دليل تكوين erosion-gully-analysis لتحليل الانحلال مع أدوا..."},"description":{"en":"Unlock the power of AI-driven erosion gully analysis with our expert guide. Learn how to optimize judgment quality and generate professional advice using Sil...","zh":"了解 erosion-gully-analysis 的技术细节，优化治理建议的专业性与可执行性，兼容 SiliconFlow 接口","ja":"erosion-gully-analysis の技術的詳細を学び、治水提案の専門性と実行可能性を最適化し、SiliconFlow インターフェースをサポート","ko":"erosion-gully-analysis의 기술적 세부 사항을 이해하고, 치수 제안의 전문성 및 실행 가능성을 최적화하고, SiliconFlow 인터페이스를 지원","es":"Aprende a configurar y utilizar el análisis de erosión de cauces con agentes de IA para mejorar la calidad de tus decisiones","fr":"Découvrez comment configurer et utiliser l''analyse d''érosion de ravins avec des outils d''IA pour améliorer la qualité de vos décisions","de":"Erfahren Sie, wie Sie die Analyse von Erosionsgräben mit KI-Agents konfigurieren und nutzen können, um die Qualität Ihrer Entscheidungen zu verbessern","pt":"Aprenda a configurar o erosion-gully-analysis para análise de erosão com AI. Melhore a qualidade de julgamento e obtenha sugestões de tratamento otimizadas","ru":"Узнайте, как настроить erosion-gully-analysis для анализа эрозии с ИИ. Повысьте качество суждения и получите оптимизированные рекомендации по лечению","ar":"تعرف على كيفية تكوين erosion-gully-analysis لتحليل الانحلال مع أدوات الذكاء الاصطناعي. تحسين جودة الحكم والحصول على اقتراحات علاج محسنة"},"definition":{"en":"erosion-gully-analysis is a specialized AI skill for analyzing gully erosion, providing stable and reusable operational workflows for improved judgment and advice generation.","zh":"erosion-gully-analysis 是一种 AI 工具，用于分析和优化治理建议","ja":"erosion-gully-analysis は、治水提案を分析および最適化する AI エージェント","ko":"erosion-gully-analysis는 치수 제안을 분석 및 최적화하는 AI 에이전트","es":"Análisis de erosión de cauces es una técnica de IA que utiliza algoritmos para evaluar y mejorar la calidad de los juicios y las recomendaciones de tratamiento","fr":"L''analyse d''érosion de ravins est une technique d''IA qui utilise des algorithmes pour évaluer et améliorer la qualité des jugements et des recommandations de traitement","de":"Die Analyse von Erosionsgräben ist eine KI-Technik, die Algorithmen verwendet, um die Qualität der Urteile und Behandlungsempfehlungen zu bewerten und zu verbessern","pt":"O que é erosion-gully-analysis? É uma ferramenta de análise de erosão que utiliza AI para melhorar a qualidade de julgamento","ru":"Что такое erosion-gully-analysis? Это инструмент анализа эрозии, который использует ИИ для повышения качества суждения","ar":"ما هو erosion-gully-analysis؟ هو أداة لتحليل الانحلال التي تستخدم أدوات الذكاء الاصطناعي لتحسين جودة الحكم"},"features":{"en":["Utilizes ai_analysis.py for AI module code","Leverages ai_prompts/screening_system.txt and ai_prompts/advice_system.txt for prompt files","Supports SiliconFlow (OpenAI-style) interface for compatibility","Allows for threshold adjustments in ai_analysis.py using _rule_screening and _rule_advice","Injects model and authorization information via environment variables (SILICONFLOW_BASE_URL, SILICONFLOW_API_KEY, SILICONFLOW_MODEL)"],"zh":["支持 SiliconFlow 接口","优化治理建议的专业性与可执行性","提供稳定可复用的操作流程","提升判断质量","使用 Python 编写","兼容多种环境变量"],"ja":["SiliconFlow インターフェースをサポート","治水提案の専門性と実行可能性を最適化","安定した再利用可能な操作フローを提供","判断の質の向上","Python で書かれた","複数の環境変数をサポート"],"ko":["SiliconFlow 인터페이스를 지원","치수 제안의 전문성 및 실행 가능성을 최적화","안정적인 재사용 가능한 운영 프로세스를 제공","판단의 품질 향상","Python으로 작성됨","여러 환경 변수를 지원"],"es":["Utiliza Python para analizar y optimizar la calidad de los juicios","Integra con SiliconFlow para mejorar la precisión de las recomendaciones de tratamiento","Permite la personalización de los umbrales de detección y las reglas de tratamiento","Utiliza algoritmos de aprendizaje automático para mejorar la calidad de los juicios y las recomendaciones","Proporciona resultados en formato JSON para una fácil integración con otras herramientas"],"fr":["Utilise Python pour analyser et optimiser la qualité des jugements","Intègre avec SiliconFlow pour améliorer la précision des recommandations de traitement","Permet la personnalisation des seuils de détection et des règles de traitement","Utilise des algorithmes d''apprentissage automatique pour améliorer la qualité des jugements et des recommandations","Fournit des résultats au format JSON pour une intégration facile avec d''autres outils"],"de":["Verwendet Python, um die Qualität der Urteile zu analysieren und zu optimieren","Integriert mit SiliconFlow, um die Genauigkeit der Behandlungsempfehlungen zu verbessern","Ermöglicht die Anpassung der Erkennungsschwellen und Behandlungsregeln","Verwendet Algorithmen des maschinellen Lernens, um die Qualität der Urteile und Empfehlungen zu verbessern","Bietet Ergebnisse im JSON-Format für eine einfache Integration mit anderen Tools"],"pt":["Utiliza AI para melhorar a qualidade de julgamento","Fornecer sugestões de tratamento otimizadas","Compatível com SiliconFlow (OpenAI)","Código de análise de AI em Python","Arquivos de prompts personalizáveis"],"ru":["Использует ИИ для повышения качества суждения","Предоставляет оптимизированные рекомендации по лечению","Компатибельный с SiliconFlow (OpenAI)","Код анализа ИИ на Python","Настраиваемые файлы-промпты"],"ar":["استخدام أدوات الذكاء الاصطناعي لتحسين جودة الحكم","تقديم اقتراحات علاج محسنة","متوافق مع SiliconFlow (OpenAI)","كود تحليل الذكاء الاصطناعي bằng Python","ملفات إعدادات قابلة للتعديل"]},"keywords":{"en":["how to use erosion-gully-analysis","what is erosion-gully-analysis","erosion-gully-analysis alternative","erosion-gully-analysis vs OpenAI","erosion-gully-analysis install guide","erosion-gully-analysis setup tutorial","ai-powered gully erosion analysis","siliconflow interface tutorial","openai style interface for erosion gully analysis"],"zh":["erosion-gully-analysis","AI 分析","治理建议","SiliconFlow","Python","环境变量","AI 工具","侵蚀沟分析"],"ja":["erosion-gully-analysis","AI 分析","治水提案","SiliconFlow","Python","環境変数","AI エージェント","侵食谷分析"],"ko":["erosion-gully-analysis","AI 분석","치수 제안","SiliconFlow","Python","환경 변수","AI 에이전트","침식 골 분석"],"es":["análisis de erosión de cauces","agentes de IA","Python","SiliconFlow","aprendizaje automático","recomendaciones de tratamiento","calidad de los juicios","integración con otras herramientas"],"fr":["analyse d''érosion de ravins","outils d''IA","Python","SiliconFlow","apprentissage automatique","recommandations de traitement","qualité des jugements","intégration avec d''autres outils"],"de":["Analyse von Erosionsgräben","KI-Agents","Python","SiliconFlow","maschinelle Lernverfahren","Behandlungsempfehlungen","Qualität der Urteile","Integration mit anderen Tools"],"pt":["análise de erosão","AI para análise de erosão","erosion-gully-analysis","SiliconFlow","OpenAI","Python para análise de AI","análise de dados de erosão"],"ru":["анализ эрозии","ИИ для анализа эрозии","erosion-gully-analysis","SiliconFlow","OpenAI","Python для анализа ИИ","анализ данных об эрозии"],"ar":["تحليل الانحلال","أدوات الذكاء الاصطناعي لتحليل الانحلال","erosion-gully-analysis","SiliconFlow","OpenAI","Python لتحليل الذكاء الاصطناعي","تحليل بيانات الانحلال"]}},"owner":"1105564578","repo":"erosion-gully-system","repoPath":"1105564578/erosion-gully-system","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.603Z","topics":[],"category":"community","skillMd":{"name":"erosion-gully-analysis","description":"用于侵蚀沟初筛与精细测量的AI分析与治理建议。适用于：封装/修改AI分析流程、调整治理判断逻辑、优化提示词、对接SiliconFlow或类似OpenAI风格接口。","bodyPreview":"# 侵蚀沟 AI 分析 Skill\n\n## 目标\n为本项目的 AI 分析模块提供稳定可复用的操作流程，支持：\n- 提升“是否治理”的判断质量\n- 优化治理建议的专业性与可执行性\n- 兼容 SiliconFlow（OpenAI 风格）接口\n\n## 关键入口\n- AI 模块代码：`ai_analysis.py`\n- 提示词文件：\n  - `ai_prompts/screening_system.txt`\n  - `ai_prompts/advice_system.txt`\n\n## 使用流程\n1) 需要提升判断质量时，优先修改 `ai_prompts/*.txt`，避免直接改逻辑。\n2) 如需调整规则兜底阈值，修改 `ai_analysis.py` 中 `_rule_screening` 与 `_rule_advice`。\n3) 模型/鉴权信息通过环境变量注入：\n   - `SILICONFLOW_BASE_URL`\n   - `SILICONFLOW_API_KEY`\n   - `SILICONFLOW_MODEL`\n\n## 输出约束\n- 必须输出 JSON，字段固定：\n  - 初筛：de","body":"# 侵蚀沟 AI 分析 Skill\n\n## 目标\n为本项目的 AI 分析模块提供稳定可复用的操作流程，支持：\n- 提升“是否治理”的判断质量\n- 优化治理建议的专业性与可执行性\n- 兼容 SiliconFlow（OpenAI 风格）接口\n\n## 关键入口\n- AI 模块代码：`ai_analysis.py`\n- 提示词文件：\n  - `ai_prompts/screening_system.txt`\n  - `ai_prompts/advice_system.txt`\n\n## 使用流程\n1) 需要提升判断质量时，优先修改 `ai_prompts/*.txt`，避免直接改逻辑。\n2) 如需调整规则兜底阈值，修改 `ai_analysis.py` 中 `_rule_screening` 与 `_rule_advice`。\n3) 模型/鉴权信息通过环境变量注入：\n   - `SILICONFLOW_BASE_URL`\n   - `SILICONFLOW_API_KEY`\n   - `SILICONFLOW_MODEL`\n\n## 输出约束\n- 必须输出 JSON，字段固定：\n  - 初筛：decision / reason / risk_level\n  - 建议：risk_level / summary / actions\n\n## 注意事项\n- 优先保证 JSON 可解析\n- 若 LLM 失败，系统会自动回退到规则结果\n"},"lastSynced":"2026-03-08T02:13:08.125Z","agentAnalysis":{"suitability":{"en":"Perfect for Environmental Analysis Agents needing advanced erosion-gully-analysis capabilities with SiliconFlow and OpenAI interfaces.","zh":"非常适合需要使用SiliconFlow和OpenAI接口进行高级侵蚀-沟壑分析的环境分析代理。","ja":"SiliconFlowとOpenAIインターフェースを使用した高度な浸食-渓谷分析機能を必要とする環境分析エージェントに最適です。","ko":"SiliconFlow와 OpenAI 인터페이스를 사용한 고급 침식-골짜기 분석 기능이 필요한 환경 분석 에이전트에게 완벽합니다.","es":"Perfecto para Agentes de Análisis Ambiental que necesitan capacidades de análisis de erosión y zanjas avanzadas con interfaces de SiliconFlow y OpenAI.","fr":"Parfait pour les Agents d''Analyse Environnementale ayant besoin de capacités d''analyse d''érosion et de ravins avancées avec des interfaces SiliconFlow et OpenAI.","de":"Perfekt für Umweltanalyse-Agents, die erweiterte Erosions- und Grabenanalysefähigkeiten mit SiliconFlow- und OpenAI-Schnittstellen benötigen.","pt":"Perfeito para Agentes de Análise Ambiental que necessitam de capacidades avançadas de análise de erosão-gulodão com interfaces SiliconFlow e OpenAI.","ru":"Идеально подходит для агентов анализа окружающей среды, которым необходимы продвинутые возможности анализа эрозии оврагов с интерфейсами SiliconFlow и OpenAI.","ar":"مثالي للوكلاء المحللين البيئيين الذين يحتاجون إلى قدرات متقدمة لتحليل تآكل الخنادق مع واجهات SiliconFlow و OpenAI."},"recommendation":{"en":"Empowers agents to generate high-quality judgments and advice for gully erosion using AI-driven analysis, supporting JSON output and compatible with SiliconFlow and OpenAI styles, leveraging environment variables for model and API key injection.","zh":"赋予代理生成高质量的判断和建议的能力，使用AI驱动的分析，支持JSON输出，并与SiliconFlow和OpenAI样式兼容，利用环境变量注入模型和API密钥。","ja":"エージェントに高品質の判断とアドバイスを生成する能力を付与します。AI駆動の分析を使用し、JSON出力をサポートし、SiliconFlowおよびOpenAIスタイルと互換性があり、環境変数を使用してモデルとAPIキーを注入します。","ko":"에이전트가 고품질의 판단과 조언을 생성할 수 있는 능력을 부여합니다. AI 驱动의 분석을 사용하고 JSON 출력을 지원하며 SiliconFlow 및 OpenAI 스타일과 호환되며 환경 변수를 사용하여 모델과 API 키를 주입합니다.","es":"Habilita a los agentes a generar juicios y consejos de alta calidad para la erosión de zanjas utilizando análisis impulsado por IA, compatible con la salida JSON y estilos de SiliconFlow y OpenAI, aprovechando variables de entorno para la inyección de modelos y claves de API.","fr":"Permet aux agents de générer des jugements et des conseils de haute qualité pour l''érosion des ravins en utilisant l''analyse pilotée par l''IA, compatible avec la sortie JSON et les styles SiliconFlow et OpenAI, en exploitant les variables d''environnement pour l''injection de modèles et de clés d''API.","de":"Ermächtigt Agenten, hochwertige Urteile und Empfehlungen für Grabenerosion zu generieren, indem sie analysieren, die von KI angetrieben wird, unterstützt JSON-Ausgabe und ist kompatibel mit SiliconFlow- und OpenAI-Stilen, indem sie Umgebungsvariablen für Modell- und API-Schlüsselinjektion nutzen.","pt":"Habilita os agentes a gerar julgamentos e conselhos de alta qualidade para a erosão dos gulodões usando análise impulsionada por IA, com suporte a saída JSON e compatível com estilos SiliconFlow e OpenAI, aproveitando variáveis de ambiente para injeção de modelo e chave de API.","ru":"Наделяет агентов возможностью генерировать высококачественные суждения и рекомендации для эрозии оврагов с помощью анализа, управляемого ИИ, поддерживающего вывод в формате JSON и совместимого со стилями SiliconFlow и OpenAI, используя переменные среды для инъекции модели и ключа API.","ar":"يمنح الوكلاء القدرة على生成 أحكام و نصائح عالية الجودة لتيارات الانجراف باستخدام تحليل مدفوع بالذكاء الاصطناعي، مع دعم لإخراج JSON ومتوافق مع أنماط SiliconFlow و OpenAI، باستخدام متغيرات البيئة لتحققيق نموذج و مفتاح API."},"useCases":{"en":["Automating gully erosion judgment quality enhancements","Optimizing advice generation for developers and researchers","Integrating with SiliconFlow and OpenAI interfaces for seamless analysis"],"zh":["自动化沟壑侵蚀判断质量增强","优化开发人员和研究人员的建议生成","与SiliconFlow和OpenAI接口集成以实现无缝分析"],"ja":["渓谷浸食の判断の品質を自動化する","開発者および研究者のアドバイス生成を最適化する","SiliconFlowおよびOpenAIインターフェースと統合して無断分析を実現する"],"ko":["골짜기 침식 판단의 품질을 자동화하는 것","개발자 및 연구자의 조언 생성을 최적화하는 것","SiliconFlow 및 OpenAI 인터페이스와 통합하여 무중단 분석을 구현하는 것"],"es":["Automatizar la mejora de la calidad de los juicios de erosión de zanjas","Optimizar la generación de consejos para desarrolladores e investigadores","Integrarse con interfaces de SiliconFlow y OpenAI para un análisis sin problemas"],"fr":["Automatiser l''amélioration de la qualité des jugements d''érosion des ravins","Optimiser la génération de conseils pour les développeurs et les chercheurs","Intégrer les interfaces SiliconFlow et OpenAI pour une analyse sans problème"],"de":["Die Automatisierung der Qualitätsverbesserung der Urteile für Grabenerosion","Die Optimierung der Generierung von Empfehlungen für Entwickler und Forscher","Die Integration mit SiliconFlow- und OpenAI-Schnittstellen für eine reibungslose Analyse"],"pt":["Automatizar a melhoria da qualidade do julgamento da erosão dos gulodões","Otimizar a geração de conselhos para desenvolvedores e pesquisadores","Integrar com interfaces SiliconFlow e OpenAI para análise sem interrupções"],"ru":["Автоматизировать улучшение качества суждения об эрозии оврагов","Оптимизировать генерацию рекомендаций для разработчиков и исследователей","Интегрироваться с интерфейсами SiliconFlow и OpenAI для бесперебойного анализа"],"ar":["أتمتة تحسين جودة الحكم على تيار الانجراف","تحسين توليد النصائح للمطورين والباحثين","التكامل مع واجهات SiliconFlow و OpenAI لتحليل متواصل"]},"limitations":{"en":["Requires SiliconFlow base URL, API key, and model environment variables","Limited to JSON output with fixed fields","Dependent on ai_analysis.py and ai_prompts files for functionality"],"zh":["需要SiliconFlow基准URL、API密钥和模型环境变量","仅限JSON输出，字段固定","依赖ai_analysis.py和ai_prompts文件来实现功能"],"ja":["SiliconFlowのベースURL、APIキー、およびモデル環境変数が必要","JSON出力のみ、フィールドは固定","機能を実現するためにai_analysis.pyおよびai_promptsファイルに依存"],"ko":["SiliconFlow 기본 URL, API 키 및 모델 환경 변수가 필요","JSON 출력만 가능, 필드는 고정","기능을 구현하기 위해 ai_analysis.py 및 ai_prompts 파일에 의존"],"es":["Requiere la URL base de SiliconFlow, la clave de API y las variables de entorno del modelo","Limitado a la salida JSON con campos fijos","Dependiente de los archivos ai_analysis.py y ai_prompts para la funcionalidad"],"fr":["Nécessite l''URL de base de SiliconFlow, la clé d''API et les variables d''environnement du modèle","Limité à la sortie JSON avec des champs fixes","Dépendant des fichiers ai_analysis.py et ai_prompts pour la fonctionnalité"],"de":["Benötigt die Basis-URL von SiliconFlow, den API-Schlüssel und die Umgebungsvariablen des Modells","Begrenzt auf die JSON-Ausgabe mit festen Feldern","Abhängig von den Dateien ai_analysis.py und ai_prompts für die Funktionalität"],"pt":["Requer URL base do SiliconFlow, chave de API e variáveis de ambiente do modelo","Limitado a saída JSON com campos fixos","Dependente dos arquivos ai_analysis.py e ai_prompts para funcionalidade"],"ru":["Требует базового URL SiliconFlow, ключа API и переменных среды модели","Ограничен выводом JSON с фиксированными полями","Зависит от файлов ai_analysis.py и ai_prompts для функциональности"],"ar":["يتطلب URL قاعدة SiliconFlow و مفتاح API ومتغيرات بيئة النموذج","محدود بإخراج JSON مع حقول ثابتة","يعتمد على ملفات ai_analysis.py و ai_prompts للوظائف"]},"version":4},"contentHash":"7d407173e6cf9b9e70ed0425c7ce2947ca2186bf2579b3aeb39394cd1ccc4cc5","qualityScore":26}');
