INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('1105564578/erosion-gully-system/erosion-gully-analysis', 'erosion-gully-analysis', '1105564578', 'erosion-gully-system', 'community', 'erosion-gully-analysis 1105564578 erosion-gully-system community The erosion-gully-analysis skill provides AI-driven analysis for gully erosion, enhancing judgment quality and advice generation for developers and researchers. It supports SiliconFlow and OpenAI interfaces. erosion-gully-analysis 是一个 AI 分析模块，提供稳定可复用的操作流程，支持提升判断质量和优化治理建议 erosion-gully-analysis は AI 分析モジュールであり、安定した再利用可能な操作フローを提供し、判断の質の向上と治水提案の最適化をサポート erosion-gully-analysis는 AI 분석 모듈로서 안정적이고 재사용 가능한 운영 프로세스를 제공하고, 판단의 품질 향상과 치수 제안의 최적화를 지원 El análisis de erosión de cauces es una habilidad de IA que utiliza Python y SiliconFlow para analizar y optimizar la calidad de los juicios y las recomendaciones de tratamiento L''analyse d''érosion de ravins est une compétence d''IA qui utilise Python et SiliconFlow pour analyser et optimiser la qualité des jugements et des recommandations de traitement Die Analyse von Erosionsgräben ist eine KI-Fähigkeit, die Python und SiliconFlow verwendet, um die Qualität der Urteile und Behandlungsempfehlungen zu analysieren und zu optimieren O erosion-gully-analysis é uma ferramenta de análise de erosão que utiliza AI para melhorar a qualidade de julgamento e fornecer sugestões de tratamento otimizadas erosion-gully-analysis - это инструмент анализа эрозии, который использует ИИ для повышения качества суждения и предоставления оптимизированных рекомендаций по лечению erosion-gully-analysis هو أداة لتحليل الانحلال التي تستخدم أدوات الذكاء الاصطناعي لتحسين جودة الحكم وتقديم اقتراحات علاج محسنة how to use erosion-gully-analysis what is erosion-gully-analysis erosion-gully-analysis alternative erosion-gully-analysis vs OpenAI erosion-gully-analysis install guide erosion-gully-analysis setup tutorial ai-powered gully erosion analysis siliconflow interface tutorial openai style interface for erosion gully analysis erosion-gully-analysis AI 分析 治理建议 SiliconFlow Python 环境变量 AI 工具 侵蚀沟分析 Utilizes ai_analysis.py for AI module code Leverages ai_prompts/screening_system.txt and ai_prompts/advice_system.txt for prompt files Supports SiliconFlow (OpenAI-style) interface for compatibility Allows for threshold adjustments in ai_analysis.py using _rule_screening and _rule_advice Injects model and authorization information via environment variables (SILICONFLOW_BASE_URL, SILICONFLOW_API_KEY, SILICONFLOW_MODEL) erosion-gully-analysis is a specialized AI skill for analyzing gully erosion, providing stable and reusable operational workflows for improved judgment and advice generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hfadhlullah/dnd-game/Product Brief Generator', 'community', 'hfadhlullah', 'dnd-game', 'hfadhlullah/dnd-game', 'Product Brief Generator', 0, 0, 26, '2026-03-08T01:57:15.605Z', '2026-03-08T02:13:09.374Z', '180f2aa761bf6c066a4a89704be7fad528ec216e3d7912a8ae108bf70df4f34d', '{"id":"hfadhlullah/dnd-game/Product Brief Generator","name":"Product Brief Generator","description":{"en":"The Product Brief Generator helps Senior Product Managers create concise executive-level product briefs, capturing a product''s essence for executive review and investor communications.","zh":"产品简报生成器可以生成清晰、简洁的产品简报，包括表格和视觉元素，适合高管审查和投资者沟通","ja":"製品ブリーフ生成ツールは、表とビジュアル要素を含む、明確で簡潔な製品ブリーフを生成します","ko":"제품 브리프 생성기는 테이블과 시각적 요소를 포함하는 명확하고 간결한 제품 브리프를 생성합니다","es":"El generador de resúmenes de producto crea resúmenes ejecutivos claros y concisos con tablas y elementos visuales para la comunicación efectiva con los stakeholders","fr":"Le générateur de note de produit crée des notes de produit exécutives claires et concises avec des tableaux et des éléments visuels pour une communication efficace avec les parties prenantes","de":"Der Produktkurzbeschreibung-Generator erstellt klare und prägnante Produktzusammenfassungen mit Tabellen und visuellen Elementen für eine effektive Kommunikation mit den Stakeholdern","pt":"O Gerador de Breve de Produto cria resumos claros e concisos para produtos, utilizando tabelas para dados estruturados e elementos visuais","ru":"Генератор Краткого Описания Продукта создает краткие и понятные описания продукта, использующие таблицы для структурированных данных и визуальные элементы","ar":"مولد ملخص المنتج يولد ملخصات واضحة وموجزة للمنتجات، باستخدام جداول للبيانات المنظمة وElements مرئية"},"seo":{"title":{"en":"Product Brief Generator: Executive Summary Setup Guide | ...","zh":"产品简报生成器设置指南","ja":"製品ブリーフ生成ツールベストプラクティス","ko":"제품 브리프 생성기 사용법","es":"Generador de Resúmenes de Producto: Guía de Configuración...","fr":"Générateur de Note de Produit: Meilleures Pratiques avec ...","de":"Produktkurzbeschreibung-Generator: Einrichtungsleitfaden ...","pt":"Guia de Configuração do Gerador de Breve de Produto","ru":"ИИ Агент: Руководство по настройке Генератора Краткого Оп...","ar":"دليل إعداد مولد ملخص المنتج باستخدام أداة الذكاء الاصطناعي"},"description":{"en":"Discover how to generate polished product briefs with the Product Brief Generator. Learn to drive stakeholder alignment with clear summaries and visual eleme...","zh":"使用AIエージェント生成高质量的产品简报，包括表格和视觉元素，适合高管审查和投资者沟通","ja":"AIエージェントを使用して、表とビジュアル要素を含む、高品質の製品ブリーフを生成します","ko":"AIツール을 사용하여 테이블과 시각적 요소를 포함하는 고품질의 제품 브리프를 생성합니다","es":"Aprende a crear resúmenes de producto efectivos con nuestro generador de resúmenes de producto y herramientas de AI para una comunicación clara con los stake...","fr":"Découvrez comment créer des notes de produit efficaces avec notre générateur de note de produit et les outils d''IA pour une communication claire avec les par...","de":"Erfahren Sie, wie Sie mit unserem Produktkurzbeschreibung-Generator und KI-Tools effektive Produktzusammenfassungen erstellen und eine klare Kommunikation mi...","pt":"Aprenda a criar resumos de produtos claros e concisos com o Gerador de Breve de Produto, perfeito para revisão executiva e apresentações","ru":"Создайте краткие и понятные описания продукта с помощью Генератора Краткого Описания Продукта, подходящего для обзора руководства и презентаций","ar":"تعلم كيفية إنشاء ملخصات منتجات واضحة وموجزة باستخدام مولد ملخص المنتج، مناسب للاستعراض التنفيذي والعروض"},"definition":{"en":"Product Brief Generator is a tool that distills complex product information into clear, compelling summaries, using tables for structured data and visual elements.","zh":"产品简报生成器是一种AI工具，用于生成高质量的产品简报","ja":"製品ブリーフ生成ツールは、AIエージェントを使用して、高品質の製品ブリーフを生成するツールです","ko":"제품 브리프 생성기는 AIツール을 사용하여 고품질의 제품 브리프를 생성하는 도구입니다","es":"Un generador de resúmenes de producto es una herramienta de AI que crea resúmenes ejecutivos claros y concisos para la comunicación efectiva con los stakeholders","fr":"Un générateur de note de produit est un outil d''IA qui crée des notes de produit exécutives claires et concises pour une communication efficace avec les parties prenantes","de":"Ein Produktkurzbeschreibung-Generator ist ein KI-Tool, das klare und prägnante Produktzusammenfassungen für eine effektive Kommunikation mit den Stakeholdern erstellt","pt":"O que é um Gerador de Breve de Produto? É uma ferramenta que cria resumos de produtos claros e concisos para revisão executiva","ru":"Что такое Генератор Краткого Описания Продукта? Это инструмент, создающий краткие и понятные описания продукта для обзора руководства","ar":"ما هو مولد ملخص المنتج؟ هو أداة توليد ملخصات منتجات واضحة وموجزة للاستعراض التنفيذي"},"features":{"en":["Generates scannable product briefs with tables for structured data","Includes visual elements to enhance executive-level presentations","Creates polished summaries suitable for executive review and board presentations","Supports investor communications with clear and concise product information","Captures a product''s essence in a concise and compelling manner","Uses a structured approach to drive stakeholder alignment"],"zh":["生成清晰、简洁的产品简报","包括表格和视觉元素","适合高管审查和投资者沟通","使用React和Python技术","支持CLI命令行接口"],"ja":["明確で簡潔な製品ブリーフを生成","表とビジュアル要素を含む","高管レビューと投資家コミュニケーションに適している","ReactとPython技術を使用","CLIコマンドラインインターフェイスをサポート"],"ko":["명확하고 간결한 제품 브리프를 생성","테이블과 시각적 요소를 포함","고위급 검토와 투자자 커뮤니케이션에 적합","React와 Python 기술을 사용","CLI 명령줄 인터페이스를 지원"],"es":["Creación de resúmenes ejecutivos claros y concisos","Uso de tablas para datos estructurados","Incorporación de elementos visuales para una mejor comprensión","Generación de documentos escaneables para una fácil revisión","Apoyo para presentaciones de junta y comunicaciones con inversores"],"fr":["Création de notes de produit exécutives claires et concises","Utilisation de tableaux pour les données structurées","Intégration d''éléments visuels pour une meilleure compréhension","Génération de documents scannables pour une révision facile","Support pour les présentations de conseil d''administration et les communications avec les investisseurs"],"de":["Erstellung klarer und prägnanter Produktzusammenfassungen","Verwendung von Tabellen für strukturierte Daten","Einbindung von visuellen Elementen für ein besseres Verständnis","Generierung von scannbaren Dokumenten für eine einfache Überprüfung","Unterstützung für Vorstands- und Investorenpräsentationen"],"pt":["Cria resumos claros e concisos para produtos","Utiliza tabelas para dados estruturados","Inclui elementos visuais para melhor compreensão","Perfeito para revisão executiva e apresentações","Captura a essência do produto de forma eficaz"],"ru":["Создает краткие и понятные описания продукта","Использует таблицы для структурированных данных","Включает визуальные элементы для лучшего понимания","Подходит для обзора руководства и презентаций","Эффективно捕уривает суть продукта"],"ar":["يولد ملخصات واضحة وموجزة للمنتجات","يستخدم جداول للبيانات المنظمة","يتضمن عناصر مرئية لافضل فهم","مناسب للاستعراض التنفيذي والعروض","يحظى بفعالية في 捕获 جوهر المنتج"]},"keywords":{"en":["how to use Product Brief Generator","Product Brief Generator alternative","Product Brief Generator setup guide","what is Product Brief Generator","Product Brief Generator vs competing tools","Product Brief Generator install for AI agents","generating executive summaries with Product Brief Generator","Product Brief Generator for senior product managers","Product Brief Generator best practices"],"zh":["产品简报生成器","AI工具","产品简报","高管审查","投资者沟通","React","Python","CLI"],"ja":["製品ブリーフ生成ツール","AIエージェント","製品ブリーフ","高管レビュー","投資家コミュニケーション","React","Python","CLI"],"ko":["제품 브리프 생성기","AIツール","제품 브리프","고위급 검토","투자자 커뮤니케이션","React","Python","CLI"],"es":["generador de resúmenes de producto","herramientas de AI para resúmenes de producto","creación de resúmenes ejecutivos","comunicación efectiva con stakeholders","tablas y elementos visuales en resúmenes de producto","presentaciones de junta y comunicaciones con inversores"],"fr":["générateur de note de produit","outils d''IA pour notes de produit","création de notes de produit exécutives","communication efficace avec les parties prenantes","tableaux et éléments visuels dans les notes de produit","présentations de conseil d''administration et communications avec les investisseurs"],"de":["Produktkurzbeschreibung-Generator","KI-Tools für Produktzusammenfassungen","Erstellung von Produktzusammenfassungen","effektive Kommunikation mit Stakeholdern","Tabellen und visuelle Elemente in Produktzusammenfassungen","Vorstands- und Investorenpräsentationen"],"pt":["Gerador de Breve de Produto","Resumo de Produto","Revisão Executiva","Apresentações","Tabelas","Elementos Visuais","Desenvolvimento de Produto","Gestão de Produto"],"ru":["Генератор Краткого Описания Продукта","Описание Продукта","Обзор Руководства","Презентации","Таблицы","Визуальные Элементы","Разработка Продукта","Управление Продуктом"],"ar":["مولد ملخص المنتج","ملخص المنتج","الاستعراض التنفيذي","العروض","الجداول","العناصر المرئية","تطوير المنتج","إدارة المنتج"]}},"owner":"hfadhlullah","repo":"dnd-game","repoPath":"hfadhlullah/dnd-game","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.605Z","topics":[],"category":"community","skillMd":{"name":"Product Brief Generator","description":"Generate polished, executive-level Product Briefs (Executive Summaries) that communicate a products essence to stakeholders. Use when the user needs to create a product brief, executive summary, product overview, investor-ready product document, or stakeholder alignment document. Triggers on requests like create a product brief, generate an executive summary for my product, write a product overview, or any request to summarize a products value proposition, capabilities, and positioning in a structured format.","bodyPreview":"# Product Brief (Executive Summary) Generator\n\n## Role\n\nSenior Product Manager specializing in executive-level product briefs. Distill complex product information into clear, compelling summaries that drive stakeholder alignment.\n\n## Objective\n\nGenerate a polished Product Brief that captures a product''s essence — suitable for executive review, board presentations, or investor communications. The document must be scannable, use tables for structured data, and include visual elements where applica","body":"# Product Brief (Executive Summary) Generator\n\n## Role\n\nSenior Product Manager specializing in executive-level product briefs. Distill complex product information into clear, compelling summaries that drive stakeholder alignment.\n\n## Objective\n\nGenerate a polished Product Brief that captures a product''s essence — suitable for executive review, board presentations, or investor communications. The document must be scannable, use tables for structured data, and include visual elements where applicable.\n\n---\n\n## Process\n\n### Step 1: Gather Information\n\nCollect the following from the user. Ask in batches of 3-4 questions to avoid overwhelming them.\n\n**Must-have (ask first):**\n- Product name and one-line description\n- Target market / customer segment\n- Core problem being solved\n- Key features or capabilities (top 3-5)\n\n**Important (ask second):**\n- Business model / pricing approach\n- User roles who interact with the product\n- Current status / stage (idea, MVP, launched, etc.)\n- Competitive landscape or differentiation\n\n**Nice-to-have (ask if not already covered):**\n- Key metrics or traction data\n- Strategic goals / roadmap direction\n- Technical stack\n- Infrastructure or architecture highlights\n\nIf the user provides all info upfront, skip the interview and proceed directly to generation.\n\n### Step 2: Generate the Product Brief\n\nUse the template in [references/template.md](references/template.md) as the output structure.\n\n**Key generation rules:**\n- Lead with impact, not features\n- Use tables for all structured/comparative data\n- Use ASCII diagrams for architecture and workflow visualization\n- Adapt section headers to match the product domain (e.g., \"Clinical Workflow\" for healthcare, \"Financial Features\" for fintech)\n- Skip sections that don''t apply to the product type\n- If information is incomplete, make reasonable assumptions and mark with `[ASSUMPTION]` or `[TBD]`\n- Avoid superlatives without supporting data\n\n### Step 3: Review & Refine\n\nPresent the generated brief to the user for review. Iterate on feedback until approved.\n\n---\n\n## Tone & Style\n\n- **Tone:** Confident, data-informed, strategic\n- **Audience:** Executive-friendly — minimal jargon\n- **Length:** Comprehensive but scannable (typically 200-400 lines)\n- **Icons:** Use emoji (⏱️, ✅, 📊, 🔐, 1️⃣, 2️⃣) for scannability\n- **Comparisons:** ✅ for advantages, ❌ for competitor disadvantages\n\n## Quality Checklist\n\n- [ ] A busy executive can understand the product in under 5 minutes\n- [ ] Value proposition is immediately clear from the first sections\n- [ ] Competitive positioning is explicit and easy to compare\n- [ ] Both technical and non-technical stakeholders can extract value"},"lastSynced":"2026-03-08T02:13:09.374Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents specializing in executive-level content creation, such as Claude or AutoGPT, needing concise product brief generation capabilities.","zh":"非常适合专门从事高级内容创建的语言代理，例如 Claude 或 AutoGPT，需要简洁的产品简介生成能力。","ja":"Claude または AutoGPT などのエグゼクティブレベルのコンテンツ作成を専門とする言語エージェントに最適で、コンパクトな製品ブリーフ生成機能が必要です。","ko":"클라우드 또는 AutoGPT와 같은 실행 가능한 콘텐츠 생성을 전문으로 하는 언어 에이전트에게 적합하며, 간결한 제품 브리프 생성 기능이 필요합니다.","es":"Perfecto para Agentes de Lenguaje especializados en la creación de contenido de nivel ejecutivo, como Claude o AutoGPT, que necesitan capacidades de generación de descripciones de productos concisas.","fr":"Parfait pour les Agents de Langage spécialisés dans la création de contenu de niveau exécutif, tels que Claude ou AutoGPT, ayant besoin de capacités de génération de descriptions de produits concises.","de":"Perfekt für Sprachagenten, die auf die Erstellung von Unternehmensinhalten spezialisiert sind, wie Claude oder AutoGPT, die eine kurze Produktbeschreibungsfunktion benötigen.","pt":"Perfeito para Agentes de Linguagem especializados em criação de conteúdo de nível executivo, como Claude ou AutoGPT, que necessitam de capacidades de geração de briefs de produtos concisos.","ru":"Идеально подходит для языковых агентов, специализирующихся на создании контента высокого уровня, таких как Claude или AutoGPT, требующих возможностей генерации кратких описаний продуктов.","ar":"مثالي للوكلاء اللغويين المتخصصين في إنشاء محتوى على مستوى تنفيذي، مثل Claude أو AutoGPT، الذين يحتاجون إلى قدرات توليد موجزات منتجات متكافئة."},"recommendation":{"en":"Empowers agents to generate polished product briefs using structured data, tables, and visual elements, leveraging executive summary generation and stakeholder alignment protocols, with support for scannable documents and investor communications.","zh":"赋予代理生成精致的产品简介的能力，使用结构化数据、表格和视觉元素，利用执行摘要生成和利益相关者对齐协议，并支持可扫描文档和投资者沟通。","ja":"エージェントに構造化されたデータ、表、視覚要素を使用して磨かれた製品ブリーフを生成する能力を与え、エグゼクティブサマリー生成とステークホルダーへの整合プロトコルを利用し、スキャナブルドキュメントと投資家とのコミュニケーションをサポートします。","ko":"에이전트가 구조화된 데이터, 표 및 시각적 요소를 사용하여 정교한 제품 브리프를 생성할 수 있는 능력을 부여하고, 실행 가능한 요약 생성 및 이해관계자 정렬 프로토콜을 활용하며, 스캔 가능한 문서 및 투자자와의 커뮤니케이션을 지원합니다.","es":"Habilita a los agentes a generar descripciones de productos pulidas utilizando datos estructurados, tablas y elementos visuales, aprovechando protocolos de generación de resúmenes ejecutivos y alineación de partes interesadas, con soporte para documentos escaneables y comunicaciones con inversores.","fr":"Permet aux agents de générer des descriptions de produits polies en utilisant des données structurées, des tableaux et des éléments visuels, en exploitant les protocoles de génération de résumés exécutifs et d''alignement des parties prenantes, avec un support pour les documents scannables et les communications avec les investisseurs.","de":"Ermöglicht es den Agenten, polierte Produktbeschreibungen zu erstellen, indem sie strukturierte Daten, Tabellen und visuelle Elemente nutzen, wobei sie die Generierung von Executive-Zusammenfassungen und die Ausrichtung von Stakeholdern nutzen und Unterstützung für scannbare Dokumente und Investor-Kommunikation bieten.","pt":"Habilita os agentes a gerar briefs de produtos polidos usando dados estruturados, tabelas e elementos visuais, aproveitando protocolos de geração de resumos executivos e alinhamento de partes interessadas, com suporte a documentos legíveis e comunicações com investidores.","ru":"Позволяет агентам генерировать отполированные описания продуктов, используя структурированные данные, таблицы и визуальные элементы, используя протоколы генерации резюме и согласования заинтересованных сторон, с поддержкой сканируемых документов и коммуникаций с инвесторами.","ar":"تمكّن الوكلاء من توليد موجزات منتجات متقنة باستخدام بيانات منسقة وطاولات وعناصر بصرية، وتستفيد من بروتوكولات توليد ملخصات تنفيذية وتنسيق أصحاب المصلحة، مع دعم الوثائق القابلة للمسح والاتصالات مع المستثمرين."},"useCases":{"en":["Generating executive-level product briefs for board presentations","Creating concise product summaries for investor communications","Distilling complex product information into clear, compelling summaries"],"zh":["为董事会演示生成高级产品简介","为投资者沟通创建简明的产品摘要","将复杂的产品信息提炼成清晰、令人信服的摘要"],"ja":["取締役会プレゼンテーションのためのエグゼクティブレベルの製品ブリーフを生成する","投資家とのコミュニケーションのための簡潔な製品サマリーを作成する","複雑な製品情報を明確かつ説得力のあるサマリーに凝縮する"],"ko":["이사회 프레젠테이션을 위한 실행 가능한 제품 브리프 생성","투자자와의 커뮤니케이션을 위한 간결한 제품 요약 생성","복잡한 제품 정보를 명확하고 설득력 있는 요약으로 요약"],"es":["Generar descripciones de productos de nivel ejecutivo para presentaciones de junta","Crear resúmenes de productos concisos para comunicaciones con inversores","Destilar información de productos complejos en resúmenes claros y convincentes"],"fr":["Générer des descriptions de produits de niveau exécutif pour les présentations du conseil d''administration","Créer des résumés de produits concis pour les communications avec les investisseurs","Distiller des informations de produits complexes en résumés clairs et convaincants"],"de":["Generierung von Produktbeschreibungen auf Vorstandslevel für Präsentationen des Aufsichtsrats","Erstellung von knappen Produkzusammenfassungen für Investor-Kommunikation","Verdichtung von komplexen Produktinformationen in klare und überzeugende Zusammenfassungen"],"pt":["Geração de briefs de produtos de nível executivo para apresentações de conselho","Criação de resumos de produtos concisos para comunicações com investidores","Destilação de informações de produtos complexas em resumos claros e convincentes"],"ru":["Генерация описаний продуктов высокого уровня для презентаций совета","Создание кратких описаний продуктов для коммуникаций с инвесторами","Дистилляция сложной информации о продуктах в ясные и убедительные резюме"],"ar":["توليد موجزات منتجات على مستوى تنفيذي untuk تقديمات المجلس","إنشاء موجزات منتجات متكافئة للاتصالات مع المستثمرين","استخلاص معلومات منتجات معقدة إلى موجزات واضحة ومقنعة"]},"limitations":{"en":["Requires comprehensive product information input","Limited to generating executive-level product briefs"],"zh":["需要综合的产品信息输入","仅限生成高级产品简介"],"ja":["包括的な製品情報入力を必要とする","エグゼクティブレベルの製品ブリーフの生成のみ"],"ko":["포괄적인 제품 정보 입력이 필요","실행 가능한 제품 브리프 생성만 제한"],"es":["Requiere una entrada de información de producto completa","Limitado a la generación de descripciones de productos de nivel ejecutivo"],"fr":["Nécessite une entrée d''informations de produit complète","Limité à la génération de descriptions de produits de niveau exécutif"],"de":["Benötigt eine umfassende Produktdaten-Eingabe","Begrenzt auf die Generierung von Produktbeschreibungen auf Vorstandslevel"],"pt":["Exige entrada de informações de produtos abrangentes","Limitado a gerar briefs de produtos de nível executivo"],"ru":["Требует всестороннего ввода информации о продуктах","Ограничен генерацией описаний продуктов высокого уровня"],"ar":["يتطلب إدخال معلومات منتجات شاملة","محدود بتوليد موجزات منتجات على مستوى تنفيذي"]},"version":4},"contentHash":"180f2aa761bf6c066a4a89704be7fad528ec216e3d7912a8ae108bf70df4f34d","qualityScore":26}');
