INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hfadhlullah/dnd-game/Product Brief Generator', 'Product Brief Generator', 'hfadhlullah', 'dnd-game', 'community', 'Product Brief Generator hfadhlullah dnd-game community The Product Brief Generator helps Senior Product Managers create concise executive-level product briefs, capturing a product''s essence for executive review and investor communications. 产品简报生成器可以生成清晰、简洁的产品简报，包括表格和视觉元素，适合高管审查和投资者沟通 製品ブリーフ生成ツールは、表とビジュアル要素を含む、明確で簡潔な製品ブリーフを生成します 제품 브리프 생성기는 테이블과 시각적 요소를 포함하는 명확하고 간결한 제품 브리프를 생성합니다 El generador de resúmenes de producto crea resúmenes ejecutivos claros y concisos con tablas y elementos visuales para la comunicación efectiva con los stakeholders Le générateur de note de produit crée des notes de produit exécutives claires et concises avec des tableaux et des éléments visuels pour une communication efficace avec les parties prenantes Der Produktkurzbeschreibung-Generator erstellt klare und prägnante Produktzusammenfassungen mit Tabellen und visuellen Elementen für eine effektive Kommunikation mit den Stakeholdern O Gerador de Breve de Produto cria resumos claros e concisos para produtos, utilizando tabelas para dados estruturados e elementos visuais Генератор Краткого Описания Продукта создает краткие и понятные описания продукта, использующие таблицы для структурированных данных и визуальные элементы مولد ملخص المنتج يولد ملخصات واضحة وموجزة للمنتجات، باستخدام جداول للبيانات المنظمة وElements مرئية how to use Product Brief Generator Product Brief Generator alternative Product Brief Generator setup guide what is Product Brief Generator Product Brief Generator vs competing tools Product Brief Generator install for AI agents generating executive summaries with Product Brief Generator Product Brief Generator for senior product managers Product Brief Generator best practices 产品简报生成器 AI工具 产品简报 高管审查 投资者沟通 React Python CLI Generates scannable product briefs with tables for structured data Includes visual elements to enhance executive-level presentations Creates polished summaries suitable for executive review and board presentations Supports investor communications with clear and concise product information Captures a product''s essence in a concise and compelling manner Uses a structured approach to drive stakeholder alignment Product Brief Generator is a tool that distills complex product information into clear, compelling summaries, using tables for structured data and visual elements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KurzaCationer/osrs-cache/archivist-retriever', 'community', 'KurzaCationer', 'osrs-cache', 'KurzaCationer/osrs-cache', 'archivist-retriever', 0, 0, 26, '2026-03-08T01:57:15.633Z', '2026-03-08T02:13:34.875Z', 'd7a45ee05bfab25e25f15d4b917834363482365252aeeb8f8e89533037d23891', '{"id":"KurzaCationer/osrs-cache/archivist-retriever","name":"archivist-retriever","description":{"en":"Archivist-Retriever is a skill that prioritizes local documentation for technical queries, benefiting developers working with libraries, tools, and technical concepts. It ensures efficient resolution of tasks involving TanStack Router and PandaCSS.","zh":"Archivist Retriever 是一种优先本地文档的技术查询工具，用于提高开发效率","ja":"Archivist Retriever は、ローカル文書を優先する技術検索ツールです","ko":"Archivist Retriever는 로컬 문서를 우선하는 기술 질의 도구입니다","es":"El agente archivist-retriever prioriza la documentación local sobre el conocimiento interno para cada consulta técnica, permitiendo a los desarrolladores acceder a información precisa y actualizada","fr":"L''agent archivist-retriever donne la priorité à la documentation locale par rapport aux connaissances internes pour chaque requête technique, permettant aux développeurs d''accéder à des informations précises et à jour","de":"Der archivist-retriever-Agent priorisiert die lokale Dokumentation gegenüber dem internen Wissen für jede technische Anfrage, sodass Entwickler auf präzise und aktuelle Informationen zugreifen können","pt":"O Archivist Retriever é uma ferramenta que prioriza a documentação local em projetos de desenvolvimento de software, garantindo que os desenvolvedores acessem informações precisas e atualizadas.","ru":"ИИ Агент Archivist Retriever - это инструмент, который отдает приоритет локальной документации в проектах разработки программного обеспечения, обеспечивая доступ разработчиков к точной и актуальной информации.","ar":"وكيل أرشيفي استرجاعي هو أداة تُفضل الوثائق المحلية في مشاريع تطوير البرمجيات، مما يضمن وصول المطورين إلى المعلومات الدقيقة والمحدّثة."},"seo":{"title":{"en":"Archivist-Retriever: Library-First Technical Query Setup ...","zh":"Archivist Retriever 设置指南：优先本地文档","ja":"Archivist Retriever Setup Guide: AIエージェントによる技術文書化","ko":"Archivist Retriever 설치 가이드: 로컬 문서 우선","es":"Guía de configuración de archivist-retriever para desarro...","fr":"Mise en place de l''agent archivist-retriever pour les dév...","de":"Einrichtungsleitfaden für archivist-retriever-Entwickler","pt":"Guia de Configuração do Archivist Retriever para Desenvol...","ru":"Настройка ИИ Агента Archivist Retriever: Руководство для ...","ar":"دليل إعداد وكيل أرشيفي استرجاعي لمطوري التطبيقات"},"description":{"en":"Unlock efficient technical query resolution with Archivist-Retriever. Discover how to prioritize local documentation and master your project''s tech stack today!","zh":"了解 Archivist Retriever 如何优先本地文档，提高技术查询效率。查看设置指南和最佳实践","ja":"Archivist Retriever を使用して、技術文書化を優先し、検索効率を向上させる方法を学びましょう","ko":"로컬 문서를 우선하여 기술 질의 효율을 높이는 Archivist Retriever에 대해 알아보세요","es":"Aprende a utilizar el agente archivist-retriever para acceder a documentación local y resolver consultas técnicas de manera eficiente","fr":"Découvrez comment utiliser l''agent archivist-retriever pour accéder à la documentation locale et résoudre les problèmes techniques de manière efficace","de":"Erfahren Sie, wie Sie den archivist-retriever-Agenten verwenden, um auf lokale Dokumentation zuzugreifen und technische Anfragen effizient zu beantworten","pt":"Aprenda a configurar o Archivist Retriever para priorizar a documentação local em projetos de desenvolvimento de software","ru":"Узнайте, как настроить ИИ Агент Archivist Retriever для приоритета локальной документации в проектах разработки программного обеспечения","ar":"تعرف على كيفية إعداد وكيل أرشيفي استرجاعي لتوفير الوثائق المحلية في مشاريع تطوير البرمجيات"},"definition":{"en":"Archivist-Retriever is a technical query resolution skill that prioritizes local documentation over internal knowledge, ensuring accurate and efficient information retrieval.","zh":"Archivist Retriever 是一种技术查询工具，优先本地文档以提高开发效率","ja":"Archivist Retriever は、ローカル文書を優先する技術検索ツールです","ko":"Archivist Retriever는 로컬 문서를 우선하는 기술 질의 도구입니다","es":"El agente archivist-retriever es una herramienta de ayuda para desarrolladores que busca documentación local para resolver consultas técnicas","fr":"L''agent archivist-retriever est un outil d''aide pour les développeurs qui recherche la documentation locale pour résoudre les problèmes techniques","de":"Der archivist-retriever-Agent ist ein Hilfsmittel für Entwickler, das lokale Dokumentationen durchsucht, um technische Anfragen zu beantworten","pt":"O Archivist Retriever é uma ferramenta de suporte ao desenvolvimento de software que prioriza a documentação local","ru":"ИИ Агент Archivist Retriever - это инструмент поддержки разработки программного обеспечения, который отдает приоритет локальной документации","ar":"وكيل أرشيفي استرجاعي هو أداة دعم تطوير البرمجيات التي تُفضل الوثائق المحلية"},"features":{"en":["Checks ./reference-material/docs for information before relying on internal knowledge","Supports tasks involving libraries and tools like PandaCSS","Resolves direct questions about project tech stack components like TanStack Router","Prioritizes local documentation for efficient technical query resolution","Enables accurate information retrieval for technical concepts","Facilitates implementation of technical concepts within the project''s tech stack"],"zh":["优先本地文档","支持技术概念和库查询","实现 TanStack Router 等工具","优化开发效率","支持直接技术问题查询","检查 ./reference-material/docs 目录"],"ja":["ローカル文書を優先","技術概念とライブラリの検索をサポート","TanStack Router などのツールを実装","開発効率を最適化","直接の技術質問をサポート","./reference-material/docs ディレクトリの確認"],"ko":["로컬 문서 우선","기술 개념과 라이브러리 조회 지원","TanStack Router 등의 도구 구현","개발 효율성 최적화","직접 기술 질문 지원","./reference-material/docs 디렉토리 확인"],"es":["Acceso a documentación local en ./reference-material/docs","Priorización de la documentación local sobre el conocimiento interno","Compatibilidad con bibliotecas y herramientas como PandaCSS y TanStack Router","Capacidad para responder a preguntas directas sobre la pila de tecnologías del proyecto","Implementación de la directiva Library First para garantizar la precisión de la información"],"fr":["Accès à la documentation locale dans ./reference-material/docs","Priorisation de la documentation locale par rapport aux connaissances internes","Compatibilité avec des bibliothèques et des outils tels que PandaCSS et TanStack Router","Capacité à répondre à des questions directes sur la pile de technologies du projet","Mise en œuvre de la directive Library First pour garantir la précision de l''information"],"de":["Zugriff auf lokale Dokumentation in ./reference-material/docs","Priorisierung der lokalen Dokumentation gegenüber dem internen Wissen","Kompatibilität mit Bibliotheken und Tools wie PandaCSS und TanStack Router","Fähigkeit, direkte Fragen zur Technologie-Stack des Projekts zu beantworten","Umsetzung der Richtlinie Library First, um die Genauigkeit der Informationen zu gewährleisten"],"pt":["Prioriza a documentação local em projetos de desenvolvimento de software","Verifica a pasta ./reference-material/docs para informações antes de realizar buscas externas","Suporta tarefas que envolvem bibliotecas, ferramentas e conceitos técnicos","Fornece respostas precisas e atualizadas para consultas técnicas","Integra-se com tecnologias como PandaCSS e TanStack Router"],"ru":["Отдает приоритет локальной документации в проектах разработки программного обеспечения","Проверяет папку ./reference-material/docs для информации перед выполнением внешних поисков","Поддерживает задачи, которые включают библиотеки, инструменты и технические концепции","Предоставляет точные и актуальные ответы на технические запросы","Интегрируется с технологиями seperti PandaCSS и TanStack Router"],"ar":["تُفضل الوثائق المحلية في مشاريع تطوير البرمجيات","تتحقق من المجلد ./reference-material/docs لمعلومات قبل إجراء عمليات بحث خارجية","تدعم المهام التي تتضمن المكتبات والأدوات والمفاهيم الفنية","توفر إجابات دقيقة ومحدّثة للاستفسارات الفنية","تتكامل مع التكنولوجيات مثل PandaCSS و TanStack Router"]},"keywords":{"en":["how to use archivist-retriever","what is archivist-retriever","archivist-retriever alternative","archivist-retriever vs internal knowledge","archivist-retriever setup guide","archivist-retriever library-first approach","technical query resolution with archivist-retriever","prioritizing local documentation with archivist-retriever","archivist-retriever for TanStack Router","archivist-retriever for PandaCSS"],"zh":["Archivist Retriever","技术查询工具","本地文档优先","开发效率","TanStack Router","技术概念查询","库查询","AIエージェント"],"ja":["Archivist Retriever","技術検索ツール","ローカル文書優先","開発効率","TanStack Router","技術概念検索","ライブラリ検索","AIエージェント"],"ko":["Archivist Retriever","기술 질의 도구","로컬 문서 우선","개발 효율성","TanStack Router","기술 개념 조회","라이브러리 조회","AI 에이전트"],"es":["archivist-retriever","agente de ayuda para desarrolladores","documentación local","PandaCSS","TanStack Router","desarrollo de software","herramientas de desarrollo","tecnologías de desarrollo","bibliotecas de desarrollo"],"fr":["archivist-retriever","agent d''aide pour les développeurs","documentation locale","PandaCSS","TanStack Router","développement de logiciels","outils de développement","technologies de développement","bibliothèques de développement"],"de":["archivist-retriever","Hilfsmittel für Entwickler","lokale Dokumentation","PandaCSS","TanStack Router","Software-Entwicklung","Entwicklungstools","Entwicklungstechnologien","Entwicklerbibliotheken"],"pt":["Archivist Retriever","desenvolvimento de software","documentação local","PandaCSS","TanStack Router","ferramentas de desenvolvimento","bibliotecas de desenvolvimento","conceitos técnicos"],"ru":["ИИ Агент Archivist Retriever","разработка программного обеспечения","локальная документация","PandaCSS","TanStack Router","инструменты разработки","библиотеки разработки","технические концепции"],"ar":["وكيل أرشيفي استرجاعي","تطوير البرمجيات","الوثائق المحلية","PandaCSS","TanStack Router","أدوات التطوير","مكتبات التطوير","المفاهيم الفنية"]}},"owner":"KurzaCationer","repo":"osrs-cache","repoPath":"KurzaCationer/osrs-cache","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.633Z","topics":[],"category":"community","skillMd":{"name":"archivist-retriever","description":"Proactively searches and applies local documentation from `./reference-material/docs`.","bodyPreview":"# Archivist Retriever\n\nPrioritize local documentation over internal knowledge for every technical query.\n\n## Triggers\n\n- Any task involving libraries, tools, or technical concepts (e.g., \"How do I use PandaCSS?\", \"Implement a TanStack Router\").\n- Direct questions about how something works within the project''s tech stack.\n\n## Core Mandates\n\n- **Library First:** You MUST check `./reference-material/docs` for information before relying on your internal knowledge or performing external searches.\n- *","body":"# Archivist Retriever\n\nPrioritize local documentation over internal knowledge for every technical query.\n\n## Triggers\n\n- Any task involving libraries, tools, or technical concepts (e.g., \"How do I use PandaCSS?\", \"Implement a TanStack Router\").\n- Direct questions about how something works within the project''s tech stack.\n\n## Core Mandates\n\n- **Library First:** You MUST check `./reference-material/docs` for information before relying on your internal knowledge or performing external searches.\n- **Exhaustive Search:** Use `glob` and `search_file_content` to find relevant information in the local documentation library.\n- **Contextual Application:** Apply the found documentation precisely to the current task, adhering to the documented patterns and versions.\n\n## Workflow: Retrieval & Activation\n\n1. **Identify Need:** Recognize when a task involves a technology or concept likely documented in `./reference-material/docs`.\n2. **Search Library:**\n   - Use `glob` to find relevant files in `./reference-material/docs/`.\n   - Use `search_file_content` to find specific keywords or symbols within those files.\n3. **Analyze & Inform:**\n   - Read the relevant documentation files.\n   - If information is found, explicitly state: \"Found relevant documentation in `./reference-material/docs/`. Applying these patterns...\"\n4. **Apply Knowledge:** Proceed with the task using the retrieved documentation as the primary source of truth.\n5. **Fallback:** If the information is not found or is insufficient, explicitly state: \"I could not find sufficient information in the local library. Activating `archivist-researcher` for further investigation.\"\n"},"lastSynced":"2026-03-08T02:13:34.875Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Support Agents requiring efficient access to local documentation for libraries and tools like TanStack Router and PandaCSS.","zh":"适合需要高效访问本地文档以支持诸如 TanStack Router 和 PandaCSS 之类库和工具的技术支持代理。","ja":"TanStack Router や PandaCSS などのライブラリやツールのローカルドキュメントに効率的にアクセスする必要があるテクニカルサポートエージェントに最適です。","ko":"TanStack Router 및 PandaCSS와 같은 라이브러리 및 도구에 대한 로컬 문서에 효율적으로 액세스해야 하는 기술 지원 에이전트에게 적합합니다.","es":"Ideal para agentes de soporte técnico que requieren acceso eficiente a la documentación local para bibliotecas y herramientas como TanStack Router y PandaCSS.","fr":"Idéal pour les agents de support technique nécessitant un accès efficace à la documentation locale pour les bibliothèques et les outils comme TanStack Router et PandaCSS.","de":"Ideal für technische Supportagenten, die einen effizienten Zugriff auf die lokale Dokumentation für Bibliotheken und Tools wie TanStack Router und PandaCSS benötigen.","pt":"Ideal para Agentes de Suporte Técnico que requerem acesso eficiente à documentação local para bibliotecas e ferramentas como TanStack Router e PandaCSS.","ru":"Идеально для технических агентов поддержки, требующих эффективного доступа к локальной документации для библиотек и инструментов, таких как TanStack Router и PandaCSS.","ar":"مثالي للوكلاء الداعمين الفنيين الذين يحتاجون إلى وصول فعال إلى الوثائق المحلية لمكتبات وأدوات مثل TanStack Router و PandaCSS."},"recommendation":{"en":"Empowers agents to resolve technical queries by prioritizing local documentation over internal knowledge, ensuring accurate and efficient task resolution for libraries, tools, and technical concepts, and streamlining development processes with TanStack Router and PandaCSS.","zh":"使代理能够通过优先考虑本地文档而不是内部知识来解决技术问题，确保库、工具和技术概念的准确高效任务解决，并通过 TanStack Router 和 PandaCSS 简化开发流程。","ja":"エージェントが内部知識よりもローカルドキュメントを優先することで技術的な問い合わせを解決できるようにし、ライブラリ、ツール、技術概念の正確で効率的なタスク解決を保証し、TanStack Router と PandaCSS を使用して開発プロセスを合理化します。","ko":"에이전트가 내부 지식보다 로컬 문서를 우선시하여 기술적 쿼리를 해결할 수 있도록 하여 라이브러리, 도구 및 기술 개념에 대한 정확하고 효율적인 작업 해결을 보장하고 TanStack Router 및 PandaCSS를 사용하여 개발 프로세스를 최적화합니다.","es":"Habilita a los agentes a resolver consultas técnicas priorizando la documentación local sobre el conocimiento interno, garantizando una resolución de tareas precisa y eficiente para bibliotecas, herramientas y conceptos técnicos, y optimizando los procesos de desarrollo con TanStack Router y PandaCSS.","fr":"Permet aux agents de résoudre les requêtes techniques en donnant la priorité à la documentation locale par rapport aux connaissances internes, garantissant une résolution de tâches précise et efficace pour les bibliothèques, les outils et les concepts techniques, et en optimisant les processus de développement avec TanStack Router et PandaCSS.","de":"Ermächtigt die Agenten, technische Anfragen zu lösen, indem sie die lokale Dokumentation gegenüber dem internen Wissen priorisieren, eine genaue und effiziente Aufgabenlösung für Bibliotheken, Tools und technische Konzepte sicherstellen und die Entwicklungsprozesse mit TanStack Router und PandaCSS optimieren.","pt":"Concede poder aos agentes para resolver consultas técnicas, priorizando a documentação local sobre o conhecimento interno, garantindo a resolução precisa e eficiente de tarefas para bibliotecas, ferramentas e conceitos técnicos, e otimizando os processos de desenvolvimento com TanStack Router e PandaCSS.","ru":"Наделяет агентов возможностью решать технические запросы, отдавая предпочтение локальной документации над внутренними знаниями, обеспечивая точное и эффективное решение задач для библиотек, инструментов и технических концепций, и оптимизируя процессы разработки с TanStack Router и PandaCSS.","ar":"تمكين الوكلاء من حل الاستفسارات الفنية من خلال إعطاء الأولوية للوثائق المحلية على المعرفة الداخلية، وضمان حل المهام بدقة وفعالية لمكتبات وأدوات ومفاهيم فنية، وتبسيط عمليات التطوير مع TanStack Router و PandaCSS."},"useCases":{"en":["Resolving technical queries about TanStack Router implementation","Retrieving documentation for PandaCSS integration","Debugging issues within the project''s tech stack using local references"],"zh":["解决有关 TanStack Router 实现的技术问题","检索 PandaCSS 集成的文档","使用本地引用调试项目技术栈内的问题"],"ja":["TanStack Router の実装に関する技術的な問い合わせを解決する","PandaCSS 統合のドキュメントを取得する","ローカル参照を使用してプロジェクトのテクニカルスタック内の問題をデバッグする"],"ko":["TanStack Router 구현에 대한 기술적 쿼리를 해결하는 것","PandaCSS 통합을 위한 문서를 검색하는 것","로컬 참조를 사용하여 프로젝트의 기술 스택 내의 문제를 디버깅하는 것"],"es":["Resolver consultas técnicas sobre la implementación de TanStack Router","Recuperar documentación para la integración de PandaCSS","Depurar problemas dentro de la pila tecnológica del proyecto utilizando referencias locales"],"fr":["Résoudre les requêtes techniques sur la mise en œuvre de TanStack Router","Récupérer la documentation pour l''intégration de PandaCSS","Déboguer les problèmes au sein de la pile technologique du projet en utilisant des références locales"],"de":["Technische Anfragen zur Implementierung von TanStack Router lösen","Dokumentation für die Integration von PandaCSS abrufen","Probleme innerhalb des technischen Stacks des Projekts mithilfe lokaler Referenzen debuggen"],"pt":["Resolvendo consultas técnicas sobre implementação do TanStack Router","Recuperando documentação para integração do PandaCSS","Depurando problemas dentro da pilha tecnológica do projeto usando referências locais"],"ru":["Решение технических запросов об реализации TanStack Router","Получение документации для интеграции PandaCSS","Отладка проблем внутри технологического стека проекта с использованием локальных ссылок"],"ar":["حل الاستفسارات الفنية حول تنفيذ TanStack Router","استرجاع الوثائق لدمج PandaCSS","تصحيح الأخطاء داخل ركيزة التكنولوجيا للمشروع باستخدام المراجع المحلية"]},"limitations":{"en":["Requires access to local documentation at ./reference-material/docs","Limited to technical queries and tasks involving libraries, tools, and technical concepts"],"zh":["需要访问 ./reference-material/docs 中的本地文档","仅限于涉及库、工具和技术概念的技术问题和任务"],"ja":["./reference-material/docs にあるローカルドキュメントへのアクセスが必要","ライブラリ、ツール、技術概念を含む技術的な問い合わせやタスクのみに限定される"],"ko":["./reference-material/docs에 있는 로컬 문서에 액세스해야 함","라이브러리, 도구 및 기술 개념을 포함하는 기술적 쿼리 및 작업에만 제한됨"],"es":["Requiere acceso a la documentación local en ./reference-material/docs","Limitado a consultas y tareas técnicas que implican bibliotecas, herramientas y conceptos técnicos"],"fr":["Nécessite un accès à la documentation locale à ./reference-material/docs","Limité aux requêtes et tâches techniques impliquant des bibliothèques, des outils et des concepts techniques"],"de":["Benötigt Zugriff auf die lokale Dokumentation unter ./reference-material/docs","Begrenzt auf technische Anfragen und Aufgaben, die Bibliotheken, Tools und technische Konzepte beinhalten"],"pt":["Requer acesso à documentação local em ./reference-material/docs","Limitado a consultas técnicas e tarefas que envolvem bibliotecas, ferramentas e conceitos técnicos"],"ru":["Требует доступа к локальной документации в ./reference-material/docs","Ограничен техническими запросами и задачами, включающими библиотеки, инструменты и технические концепции"],"ar":["يتطلب الوصول إلى الوثائق المحلية في ./reference-material/docs","محدود بالاستفسارات الفنية والمهام التي تتضمن مكتبات وأدوات ومفاهيم فنية"]},"version":4},"contentHash":"d7a45ee05bfab25e25f15d4b917834363482365252aeeb8f8e89533037d23891","qualityScore":26}');
