INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('davisschenk/tilt-hydrometer-web/ralph-cycle', 'ralph-cycle', 'davisschenk', 'tilt-hydrometer-web', 'community', 'ralph-cycle davisschenk tilt-hydrometer-web community The ralph-cycle skill automates a single development cycle following the Ralph Wiggum Methodology, benefiting developers by simplifying task implementation and verification. Ralph-Cycle是一种遵循Ralph Wiggum Methodology的开发周期工具，通过智能上下文选择和任务实现来优化开发流程 Ralph-CycleはRalph Wiggum Methodologyに基づく開発サイクルツールで、スマートなコンテキスト選択とタスク実装で開発プロセスを最適化します Ralph-Cycle은 Ralph Wiggum Methodology를 기반으로 하는 개발 사이클 도구로, 스마트 컨텍스트 선택과 태스크 구현을 통해 개발 프로세스를 최적화합니다 ralph-cycle es una herramienta de desarrollo que sigue la metodología Ralph Wiggum para mejorar la productividad. Lee el archivo prd.json y progress.md para determinar el siguiente paso lógico ralph-cycle est un outil de développement qui suit la méthodologie Ralph Wiggum pour améliorer la productivité. Il lit les fichiers prd.json et progress.md pour déterminer l''étape logique suivante ralph-cycle ist ein Entwicklungstool, das die Ralph-Wiggum-Methode befolgt, um die Produktivität zu steigern. Es liest die Dateien prd.json und progress.md, um den nächsten logischen Schritt zu bestimmen O ralph-cycle é uma habilidade que executa um ciclo de desenvolvimento seguindo a Metodologia Ralph Wiggum, incluindo seleção de contexto inteligente e verificação de tarefas Ralph-cycle - это навык, который выполняет цикл разработки в соответствии с Методологией Ральфа Виггума, включая умный выбор контекста и проверку задач ralph-cycle هو مهارة تنفذ دورة تطوير متبعة لمنهجية رالف ويغوم، بما في ذلك اختيار السياق الذكي والتحقق من المهام how to use ralph-cycle ralph-cycle alternative ralph-cycle setup guide what is ralph-cycle ralph-cycle vs agile methodology ralph-cycle install ralph-cycle development cycle automation Ralph-Cycle AI工具 开发周期 智能上下文选择 任务实现 代码提交 prd.json progress.md Reads prd.json and progress.md to determine the most logical next step Analyzes backlog using the Ralph Wiggum Methodology Executes a single development cycle with task implementation, verification, and commit Requires .windsurf/rules/tech-stack.md for technical stack configuration Utilizes selection logic to choose the next task ralph-cycle is a development cycle automation skill that executes a single cycle of task implementation, verification, and commit using the Ralph Wiggum Methodology.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nozomio-labs/nia-rules-for-agents/nia', 'community', 'nozomio-labs', 'nia-rules-for-agents', 'nozomio-labs/nia-rules-for-agents', 'nia', 0, 0, 26, '2026-03-08T01:57:15.641Z', '2026-03-08T02:13:41.934Z', 'e2592fa81198b9b78377143da01584bdb224b25c4523dff6fa46505485af1813', '{"id":"nozomio-labs/nia-rules-for-agents/nia","name":"nia","description":{"en":"Nia provides tools for indexing and searching external repositories, research papers, and local folders, benefiting AI agents and developers. Its primary goal is to reduce hallucinations in LLMs.","zh":"Nia提供了预配置规则，教AI编码代理如何有效地使用索引和搜索工具","ja":"Niaは、事前設定ルールを提供し、AIエージェントが索引と検索ツールを効果的に使用できるようにします","ko":"Nia는 사전 구성 규칙을 제공하여 AI 에이전트가 인덱싱 및 검색 도구를 효과적으로 사용할 수 있도록 합니다","es":"Nia proporciona herramientas para indexar y buscar repositorios externos, artículos de investigación y carpetas locales, y realizar investigaciones impulsadas por inteligencia artificial","fr":"Nia fournit des outils pour indexer et rechercher des référentiels externes, des articles de recherche et des dossiers locaux, et effectuer des recherches alimentées par l''intelligence artificielle","de":"Nia bietet Tools zur Indizierung und Suche externer Repositorys, Forschungsartikeln und lokalen Ordnern sowie zur Durchführung von künstlich intelligenter Forschung","pt":"Nia fornece ferramentas para indexação e pesquisa de repositórios externos, documentos e pacotes, reduzindo alucinações em LLMs","ru":"Nia предоставляет инструменты для индексации и поиска внешних репозиториев, документов и пакетов, снижая галлюцинации в LLM","ar":"توفر Nia أدوات لفهارس و بحث المستودعات الخارجية، والوثائق، والحزم، وتقليل الهلوسة في LLMs"},"seo":{"title":{"en":"Nia: Setup Guide for AI Agents | AI Agent Skill","zh":"Nia Setup Guide: AI编码代理索引和搜索工具","ja":"Niaの設定ガイド: AIエージェントのインデックスと検索ツール","ko":"Nia 설정 가이드: AI 에이전트 인덱싱 및 검색 