INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nozomio-labs/nia-rules-for-agents/nia', 'nia', 'nozomio-labs', 'nia-rules-for-agents', 'community', 'nia nozomio-labs nia-rules-for-agents community Nia provides tools for indexing and searching external repositories, research papers, and local folders, benefiting AI agents and developers. Its primary goal is to reduce hallucinations in LLMs. Nia提供了预配置规则，教AI编码代理如何有效地使用索引和搜索工具 Niaは、事前設定ルールを提供し、AIエージェントが索引と検索ツールを効果的に使用できるようにします Nia는 사전 구성 규칙을 제공하여 AI 에이전트가 인덱싱 및 검색 도구를 효과적으로 사용할 수 있도록 합니다 Nia proporciona herramientas para indexar y buscar repositorios externos, artículos de investigación y carpetas locales, y realizar investigaciones impulsadas por inteligencia artificial Nia fournit des outils pour indexer et rechercher des référentiels externes, des articles de recherche et des dossiers locaux, et effectuer des recherches alimentées par l''intelligence artificielle Nia bietet Tools zur Indizierung und Suche externer Repositorys, Forschungsartikeln und lokalen Ordnern sowie zur Durchführung von künstlich intelligenter Forschung Nia fornece ferramentas para indexação e pesquisa de repositórios externos, documentos e pacotes, reduzindo alucinações em LLMs Nia предоставляет инструменты для индексации и поиска внешних репозиториев, документов и пакетов, снижая галлюцинации в LLM توفر Nia أدوات لفهارس و بحث المستودعات الخارجية، والوثائق، والحزم، وتقليل الهلوسة في LLMs how to use nia what is nia nia alternative nia vs webfetch nia install nia setup guide nia for ai agents reduce hallucinations in llms indexed sources for ai research Nia AI编码代理 AI索引和搜索工具 大型语言模型幻觉减少 AI驱动的研究 Nia-First工作流程 外部存储库索引 研究论文索引 本地文件夹索引 Indexes external repositories for AI-powered research Supports searching research papers and local folders Provides up-to-date context for AI agents using `manage_resource` command Reduces hallucinations in LLMs with indexed sources Allows listing indexed sources using `manage_resource(action=''list'', query=''relevant-keyword'')` Nia is a tool for indexing and searching external repositories, providing up-to-date context for AI agents and reducing hallucinations in LLMs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thongdn-it/react-agent-skills/tailwind', 'community', 'thongdn-it', 'react-agent-skills', 'thongdn-it/react-agent-skills', 'tailwind', 0, 0, 26, '2026-03-08T01:57:15.655Z', '2026-03-08T02:13:57.703Z', 'ba473b96fa12e924c6387a037a1c58dcd7f7619ff4119fd247fc858b67d04ec0', '{"id":"thongdn-it/react-agent-skills/tailwind","name":"tailwind","description":{"en":"The Tailwind skill provides a comprehensive performance optimization guide for Tailwind CSS v4 applications, maintained by Tailwind Labs, benefiting React ecosystem developers.","zh":"Tailwind CSS v4 最佳实践配置指南，包含 42 条规则和 8 个类别，帮助您优化应用程序性能和代码质量","ja":"Tailwind CSS v4 ベストプラクティス設定ガイド - 42 のルールと 8 つのカテゴリでアプリケーションのパフォーマンスとコード品質を向上させる","ko":"Tailwind CSS v4 최적화 설정 가이드 - 42개의 규칙과 8개의 카테고리로 애플리케이션의 성능과 코드 품질을 향상시키는","es":"Tailwind CSS v4 es un conjunto de habilidades de agente de inteligencia artificial para la optimización de rendimiento de aplicaciones React, con 42 reglas para la refactorización y generación de código automatizadas","fr":"Tailwind CSS v4 est un ensemble de compétences d''agent d''intelligence artificielle pour l''optimisation des performances d''applications React, avec 42 règles pour la refactoring et la génération de code automatisées","de":"Tailwind CSS v4 ist eine Sammlung von KI-Agenten-Fähigkeiten für die Leistungsoptimierung von React-Anwendungen, mit 42 Regeln für die automatisierte Refactoring und Codegenerierung","pt":"O Tailwind CSS v4 é uma ferramenta poderosa para desenvolvedores React. Aprenda a configurá-lo e otimizá-lo com nossas melhores práticas","ru":"Tailwind CSS v4 - это мощный инструмент для разработчиков React. Узнайте, как настроить и оптимизировать его с помощью наших лучших практик для ИИ Агентов","ar":"Tailwind CSS v4 هو أداة قوية للمطورين React. تعلم كيفية إعدادها وتحسينها باستخدام أفضل الممارسات لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Tailwind: Comprehensive Performance Optimization Guide | ...","zh":"Tailwind CSS v4 最佳实践配置指南","ja":"Tailwind CSS v4 ベストプラクティス設定ガイド - AIエージェント","ko":"Tailwind CSS v4 최적화 설정 가이드 - AI 도구","es":"Guía de configuración de Tailwind CSS v4","fr":"Guide de mise en place de Tailwind CSS v4","de":"Einrichtungsleitfaden für Tailwind CSS v4","pt":"Guia de Configuração do Tailwind CSS v4","ru":"Настройка Tailwind CSS v4: Лучшие Практики для ИИ Агентов","ar":"دليل إعداد Tailwind CSS v4 لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of Tailwind CSS v4 with our expert guide, featuring 42 rules for automated refactoring and code generation - get started now!","zh":"优化您的 Tailwind CSS v4 应用程序，了解 42 条规则和 8 个类别，提高性能和代码质量","ja":"Tailwind CSS v4 アプリケーションのパフォーマンスとコード品質を向上させる 42 のルールと 8 つのカテゴリ - AIエージェント","ko":"Tailwind CSS v4 애플리케이션의 성능과 코드 품질을 향상시키는 42개의 규칙과 8개의 카테고리 - AI 도구","es":"Optimice el rendimiento de su aplicación con las mejores prácticas de Tailwind CSS v4, incluyendo 42 reglas para la refactorización y generación de código au...","fr":"Optimisez les performances de votre application avec les meilleures pratiques de Tailwind CSS v4, comprenant 42 règles pour la refactoring et la génération d...","de":"Optimieren Sie die Leistung Ihrer Anwendung mit den Best Practices von Tailwind CSS v4, einschließlich 42 Regeln für die automatisierte Refactoring und Codeg...","pt":"Aprenda a configurar e otimizar o Tailwind CSS v4 com nossas melhores práticas e guias de desempenho","ru":"Узнайте, как настроить и оптимизировать Tailwind CSS v4 с помощью наших лучших практик и руководств по производительности для ИИ Агентов","ar":"تعلم كيفية إعداد وتحسين Tailwind CSS v4 باستخدام أفضل الممارسات ودلائل الأداء لأدوات الذكاء الاصطناعي"},"definition":{"en":"Tailwind is a collection of AI agent skills for the React ecosystem, focusing on Tailwind CSS v4 best practices and performance optimization.","zh":"Tailwind CSS v4 是一个 CSS 框架，提供了一套最佳实践配置指南，帮助开发者优化