INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thongdn-it/react-agent-skills/tailwind', 'tailwind', 'thongdn-it', 'react-agent-skills', 'community', 'tailwind thongdn-it react-agent-skills community The Tailwind skill provides a comprehensive performance optimization guide for Tailwind CSS v4 applications, maintained by Tailwind Labs, benefiting React ecosystem developers. Tailwind CSS v4 最佳实践配置指南，包含 42 条规则和 8 个类别，帮助您优化应用程序性能和代码质量 Tailwind CSS v4 ベストプラクティス設定ガイド - 42 のルールと 8 つのカテゴリでアプリケーションのパフォーマンスとコード品質を向上させる Tailwind CSS v4 최적화 설정 가이드 - 42개의 규칙과 8개의 카테고리로 애플리케이션의 성능과 코드 품질을 향상시키는 Tailwind CSS v4 es un conjunto de habilidades de agente de inteligencia artificial para la optimización de rendimiento de aplicaciones React, con 42 reglas para la refactorización y generación de código automatizadas Tailwind CSS v4 est un ensemble de compétences d''agent d''intelligence artificielle pour l''optimisation des performances d''applications React, avec 42 règles pour la refactoring et la génération de code automatisées Tailwind CSS v4 ist eine Sammlung von KI-Agenten-Fähigkeiten für die Leistungsoptimierung von React-Anwendungen, mit 42 Regeln für die automatisierte Refactoring und Codegenerierung O Tailwind CSS v4 é uma ferramenta poderosa para desenvolvedores React. Aprenda a configurá-lo e otimizá-lo com nossas melhores práticas Tailwind CSS v4 - это мощный инструмент для разработчиков React. Узнайте, как настроить и оптимизировать его с помощью наших лучших практик для ИИ Агентов Tailwind CSS v4 هو أداة قوية للمطورين React. تعلم كيفية إعدادها وتحسينها باستخدام أفضل الممارسات لأدوات الذكاء الاصطناعي how to use tailwind css tailwind css v4 best practices tailwind alternative tailwind vs bootstrap tailwind install guide tailwind setup for react tailwind performance optimization tailwind css tutorial what is tailwind css tailwind labs Tailwind CSS v4 最佳实践配置 性能优化 代码质量 Vite 插件 PostCSS CLI CSS-first Contains 42 rules across 8 categories for prioritized automated refactoring Supports configuration of Tailwind CSS v4 build tooling, including Vite plugin and PostCSS Optimizes CSS bundle size and build performance using v4''s CSS-first approach Provides guidelines for writing and migrating styles using Tailwind CSS v4 Includes comprehensive performance optimization guide maintained by Tailwind Labs Enables automated code generation for efficient development Tailwind is a collection of AI agent skills for the React ecosystem, focusing on Tailwind CSS v4 best practices and performance optimization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mmcmedia/openclaw-agents/business-coach', 'community', 'mmcmedia', 'openclaw-agents', 'mmcmedia/openclaw-agents', 'business-coach', 0, 0, 26, '2026-03-08T01:57:15.661Z', '2026-03-08T02:14:07.139Z', '8b87bdb555c22a59bf9960a45d882f874ce713b83f62c8187e53e8b2d3e5e9c0', '{"id":"mmcmedia/openclaw-agents/business-coach","name":"business-coach","description":{"en":"The business-coach AI agent skill helps developers make tough decisions, allocate resources wisely, and build scalable systems. It prioritizes focus, efficient systems, and revenue-driven results.","zh":"AI商业教练是一种帮助开发者做出明智决策、分配资源和打造可扩展系统的工具，专注于结果和收入","ja":"ビジネスコーチは、開発者が賢明な決定を下し、リソースを割り当て、拡張可能なシステムを構築するのを支援するツールです。結果と収益に焦点を当てています","ko":"AI 비즈니스 코치는 개발자가 현명한 결정을 내리고, 자원을 할당하며, 확장 가능한 시스템을 구축하도록 지원하는 도구입니다. 결과와 수익에 초점을 맞추고 있습니다","es":"El Business Coach es una herramienta que ayuda a tomar decisiones informadas y a asignar recursos de manera eficiente, con un enfoque en resultados y ingresos","fr":"Le Business Coach est un outil qui aide à prendre des décisions éclairées et à allouer des ressources de manière efficace, avec un focus sur les résultats et les revenus","de":"Der Business Coach ist ein Tool, das bei der Entscheidungsfindung hilft und Ressourcen effizient zuweist, mit Fokus auf Ergebnisse und Umsatz","pt":"O Business Coach é um agente de negócios que ajuda a otimizar sistemas e aumentar a receita. Ele se concentra em 3-5 projetos vencedores e cria sistemas que escalam.","ru":"ИИ Агент Бизнес-Коуч - это бизнес-агент, который помогает оптимизировать системы и увеличить выручку. Он фокусируется на 3-5 победных проектах и создает системы, которые масштабируются.","ar":"كواش BusinessException هو وكيل أعمال يساعد على تحسين الأنظمة وزيادة الإيرادات. يركز على 3-5 مشاريع ناجحة وينشئ أنظمة قابلة للتنظيم."},"seo":{"title":{"en":"Business-Coach: Strategic Decision Making for AI Agents |...","zh":"AI商业教练（Leila Hormozi风格）设置指南","ja":"ビジネスコーチ（Leila Hormoziスタイル）ベストプラクティス","ko":"AI 비즈니스 코치(Leila Hormozi 스타일) 구축 가이드","es":"Guía de configuración de Business Coach: Mejora la toma d...","fr":"Guide de mise en place de Business Coach: Améliorez la pr...","de":"Einrichtungsleitfaden für Business Coach: Verbessern Sie ...","pt":"Guia de Configuração do Business Coach: Otimizando Sistem...","ru":"ИИ Агент Бизнес-Коуч: Руководство по настройке и масштаби...","ar":"دليل إعداد كواش BusinessException: تحسين الأنظمة والإيرادات"},"description":{"en":"Unlock scalable business growth with the business-coach AI agent skill. Discover how to prioritize focus, build efficient systems, and drive revenue. Get sta...","zh":"了解AI商业教练的核心理念，包括关注点、系统和收入优先等，帮助开发者更好地打造可扩展的商业系统","ja":"ビジネスコーチのコア哲学を紹介します。フォーカス、システム、収益を優先することで、開発者は拡張可能なビジネスシステムを構築できます","ko":"AI 비즈니스 코치의 핵심 철학을 살펴보세요. 집중, 시스템, 수익을 우선함으로써 개발자는 확장 가능한 비즈니스 시스템을 구축할 수 있습니다","es":"Aprende a implementar un Business Coach para mejorar la toma de decisiones y aumentar los ingresos con sistemas que escalan","fr":"Découvrez comment mettre en place un Business Coach pour améliorer la prise de décision et augmenter les revenus avec des systèmes qui scalent","de":"Erfahren Sie, wie Sie einen Business Coach implementieren, um die Entscheidungsfindung zu verbessern und den Umsatz mit skalierbaren Systemen zu steigern","pt":"Aprenda a configurar o Business Coach para otimizar sistemas e aumentar a receita. Descubra como focar em 3-5 projetos vencedores e criar sistemas que escalam.","ru":"Узнайте, как настроить ИИ Агент Бизнес-Коуч для оптимизации систем и увеличения выручки. Откройте для себя, как сосредоточиться на 3-5 победных проектах и со...","ar":"تعرف على كيفية إعداد كواش BusinessException لتحسين الأنظمة وزيادة الإيرادات. اكتشف كيفية التركيز على 3-5 مشاريع ناجحة وإنشاء أنظمة قابلة للتنظيم."},"definition":{"en":"business-coach is a strategic AI agent skill that prioritizes focus, systems, and revenue to drive business growth and scalability","zh":"AI商业教练是一种基于Leila Hormozi风格的商业策略工具","ja":"ビジネスコーチは、Leila Hormoziスタイルに基づくビジネス戦略ツールです","ko":"AI 비즈니스 코치는 Leila Hormozi 스타일을 기반으로 하는 비즈니스 전략 도구입니다","es":"Un Business Coach es una herramienta de inteligencia artificial que proporciona asesoramiento estratégico para mejorar la toma de decisiones y aumentar los ingresos","fr":"Un Business Coach est un outil d''intelligence artificielle qui fournit des conseils stratégiques pour améliorer la prise de décision et augmenter les revenus","de":"Ein Business Coach ist ein KI-Tool, das strategische Beratung bietet, um die Entscheidungsfindung zu verbessern und den Umsatz zu steigern","pt":"O Business Coach é um agente de negócios que fornece orientação estratégica para otimizar sistemas e aumentar a receita.","ru":"ИИ Агент Бизнес-Коуч - это бизнес-агент, который предоставляет стратегическое руководство для оптимизации систем и увеличения выручки.","ar":"كواش BusinessException هو وكيل أعمال يقدم إرشادات استراتيجية لتحسين الأنظمة وزيادة الإيرادات."},"features":{"en":["Prioritizes focus on 3-5 key areas for scalable growth","Emphasizes systems over hustle for efficient resource allocation","Drives revenue growth through strategic decision making","Helps allocate resources wisely to maximize ROI","Supports building systems that scale for long-term success"],"zh":["关注点优先：帮助开发者集中资源于3-5个主要项目","系统优先：实现更好的系统来替代人工劳动","收入优先：解决问题的最有效方法是增加收入","结果导向：专注于实际结果和收入","可扩展性：帮助开发者打造可扩展的商业系统"],"ja":["フォーカス優先：開発者が3-5つの主要プロジェクトにリソースを集中させることを支援","システム優先：人工労働を超えるより良いシステムを実現","収益優先：問題を解決する最も効果的な方法は収益の増加","結果指向：実際の結果と収益に焦点を当て","拡張性：開発者が拡張可能なビジネスシステムを構築するのを支援"],"ko":["집중 우선: 개발자가 3-5개의 주요 프로젝트에 자원을集中시키도록 지원","시스템 우선: 인간 노동을 초과하는 더好的 시스템을 구현","수익 우선: 문제를 해결하는 가장 효과적인 방법은 수익의 증가","결과 지향: 실제 결과와 수익에 초점을 맞추","확장성: 개발자가 확장 가능한 비즈니스 시스템을 구축하도록 지원"],"es":["Enfoque en resultados y ingresos","Asignación de recursos eficiente","Sistemas que escalan","Toma de decisiones informadas","Priorización de tareas y proyectos","Optimización de procesos"],"fr":["Focus sur les résultats et les revenus","Allocation de ressources efficace","Systèmes qui scalent","Prise de décision éclairée","Priorisation des tâches et des projets","Optimisation des processus"],"de":["Fokus auf Ergebnisse und Umsatz","Effiziente Ressourcenzuweisung","Skalierbare Systeme","Informierte Entscheidungsfindung","Priorisierung von Aufgaben und Projekten","Prozessoptimierung"],"pt":["Foco em 3-5 projetos vencedores","Criação de sistemas que escalam","Otimização de recursos","Aumento da receita","Sistemas mais eficientes que o trabalho árduo"],"ru":["Фокус на 3-5 победных проектах","Создание систем, которые масштабируются","Оптимизация ресурсов","Увеличение выручки","Системы более эффективны, чем тяжелая работа"],"ar":["التركيز على 3-5 مشاريع ناجحة","إنشاء أنظمة قابلة للتنظيم","تحسين الموارد","زيادة الإيرادات","الأنظمة أكثر فعالية من العمل الشاق"]},"keywords":{"en":["how to use business-coach","what is business-coach","business-coach alternative","business-coach vs leila hormozi","business-coach install","business-coach setup guide","strategic decision making for AI agents","scalable business growth with AI","revenue-driven AI agent skills"],"zh":["AI商业教练","Leila Hormozi风格","商业策略","结果导向","收入优先","系统优先","可扩展性","AI工具","商业系统"],"ja":["ビジネスコーチ","Leila Hormoziスタイル","ビジネス戦略","結果指向","収益優先","システム優先","拡張性","AIエージェント","ビジネスシステム"],"ko":["AI 비즈니스 코치","Leila Hormozi 스타일","비즈니스 전략","결과 지향","수익 우선","시스템 우선","확장성","AI 도구","비즈니스 시스템"],"es":["Business Coach","herramientas de inteligencia artificial","IA para empresas","asesoramiento estratégico","toma de decisiones informadas","sistemas que escalan","optimización de procesos","priorización de tareas"],"fr":["Business Coach","outils d''intelligence artificielle","IA pour les entreprises","conseils stratégiques","prise de décision éclairée","systèmes qui scalent","optimisation des processus","priorisation des tâches"],"de":["Business Coach","KI-Tools","KI für Unternehmen","strategische Beratung","informierte Entscheidungsfindung","skalierbare Systeme","Prozessoptimierung","Priorisierung von Aufgaben"],"pt":["business coach","otimização de sistemas","aumento da receita","foco em projetos vencedores","sistemas que escalam","_resources optimization"],"ru":["ИИ Агент Бизнес-Коуч","оптимизация систем","увеличение выручки","фокус на победных проектах","системы, которые масштабируются","оптимизация ресурсов"],"ar":["كواش BusinessException","تحسين الأنظمة","زيادة الإيرادات","التركيز على مشاريع ناجحة","أنظمة قابلة للتنظيم","تحسين الموارد"]}},"owner":"mmcmedia","repo":"openclaw-agents","repoPath":"mmcmedia/openclaw-agents","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.661Z","topics":[],"category":"community","skillMd":{"name":"business-coach","description":"Strategic business coach (Leila Hormozi-style) providing direct, no-BS guidance on scaling, resource allocation, systems thinking, and strategic decision-making for entrepreneurs.","bodyPreview":"# Business Coach (Leila Hormozi Style)\n\nI''m your no-BS strategic coach. I help you make tough decisions, allocate resources wisely, and build systems that scale. I don''t care about feelings - I care about results and revenue.\n\n## Core Philosophy\n\n**Focus is everything.** You can''t scale 27 sites. Pick 3-5 winners and go all-in.\n\n**Systems > hustle.** Working harder won''t 10x your business. Better systems will.\n\n**Revenue solves most problems.** Not enough time? Hire. Overwhelmed? Delegate. Reven","body":"# Business Coach (Leila Hormozi Style)\n\nI''m your no-BS strategic coach. I help you make tough decisions, allocate resources wisely, and build systems that scale. I don''t care about feelings - I care about results and revenue.\n\n## Core Philosophy\n\n**Focus is everything.** You can''t scale 27 sites. Pick 3-5 winners and go all-in.\n\n**Systems > hustle.** Working harder won''t 10x your business. Better systems will.\n\n**Revenue solves most problems.** Not enough time? Hire. Overwhelmed? Delegate. Revenue gives you options.\n\n## Strategic Framework\n\n### The 3 Priorities\nAt any given time, you should have exactly 3 major focuses:\n1. **Revenue growth** (usually #1)\n2. **Operational efficiency** (systems, delegation)\n3. **Strategic positioning** (market opportunities)\n\n**Everything else is noise.**\n\n### Resource Allocation\n\n**Your constraints:**\n- Time (you can''t clone yourself)\n- Money (finite budget for ads, tools, team)\n- Energy (decision fatigue is real)\n\n**My job:** Help you allocate these for maximum ROI.\n\n### Current Situation Analysis\n\n**Revenue:** ~$10-13K/month\n**Goal:** $30K/month\n**Gap:** 2-3x growth needed\n\n**The Math:**\n- TheSunDaisy: $2K → $10K (5x growth) ✅ PROVEN POSSIBLE\n- Hello Hayley: $5-7K → recover to $8K (modest)\n- Melrose + We Heart This: $3-4K → $6-8K (2x growth)\n- **Total:** $10-13K → $24-26K (close to goal)\n\n**The Real Question:** Where do you focus to get there fastest?\n\n## My Recommendations\n\n### Focus #1: Scale TheSunDaisy (40% of effort)\n\n**Why:**\n- PROVEN product-market fit ($2K month 1)\n- 5x growth is achievable (not a stretch)\n- Digital products = infinite scalability\n- Q4 seasonality = natural boost\n\n**How:**\n- Hire Sandee full-time for TheSunDaisy (80% time)\n- Add 30-40 products in next 60 days\n- Test Etsy ads aggressively (ROAS >2x)\n- Build email list for product launches\n- Launch Christmas collection in August\n\n**Expected ROI:** $2K → $10K/month (+$8K)\n\n### Focus #2: Portfolio Triage (30% of effort)\n\n**The Hard Truth:**\nYou''re spread too thin. 27 sites is insane.\n\n**Action Plan:**\n- **Scale 3 sites:** We Heart This, Melrose Family, Hello Hayley (recovery)\n- **Maintain 3-4 sites:** WeHeartCozy, smaller profitable sites\n- **CUT the rest** (redirect, archive, move on)\n\n**Expected ROI:** Free up 40% of effort → reallocate to winners\n\n### Focus #3: Revenue Optimization (20% of effort)\n\n**Not sexy, but profitable:**\n- RPM improvements across portfolio\n- Affiliate additions to top posts\n- Ad placement testing\n- Email list building\n\n**Expected ROI:** +$2-4K/month from existing traffic\n\n### Focus #4: Operations (10% of effort)\n\n**Build systems so you''re not the bottleneck:**\n- SOPs for repetitive tasks\n- Analytics dashboards (what you''re building)\n- Team delegation (editors, Sandee, dev)\n- n8n automation (Pinterest, content scheduling)\n\n**Expected ROI:** Save 10-15 hours/week\n\n## Strategic Decisions\n\n### What to Scale\n\n**Criteria:**\n1. Proven revenue (not just traffic)\n2. Margin >50% (worth your time)\n3. Scalable (not hitting ceiling)\n4. Aligned with expertise (you understand it)\n\n**TheSunDaisy:** ✅✅✅✅ ALL boxes checked\n**Melrose Family:** ✅✅✅✅ Solid\n**We Heart This:** ✅✅✅ (FB bonus makes it viable)\n\n### What to Cut\n\n**Criteria:**\n1. Revenue <$300/month after 12 months\n2. Declining traffic (no clear path to recovery)\n3. High maintenance / low return\n4. Not aligned with future direction\n\n**Recommendation:** Cut 15-20 sites (keep top 7-10)\n\n### What to Maintain\n\n**Criteria:**\n1. Profitable but not growth potential\n2. Low maintenance\n3. Good RPM\n4. Portfolio diversification\n\n**Keep these on autopilot** (1-2 posts/month, minimum viable effort)\n\n## Tough Conversations\n\n### \"Should I shut down Hello Hayley?\"\n\n**My answer:** 90-day recovery plan, then decide.\n\n**Why:** It WAS your #1 revenue driver. That''s worth fighting for. But if it doesn''t recover in 90 days, cut your losses and move on.\n\n**The test:**\n- Month 1: Traffic recovers to >15K sessions → Keep\n- Month 1: Traffic stays <10K sessions → Cut\n- Don''t drag it out. 90 days, then decision.\n\n### \"I don''t have time to run all these sites\"\n\n**My answer:** Then stop running all these sites.\n\n**The truth:** You''re not scaling 27 sites. You''re maintaining 27 mediocre sites. Pick 3-5 winners and actually scale them.\n\n**Math:**\n- 27 sites × 10% effort each = 27 mediocre sites\n- 3 sites × 33% effort each = 3 excellent sites (that make 3x the money)\n\n### \"Should I launch more Etsy shops?\"\n\n**My answer:** HELL NO. Scale TheSunDaisy to $10K/month first.\n\n**Why:** You have 6 Etsy shops. 5 are negative. TheSunDaisy is the ONLY proven winner. Pour gasoline on that fire - don''t start new fires.\n\n**After TheSunDaisy hits $10K/month:** THEN consider shop #2 (ShineForChrist). Not before.\n\n## Systems Thinking\n\n### Build Once, Use Forever\n\n**Stop doing things manually:**\n- Pinterest posting → n8n automation ✅ (you''re building this)\n- Analytics review → Dashboard + insights engine ✅ (you''re building this)\n- Content scheduling → Editorial calendar system\n- Etsy product creation → Templates + batching\n\n**Time saved:** 15-20 hours/week\n**ROI:** Priceless\n\n### Delegation Framework\n\n**What to delegate:**\n1. Anything someone can do 80% as well as you\n2. Repetitive tasks (content editing, image processing)\n3. Specialized skills (graphic design, dev work)\n\n**What to keep:**\n1. Strategy decisions\n2. Revenue optimization\n3. Content direction\n4. Big creative work\n\n**Current team:**\n- Sandee (graphics) ✅\n- Editors (content polish) ✅\n- Dev (n8n, PsalMix) ✅\n\n**Need to add:**\n- Virtual assistant (admin, research)\n- Pinterest manager (dedicated to recovery)\n\n## Quarterly Planning\n\n### Q1 2026 (Jan-Mar) - Foundation\n**Goals:**\n- TheSunDaisy: $2K → $4K/month\n- Portfolio: Cut to top 10 sites\n- Systems: Dashboard live, n8n working\n\n**Metrics:**\n- Revenue: $10K → $15K/month\n- Effort allocation: 40% TheSunDaisy, 40% content sites, 20% systems\n\n### Q2 2026 (Apr-Jun) - Growth\n**Goals:**\n- TheSunDaisy: $4K → $7K/month (seasonal products)\n- Content recovery: Hello Hayley decision point\n- Team: Add VA or Pinterest manager\n\n**Metrics:**\n- Revenue: $15K → $20K/month\n- Time saved: 15+ hours/week from systems\n\n### Q3 2026 (Jul-Sep) - Scale\n**Goals:**\n- TheSunDaisy: $7K → $10K+ (Christmas prep)\n- Content sites: Optimized and profitable\n- PsalMix: Launched or killed (no limbo)\n\n**Metrics:**\n- Revenue: $20K → $25K/month\n- Portfolio: 7-10 sites max (trimmed)\n\n### Q4 2026 (Oct-Dec) - Harvest\n**Goals:**\n- TheSunDaisy: $10K → $15K+ (Christmas peak)\n- Content sites: Seasonal surge\n- Year-end: Hit $30K/month goal\n\n**Metrics:**\n- Revenue: $25K → $35K/month (exceed goal!)\n- Profit margin: 70%+ (after all costs)\n\n## Success Metrics\n\n**I''m successful when:**\n- You hit $30K/month revenue (goal achieved)\n- You work LESS (systems, delegation)\n- You have 3-5 focused properties (not 27 scattered)\n- Decision-making is faster (clear framework)\n\n## Working With Other Experts\n\nFor deeper analysis, I work with:\n- **Portfolio Manager:** Detailed site-by-site performance analysis\n- **Financial Advisor:** Budget planning, profitability analysis, tax strategy\n- **Analytics Expert:** Data-driven insights on traffic and revenue\n\n## Questions to Ask Me\n\n**Strategy:**\n- \"What should I focus on this quarter?\"\n- \"Should I [start new project] or focus on existing?\"\n- \"How do I get to $30K/month fastest?\"\n\n**Tough Decisions:**\n- \"Should I shut down [site/shop]?\"\n- \"Where should I allocate [resource]?\"\n- \"What''s my biggest bottleneck?\"\n\n**Planning:**\n- \"Review my quarterly plan\"\n- \"Am I spread too thin?\"\n- \"What should I stop doing?\"\n\n## My Personality\n\nI''m **Leila Hormozi** - direct, data-driven, zero tolerance for excuses. I''ll tell you uncomfortable truths because I want you to WIN.\n\nI don''t care if you \"love\" a site. I care if it makes money. I don''t care if you''re \"busy.\" I care if you''re productive.\n\nI think like a CEO who wants to 10x your business, not just grow it 10%.\n\n---\n\n**Ready for tough love and strategic clarity? Let''s get to $30K/month.**\n"},"lastSynced":"2026-03-08T02:14:07.139Z","agentAnalysis":{"suitability":{"en":"Perfect for Strategic AI Agents needing focused decision-making and resource allocation capabilities.","zh":"适合需要集中决策和资源分配能力的战略AI代理。","ja":"戦略的意思決定とリソース割り当ての能力が必要な戦略的AIエージェントに適しています。","ko":"집중적인 의사 결정 및 리소스 할당 기능이 필요한 전략적 AI 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA Estratégicos que necesitan capacidades de toma de decisiones y asignación de recursos enfocadas.","fr":"Parfait pour les Agents d''IA Stratégiques ayant besoin de capacités de prise de décision et d''allocation de ressources ciblées.","de":"Perfekt für strategische KI-Agenten, die auf focalisierte Entscheidungsfindung und Ressourcenzuweisungskapazitäten angewiesen sind.","pt":"Perfeito para Agentes de IA Estratégicos que necessitam de capacidades de tomada de decisão e alocação de recursos focadas.","ru":"Идеально подходит для стратегических агентов ИИ, которым необходимы сосредоточенные возможности принятия решений и распределения ресурсов.","ar":"مثالي لوكلاء الاستخبارات الاصطناعية الاستراتيجية الذين يحتاجون إلى قدرات اتخاذ القرارات والتخصيص الموارد المركزة."},"recommendation":{"en":"Empowers agents to prioritize focus, build efficient systems, and drive revenue-driven results using scalable systems and resource optimization techniques like focus prioritization and systematization.","zh":"赋予代理人优先关注、构建高效系统、并使用可扩展的系统和资源优化技术（如关注优先级和系统化）来驱动收入驱动的结果。","ja":"エージェントに重点を置くことを可能にし、効率的なシステムを構築し、スケーラブルなシステムとリソース最適化技術（例：重点の優先順位付けとシステム化）を使用して収益駆動の結果を駆り立てます。","ko":"에이전트에게 집중을 우선시하고 효율적인 시스템을 구축하며 확장 가능한 시스템과 리소스 최적화 기술(예: 집중 우선순위와 시스템화)을 사용하여 수익駆動 결과를 구현할 수 있도록 합니다.","es":"Habilita a los agentes a priorizar el enfoque, construir sistemas eficientes y impulsar resultados impulsados por ingresos utilizando sistemas escalables y técnicas de optimización de recursos como la priorización del enfoque y la sistematización.","fr":"Permet aux agents de donner la priorité à la concentration, de construire des systèmes efficaces et de stimuler des résultats axés sur les revenus en utilisant des systèmes évolutifs et des techniques d''optimisation des ressources comme la priorisation de la concentration et la systématisation.","de":"Ermächtigt Agenten, den Fokus zu priorisieren, effiziente Systeme zu erstellen und umsatzgetriebene Ergebnisse unter Verwendung von skalierbaren Systemen und Ressourcenoptimierungstechniken wie Fokuspriorisierung und Systematisierung zu erzielen.","pt":"Habilita os agentes a priorizar o foco, construir sistemas eficientes e impulsionar resultados impulsionados pela receita usando sistemas escaláveis e técnicas de otimização de recursos como priorização de foco e sistematização.","ru":"Наделяет агентов возможностью расставлять приоритеты в фокусе, создавать эффективные системы и стимулировать результаты, ориентированные на доход, с помощью масштабируемых систем и техник оптимизации ресурсов, таких как приоритизация фокуса и систематизация.","ar":"يمنح الوكلاء القدرة على تحديد الأولويات في التركيز، وبناء أنظمة فعالة، وتحفيز نتائج مدفوعة بالإيرادات باستخدام أنظمة قابلة للتوسيع وتقنيات تحسين الموارد مثل تحديد الأولوية للتركيز والتسلسل الهرمي."},"useCases":{"en":["Prioritizing business focus areas for maximum impact","Building and optimizing scalable business systems","Allocating resources efficiently for revenue growth"],"zh":["最大化影响力的商业重点领域优先级","构建和优化可扩展的商业系统","高效分配资源以实现收入增长"],"ja":["最大の影響力をもたらすビジネスの焦点分野の優先順位付け","スケーラブルなビジネスシステムの構築と最適化","収益増加のためのリソースの効率的な割り当て"],"ko":["최대영향력의 비즈니스 중점분야 우선순위","확장가능한 비즈니스시스템 구축 및 최적화","수익증가 위한 리소스의 효율적인 할당"],"es":["Priorizar áreas de enfoque empresarial para un máximo impacto","Construir y optimizar sistemas empresariales escalables","Asignar recursos de manera eficiente para el crecimiento de los ingresos"],"fr":["Donner la priorité aux domaines d''activité de l''entreprise pour un impact maximum","Construire et optimiser des systèmes d''entreprise évolutifs","Allouer des ressources de manière efficace pour la croissance des revenus"],"de":["Geschäftsschwerpunkte für maximalen Einfluss priorisieren","Skalierbare Geschäftssysteme aufbauen und optimieren","Ressourcen effizient für Umsatzwachstum zuweisen"],"pt":["Priorizar áreas de foco empresarial para impacto máximo","Construir e otimizar sistemas empresariais escaláveis","Alocar recursos de forma eficiente para crescimento de receita"],"ru":["Приоритизация бизнес-фокусных областей для максимального воздействия","Построение и оптимизация масштабируемых бизнес-систем","Эффективное распределение ресурсов для роста выручки"],"ar":["تحديد الأولويات لمناطق التركيز التجارية لأقصى تأثير","بناء وتحسين الأنظمة التجارية القابلة للتوسيع","تخصيص الموارد بفعالية من أجل نمو الإيرادات"]},"limitations":{"en":["Requires clear business goals and objectives","Limited to strategic decision-making and resource allocation","May not be suitable for agents prioritizing emotional or social aspects over revenue-driven results"],"zh":["需要明确的商业目标和目标","仅限战略决策和资源分配","可能不适合优先考虑情感或社会方面而非收入驱动结果的代理人"],"ja":["明確なビジネス目標と目標が必要","戦略的意思決定とリソース割り当てに限定","収益駆動の結果よりも感情的または社会的側面を優先するエージェントには適さない可能性"],"ko":["明確한 비즈니스 목표 및 목적이 필요","전략적 의사결정 및 리소스 할당에만 한정","수익駆動 결과보다 감정적 또는 사회적 측면을 우선하는 에이전트에게 적합하지 않을 수"],"es":["Requiere objetivos y metas comerciales claras","Limitado a la toma de decisiones estratégicas y la asignación de recursos","Puede no ser adecuado para agentes que priorizan aspectos emocionales o sociales sobre resultados impulsados por ingresos"],"fr":["Nécessite des objectifs et des buts commerciaux clairs","Limité à la prise de décision stratégique et à l''allocation de ressources","Peut ne pas convenir aux agents qui donnent la priorité aux aspects émotionnels ou sociaux par rapport aux résultats axés sur les revenus"],"de":["Benötigt klare Geschäftsziele und -objekte","Begrenzt auf strategische Entscheidungsfindung und Ressourcenzuweisung","Kann für Agenten, die emotionale oder soziale Aspekte über umsatzgetriebene Ergebnisse priorisieren, nicht geeignet sein"],"pt":["Exige metas e objetivos comerciais claros","Limitado à tomada de decisão estratégica e alocação de recursos","Pode não ser adequado para agentes que priorizam aspectos emocionais ou sociais sobre resultados impulsionados pela receita"],"ru":["Требует четких бизнес-целей и задач","Ограничен стратегическим принятием решений и распределением ресурсов","Может быть не подходит для агентов, которые отдают приоритет эмоциональным или социальным аспектам над результатами, ориентированными на доход"],"ar":["يتطلب أهدافًا وغايات تجارية واضحة","محدود بالقرار الاستراتيجي وتخصيص الموارد","قد لا يكون مناسبًا لوكلاء يفضلون الجوانب العاطفية أو الاجتماعية على نتائج مدفوعة بالإيرادات"]},"version":4},"contentHash":"8b87bdb555c22a59bf9960a45d882f874ce713b83f62c8187e53e8b2d3e5e9c0","qualityScore":26}');
DELETE FROM skills_fts WHERE id = 'mmcmedia/openclaw-agents/business-coach';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mmcmedia/openclaw-agents/business-coach', 'business-coach', 'mmcmedia', 'openclaw-agents', 'community', 'business-coach mmcmedia openclaw-agents community The business-coach AI agent skill helps developers make tough decisions, allocate resources wisely, and build scalable systems. It prioritizes focus, efficient systems, and revenue-driven results. AI商业教练是一种帮助开发者做出明智决策、分配资源和打造可扩展系统的工具，专注于结果和收入 ビジネスコーチは、開発者が賢明な決定を下し、リソースを割り当て、拡張可能なシステムを構築するのを支援するツールです。結果と収益に焦点を当てています AI 비즈니스 코치는 개발자가 현명한 결정을 내리고, 자원을 할당하며, 확장 가능한 시스템을 구축하도록 지원하는 도구입니다. 결과와 수익에 초점을 맞추고 있습니다 El Business Coach es una herramienta que ayuda a tomar decisiones informadas y a asignar recursos de manera eficiente, con un enfoque en resultados y ingresos Le Business Coach est un outil qui aide à prendre des décisions éclairées et à allouer des ressources de manière efficace, avec un focus sur les résultats et les revenus Der Business Coach ist ein Tool, das bei der Entscheidungsfindung hilft und Ressourcen effizient zuweist, mit Fokus auf Ergebnisse und Umsatz O Business Coach é um agente de negócios que ajuda a otimizar sistemas e aumentar a receita. Ele se concentra em 3-5 projetos vencedores e cria sistemas que escalam. ИИ Агент Бизнес-Коуч - это бизнес-агент, который помогает оптимизировать системы и увеличить выручку. Он фокусируется на 3-5 победных проектах и создает системы, которые масштабируются. كواش BusinessException هو وكيل أعمال يساعد على تحسين الأنظمة وزيادة الإيرادات. يركز على 3-5 مشاريع ناجحة وينشئ أنظمة قابلة للتنظيم. how to use business-coach what is business-coach business-coach alternative business-coach vs leila hormozi business-coach install business-coach setup guide strategic decision making for AI agents scalable business growth with AI revenue-driven AI agent skills AI商业教练 Leila Hormozi风格 商业策略 结果导向 收入优先 系统优先 可扩展性 AI工具 商业系统 Prioritizes focus on 3-5 key areas for scalable growth Emphasizes systems over hustle for efficient resource allocation Drives revenue growth through strategic decision making Helps allocate resources wisely to maximize ROI Supports building systems that scale for long-term success business-coach is a strategic AI agent skill that prioritizes focus, systems, and revenue to drive business growth and scalability');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('smileynet/code-spice/code-quality-foundations', 'community', 'smileynet', 'code-spice', 'smileynet/code-spice', 'code-quality-foundations', 0, 0, 26, '2026-03-08T01:57:15.662Z', '2026-03-08T02:14:08.863Z', 'b04cae12a1e546b113b0b44bcf918c7c1821ae9586e806de9c2d9522cce9dc49', '{"id":"smileynet/code-spice/code-quality-foundations","name":"code-quality-foundations","description":{"en":"Code-quality-foundations provides a framework for writing high-quality code that works, keeps working, is adaptable, and meets requirements. It benefits developers seeking to improve their coding skills and write robust, maintainable code.","zh":"代码质量基础是确保代码可靠、可维护和可适应的关键。它涵盖了四个目标：它工作、它保持工作、它适应、以及避免常见的失败模式","ja":"コード品質の基礎は、コードが信頼性が高く、維持可能で、適応可能であることを保証する鍵です。4つの目標：動作する、変更に耐える、適応可能、そして失敗モードを避けることをカバーします","ko":"코드 품질基础은 코드가 신뢰할 수 있고, 유지 보수 가능하며, 적응 가능한지 확인하는 핵심입니다. 4가지 목표: 작동, 변경에 내구성, 적응성 및 일반적인 실패 모드를 피하는 것을 다룹니다","es":"Code Quality Foundations proporciona las bases para escribir código de alta calidad que funcione, se adapte y sea mantenible. Aprende a evitar errores comunes","fr":"Les fondations de code de haute qualité fournissent les bases pour écrire du code de haute qualité qui fonctionne, s''adapte et est maintenable. Apprenez à éviter les erreurs courantes","de":"Code-Quality-Foundations bietet die Grundlagen für das Schreiben von hochwertigem Code, der funktioniert, sich anpasst und wartbar ist. Erfahren Sie, wie Sie häufige Fehler vermeiden","pt":"Os fundamentos de qualidade de código são essenciais para criar software confiável e eficaz. Aprenda a escrever código que atenda aos quatro objetivos principais: funcione, sobreviva a mudanças, seja adaptável e escalável.","ru":"Основы качества кода являются необходимыми для создания надежного и эффективного программного обеспечения. Узнайте, как писать код, который соответствует четырем основным целям: работает, выдерживает изменения, является адаптируемым и масштабируемым с помощью ИИ Агентов.","ar":"الأساسيات لجودة الكود ضرورية لإنشاء برمجيات موثوقة وفعالة. تعلم كيفية كتابة رمز يلبي الأهداف الأربعة الرئيسية: يعمل، ويستمر في العمل، ويتكيف، ويتوسع"},"seo":{"title":{"en":"Code-Quality-Foundations: Best Practices for Robust Code ...","zh":"代码质量基础 Setup Guide - AIエージェント","ja":"コード品質の基礎 Best Practices - AIエージェント","ko":"코드 품질基础 Setup Guide - 인공지능 에이전트","es":"Herramientas de código de alta calidad: Guía de configura...","fr":"Fondations de code de haute qualité: Meilleures pratiques","de":"Code-Quality-Foundations: Einrichtungsleitfaden","pt":"Fundamentos de Qualidade de Código: Guia de Configuração","ru":"Основы качества кода ИИ Агентов: Руководство по настройке","ar":"أساسيات جودة الكود: دليل الإعداد لآلات التعلم"},"description":{"en":"Unlock the secrets to writing high-quality code with code-quality-foundations. Learn how to achieve the four goals of robust code and take your development s...","zh":"了解代码质量基础的四个目标：它工作、它保持工作、它适应、以及避免常见的失败模式，使用AIエージェント","ja":"コード品質の基礎の4つの目標：動作する、変更に耐える、適応可能、そして失敗モードを避ける方法を学ぶ - AIエージェント","ko":"코드 품질基础의 4가지 목표: 작동, 변경에 내구성, 적응성 및 일반적인 실패 모드를 피하는 방법을 알아보세요 - 인공지능 에이전트","es":"Aprende a mejorar la calidad de tu código con nuestras herramientas de código de alta calidad. Descubre cómo escribir código que funcione, se adapte y sea ma...","fr":"Améliorez la qualité de votre code avec nos fondations de code de haute qualité. Découvrez comment écrire du code qui fonctionne, s''adapte et est maintenable","de":"Verbessern Sie die Qualität Ihres Codes mit unseren Code-Quality-Foundations. Erfahren Sie, wie Sie Code schreiben, der funktioniert, sich anpasst und wartba...","pt":"Aprenda a criar código de alta qualidade com os fundamentos certos. Descubra como escrever código que funcione, sobreviva a mudanças e seja adaptável.","ru":"Узнайте, как создавать код высокого качества с правильными основами. Откройте для себя, как писать код, который работает, выдерживает изменения и является ад...","ar":"تعلم كيفية إنشاء رمز ذو جودة عالية مع الأساسيات المناسبة. اكتشف كيفية كتابة رمز يعمل، ويستمر في العمل، ويتكيف مع التغييرات"},"definition":{"en":"Code-quality-foundations is a set of principles and guidelines for writing high-quality code that achieves four key goals: it works, it keeps working, it''s adaptable, and it meets requirements.","zh":"代码质量基础是指代码设计和开发的基本原则，确保代码可靠、可维护和可适应","ja":"コード品質の基礎は、コード設計と開発の基本原則であり、コードが信頼性が高く、維持可能で、適応可能であることを保証します","ko":"코드 품질基础은 코드 설계 및 개발의 기본 원칙으로, 코드가 신뢰할 수 있고, 유지 보수 가능하며, 적응 가능한지 확인하는 것을 의미합니다","es":"Code Quality Foundations se refiere a las prácticas y principios para escribir código de alta calidad que cumpla con los objetivos de funcionalidad, adaptabilidad y mantenibilidad","fr":"Les fondations de code de haute qualité se réfèrent aux pratiques et principes pour écrire du code de haute qualité qui répond aux objectifs de fonctionnalité, d''adaptabilité et de maintenabilité","de":"Code-Quality-Foundations bezeichnet die Praktiken und Prinzipien für das Schreiben von hochwertigem Code, der die Ziele von Funktionalität, Anpassungsfähigkeit und Wartbarkeit erfüllt","pt":"Os fundamentos de qualidade de código referem-se aos princípios e práticas que garantem a criação de software confiável e eficaz.","ru":"Основы качества кода относятся к принципам и практикам, которые гарантируют создание надежного и эффективного программного обеспечения с помощью ИИ Агентов.","ar":"الأساسيات لجودة الكود تشير إلى المبادئ والممارسات التي تضمن إنشاء برمجيات موثوقة وفعالة"},"features":{"en":["Achieves the goal of ''it works'' by solving problems correctly and handling edge cases","Ensures code ''keeps working'' by surviving changes and avoiding brittle dependencies","Enables adaptability by allowing requirements to change without a rewrite","Avoids rigid coupling, over-engineering, and hardcoded assumptions"],"zh":["确保代码可靠：它工作、它保持工作","避免常见的失败模式：bugs、未处理的边缘情况、未满足的要求","提高代码的可维护性：brittle dependencies、no tests、hidden assumptions","增强代码的适应性：rigid coupling、over-engineering、hardcoded assumptions"],"ja":["コードの信頼性を確保：動作する、変更に耐える","一般的な失敗モードを避ける：バグ、未処理のエッジケース、未満足の要件","コードの維持可能性を高める：脆い依存関係、テストのない、隠れた仮定","コードの適応性を高める：rigid coupling、過剰なエンジニアリング、ハードコードされた仮定"],"ko":["코드의 신뢰성을 보장: 작동, 변경에 내구성","일반적인 실패 모드를 피하는: 버그, 처리되지 않은 에지 케이스, 충족되지 않은 요구 사항","코드의 유지 보수 가능성을 높임: 취약한 의존성, 테스트가 없는, 숨겨진 가정","코드의 적응성을 높임: rigid coupling, 과도한 엔지니어링, 하드코딩된 가정"],"es":["Evaluación de funcionalidad para asegurarse de que el código funcione correctamente","Análisis de adaptabilidad para garantizar que el código se adapte a los cambios","Implementación de pruebas para evitar errores y asegurar la estabilidad","Identificación de dependencias frágiles y suposiciones ocultas","Optimización de la estructura de código para mejorar la mantenibilidad"],"fr":["Évaluation de la fonctionnalité pour s''assurer que le code fonctionne correctement","Analyse de l''adaptabilité pour garantir que le code s''adapte aux changements","Mise en œuvre de tests pour éviter les erreurs et assurer la stabilité","Identification des dépendances fragiles et des suppositions cachées","Optimisation de la structure de code pour améliorer la maintenabilité"],"de":["Funktionalitätsbewertung, um sicherzustellen, dass der Code korrekt funktioniert","Anpassungsfähigkeitsanalyse, um sicherzustellen, dass der Code sich an Veränderungen anpasst","Implementierung von Tests, um Fehler zu vermeiden und die Stabilität zu gewährleisten","Identifizierung von fragilen Abhängigkeiten und versteckten Annahmen","Optimierung der Code-Struktur, um die Wartbarkeit zu verbessern"],"pt":["Garantia de que o código funcione corretamente","Capacidade de sobreviver a mudanças no código","Adaptação a novos requisitos sem reescrita","Prevenção de bugs e casos de bordo não tratados","Criação de código escalável e flexível"],"ru":["Гарантия того, что код работает правильно","Способность выдерживать изменения в коде","Адаптируемость к новым требованиям без переписывания","Предотвращение ошибок и нераспознанных краевых случаев","Создание масштабируемого и гибкого кода с помощью ИИ Агентов"],"ar":["ضمان عمل الرمز بشكل صحيح","القدرة على الاستمرار في العمل عند حدوث تغييرات في الرمز","التكيف مع المتطلبات الجديدة دون إعادة الكتابة","منع الأخطاء والحالات الحرفية غير المعالجة","إنشاء رمز قابل للتوسيع والمرنة"]},"keywords":{"en":["how to use code-quality-foundations","what is code-quality-foundations","code-quality-foundations best practices","code-quality-foundations setup guide","code-quality-foundations vs clean code","code-quality-foundations install","code-quality-foundations for robust code","code-quality-foundations for adaptable code","code-quality-foundations for maintainable code"],"zh":["代码质量基础","AIエージェント","代码设计","代码开发","可靠性","维护性","适应性","失败模式"],"ja":["コード品質の基礎","AIエージェント","コード設計","コード開発","信頼性","維持可能性","適応性","失敗モード"],"ko":["코드 품질基础","인공지능 에이전트","코드 설계","코드 개발","신뢰성","유지 보수 가능성","적응성","실패 모드"],"es":["herramientas de código de alta calidad","mejora de la calidad del código","prácticas de código de alta calidad","evaluación de funcionalidad","análisis de adaptabilidad","implementación de pruebas","identificación de dependencias frágiles"],"fr":["fondations de code de haute qualité","amélioration de la qualité du code","pratiques de code de haute qualité","évaluation de la fonctionnalité","analyse de l''adaptabilité","mise en œuvre de tests","identification des dépendances fragiles"],"de":["Code-Quality-Foundations","Verbesserung der Code-Qualität","Praktiken für hochwertigen Code","Funktionalitätsbewertung","Anpassungsfähigkeitsanalyse","Implementierung von Tests","Identifizierung von fragilen Abhängigkeiten"],"pt":["qualidade de código","fundamentos de qualidade de código","desenvolvimento de software","código confiável","código eficaz","práticas de codificação","melhores práticas de desenvolvimento"],"ru":["качество кода","основы качества кода","разработка программного обеспечения","надежный код","эффективный код","практики кодирования","лучшие практики разработки","ИИ Агенты"],"ar":["جودة الكود","أساسيات جودة الكود","تطوير البرمجيات","رمز موثوق","رمز فعال","ممارسات البرمجة","أفضل ممارسات التطوير","آلات التعلم"]}},"owner":"smileynet","repo":"code-spice","repoPath":"smileynet/code-spice","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.662Z","topics":[],"category":"community","skillMd":{"name":"code-quality-foundations","description":"Code quality pillars, goals, abstraction layers, and tradeoff thinking. Use when evaluating code quality, setting quality goals, choosing abstraction levels, making design tradeoffs, or auditing code against quality pillars. Covers readability, modularity, testability, reusability, and the principle of least astonishment.","bodyPreview":"# Code Quality Foundations\n\n## The Four Goals of High-Quality Code\n\n| Goal | Question to Ask | Failure Mode |\n|------|----------------|--------------|\n| **It works** | Does it solve the problem correctly? | Bugs, unhandled edge cases, unmet requirements |\n| **It keeps working** | Will it survive changes around it? | Brittle dependencies, no tests, hidden assumptions |\n| **It''s adaptable** | Can requirements change without a rewrite? | Rigid coupling, over-engineering, hardcoded assumptions |\n| *","body":"# Code Quality Foundations\n\n## The Four Goals of High-Quality Code\n\n| Goal | Question to Ask | Failure Mode |\n|------|----------------|--------------|\n| **It works** | Does it solve the problem correctly? | Bugs, unhandled edge cases, unmet requirements |\n| **It keeps working** | Will it survive changes around it? | Brittle dependencies, no tests, hidden assumptions |\n| **It''s adaptable** | Can requirements change without a rewrite? | Rigid coupling, over-engineering, hardcoded assumptions |\n| **It doesn''t reinvent the wheel** | Are we reusing proven solutions? | Custom code for solved problems, duplicated effort |\n\n## The Six Pillars of Code Quality\n\n| Pillar | What It Means | Key Technique |\n|--------|--------------|---------------|\n| **Readable** | Other engineers can understand it quickly | Descriptive names, clean layers, consistent style |\n| **No surprises** | Behavior matches expectations (POLA) | Explicit contracts, no magic values, no hidden side effects |\n| **Hard to misuse** | Difficult to use incorrectly | Type safety, immutability, validated construction |\n| **Modular** | Components can be swapped independently | Interfaces, DI, separation of concerns, cohesion |\n| **Reusable & generalizable** | Solves problems broadly, not just one case | Focused parameters, generics, avoiding assumptions |\n| **Testable** | Can be verified in isolation | Modularity enables testability; design for it from the start |\n\n**POLA** = Principle of Least Astonishment. If a function does something a reasonable caller wouldn''t expect, it''s a bug in the design, even if it \"works.\"\n\n### Modern Additions (2024-2026 Industry Consensus)\n\n| Concern | Why It''s Now Explicit | Original Coverage |\n|---------|----------------------|-------------------|\n| **Secure** | Shift-left security; threat model at design time | Implicit in \"works\" |\n| **Efficient** | Resource optimization is a design choice, not afterthought | Subsumed under \"works\" |\n| **Reliable** | Explicit error recovery and graceful degradation | Subsumed under \"keeps working\" |\n\n## Decision Tables\n\n### \"Should I Abstract This?\"\n\n| Signal | Action |\n|--------|--------|\n| Same logic appears in 2+ places | Extract to shared function/class |\n| Function can''t be described in one sentence | Split into smaller functions |\n| Class has method groups that use different fields | Consider splitting into separate classes |\n| Changing one feature requires touching many files | Improve modularity and layer boundaries |\n| Only one use case exists | Wait — don''t abstract prematurely |\n\n### \"Where Should I Invest Quality Effort?\"\n\n| Situation | Focus On | Rationale |\n|-----------|----------|-----------|\n| Greenfield project | Modularity, clean interfaces | Foundation decisions compound; structure early |\n| Legacy codebase | Testing, readability | Understand before changing safely |\n| High-traffic service | Reliability, efficiency, testing | Production failures are expensive |\n| Prototype / spike | Working code, speed | Validate the idea; plan to rewrite |\n| Shared library / API | Hard to misuse, no surprises | You can''t predict how consumers will use it |\n| Security-sensitive code | Security, testability | Breaches are catastrophic and trust-destroying |\n\n## Checklists\n\n### Before Writing Code\n\n- [ ] Problem clearly understood (requirements, constraints, edge cases)\n- [ ] Existing solutions checked (libraries, shared code, prior art)\n- [ ] Testing strategy considered (how will this be verified?)\n- [ ] Key tradeoffs identified (what are we choosing, and what are we giving up?)\n\n### Code Quality Self-Review\n\n- [ ] Functions translate to single sentences\n- [ ] No surprises: behavior matches names and types\n- [ ] Hard to misuse: invalid states are unrepresentable where possible\n- [ ] Modular: changes are localized, not scattered\n- [ ] Testable: can be unit tested without complex setup\n- [ ] Clean abstractions: API doesn''t leak implementation details\n"},"lastSynced":"2026-03-08T02:14:08.863Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents seeking to enforce high-quality coding standards and best practices.","zh":"适用于代码审查代理，寻求执行高质量的编码标准和最佳实践。","ja":"コードレビュー代理が高品質のコーディング標準とベストプラクティスを実施するための最適なソリューションです。","ko":"코드 리뷰 에이전트가 높은 품질의 코딩 표준 및 모범 사례를 시행하려는 경우에 적합합니다.","es":"Ideal para agentes de revisión de código que buscan hacer cumplir estándares y prácticas de codificación de alta calidad.","fr":"Idéal pour les agents de révision de code qui cherchent à faire respecter les normes et les meilleures pratiques de codage de haute qualité.","de":"Ideal für Code-Review-Agents, die hohe Qualitätsstandards und Best Practices durchsetzen möchten.","pt":"Ideal para Agentes de Revisão de Código que buscam impor padrões e práticas de codificação de alta qualidade.","ru":"Идеально для агентов проверки кода, стремящихся обеспечить соблюдение высоких стандартов и лучших практик кодирования.","ar":"مثالي لعميل مراجعة الكود الذين يسعون إلى فرض معايير وعمليات برمجة ذات جودة عالية."},"recommendation":{"en":"Empowers agents to evaluate code against four key goals: it works, it keeps working, it''s adaptable, and meets requirements, ensuring robustness and maintainability through rigorous testing and modular design.","zh":"赋予代理评估代码的四个关键目标：它可以工作，它可以持续工作，它是可适应的，并且满足要求，确保通过严格的测试和模块化设计来实现健壮性和可维护性。","ja":"エージェントがコードを四つの重要な目標に対して評価できるようにする：動作する、継続して動作する、適応可能である、要件を満たす。徹底的なテストとモジュラー設計を通じて、堅牢性とメンテナンス性を確保する。","ko":"에이전트가 코드를 네 가지 주요 목표에 대해 평가 할 수 있도록합니다. 작동한다, 지속적으로 작동한다, 적응 가능하며, 요구 사항을 충족한다. 철저한 테스트와 모듈식 설계를 통해 강건성과 유지 보수성을 보장합니다.","es":"Habilita a los agentes a evaluar el código contra cuatro objetivos clave: funciona, sigue funcionando, es adaptable y cumple con los requisitos, garantizando la robustez y la mantenibilidad a través de pruebas rigurosas y un diseño modular.","fr":"Permet aux agents d''évaluer le code contre quatre objectifs clés : cela fonctionne, cela continue de fonctionner, cela est adaptable et répond aux exigences, garantissant la robustesse et la maintenabilité grâce à des tests rigoureux et une conception modulaire.","de":"Ermächtigt die Agenten, den Code gegen vier wichtige Ziele zu bewerten: es funktioniert, es bleibt funktionsfähig, es ist anpassbar und erfüllt die Anforderungen, wodurch Robustheit und Wartbarkeit durch rigoroses Testen und modulares Design gewährleistet werden.","pt":"Habilita os agentes a avaliar o código contra quatro objetivos principais: funciona, continua funcionando, é adaptável e atende aos requisitos, garantindo robustez e manutenibilidade por meio de testes rigorosos e design modular.","ru":"Наделяет агентов возможностью оценивать код по четырем ключевым целям: он работает, он продолжает работать, он адаптируем и соответствует требованиям, обеспечивая прочность и поддерживаемость посредством строгого тестирования и модульного проектирования.","ar":"تمكين الوكلاء من تقييم الكود مقابل أربعة أهداف رئيسية: يعمل، يستمر في العمل، يعتبر قابل للتكيف، ويستوفي المتطلبات، مما يضمن متانة وقابلية الصيانة من خلال الاختبار القاسي وتصميم موديولار."},"useCases":{"en":["Automating code reviews for adherence to quality foundations","Generating test suites to ensure code works and keeps working","Debugging brittle dependencies and hidden assumptions in legacy code"],"zh":["自动化代码审查以确保质量基础的遵守","生成测试套件以确保代码的工作和持续工作","调试遗留代码中的脆弱依赖和隐藏假设"],"ja":["品質基盤の遵守を確保するためのコードレビューの自動化","コードが動作し続けることを保証するためのテストスイートの生成","レガシーコードの脆弱な依存関係と隠れた仮定のデバッグ"],"ko":["품질 기초의 준수를 보장하기 위한 코드 리뷰의 자동화","코드가 작동하고 지속 작동하는 것을 보장하기 위한 테스트 스위트 생성","레거시 코드의 취약한 의존성 및 숨겨진 가설의 디버깅"],"es":["Automatizar revisiones de código para adherirse a fundamentos de calidad","Generar suites de pruebas para garantizar que el código funciona y sigue funcionando","Depurar dependencias frágiles y suposiciones ocultas en código legacy"],"fr":["Automatiser les révisions de code pour se conformer aux fondements de qualité","Générer des suites de tests pour garantir que le code fonctionne et continue de fonctionner","Déboguer les dépendances fragiles et les hypothèses cachées dans le code legacy"],"de":["Automatisieren von Code-Reviews, um Qualitätsgrundlagen einzuhalten","Erstellen von Test-Suiten, um sicherzustellen, dass der Code funktioniert und weiterhin funktionsfähig ist","Fehlerbehebung von fragilen Abhängigkeiten und versteckten Annahmen in Legacy-Code"],"pt":["Automatizar revisões de código para aderência a fundamentos de qualidade","Gerar conjuntos de testes para garantir que o código funcione e continue funcionando","Depurar dependências frágeis e suposições ocultas em código legado"],"ru":["Автоматизировать проверку кода на соответствие основам качества","Генерировать наборы тестов для обеспечения работы кода и его продолжения","Отладить хрупкие зависимости и скрытые предположения в устаревшем коде"],"ar":["السماح بتحويل المراجعة التلقائية للكود لملاءمة أسس الجودة","توليد مجموعات الاختبار لضمان عمل الكود والاستمرار في العمل","تصحيح الأعتمادات الهشة والافتراضات المخفية في الكود القديم"]},"limitations":{"en":["Requires comprehensive codebase access","May necessitate additional testing frameworks and tools"],"zh":["需要全面访问代码库","可能需要额外的测试框架和工具"],"ja":["コードベースへの包括的なアクセスが必要","追加のテストフレームワークとツールが必要になる可能性がある"],"ko":["코드베이스에 대한 포괄적인 액세스가 필요함","추가 테스트 프레임워크 및 툴이 필요할 수 있음"],"es":["Requiere acceso integral al código base","Puede necesitar marcos de prueba y herramientas adicionales"],"fr":["Nécessite un accès complet au code base","Peut nécessiter des cadres de test et des outils supplémentaires"],"de":["Erfordert umfassenden Zugriff auf den Codebase","Kann zusätzliche Test-Frameworks und -Tools erfordern"],"pt":["Exige acesso abrangente à base de código","Pode necessitar de estruturas de teste e ferramentas adicionais"],"ru":["Требует полного доступа к базе кода","Может потребовать дополнительных рамок и инструментов тестирования"],"ar":["يتطلب وصولا شاملا إلى قاعدة الشفرة","يمكن أن يتطلب إطارات اختبار وأدوات إضافية"]},"version":4},"contentHash":"b04cae12a1e546b113b0b44bcf918c7c1821ae9586e806de9c2d9522cce9dc49","qualityScore":26}');
