INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('smileynet/code-spice/code-quality-foundations', 'code-quality-foundations', 'smileynet', 'code-spice', 'community', 'code-quality-foundations smileynet code-spice community Code-quality-foundations provides a framework for writing high-quality code that works, keeps working, is adaptable, and meets requirements. It benefits developers seeking to improve their coding skills and write robust, maintainable code. 代码质量基础是确保代码可靠、可维护和可适应的关键。它涵盖了四个目标：它工作、它保持工作、它适应、以及避免常见的失败模式 コード品質の基礎は、コードが信頼性が高く、維持可能で、適応可能であることを保証する鍵です。4つの目標：動作する、変更に耐える、適応可能、そして失敗モードを避けることをカバーします 코드 품질基础은 코드가 신뢰할 수 있고, 유지 보수 가능하며, 적응 가능한지 확인하는 핵심입니다. 4가지 목표: 작동, 변경에 내구성, 적응성 및 일반적인 실패 모드를 피하는 것을 다룹니다 Code Quality Foundations proporciona las bases para escribir código de alta calidad que funcione, se adapte y sea mantenible. Aprende a evitar errores comunes Les fondations de code de haute qualité fournissent les bases pour écrire du code de haute qualité qui fonctionne, s''adapte et est maintenable. Apprenez à éviter les erreurs courantes Code-Quality-Foundations bietet die Grundlagen für das Schreiben von hochwertigem Code, der funktioniert, sich anpasst und wartbar ist. Erfahren Sie, wie Sie häufige Fehler vermeiden Os fundamentos de qualidade de código são essenciais para criar software confiável e eficaz. Aprenda a escrever código que atenda aos quatro objetivos principais: funcione, sobreviva a mudanças, seja adaptável e escalável. Основы качества кода являются необходимыми для создания надежного и эффективного программного обеспечения. Узнайте, как писать код, который соответствует четырем основным целям: работает, выдерживает изменения, является адаптируемым и масштабируемым с помощью ИИ Агентов. الأساسيات لجودة الكود ضرورية لإنشاء برمجيات موثوقة وفعالة. تعلم كيفية كتابة رمز يلبي الأهداف الأربعة الرئيسية: يعمل، ويستمر في العمل، ويتكيف، ويتوسع how to use code-quality-foundations what is code-quality-foundations code-quality-foundations best practices code-quality-foundations setup guide code-quality-foundations vs clean code code-quality-foundations install code-quality-foundations for robust code code-quality-foundations for adaptable code code-quality-foundations for maintainable code 代码质量基础 AIエージェント 代码设计 代码开发 可靠性 维护性 适应性 失败模式 Achieves the goal of ''it works'' by solving problems correctly and handling edge cases Ensures code ''keeps working'' by surviving changes and avoiding brittle dependencies Enables adaptability by allowing requirements to change without a rewrite Avoids rigid coupling, over-engineering, and hardcoded assumptions Code-quality-foundations is a set of principles and guidelines for writing high-quality code that achieves four key goals: it works, it keeps working, it''s adaptable, and it meets requirements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JDenn0514/surveycore/cran', 'community', 'JDenn0514', 'surveycore', 'JDenn0514/surveycore', 'cran', 0, 0, 26, '2026-03-07T13:32:26Z', '2026-03-08T02:14:09.878Z', '89367a85221e5962ded417719386a23f9b1a7c31173a66a89ee7c90253b62e42', '{"id":"JDenn0514/surveycore/cran","name":"cran","description":{"en":"cran provides core survey analysis infrastructure, benefiting researchers and developers working with R and survey analysis. It streamlines projects with defined rules and checks.","zh":"CRAN 提交指南为 Surveyverse 项目提供了 R CMD check 和 devtools::check() 的最佳实践","ja":"CRAN 提交ガイドは、Surveyverse プロジェクトの R CMD check と devtools::check() のベストプラクティスを提供する","ko":"CRAN 제출 가이드는 Surveyverse 프로젝트의 R CMD check 및 devtools::check() 최적화 방법을 제공합니다","es":"CRAN es una infraestructura central para el análisis de encuestas, que utiliza R y devtools para garantizar la calidad de los paquetes","fr":"CRAN est une infrastructure centrale pour l''analyse d''enquêtes, qui utilise R et devtools pour assurer la qualité des packages","de":"CRAN ist eine zentrale Infrastruktur für die Umfrageanalyse, die R und devtools verwendet, um die Qualität der Pakete zu gewährleisten","pt":"O CRAN é uma infraestrutura de análise de pesquisas que utiliza o R e o devtools para análise de dados. Aprenda a configurá-lo com nossa guia","ru":"CRAN - это инфраструктура анализа опросов, которая использует R и devtools для анализа данных. Узнайте, как ее настроить с нашей помощью","ar":"أداة CRAN هي بنية تحتية لتحليل الاستطلاعات التي تستخدم R و devtools لتحليل البيانات. تعلم كيفية إعدادها مع دليلنا"},"seo":{"title":{"en":"cran: Core Survey Analysis Infrastructure Setup Guide | A...","zh":"CRAN 设置指南：Surveyverse 项目最佳实践","ja":"CRAN Setup Guide: Surveyverse プロジェクトのベストプラクティス","ko":"CRAN 설정 가이드: Surveyverse 프로젝트 최적화","es":"Guía de configuración de CRAN para análisis de encuestas","fr":"Guide de configuration de CRAN pour l''analyse d''enquêtes","de":"CRAN-Konfigurationsleitfaden für Umfrageanalysen","pt":"Guia de Configuração do CRAN para Análise de Pesquisas","ru":"Настройка ИИ Агента CRAN для Анализа Опросов","ar":"إعداد أداة CRAN للتحليل الاستباقي"},"description":{"en":"Unlock efficient survey analysis with cran. Learn how to leverage R CMD check, devtools, and pre-approved notes for seamless project execution. Get started now!","zh":"了解 CRAN 提交指南，优化 Surveyverse 项目的 R CMD check 和 devtools::check()","ja":"CRAN 提交ガイドを理解し、Surveyverse プロジェクトの R CMD check と devtools::check() を最適化する","ko":"CRAN 제출 가이드를 이해하고 Surveyverse 프로젝트의 R CMD check 및 devtools::check()를 최적화합니다","es":"Aprende a configurar CRAN para análisis de encuestas con R y devtools","fr":"Découvrez comment configurer CRAN pour l''analyse d''enquêtes avec R et devtools","de":"Erfahren Sie, wie Sie CRAN für Umfrageanalysen mit R und devtools konfigurieren","pt":"Aprenda a configurar o CRAN para análise de pesquisas com nossa guia passo a passo. Descubra como utilizar o R e o devtools para análise de dados","ru":"Узнайте, как настроить ИИ Агент CRAN для анализа опросов с нашей пошаговой инструкцией. Откройте для себя, как использовать R и devtools для анализа данных","ar":"تعلم كيفية إعداد أداة CRAN للتحليل الاستباقي مع دليلنا خطوة بخطوة. اكتشف كيفية استخدام R و devtools لتحليل البيانات"},"definition":{"en":"cran is a core survey analysis infrastructure that provides a set of rules and checks for R packages, ensuring seamless project execution and high-quality results.","zh":"CRAN 是一个核心的调查分析基础设施，提供 R 包管理和检查","ja":"CRAN は、R パッケージの管理とチェックを提供する核心の調査分析インフラストラクチャです","ko":"CRAN은 R 패키지 관리 및 검사를 제공하는 핵심 조사 분석 인프라입니다","es":"CRAN es una infraestructura de análisis de encuestas que utiliza R para garantizar la calidad de los paquetes","fr":"CRAN est une infrastructure d''analyse d''enquêtes qui utilise R pour assurer la qualité des packages","de":"CRAN ist eine Infrastruktur für die Umfrageanalyse, die R verwendet, um die Qualität der Pakete zu gewährleisten","pt":"O que é CRAN? É uma infraestrutura de análise de pesquisas que utiliza o R para análise de dados","ru":"Что такое CRAN? Это инфраструктура анализа опросов, которая использует R для анализа данных","ar":"ما هي أداة CRAN؟ هي بنية تحتية لتحليل الاستطلاعات التي تستخدم R لتحليل البيانات"},"features":{"en":["Utilizes R CMD check for targeted error and warning detection","Employs devtools::check() for cadence and pre-approved notes management","References r-package-conventions.md for standardized project structure","Supports preflight-checklist.md for thorough project preparation","Enforces rules for Surveyverse projects, including ≤2 notes and 0 errors"],"zh":["R CMD check 目标（0 错误，0 警告，≤2 备注）","pre-approved 备注和 devtools::check() 节奏","Surveyverse 项目的四阶段过程","devtools::check() 和 R CMD check 的集成","r-package-conventions.md §3 中定义的规则","preflight-checklist.md 参考文档"],"ja":["R CMD check ターゲット（0 エラー、0 警告、≤2 ノート）","pre-approved ノートと devtools::check() のリズム","Surveyverse プロジェクトの 4 つのステージ","devtools::check() と R CMD check の統合","r-package-conventions.md §3 で定義されたルール","preflight-checklist.md リファレンス ドキュメント"],"ko":["R CMD check 목표（0 오류，0 경고，≤2 노트）","pre-approved 노트 및 devtools::check() 리듬","Surveyverse 프로젝트의 4단계 과정","devtools::check() 및 R CMD check 통합","r-package-conventions.md §3에서 정의된 규칙","preflight-checklist.md 참조 문서"],"es":["Utiliza R CMD check para garantizar la calidad de los paquetes","Integra con devtools para automatizar las pruebas","Sigue las convenciones de paquetes de R definidas en r-package-conventions.md","Utiliza un enfoque de cuatro etapas para el análisis de encuestas","Incluye una lista de verificación previa al vuelo para garantizar la calidad de los paquetes"],"fr":["Utilise R CMD check pour assurer la qualité des packages","Intègre avec devtools pour automatiser les tests","Suit les conventions de packages R définies dans r-package-conventions.md","Utilise une approche en quatre étapes pour l''analyse d''enquêtes","Inclut une liste de vérification préalable pour assurer la qualité des packages"],"de":["Verwendet R CMD check, um die Qualität der Pakete zu gewährleisten","Integriert mit devtools, um die Tests zu automatisieren","Befolgt die Paketkonventionen von R, die in r-package-conventions.md definiert sind","Verwendet einen vierstufigen Ansatz für die Umfrageanalyse","Enthält eine Vorflug-Checkliste, um die Qualität der Pakete zu gewährleisten"],"pt":["Utiliza o R para análise de dados","Integração com devtools para análise de pacotes","Suporte a análise de pesquisas com Surveyverse","Seguimento das convenções de pacote R","Utiliza R CMD check para análise de erros"],"ru":["Использует R для анализа данных","Интеграция с devtools для анализа пакетов","Поддержка анализа опросов с Surveyverse","Следование конвенциям пакета R","Использует R CMD check для анализа ошибок"],"ar":["استخدام R لتحليل البيانات","التكامل مع devtools لتحليل الحزم","دعم تحليل الاستطلاعات مع Surveyverse","متابعة اتفاقيات حزمة R","استخدام R CMD check لتحليل الأخطاء"]},"keywords":{"en":["how to use cran for survey analysis","cran vs other survey analysis tools","cran install guide for R","what is cran in R programming","cran alternative for data analysis","cran setup guide for AI agents","cran tutorial for researchers","cran best practices for survey analysis"],"zh":["CRAN 提交指南","Surveyverse 项目","R CMD check","devtools::check()","r 包管理","调查分析基础设施","AI 工具","R 语言","数据分析"],"ja":["CRAN 提交ガイド","Surveyverse プロジェクト","R CMD check","devtools::check()","R パッケージ管理","調査分析インフラストラクチャ","AI エージェント","R 言語","データ分析"],"ko":["CRAN 제출 가이드","Surveyverse 프로젝트","R CMD check","devtools::check()","R 패키지 관리","조사 분석 인프라","AI 에이전트","R 언어","데이터 분석"],"es":["CRAN","análisis de encuestas","R","devtools","r-package-conventions","configuración de CRAN","guía de configuración de CRAN","análisis de encuestas con R"," Agentes de inteligencia artificial para análisis de encuestas"],"fr":["CRAN","analyse d''enquêtes","R","devtools","r-package-conventions","configuration de CRAN","guide de configuration de CRAN","analyse d''enquêtes avec R","Outils d''intelligence artificielle pour l''analyse d''enquêtes"],"de":["CRAN","Umfrageanalyse","R","devtools","r-package-conventions","CRAN-Konfiguration","CRAN-Konfigurationsleitfaden","Umfrageanalyse mit R","Künstliche Intelligenz-Tools für die Umfrageanalyse"],"pt":["CRAN","análise de pesquisas","R","devtools","Surveyverse","análise de dados","infraestrutura de análise","configuração do CRAN"],"ru":["CRAN","анализ опросов","R","devtools","Surveyverse","анализ данных","инфраструктура анализа","настройка ИИ Агента CRAN"],"ar":["CRAN","تحليل الاستطلاعات","R","devtools","Surveyverse","تحليل البيانات","بنية تحتية للتحليل","إعداد أداة CRAN"]}},"owner":"JDenn0514","repo":"surveycore","repoPath":"JDenn0514/surveycore","stars":0,"forks":0,"updatedAt":"2026-03-07T13:32:26Z","topics":["data","r","resear","survey-analysis"],"category":"community","skillMd":{"name":"cran","description":">","bodyPreview":"# CRAN Submission\n\n> **Surveyverse projects:** R CMD check targets (0 errors, 0 warnings, ≤2 notes),\n> pre-approved notes, and `devtools::check()` cadence are defined in\n> `r-package-conventions.md §3`. Those rules take precedence over generic guidance here.\n\n## The four-stage arc\n\n| Stage | What you''re doing | Reference |\n|-------|-------------------|-----------|\n| **Prepare** | DESCRIPTION, docs, URLs, admin — the things `devtools::check()` won''t catch | [preflight-checklist.md](references/pre","body":"# CRAN Submission\n\n> **Surveyverse projects:** R CMD check targets (0 errors, 0 warnings, ≤2 notes),\n> pre-approved notes, and `devtools::check()` cadence are defined in\n> `r-package-conventions.md §3`. Those rules take precedence over generic guidance here.\n\n## The four-stage arc\n\n| Stage | What you''re doing | Reference |\n|-------|-------------------|-----------|\n| **Prepare** | DESCRIPTION, docs, URLs, admin — the things `devtools::check()` won''t catch | [preflight-checklist.md](references/preflight-checklist.md) |\n| **Check** | `R CMD check --as-cran`, platform testing, NOTE triage | [check-and-triage.md](references/check-and-triage.md) |\n| **Submit** | Build tarball, `devtools::submit_cran()`, write `cran-comments.md` | [submit-and-respond.md](references/submit-and-respond.md) |\n| **Respond** | Point-by-point reviewer responses, resubmission | [submit-and-respond.md](references/submit-and-respond.md) |\n\n## Tool map\n\n| Task | Tool |\n|------|------|\n| Full local check | `devtools::check()` |\n| CRAN-style check (fast iteration) | `devtools::check(args = \"--as-cran\")` |\n| CRAN-style check (submission confidence) | `R CMD build .` then `R CMD check --as-cran pkg_x.y.z.tar.gz` |\n| Docs and examples only | `devtools::check_man()` |\n| Windows + R-devel | `devtools::check_win_devel()` |\n| Multi-platform preflight | `rhub::check_for_cran()` |\n| URL validation | `urlchecker::url_check()` |\n| Submit to CRAN | `devtools::submit_cran()` |\n| Generate release issue checklist | `usethis::use_release_issue()` |\n| Create `cran-comments.md` | `usethis::use_cran_comments()` |\n| Create `NEWS.md` | `usethis::use_news_md()` |\n| Bump version | `usethis::use_version()` |\n\n## The CRAN mindset\n\nCRAN checks run in a **minimal, non-interactive environment** with no hidden\ndependencies. Write code as if:\n\n- There is no network access during checks (examples, tests, vignettes)\n- Nothing is written outside `tempdir()`\n- There are no interactive prompts\n- Examples run in a few seconds each — not minutes\n- No binary executables are bundled in the source package\n\nPrefer fixes that make checks green everywhere over explanations that justify\nfragility.\n\n## ERROR / WARNING / NOTE triage\n\n- **ERRORs**: Always blockers. Fix before submission.\n- **WARNINGs**: Almost always blockers. Very rare contextual exceptions.\n- **NOTEs**: Split into two types:\n  - *Actionable* — fix it (undeclared dependency, broken URL, too-long examples)\n  - *Contextual* — explain in `cran-comments.md` (incoming feasibility NOTE on new submissions)\n\nWhen keeping a NOTE, `cran-comments.md` must answer:\n\n1. What is the NOTE?\n2. Why does it happen?\n3. Why is it safe / expected?\n4. What did you do to minimize it?\n\n## Quality gate (recommended order)\n\n1. `devtools::check()` is clean — 0 errors, 0 warnings\n2. Preflight checklist complete — see [preflight-checklist.md](references/preflight-checklist.md)\n3. Tarball check: `R CMD build .` → `R CMD check --as-cran pkg_x.y.z.tar.gz`\n4. Cross-platform: `devtools::check_win_devel()` at minimum; R-hub for broader coverage\n5. `cran-comments.md` written and reviewed\n6. Ready to respond point-by-point if CRAN asks\n\n## High-frequency failure surfaces\n\n- **DESCRIPTION metadata**: Title case, forbidden phrases, missing `cph` role\n- **Documentation**: Missing `@return` or `@examples` on exported functions\n- **Examples**: network calls, unseeded randomness, writes outside tempdir, commented-out code\n- **URLs**: HTTP instead of HTTPS, redirecting links\n- **Undeclared dependencies**: packages used in code/examples/tests but absent from DESCRIPTION\n- **Package size / runtime**: large embedded data, slow vignettes or examples\n\n## External resources\n\n- CRAN policy: https://cran.r-project.org/web/packages/policies.html\n- CRAN submission checklist: https://cran.r-project.org/web/packages/submission_checklist.html\n- Writing R Extensions (R CMD check): https://cran.r-project.org/doc/manuals/r-release/R-exts.html\n- R Packages (2e) — releasing to CRAN: https://r-pkgs.org/release.html\n- win-builder: https://win-builder.r-project.org/\n- macbuilder: https://mac.r-project.org/macbuilder/submit.html\n"},"lastSynced":"2026-03-08T02:14:09.878Z","agentAnalysis":{"suitability":{"en":"Perfect for R-Based Agents needing streamlined survey analysis and CRAN submission capabilities.","zh":"适合需要简化调查分析和CRAN提交功能的基于R的代理。","ja":"Rベースのエージェントがストリーミングした調査分析とCRANの提出機能を必要とする場合に最適です。","ko":"조사 분석과 CRAN 제출 기능을簡略化해야 하는 R 기반 에이전트에게 적합합니다.","es":"Perfecto para agentes basados en R que necesitan un análisis de encuestas optimizado y capacidades de presentación de CRAN.","fr":"Parfait pour les agents basés sur R nécessitant une analyse d''enquêtes rationalisée et des capacités de soumission CRAN.","de":"Perfekt für R-basierte Agenten, die eine optimierte Umfrageanalyse und CRAN-Einreichungsfunktionen benötigen.","pt":"Perfeito para Agentes Baseados em R que precisam de análise de survey simplificada e capacidades de envio para o CRAN.","ru":"Идеально для агентов на основе R, которым необходима упрощенная анализ опросов и возможности отправки в CRAN.","ar":"مثالي للوكلاء الذين يعملون باللغة R والذين يحتاجون إلى تحليل مسح مبسط وقدرات تقديم CRAN."},"recommendation":{"en":"Empowers agents to perform comprehensive content analysis, leveraging devtools::check() and R CMD check for survey projects, ensuring adherence to predefined rules and checks, and streamlining projects with defined targets and notes.","zh":"赋予代理执行全面内容分析的能力，利用devtools::check()和R CMD check来检查调查项目，确保遵守预定义的规则和检查，并通过定义的目标和备注来简化项目。","ja":"エージェントが包括的なコンテンツ分析を実行することを可能にし、devtools::check()およびR CMD checkを利用して調査プロジェクトをチェックし、事前に定義されたルールやチェックに従い、ターゲットやノートを定義することでプロジェクトを簡素化する。","ko":"에이전트가 종합적인 콘텐츠 분석을 수행할 수 있도록하여, devtools::check()와 R CMD check를 이용하여 조사 프로젝트를 확인하고, 미리 정의된 규칙 및 체크를 준수하며, 정의된 목표 및 노트로 프로젝트를 간소화한다.","es":"Permite a los agentes realizar un análisis de contenido integral, aprovechando devtools::check() y R CMD check para proyectos de encuestas, garantizando el cumplimiento de reglas y controles predefinidos, y racionalizando los proyectos con objetivos y notas definidos.","fr":"Permet aux agents d''effectuer une analyse de contenu complète, en exploitant devtools::check() et R CMD check pour les projets d''enquêtes, en garantissant le respect des règles et des vérifications prédéfinies, et en rationalisant les projets avec des cibles et des notes définies.","de":"Ermöglicht es den Agenten, eine umfassende Inhaltsanalyse durchzuführen, indem sie devtools::check() und R CMD check für Umfrageprojekte nutzen, um die Einhaltung vordefinierter Regeln und Prüfungen sicherzustellen und die Projekte mit definierten Zielen und Notizen zu rationalisieren.","pt":"Habilita os agentes a realizar análises de conteúdo abrangentes, aproveitando devtools::check() e R CMD check para projetos de survey, garantindo a adesão a regras e verificações predefinidas e simplificando projetos com alvos e notas definidos.","ru":"Наделяет агентов возможностью проводить всесторонний анализ контента, используя devtools::check() и R CMD check для проектов опросов, обеспечивая соблюдение предопределенных правил и проверок, и оптимизируя проекты с определёнными целями и заметками.","ar":"يمكن للوكلاء من خلاله إجراء تحليل محتوى شامل ، مستفيدًا من devtools::check() و R CMD check لمشاريع المسح ، وضمان الالتزام بالقواعد والفحوصات المحددة مسبقًا ، وتيسير المشاريع مع أهداف وملاحظات محددة."},"useCases":{"en":["Automating survey analysis workflows","Validating R packages against CRAN submission rules","Generating pre-approved notes for survey projects"],"zh":["自动化调查分析工作流程","验证R包是否符合CRAN提交规则","为调查项目生成预批准备注"],"ja":["調査分析ワークフローの自動化","RパッケージをCRAN提出ルールに適合させるための検証","調査プロジェクト用の事前承認済みノートの生成"],"ko":["조사 분석 워크플로우의 자동화","R 패키지를 CRAN 제출 규칙에 맞추는 검증","조사 프로젝트를 위한 사전 승인된 노트 생성"],"es":["Automatización de flujos de trabajo de análisis de encuestas","Validación de paquetes R frente a reglas de presentación de CRAN","Generación de notas preaprobadas para proyectos de encuestas"],"fr":["Automatisation des flux de travail d''analyse d''enquêtes","Validation des packages R par rapport aux règles de soumission CRAN","Génération de notes préapprouvées pour les projets d''enquêtes"],"de":["Automatisierung von Umfrageanalyse-Workflows","Validierung von R-Paketen gegen CRAN-Einreichungsregeln","Generierung von vorab genehmigten Notizen für Umfrageprojekte"],"pt":["Automatizar fluxos de trabalho de análise de survey","Validar pacotes R contra regras de envio para o CRAN","Gerar notas pré-aprovadas para projetos de survey"],"ru":["Автоматизировать рабочие процессы анализа опросов","Проверять пакеты R на соответствие правилам отправки в CRAN","Генерировать предварительно одобренные заметки для проектов опросов"],"ar":["تحويلfluxس 자동اتيزيح للتحليل المسح","التحقق من حزم R مقابل قواعد إرسال إلى CRAN","توليد ملاحظات مسبقًا الموافق عليها لمشاريع المسح"]},"limitations":{"en":["Requires R environment","Specific to survey analysis and CRAN submission","Adherence to r-package-conventions.md guidelines"],"zh":["需要R环境","仅适用于调查分析和CRAN提交","遵守r-package-conventions.md指南"],"ja":["R環境が必要","調査分析およびCRAN提出に特化","r-package-conventions.mdガイドラインに従う"],"ko":["R 환경이 필요","조사 분석 및 CRAN 제출에 특화","r-package-conventions.md 가이드라인을 따름"],"es":["Requiere entorno R","Específico para el análisis de encuestas y la presentación de CRAN","Cumplimiento de las directrices de r-package-conventions.md"],"fr":["Nécessite un environnement R","Spécifique à l''analyse d''enquêtes et à la soumission CRAN","Respect des directives de r-package-conventions.md"],"de":["Benötigt R-Umgebung","Spezifisch für Umfrageanalyse und CRAN-Einreichung","Einhaltung der Richtlinien von r-package-conventions.md"],"pt":["Requer ambiente R","Específico para análise de survey e envio para o CRAN","Adesão às diretrizes r-package-conventions.md"],"ru":["Требуется среда R","Относится конкретно к анализу опросов и отправке в CRAN","Соблюдение руководства r-package-conventions.md"],"ar":["يتطلب بيئة R","نوعي للتحليل المسح وإرسال إلى CRAN","الامتثال للإرشادات r-package-conventions.md"]},"version":4},"contentHash":"89367a85221e5962ded417719386a23f9b1a7c31173a66a89ee7c90253b62e42","qualityScore":26}');
